INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_challenge#2','math',2,2,'u1','L06','g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',2,'sa','auto','1000씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-2-u1-C5","difficulty":2,"kind":"sa","stem":"1000씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","answer":["6450"],"explanation":["1000씩 거꾸로 뛰면 천의 자리 숫자가 1씩 작아져요.","7450에서 1000만큼 거꾸로 뛰면 6450이에요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[9450,8450,7450,null,5450],"step":1000,"dir":"down"},"variant_rule":{"skip4":{"ask":"blank","step":[1000],"dir":"down"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_challenge#3','math',2,2,'u1','L06','g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',3,'mc','auto','2360에서 1000씩 3번 뛰어 센 수는 무엇인가요?',ARRAY['M2-2-u1-X12']::text[],true,'{"seq":3,"concept":"M2-2-u1-C5","difficulty":3,"kind":"mc","stem":"2360에서 1000씩 3번 뛰어 센 수는 무엇인가요?","options":[{"t":"5360","correct":true},{"t":"2363","mis":"M2-2-u1-X12"},{"t":"2660","mis":"M2-2-u1-X12"}],"explanation":["2360, 3360, 4360, 5360 — 1000씩 3번이에요.","천의 자리만 1씩 커져요.","1000씩 3번은 1씩 3번, 100씩 3번과 달라요."],"variant_rule":{"alt":[{"stem":"4785에서 100씩 2번 뛰어 센 수는 무엇인가요?","options":[{"t":"4985","correct":true},{"t":"4805","mis":"M2-2-u1-X12"},{"t":"6785","mis":"M2-2-u1-X12"}],"explanation":["4785, 4885, 4985 — 100씩 2번이에요.","백의 자리만 1씩 커져요.","100씩 2번은 10씩 2번, 1000씩 2번과 달라요."]},{"stem":"5998에서 1씩 4번 뛰어 센 수는 무엇인가요?","options":[{"t":"6002","correct":true},{"t":"6038","mis":"M2-2-u1-X12"},{"t":"9998","mis":"M2-2-u1-X12"}],"explanation":["5998, 5999, 6000, 6001, 6002 — 1씩 4번이에요.","5999 다음은 6000이에요.","자리가 넘어가는 곳을 조심해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_challenge#4','math',2,2,'u1','L06','g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',3,'mc','auto','어떤 수에서 1000씩 4번 뛰어 세었더니 8000이 되었어요. 어떤 수는 무엇인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X12']::text[],true,'{"seq":4,"concept":"M2-2-u1-C5","difficulty":3,"kind":"mc","stem":"어떤 수에서 1000씩 4번 뛰어 세었더니 8000이 되었어요. 어떤 수는 무엇인가요?","options":[{"t":"4000","correct":true},{"t":"12000","mis":"M2-2-u1-X15"},{"t":"7996","mis":"M2-2-u1-X12"}],"explanation":["8000에서 1000씩 거꾸로 4번 뛰어 세요.","8000, 7000, 6000, 5000, 4000 — 어떤 수는 4000이에요.","「어떤 수에서 뛰어 셌다」면 거꾸로 세어 찾아요."],"variant_rule":{"alt":[{"stem":"어떤 수에서 100씩 3번 뛰어 세었더니 5000이 되었어요. 어떤 수는 무엇인가요?","options":[{"t":"4700","correct":true},{"t":"5300","mis":"M2-2-u1-X15"},{"t":"4997","mis":"M2-2-u1-X12"}],"explanation":["5000에서 100씩 거꾸로 3번 뛰어 세요.","5000, 4900, 4800, 4700 — 어떤 수는 4700이에요.","「어떤 수에서 뛰어 셌다」면 거꾸로 세어 찾아요."]},{"stem":"어떤 수에서 10씩 5번 뛰어 세었더니 3020이 되었어요. 어떤 수는 무엇인가요?","options":[{"t":"2970","correct":true},{"t":"3070","mis":"M2-2-u1-X15"},{"t":"3015","mis":"M2-2-u1-X12"}],"explanation":["3020에서 10씩 거꾸로 5번 뛰어 세요.","3020, 3010, 3000, 2990, 2980, 2970 — 어떤 수는 2970이에요.","3000에서 10 작아지면 2990 — 천의 자리에서 빌려 와요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_challenge#5','math',2,2,'u1','L06','g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',3,'mc','auto','얼마씩 거꾸로 뛰어 세었나요?',ARRAY['M2-2-u1-X12']::text[],true,'{"seq":5,"concept":"M2-2-u1-C5","difficulty":3,"kind":"mc","stem":"얼마씩 거꾸로 뛰어 세었나요?","options":[{"t":"100씩","correct":true},{"t":"1000씩","mis":"M2-2-u1-X12"},{"t":"10씩","mis":"M2-2-u1-X12"}],"explanation":["6505, 6405, 6305 … 하고 백의 자리 숫자만 1씩 작아져요.","그래서 100씩 거꾸로 뛰어 세었어요.","어느 자리 숫자가 바뀌는지 보면 몇씩 뛰었는지 알 수 있어요."],"asset":{"type":"jump_row","cells":[6505,6405,6305,6205,6105],"step":null,"dir":"down"},"variant_rule":{"skip4":{"ask":"step","step":[1,10,100,1000],"dir":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_challenge#6','math',2,2,'u1','L06','g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',3,'error','auto','5990부터 뛰어 센 다음 수를 썼어요. 잘못 쓴 친구는 누구인가요?',ARRAY['M2-2-u1-X01','M2-2-u1-X11']::text[],true,'{"seq":6,"concept":"M2-2-u1-C5","difficulty":3,"kind":"error","stem":"5990부터 뛰어 센 다음 수를 썼어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"서아: 10씩 뛰면 5990 다음은 59100이야.","correct":true,"mis_target":"M2-2-u1-X01"},{"t":"주원: 1씩 뛰면 5990 다음은 5991이야.","mis":"M2-2-u1-X11"},{"t":"라온: 1000씩 뛰면 5990 다음은 6990이야.","mis":"M2-2-u1-X11"}],"explanation":["5990에서 10을 더 뛰면 십의 자리가 10이 돼요.","백·천의 자리로 차례로 넘어가 6000이에요.","서아가 잘못 썼어요."],"variant_rule":{"alt":[{"stem":"4000부터 거꾸로 뛰어 센 다음 수를 썼어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"지호: 10씩 거꾸로 뛰면 4000 다음은 4990이야.","correct":true,"mis_target":"M2-2-u1-X01"},{"t":"하린: 1씩 거꾸로 뛰면 4000 다음은 3999야.","mis":"M2-2-u1-X11"},{"t":"도윤: 1000씩 거꾸로 뛰면 4000 다음은 3000이야.","mis":"M2-2-u1-X11"}],"explanation":["4000에서 10을 거꾸로 뛰면 천의 자리에서 하나를 빌려 와야 해요.","4000보다 10 작은 수는 3990이에요.","지호가 잘못 썼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_challenge#7','math',2,2,'u1','L06','g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',3,'ox','auto','7004부터 1씩 거꾸로 5번 뛰어 세면 7000이에요.',ARRAY['M2-2-u1-X01']::text[],true,'{"seq":7,"concept":"M2-2-u1-C5","difficulty":3,"kind":"ox","stem":"7004부터 1씩 거꾸로 5번 뛰어 세면 7000이에요.","answer":"X","reason_options":[{"t":"7003, 7002, 7001, 7000, 6999라서 6999니까","correct":true},{"t":"일의 자리 4에서 거꾸로 세면 0에서 멈추니까","mis":"M2-2-u1-X01"}],"mis":"M2-2-u1-X01","explanation":["1씩 거꾸로 5번이면 7003, 7002, 7001, 7000, 6999예요.","7000 다음 한 번 더 세면 6999가 돼요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"2995부터 1씩 5번 뛰어 세면 3000이에요.","answer":"O","reason_options":[{"t":"2996, 2997, 2998, 2999, 3000이니까","correct":true},{"t":"2995, 2996, 2997, 2998, 2999라서","mis":"M2-2-u1-X12"}],"explanation":["1씩 5번이면 2996, 2997, 2998, 2999, 3000이에요.","2999 다음은 3000이에요.","그래서 맞는 말이에요."]},{"stem":"3900부터 100씩 2번 뛰어 세면 31100이에요.","answer":"X","reason_options":[{"t":"4000, 4100이라서 4100이니까","correct":true},{"t":"39 다음은 310, 311이라서","mis":"M2-2-u1-X01"}],"explanation":["3900, 4000, 4100이에요.","3900 다음은 4000 — 백의 자리가 넘어가 천의 자리가 1 커져요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_challenge#8','math',2,2,'u1','L06','g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',4,'mc','auto','규칙에 따라 뛰어 세었어요. 2350, 2450, 2550, ★, 2750 — ★보다 1000만큼 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X12']::text[],true,'{"seq":8,"concept":"M2-2-u1-C5","difficulty":4,"kind":"mc","stem":"규칙에 따라 뛰어 세었어요. 2350, 2450, 2550, ★, 2750 — ★보다 1000만큼 더 큰 수는 무엇인가요?","options":[{"t":"3650","correct":true},{"t":"2750","mis":"M2-2-u1-X12"},{"t":"2660","mis":"M2-2-u1-X12"}],"explanation":["100씩 뛰어 세었어요 — ★은 2650이에요.","2650보다 1000 큰 수는 3650이에요.","먼저 규칙으로 ★을 찾고 나서 묻는 말을 풀어요."],"variant_rule":{"alt":[{"stem":"규칙에 따라 뛰어 세었어요. 7408, 6408, 5408, ★, 3408 — ★보다 10만큼 더 큰 수는 무엇인가요?","options":[{"t":"4418","correct":true},{"t":"5408","mis":"M2-2-u1-X12"},{"t":"4409","mis":"M2-2-u1-X12"}],"explanation":["1000씩 거꾸로 뛰어 세었어요 — ★은 4408이에요.","4408보다 10 큰 수는 4418이에요.","먼저 규칙으로 ★을 찾아요."]},{"stem":"규칙에 따라 뛰어 세었어요. 6997, 6998, 6999, ★, 7001 — ★보다 100만큼 더 작은 수는 무엇인가요?","options":[{"t":"6900","correct":true},{"t":"7100","mis":"M2-2-u1-X15"},{"t":"6999","mis":"M2-2-u1-X12"}],"explanation":["1씩 뛰어 세었어요 — ★은 7000이에요.","7000보다 100 작은 수는 6900이에요.","먼저 규칙으로 ★을 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_challenge#9','math',2,2,'u1','L06','g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',4,'mc','auto','1740부터 100씩 뛰어 셀 때, 2000보다 큰 수 가운데 처음 나오는 수는 무엇인가요?',ARRAY['M2-2-u1-X11','M2-2-u1-X12']::text[],true,'{"seq":9,"concept":"M2-2-u1-C5","difficulty":4,"kind":"mc","stem":"1740부터 100씩 뛰어 셀 때, 2000보다 큰 수 가운데 처음 나오는 수는 무엇인가요?","options":[{"t":"2040","correct":true},{"t":"2100","mis":"M2-2-u1-X11"},{"t":"2140","mis":"M2-2-u1-X12"}],"explanation":["1740, 1840, 1940, 2040이에요.","2000보다 큰 수 가운데 처음 나오는 수는 2040이에요.","100씩 뛰면 십·일의 자리 40은 그대로예요."],"variant_rule":{"alt":[{"stem":"3650부터 1000씩 뛰어 셀 때, 8000보다 큰 수 가운데 처음 나오는 수는 무엇인가요?","options":[{"t":"8650","correct":true},{"t":"8001","mis":"M2-2-u1-X11"},{"t":"9000","mis":"M2-2-u1-X11"}],"explanation":["3650, 4650, 5650, 6650, 7650, 8650이에요.","8000보다 큰 수 가운데 처음 나오는 수는 8650이에요.","1000씩 뛰면 백·십·일의 자리는 그대로예요."]},{"stem":"6993부터 1씩 뛰어 셀 때, 7000보다 큰 수 가운데 처음 나오는 수는 무엇인가요?","options":[{"t":"7001","correct":true},{"t":"7010","mis":"M2-2-u1-X11"},{"t":"7000","mis":"M2-2-u1-X13"}],"explanation":["6993, … 6999, 7000, 7001이에요.","7000보다 큰 수 가운데 처음 나오는 수는 7001이에요.","7000은 7000보다 크지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_challenge#10','math',2,2,'u1','L06','g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',4,'essay','teacher','3990부터 10씩 뛰어 세면 다음 수는 무엇인지 쓰고, 그 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u1-C5","difficulty":4,"kind":"essay","stem":"3990부터 10씩 뛰어 세면 다음 수는 무엇인지 쓰고, 그 까닭을 설명해 보세요.","answer_guide":{"answer":"4000. 3990에서 10을 더하면 십의 자리가 10이 되어 백의 자리로 넘어가고, 백의 자리도 10이 되어 천의 자리로 넘어가므로 4000이 된다.","scoring_points":["다음 수를 4000이라고 바르게 썼는가","십의 자리가 10이 되어 윗자리로 넘어간다고 말했는가","39100처럼 이어 쓰지 않는 까닭을 말했는가"]},"explanation":["3990 다음 10씩이면 십의 자리가 10이 돼요.","10은 윗자리로 넘어가고, 백의 자리도 10이 되어 천의 자리가 1 커져 4000이에요.","숫자를 이어 붙이지 않고 자리를 넘겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_basic#1','math',2,2,'u1','L07','g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',1,'mc','auto','3542와 3524 중에서 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13']::text[],true,'{"seq":1,"concept":"M2-2-u1-C6","difficulty":1,"kind":"mc","stem":"3542와 3524 중에서 더 큰 수는 무엇인가요?","options":[{"t":"3542","correct":true},{"t":"3524","mis":"M2-2-u1-X13"}],"explanation":["천의 자리와 백의 자리가 같아요.","십의 자리를 보면 4는 2보다 커요 — 더 큰 수는 3542예요.","높은 자리가 다르면 낮은 자리는 보지 않아도 돼요."],"variant_rule":{"cmp4d":{"ask":"big","same":"thh"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_basic#2','math',2,2,'u1','L07','g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',1,'mc','auto','6372와 6519 중에서 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13']::text[],true,'{"seq":2,"concept":"M2-2-u1-C6","difficulty":1,"kind":"mc","stem":"6372와 6519 중에서 더 큰 수는 무엇인가요?","options":[{"t":"6519","correct":true},{"t":"6372","mis":"M2-2-u1-X13"}],"explanation":["천의 자리가 같아요.","백의 자리를 보면 5는 3보다 커요 — 더 큰 수는 6519예요.","십·일의 자리가 커도 백의 자리가 먼저예요."],"variant_rule":{"cmp4d":{"ask":"big","same":"th"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_basic#3','math',2,2,'u1','L07','g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',1,'mc','auto','두 수의 크기를 바르게 비교한 것은 어느 것인가요?',ARRAY['M2-2-u1-X14']::text[],true,'{"seq":3,"concept":"M2-2-u1-C6","difficulty":1,"kind":"mc","stem":"두 수의 크기를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"1999 < 2005","correct":true},{"t":"1999 > 2005","mis":"M2-2-u1-X14"}],"explanation":["천의 자리에서 처음으로 달라요 — 2는 1보다 커요.","그래서 2005는 1999보다 커요 — 1999 < 2005.","> 와 < 는 벌어진 쪽이 큰 수를 향해요."],"variant_rule":{"cmp4d":{"ask":"sign"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_basic#4','math',2,2,'u1','L07','g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',1,'mc','auto','5107과 5400 중에서 더 작은 수는 무엇인가요?',ARRAY['M2-2-u1-X13']::text[],true,'{"seq":4,"concept":"M2-2-u1-C6","difficulty":1,"kind":"mc","stem":"5107과 5400 중에서 더 작은 수는 무엇인가요?","options":[{"t":"5107","correct":true},{"t":"5400","mis":"M2-2-u1-X13"}],"explanation":["천의 자리가 같아요.","백의 자리를 보면 1은 4보다 작아요 — 더 작은 수는 5107이에요.","높은 자리부터 차례로 견주어요."],"variant_rule":{"cmp4d":{"ask":"small","same":"th"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_basic#5','math',2,2,'u1','L07','g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',2,'mc','auto','6154, 5987, 5843 가운데 가장 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],true,'{"seq":5,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"6154, 5987, 5843 가운데 가장 큰 수는 무엇인가요?","options":[{"t":"6154","correct":true},{"t":"5987","mis":"M2-2-u1-X13"},{"t":"5843","mis":"M2-2-u1-X15"}],"explanation":["높은 자리(천의 자리)부터 차례로 견주어요.","가장 큰 수는 6154예요.","뒤쪽 숫자가 크다고 큰 수가 아니에요 — 높은 자리가 먼저예요."],"variant_rule":{"cmp4d":{"ask":"max3"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_basic#6','math',2,2,'u1','L07','g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',2,'mc','auto','7105, 7150, 7015 가운데 가장 작은 수는 무엇인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],true,'{"seq":6,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"7105, 7150, 7015 가운데 가장 작은 수는 무엇인가요?","options":[{"t":"7015","correct":true},{"t":"7105","mis":"M2-2-u1-X13"},{"t":"7150","mis":"M2-2-u1-X15"}],"explanation":["천의 자리는 모두 7이에요 — 백의 자리를 견주어요.","백의 자리가 0인 7015가 가장 작아요.","일의 자리가 작다고 작은 수가 아니에요 — 높은 자리가 먼저예요."],"variant_rule":{"cmp4d":{"ask":"min3"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_basic#7','math',2,2,'u1','L07','g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',2,'ox','auto','1999와 2005 가운데 뒤쪽 숫자가 큰 1999가 더 커요.',ARRAY['M2-2-u1-X13']::text[],true,'{"seq":7,"concept":"M2-2-u1-C6","difficulty":2,"kind":"ox","stem":"1999와 2005 가운데 뒤쪽 숫자가 큰 1999가 더 커요.","answer":"X","reason_options":[{"t":"천의 자리 2가 1보다 커서 2005가 더 크니까","correct":true},{"t":"9가 많으면 더 큰 수니까","mis":"M2-2-u1-X13"}],"mis":"M2-2-u1-X13","explanation":["천의 자리를 먼저 봐요 — 1과 2예요.","천의 자리 2가 더 커서 2005가 더 커요.","그래서 틀린 말이에요 — 1999의 뒤쪽 9들은 볼 필요가 없어요."],"variant_rule":{"alt":[{"stem":"2046은 1422보다 커요.","answer":"O","reason_options":[{"t":"천의 자리 2가 1보다 크니까","correct":true},{"t":"1422는 백의 자리 4가 커서 더 크니까","mis":"M2-2-u1-X13"}],"explanation":["천의 자리를 보면 2가 1보다 커요.","그래서 2046이 더 커요.","그래서 맞는 말이에요."]},{"stem":"일의 자리 숫자가 더 크면 더 큰 수예요.","answer":"X","reason_options":[{"t":"천의 자리부터 차례로 견주어야 하니까","correct":true},{"t":"일의 자리가 커야 크니까","mis":"M2-2-u1-X13"}],"explanation":["네 자리 수는 천의 자리부터 견주어요.","천의 자리가 같으면 백의 자리, 그다음 십·일의 자리를 봐요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_basic#8','math',2,2,'u1','L07','g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',2,'blank','auto','8130 (        ) 8103 — 빈칸에 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u1-X14','M2-2-u1-X13']::text[],true,'{"seq":8,"concept":"M2-2-u1-C6","difficulty":2,"kind":"blank","stem":"8130 (        ) 8103 — 빈칸에 알맞은 것은 어느 것인가요?","options":[{"t":">","correct":true},{"t":"<","mis":"M2-2-u1-X14"},{"t":"=","mis":"M2-2-u1-X13"}],"explanation":["천의 자리와 백의 자리가 같아요.","십의 자리를 보면 3이 0보다 커서 8130이 더 커요.","큰 쪽으로 벌어지게 — 8130 > 8103이에요."],"variant_rule":{"alt":[{"stem":"4999 (        ) 5001 — 빈칸에 알맞은 것은 어느 것인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M2-2-u1-X14"},{"t":"=","mis":"M2-2-u1-X13"}],"explanation":["천의 자리를 보면 4가 5보다 작아요.","그래서 4999가 더 작아요.","작은 쪽을 뾰족하게 — 4999 < 5001이에요."]},{"stem":"2760 (        ) 2706 — 빈칸에 알맞은 것은 어느 것인가요?","options":[{"t":">","correct":true},{"t":"<","mis":"M2-2-u1-X14"},{"t":"=","mis":"M2-2-u1-X13"}],"explanation":["천의 자리와 백의 자리가 같아요.","십의 자리를 보면 6이 0보다 커요.","그래서 2760 > 2706이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_basic#9','math',2,2,'u1','L07','g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',2,'match','auto','두 수 가운데 더 큰 수끼리 이어 보세요.','{}'::text[],true,'{"seq":9,"concept":"M2-2-u1-C6","difficulty":2,"kind":"match","stem":"두 수 가운데 더 큰 수끼리 이어 보세요.","pairs":[{"l":"3080과 3800","r":"3800"},{"l":"2999와 3001","r":"3001"},{"l":"7510과 7150","r":"7510"}],"mis":"M2-2-u1-X13","explanation":["3080과 3800은 백의 자리 8이 커서 3800이 커요.","2999와 3001은 천의 자리 3이 커서 3001, 7510과 7150은 백의 자리 5가 커서 7510이에요.","높은 자리부터 차례로 견주어요."],"variant_rule":{"alt":[{"stem":"두 수 가운데 더 작은 수끼리 이어 보세요.","pairs":[{"l":"6200과 6020","r":"6020"},{"l":"1999와 2000","r":"1999"},{"l":"8450과 8540","r":"8450"}],"explanation":["6200과 6020은 백의 자리 0이 작아서 6020이 작아요.","1999와 2000은 천의 자리 1이 작아서 1999, 8450과 8540은 8450이에요.","높은 자리부터 차례로 견주어요."]},{"stem":"이번에는 다른 보기예요. 두 수 가운데 더 큰 수끼리 이어 보세요.","pairs":[{"l":"5090과 5900","r":"5900"},{"l":"4000과 3999","r":"4000"},{"l":"2630과 2360","r":"2630"}],"explanation":["5090과 5900은 백의 자리 9가 커서 5900이에요.","4000과 3999는 천의 자리 4가 커서 4000, 2630과 2360은 2630이에요.","높은 자리부터 차례로 견주어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_basic#10','math',2,2,'u1','L07','g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',3,'mc','auto','독도 방문자가 3월에 5591명, 4월에 5519명, 5월에 5951명이었어요. 방문자가 가장 많은 달은 언제인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],true,'{"seq":10,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"독도 방문자가 3월에 5591명, 4월에 5519명, 5월에 5951명이었어요. 방문자가 가장 많은 달은 언제인가요?","options":[{"t":"5월","correct":true},{"t":"3월","mis":"M2-2-u1-X13"},{"t":"4월","mis":"M2-2-u1-X15"}],"explanation":["세 수의 천의 자리는 5로 같아요.","백의 자리는 5·5·9라 5월이 가장 커요.","그래서 방문자가 가장 많은 달은 5월이에요."],"variant_rule":{"alt":[{"stem":"손수건이 가 상자에 1536장, 나 상자에 1563장, 다 상자에 1356장 있어요. 가장 적게 든 상자는 어느 것인가요?","options":[{"t":"다 상자","correct":true},{"t":"가 상자","mis":"M2-2-u1-X13"},{"t":"나 상자","mis":"M2-2-u1-X15"}],"explanation":["세 수의 천의 자리는 1로 같아요.","백의 자리는 5·5·3이라 다 상자가 가장 적어요.","「가장 적게」를 잘 읽어요."]},{"stem":"연날리기에 연이 첫째 날 2108개, 둘째 날 2081개, 셋째 날 2180개 쓰였어요. 가장 많이 쓰인 날은 언제인가요?","options":[{"t":"셋째 날","correct":true},{"t":"첫째 날","mis":"M2-2-u1-X13"},{"t":"둘째 날","mis":"M2-2-u1-X15"}],"explanation":["세 수의 천의 자리는 2, 백의 자리는 1·0·1이에요.","2108과 2180은 십의 자리를 보면 8이 0보다 커요 — 셋째 날이에요.","일의 자리가 아니라 십의 자리부터 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_challenge#1','math',2,2,'u1','L07','g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',2,'mc','auto','3871, 4120, 3817 가운데 가장 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],true,'{"seq":1,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"3871, 4120, 3817 가운데 가장 큰 수는 무엇인가요?","options":[{"t":"4120","correct":true},{"t":"3871","mis":"M2-2-u1-X13"},{"t":"3817","mis":"M2-2-u1-X15"}],"explanation":["높은 자리(천의 자리)부터 차례로 견주어요.","가장 큰 수는 4120이에요.","뒤쪽 숫자가 크다고 큰 수가 아니에요 — 높은 자리가 먼저예요."],"variant_rule":{"cmp4d":{"ask":"max3"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_challenge#2','math',2,2,'u1','L07','g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',2,'mc','auto','수 카드 3, 8, 5, 1을 한 번씩 모두 써서 만들 수 있는 가장 큰 네 자리 수는 무엇인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X16']::text[],true,'{"seq":2,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"수 카드 3, 8, 5, 1을 한 번씩 모두 써서 만들 수 있는 가장 큰 네 자리 수는 무엇인가요?","options":[{"t":"8531","correct":true},{"t":"1358","mis":"M2-2-u1-X15"},{"t":"8513","mis":"M2-2-u1-X16"}],"explanation":["가장 큰 8을 천의 자리에 놓아요.","남은 카드도 큰 수부터 — 8531이에요.","높은 자리일수록 큰 숫자를 놓아요."],"variant_rule":{"cards4":{"ask":"max"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_challenge#3','math',2,2,'u1','L07','g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',3,'mc','auto','수 카드 4, 0, 7, 2를 한 번씩 모두 써서 만들 수 있는 가장 작은 네 자리 수는 무엇인가요?',ARRAY['M2-2-u1-X16','M2-2-u1-X15']::text[],true,'{"seq":3,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"수 카드 4, 0, 7, 2를 한 번씩 모두 써서 만들 수 있는 가장 작은 네 자리 수는 무엇인가요?","options":[{"t":"2047","correct":true},{"t":"247","mis":"M2-2-u1-X16"},{"t":"7420","mis":"M2-2-u1-X15"}],"explanation":["0은 천의 자리에 놓을 수 없어요(그러면 세 자리 수).","천의 자리에 2, 백의 자리에 0, 그다음 4, 7 — 2047이에요.","0이 있으면 천의 자리 다음 자리에 놓아요."],"variant_rule":{"cards4":{"ask":"min","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_challenge#4','math',2,2,'u1','L07','g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',3,'mc','auto','4518 < □618에서 □에 들어갈 수 있는 가장 작은 수는 무엇인가요? (□에는 1부터 9까지)',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],true,'{"seq":4,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"4518 < □618에서 □에 들어갈 수 있는 가장 작은 수는 무엇인가요? (□에는 1부터 9까지)","options":[{"t":"4","correct":true},{"t":"5","mis":"M2-2-u1-X13"},{"t":"1","mis":"M2-2-u1-X15"}],"explanation":["□가 4이면 4618 — 천의 자리가 같으니 백의 자리 6과 5를 견주어요.","6이 5보다 커서 4618 > 4518이에요. □가 3이면 3618이라 작아요.","그래서 가장 작은 수는 4예요."],"variant_rule":{"alt":[{"stem":"3725 < □650에서 □에 들어갈 수 있는 가장 작은 수는 무엇인가요? (□에는 1부터 9까지)","options":[{"t":"4","correct":true},{"t":"3","mis":"M2-2-u1-X13"},{"t":"9","mis":"M2-2-u1-X15"}],"explanation":["□가 3이면 3650 — 백의 자리 6이 7보다 작아 3725보다 작아요.","□가 4이면 4650 — 천의 자리 4가 3보다 커요.","그래서 가장 작은 수는 4예요."]},{"stem":"7□48은 7562보다 커요. □에 들어갈 수 있는 가장 작은 수는 무엇인가요?","options":[{"t":"6","correct":true},{"t":"5","mis":"M2-2-u1-X13"},{"t":"0","mis":"M2-2-u1-X15"}],"explanation":["천의 자리는 7로 같으니 백의 자리를 견주어요.","□가 5이면 7548 — 십의 자리 4가 6보다 작아 7562보다 작아요. □가 6이면 7648이라 커요.","그래서 가장 작은 수는 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_challenge#5','math',2,2,'u1','L07','g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',3,'sa','auto','6□45는 6345보다 작아요. □에 들어갈 수 있는 수는 모두 몇 개인가요?','{}'::text[],true,'{"seq":5,"concept":"M2-2-u1-C6","difficulty":3,"kind":"sa","stem":"6□45는 6345보다 작아요. □에 들어갈 수 있는 수는 모두 몇 개인가요?","answer":["3","3개"],"explanation":["천의 자리는 6으로 같으니 백의 자리를 견주어요.","□가 3이면 6345와 같아요 — □는 3보다 작은 0, 1, 2예요.","그래서 모두 3개예요."],"variant_rule":{"alt":[{"stem":"2□80은 2560보다 커요. □에 들어갈 수 있는 수는 모두 몇 개인가요?","answer":["5","5개"],"explanation":["천의 자리는 2로 같으니 백의 자리를 견주어요.","□가 5이면 2580 — 십의 자리 8이 6보다 커서 2560보다 커요. □는 5, 6, 7, 8, 9예요.","그래서 모두 5개예요 — □가 백의 자리 숫자 5와 같을 때도 꼭 살펴요."]},{"stem":"83□4는 8374보다 작아요. □에 들어갈 수 있는 수는 모두 몇 개인가요?","answer":["7","7개"],"explanation":["천·백의 자리가 같으니 십의 자리를 견주어요.","□가 7이면 8374와 같아요 — □는 0부터 6까지예요.","그래서 모두 7개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_challenge#6','math',2,2,'u1','L07','g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',3,'error','auto','친구들이 두 수를 비교했어요. 잘못 비교한 친구는 누구인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X14']::text[],true,'{"seq":6,"concept":"M2-2-u1-C6","difficulty":3,"kind":"error","stem":"친구들이 두 수를 비교했어요. 잘못 비교한 친구는 누구인가요?","options":[{"t":"도하: 2998 > 3002 (9가 0보다 크니까)","correct":true,"mis_target":"M2-2-u1-X13"},{"t":"유진: 4500 < 5040","mis":"M2-2-u1-X14"},{"t":"세아: 6710 > 6170","mis":"M2-2-u1-X13"}],"explanation":["2998과 3002는 천의 자리부터 봐요 — 2는 3보다 작아요.","그래서 2998 < 3002예요.","도하가 잘못 비교했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 두 수를 비교했어요. 잘못 비교한 친구는 누구인가요?","options":[{"t":"준우: 8360 < 8291 (십의 자리 6이 9보다 작아서)","correct":true,"mis_target":"M2-2-u1-X13"},{"t":"서준: 9005 > 8999","mis":"M2-2-u1-X13"},{"t":"라희: 7120 < 7210","mis":"M2-2-u1-X14"}],"explanation":["8360과 8291은 천의 자리가 같으니 백의 자리를 봐요 — 3이 2보다 커요.","그래서 8360 > 8291이에요.","준우가 잘못 비교했어요 — 백의 자리를 건너뛰었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_challenge#7','math',2,2,'u1','L07','g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',3,'mc','auto','독도 이야기에 나오는 연도 2005, 1982, 2010, 1999 가운데 가장 오래전 연도는 무엇인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X13']::text[],true,'{"seq":7,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"독도 이야기에 나오는 연도 2005, 1982, 2010, 1999 가운데 가장 오래전 연도는 무엇인가요?","options":[{"t":"1982","correct":true},{"t":"2010","mis":"M2-2-u1-X15"},{"t":"1999","mis":"M2-2-u1-X13"}],"explanation":["수가 작을수록 오래전이에요 — 가장 작은 수를 찾아요.","천의 자리가 1인 1982와 1999 가운데 십의 자리 8이 9보다 작아요.","그래서 가장 오래전 연도는 1982예요."],"variant_rule":{"alt":[{"stem":"독도 이야기에 나오는 연도 2005, 1982, 2010, 1999 가운데 가장 최근 연도는 무엇인가요?","options":[{"t":"2010","correct":true},{"t":"1982","mis":"M2-2-u1-X15"},{"t":"2005","mis":"M2-2-u1-X13"}],"explanation":["수가 클수록 최근이에요 — 가장 큰 수를 찾아요.","천의 자리가 2인 2005와 2010 가운데 십의 자리 1이 0보다 커요.","그래서 가장 최근 연도는 2010이에요."]},{"stem":"연도 1953, 1935, 1995 가운데 가장 오래전 연도는 무엇인가요?","options":[{"t":"1935","correct":true},{"t":"1995","mis":"M2-2-u1-X15"},{"t":"1953","mis":"M2-2-u1-X13"}],"explanation":["천·백의 자리가 1, 9로 같아요.","십의 자리 3이 가장 작아 1935가 가장 작아요.","수가 작을수록 오래전이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_challenge#8','math',2,2,'u1','L07','g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',4,'mc','auto','천의 자리 숫자가 5이고, 백의 자리 숫자가 십의 자리 숫자보다 큰 네 자리 수 가운데 5400보다 작은 가장 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],true,'{"seq":8,"concept":"M2-2-u1-C6","difficulty":4,"kind":"mc","stem":"천의 자리 숫자가 5이고, 백의 자리 숫자가 십의 자리 숫자보다 큰 네 자리 수 가운데 5400보다 작은 가장 큰 수는 무엇인가요?","options":[{"t":"5329","correct":true},{"t":"5399","mis":"M2-2-u1-X13"},{"t":"5432","mis":"M2-2-u1-X15"}],"explanation":["5400보다 작으니 백의 자리 숫자는 3까지예요(54□□는 5400 이상).","백의 자리가 3이면 십의 자리는 3보다 작아야 해요 — 가장 큰 것은 2, 일의 자리는 9예요.","그래서 5329예요."],"variant_rule":{"alt":[{"stem":"천의 자리 숫자가 3이고, 일의 자리 숫자가 십의 자리 숫자보다 큰 네 자리 수 가운데 가장 작은 수는 무엇인가요?","options":[{"t":"3001","correct":true},{"t":"3000","mis":"M2-2-u1-X13"},{"t":"3010","mis":"M2-2-u1-X16"}],"explanation":["가장 작은 수는 백·십의 자리를 0으로 해요.","일의 자리는 0보다 커야 하니 가장 작은 1이에요.","그래서 3001이에요."]},{"stem":"천의 자리 숫자가 7이고, 네 숫자가 모두 다른 수 가운데 7600보다 큰 가장 작은 수는 무엇인가요?","options":[{"t":"7601","correct":true},{"t":"7600","mis":"M2-2-u1-X13"},{"t":"7610","mis":"M2-2-u1-X16"}],"explanation":["7600보다 커야 하니 760□에서 □는 1부터예요.","7, 6, 0, 1은 모두 달라요.","그래서 7601이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_challenge#9','math',2,2,'u1','L07','g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',4,'mc','auto','수 카드 6, 0, 2, 9, 4 가운데 네 장을 골라 만들 수 있는 네 자리 수 가운데 5000보다 작은 가장 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X16']::text[],true,'{"seq":9,"concept":"M2-2-u1-C6","difficulty":4,"kind":"mc","stem":"수 카드 6, 0, 2, 9, 4 가운데 네 장을 골라 만들 수 있는 네 자리 수 가운데 5000보다 작은 가장 큰 수는 무엇인가요?","options":[{"t":"4962","correct":true},{"t":"9642","mis":"M2-2-u1-X15"},{"t":"4026","mis":"M2-2-u1-X16"}],"explanation":["5000보다 작으려면 천의 자리에 6·9는 올 수 없고 0도 올 수 없어요 — 가장 큰 4예요.","남은 카드 6, 0, 2, 9 가운데 큰 수부터 — 9, 6, 2예요.","그래서 4962예요."],"variant_rule":{"alt":[{"stem":"수 카드 1, 7, 0, 4, 8 가운데 네 장을 골라 만들 수 있는 네 자리 수 가운데 가장 작은 수는 무엇인가요?","options":[{"t":"1047","correct":true},{"t":"147","mis":"M2-2-u1-X16"},{"t":"8741","mis":"M2-2-u1-X15"}],"explanation":["0은 천의 자리에 올 수 없어요 — 가장 작은 1을 놓아요.","남은 카드 가운데 작은 0, 4, 7을 차례로 놓아요.","그래서 1047이에요."]},{"stem":"수 카드 5, 8, 3, 1, 6 가운데 네 장을 골라 만들 수 있는 네 자리 수 가운데 6000보다 큰 가장 작은 수는 무엇인가요?","options":[{"t":"6135","correct":true},{"t":"5136","mis":"M2-2-u1-X13"},{"t":"8653","mis":"M2-2-u1-X15"}],"explanation":["6000보다 크려면 천의 자리는 6이나 8 — 작은 6을 놓아요.","남은 카드 가운데 작은 1, 3, 5를 차례로 놓아요.","그래서 6135예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_challenge#10','math',2,2,'u1','L07','g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',4,'essay','teacher','1999와 2005 가운데 더 큰 수를 고르고, 높은 자리부터 비교하는 방법으로 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u1-C6","difficulty":4,"kind":"essay","stem":"1999와 2005 가운데 더 큰 수를 고르고, 높은 자리부터 비교하는 방법으로 설명해 보세요.","answer_guide":{"answer":"2005가 더 크다. 천의 자리를 보면 2가 1보다 크므로 2005가 더 크다. 1999의 뒤쪽 9들은 볼 필요가 없다.","scoring_points":["2005를 골랐는가","천의 자리 2와 1을 견주어 설명했는가","뒤쪽 숫자(9)로 판단하지 않았는가"]},"explanation":["천의 자리를 먼저 봐요 — 1과 2예요.","2가 더 크니 2005가 더 커요.","높은 자리가 다르면 낮은 자리는 볼 필요가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#1','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C1',1,'mc','auto','999보다 1만큼 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X01','M2-2-u1-X12']::text[],false,'{"seq":1,"concept":"M2-2-u1-C1","difficulty":1,"kind":"mc","stem":"999보다 1만큼 더 큰 수는 무엇인가요?","options":[{"t":"1000","correct":true},{"t":"9910","mis":"M2-2-u1-X01"},{"t":"998","mis":"M2-2-u1-X12"}],"explanation":["999 바로 다음 수예요.","999보다 1 큰 수는 1000이에요.","9 뒤에 10을 붙이지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#2','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C2',1,'mc','auto','1000이 5개이면 얼마인가요?',ARRAY['M2-2-u1-X03']::text[],true,'{"seq":2,"concept":"M2-2-u1-C2","difficulty":1,"kind":"mc","stem":"1000이 5개이면 얼마인가요?","options":[{"t":"5000","correct":true},{"t":"1005","mis":"M2-2-u1-X03"},{"t":"500","mis":"M2-2-u1-X03"}],"explanation":["1000이 5개이면 5000이에요.","「오천」이라고 읽어요.","개수는 천의 자리에 쓰고, 백·십·일의 자리는 0이에요."],"variant_rule":{"n4":{"ask":"thou"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#3','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C3',1,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X06','M2-2-u1-X05']::text[],true,'{"seq":3,"concept":"M2-2-u1-C3","difficulty":1,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"2475","correct":true},{"t":"5742","mis":"M2-2-u1-X06"},{"t":"2000400705","mis":"M2-2-u1-X05"}],"explanation":["1000이 2개, 100이 4개, 10이 7개, 1이 5개예요.","천의 자리 2, 백의 자리 4, 십의 자리 7, 일의 자리 5 — 2475예요.","천·백·십·일 차례로 숫자를 써요."],"asset":{"type":"blocks4","th":2,"h":4,"t":7,"o":5},"variant_rule":{"n4":{"ask":"build"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#4','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C3',1,'match','auto','수와 읽기를 바르게 이어 보세요.','{}'::text[],false,'{"seq":4,"concept":"M2-2-u1-C3","difficulty":1,"kind":"match","stem":"수와 읽기를 바르게 이어 보세요.","pairs":[{"l":"5207","r":"오천이백칠"},{"l":"5027","r":"오천이십칠"},{"l":"5270","r":"오천이백칠십"}],"mis":"M2-2-u1-X07","explanation":["5207은 「오천이백칠」이에요.","5027은 「오천이십칠」, 5270은 「오천이백칠십」이에요.","0인 자리는 읽지 않고, 숫자 뒤에 자리 이름을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#5','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C4',1,'mc','auto','4826에서 백의 자리 숫자는 무엇인가요?',ARRAY['M2-2-u1-X08','M2-2-u1-X09']::text[],true,'{"seq":5,"concept":"M2-2-u1-C4","difficulty":1,"kind":"mc","stem":"4826에서 백의 자리 숫자는 무엇인가요?","options":[{"t":"8","correct":true},{"t":"2","mis":"M2-2-u1-X08"},{"t":"800","mis":"M2-2-u1-X09"}],"explanation":["4826은 천의 자리 4, 백의 자리 8, 십의 자리 2, 일의 자리 6이에요.","백의 자리 숫자는 8이에요.","자리는 왼쪽부터 천·백·십·일 — 숫자를 물으면 값이 아니라 숫자 하나로 답해요."],"variant_rule":{"pv4":{"ask":"digit"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#6','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C5',1,'mc','auto','1000씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X11']::text[],true,'{"seq":6,"concept":"M2-2-u1-C5","difficulty":1,"kind":"mc","stem":"1000씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"6500","correct":true},{"t":"5510","mis":"M2-2-u1-X11"},{"t":"5600","mis":"M2-2-u1-X11"}],"explanation":["1000씩 뛰면 천의 자리 숫자가 1씩 커져요.","5500에서 1000만큼 뛰면 6500이에요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[2500,3500,4500,5500,null],"step":1000},"variant_rule":{"skip4":{"ask":"next","step":[1000]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#7','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C6',1,'mc','auto','6380과 6830 중에서 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13']::text[],true,'{"seq":7,"concept":"M2-2-u1-C6","difficulty":1,"kind":"mc","stem":"6380과 6830 중에서 더 큰 수는 무엇인가요?","options":[{"t":"6830","correct":true},{"t":"6380","mis":"M2-2-u1-X13"}],"explanation":["천의 자리가 같아요.","백의 자리를 보면 8은 3보다 커요 — 더 큰 수는 6830이에요.","높은 자리가 다르면 낮은 자리는 보지 않아도 돼요."],"variant_rule":{"cmp4d":{"ask":"big","same":"th"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#8','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C2',1,'sa','auto','6000은 1000이 몇 개인가요?','{}'::text[],true,'{"seq":8,"concept":"M2-2-u1-C2","difficulty":1,"kind":"sa","stem":"6000은 1000이 몇 개인가요?","answer":["6","6개"],"explanation":["6000은 천의 자리 숫자가 6이에요.","1000이 6개예요.","천의 자리 숫자가 1000의 개수예요."],"variant_rule":{"n4":{"ask":"tcount"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#9','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C1',2,'blank','auto','1000은 900보다 (        )만큼 더 큰 수예요.',ARRAY['M2-2-u1-X12']::text[],false,'{"seq":9,"concept":"M2-2-u1-C1","difficulty":2,"kind":"blank","stem":"1000은 900보다 (        )만큼 더 큰 수예요.","options":[{"t":"100","correct":true},{"t":"10","mis":"M2-2-u1-X12"},{"t":"1","mis":"M2-2-u1-X12"}],"explanation":["900 다음 100씩 뛰면 1000이에요.","그래서 1000은 900보다 100 커요.","백 모형 1개 차이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#10','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C3',2,'mc','auto','「사천구」를 수로 쓰면 무엇인가요?',ARRAY['M2-2-u1-X05','M2-2-u1-X04']::text[],true,'{"seq":10,"concept":"M2-2-u1-C3","difficulty":2,"kind":"mc","stem":"「사천구」를 수로 쓰면 무엇인가요?","options":[{"t":"4009","correct":true},{"t":"40009","mis":"M2-2-u1-X05"},{"t":"49","mis":"M2-2-u1-X04"}],"explanation":["「사천구」는 1000이 4개, 100이 0개, 10이 0개, 1이 9개예요.","수로 쓰면 4009예요.","읽지 않은 자리에는 0을 써요."],"variant_rule":{"n4":{"ask":"write","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#11','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C4',2,'mc','auto','9475에서 숫자 4가 나타내는 값은 얼마인가요?',ARRAY['M2-2-u1-X08','M2-2-u1-X09']::text[],true,'{"seq":11,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"9475에서 숫자 4가 나타내는 값은 얼마인가요?","options":[{"t":"400","correct":true},{"t":"4000","mis":"M2-2-u1-X08"},{"t":"4","mis":"M2-2-u1-X09"}],"explanation":["숫자 4는 백의 자리에 있어요.","백의 자리 4는 400을 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"variant_rule":{"pv4":{"ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#12','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C4',2,'mc','auto','3742를 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],true,'{"seq":12,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"3742를 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"3000 + 700 + 40 + 2","correct":true},{"t":"3 + 7 + 4 + 2","mis":"M2-2-u1-X09"},{"t":"3000 + 400 + 70 + 2","mis":"M2-2-u1-X08"}],"explanation":["3742는 천의 자리 3, 백의 자리 7, 십의 자리 4, 일의 자리 2예요.","각 자리의 값은 3000, 700, 40, 2 — 3742 = 3000 + 700 + 40 + 2.","숫자 하나하나에 자리 값을 붙여야 해요."],"variant_rule":{"pv4":{"ask":"expand"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#13','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C5',2,'mc','auto','얼마씩 뛰어 세었나요?',ARRAY['M2-2-u1-X12']::text[],true,'{"seq":13,"concept":"M2-2-u1-C5","difficulty":2,"kind":"mc","stem":"얼마씩 뛰어 세었나요?","options":[{"t":"100씩","correct":true},{"t":"1000씩","mis":"M2-2-u1-X12"},{"t":"10씩","mis":"M2-2-u1-X12"}],"explanation":["5200, 5300, 5400 … 하고 백의 자리 숫자만 1씩 커져요.","그래서 100씩 뛰어 세었어요.","어느 자리 숫자가 바뀌는지 보면 몇씩 뛰었는지 알 수 있어요."],"asset":{"type":"jump_row","cells":[5200,5300,5400,5500,5600],"step":null},"variant_rule":{"skip4":{"ask":"step","step":[1,10,100,1000],"dir":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#14','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C6',2,'mc','auto','두 수의 크기를 바르게 비교한 것은 어느 것인가요?',ARRAY['M2-2-u1-X14']::text[],true,'{"seq":14,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"두 수의 크기를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"6030 > 5980","correct":true},{"t":"6030 < 5980","mis":"M2-2-u1-X14"}],"explanation":["천의 자리에서 처음으로 달라요 — 6은 5보다 커요.","그래서 6030은 5980보다 커요 — 6030 > 5980.","> 와 < 는 벌어진 쪽이 큰 수를 향해요."],"variant_rule":{"cmp4d":{"ask":"sign"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#15','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C2',2,'error','auto','친구들이 몇천에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u1-X03','M2-2-u1-X07','M2-2-u1-X12']::text[],false,'{"seq":15,"concept":"M2-2-u1-C2","difficulty":2,"kind":"error","stem":"친구들이 몇천에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우: 7000은 1000이 70개야.","correct":true,"mis_target":"M2-2-u1-X03"},{"t":"하린: 7000은 「칠천」이라고 읽어.","mis":"M2-2-u1-X07"},{"t":"도윤: 7000은 6000보다 1000 큰 수야.","mis":"M2-2-u1-X12"}],"explanation":["7000은 천의 자리 숫자가 7이에요.","그래서 1000이 7개예요 — 70개가 아니에요.","은우가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#16','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C7',2,'mc','auto','100이 23개인 수는 얼마인가요?',ARRAY['M2-2-u1-X02','M2-2-u1-X10']::text[],true,'{"seq":16,"concept":"M2-2-u1-C7","difficulty":2,"kind":"mc","stem":"100이 23개인 수는 얼마인가요?","options":[{"t":"2300","correct":true},{"t":"10023","mis":"M2-2-u1-X02"},{"t":"230","mis":"M2-2-u1-X10"}],"explanation":["100이 10개면 1000이에요.","100이 23개는 1000이 2개, 100이 3개 — 2300이에요.","100이 10개 넘게 모이면 1000으로 바꿔 세요."],"variant_rule":{"n4":{"ask":"hund"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#17','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C5',3,'mc','auto','10씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X01','M2-2-u1-X11']::text[],true,'{"seq":17,"concept":"M2-2-u1-C5","difficulty":3,"kind":"mc","stem":"10씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"4000","correct":true},{"t":"39100","mis":"M2-2-u1-X01"},{"t":"3991","mis":"M2-2-u1-X11"}],"explanation":["10씩 뛰면 십의 자리 숫자가 1씩 커져요.","3990에서 10만큼 뛰면 4000이에요.","십의 자리가 10이 되면 바로 윗자리가 1 커지고 십의 자리는 0이 돼요."],"asset":{"type":"jump_row","cells":[3970,3980,3990,null,4010],"step":10},"variant_rule":{"skip4":{"ask":"blank","step":[10],"cross":true,"dir":"up"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#18','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C6',3,'mc','auto','4960, 5120, 4690 가운데 가장 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],true,'{"seq":18,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"4960, 5120, 4690 가운데 가장 큰 수는 무엇인가요?","options":[{"t":"5120","correct":true},{"t":"4960","mis":"M2-2-u1-X13"},{"t":"4690","mis":"M2-2-u1-X15"}],"explanation":["높은 자리(천의 자리)부터 차례로 견주어요.","가장 큰 수는 5120이에요.","뒤쪽 숫자가 크다고 큰 수가 아니에요 — 높은 자리가 먼저예요."],"variant_rule":{"cmp4d":{"ask":"max3"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#19','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C7',3,'mc','auto','돈은 모두 얼마인가요?',ARRAY['M2-2-u1-X10']::text[],true,'{"seq":19,"concept":"M2-2-u1-C7","difficulty":3,"kind":"mc","stem":"돈은 모두 얼마인가요?","options":[{"t":"3340원","correct":true},{"t":"21340원","mis":"M2-2-u1-X10"},{"t":"2340원","mis":"M2-2-u1-X10"}],"explanation":["100원짜리 13개는 천 원짜리 1장과 100원짜리 3개로 바꿀 수 있어요.","천 원짜리 3장, 100원짜리 3개, 10원짜리 4개 — 3340원이에요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks4","th":2,"h":13,"t":4,"o":0,"unit":"coin"},"variant_rule":{"n4":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#20','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C3',3,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X10']::text[],true,'{"seq":20,"concept":"M2-2-u1-C3","difficulty":3,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"2263","correct":true},{"t":"11263","mis":"M2-2-u1-X10"},{"t":"1263","mis":"M2-2-u1-X10"}],"explanation":["백 모형 12개는 천 모형 1개와 백 모형 2개로 바꿀 수 있어요.","1000이 2개, 100이 2개, 10이 6개, 1이 3개 — 2263이에요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks4","th":1,"h":12,"t":6,"o":3},"variant_rule":{"n4":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#21','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C4',3,'ox','auto','7373에서 두 숫자 7이 나타내는 값은 같아요.',ARRAY['M2-2-u1-X09']::text[],false,'{"seq":21,"concept":"M2-2-u1-C4","difficulty":3,"kind":"ox","stem":"7373에서 두 숫자 7이 나타내는 값은 같아요.","answer":"X","reason_options":[{"t":"앞의 7은 7000, 뒤의 7은 70이니까","correct":true},{"t":"같은 숫자는 값도 같으니까","mis":"M2-2-u1-X09"}],"mis":"M2-2-u1-X09","explanation":["앞의 7은 천의 자리라 7000이에요.","뒤의 7은 십의 자리라 70이에요.","그래서 틀린 말이에요 — 자리에 따라 값이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#22','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C6',3,'mc','auto','수 카드 2, 9, 6, 3을 한 번씩 모두 써서 만들 수 있는 가장 큰 네 자리 수는 무엇인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X16']::text[],true,'{"seq":22,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"수 카드 2, 9, 6, 3을 한 번씩 모두 써서 만들 수 있는 가장 큰 네 자리 수는 무엇인가요?","options":[{"t":"9632","correct":true},{"t":"2369","mis":"M2-2-u1-X15"},{"t":"9623","mis":"M2-2-u1-X16"}],"explanation":["가장 큰 9를 천의 자리에 놓아요.","남은 카드도 큰 수부터 — 9632예요.","높은 자리일수록 큰 숫자를 놓아요."],"variant_rule":{"cards4":{"ask":"max"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#23','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C7',4,'mc','auto','천 원짜리 3장과 100원짜리 동전 4개를 모두 100원짜리 동전으로 바꾸면 몇 개가 되나요?',ARRAY['M2-2-u1-X03','M2-2-u1-X04']::text[],false,'{"seq":23,"concept":"M2-2-u1-C7","difficulty":4,"kind":"mc","stem":"천 원짜리 3장과 100원짜리 동전 4개를 모두 100원짜리 동전으로 바꾸면 몇 개가 되나요?","options":[{"t":"34","correct":true},{"t":"7","mis":"M2-2-u1-X03"},{"t":"304","mis":"M2-2-u1-X04"}],"explanation":["천 원짜리 한 장은 100원짜리 10개예요.","천 원짜리 3장은 100원짜리 30개 — 4개를 더하면 34개예요.","3400원은 100이 34개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#24','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C6',4,'mc','auto','5□73은 5672보다 커요. □에 들어갈 수 있는 수는 모두 몇 개인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],false,'{"seq":24,"concept":"M2-2-u1-C6","difficulty":4,"kind":"mc","stem":"5□73은 5672보다 커요. □에 들어갈 수 있는 수는 모두 몇 개인가요?","options":[{"t":"4","correct":true},{"t":"3","mis":"M2-2-u1-X13"},{"t":"5","mis":"M2-2-u1-X15"}],"explanation":["천의 자리는 5로 같으니 백의 자리를 견주어요.","□가 6이면 5673 — 십의 자리는 같고 일의 자리 3이 2보다 커서 커요. □는 6, 7, 8, 9예요.","그래서 모두 4개예요 — □가 같을 때도 꼭 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#25','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C5',4,'essay','teacher','2995부터 1씩 7번 뛰어 센 수를 차례로 쓰고, 자리가 바뀌는 곳을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u1-C5","difficulty":4,"kind":"essay","stem":"2995부터 1씩 7번 뛰어 센 수를 차례로 쓰고, 자리가 바뀌는 곳을 설명해 보세요.","answer_guide":{"answer":"2996, 2997, 2998, 2999, 3000, 3001, 3002. 2999 다음에 일의 자리가 10이 되어 십의 자리로, 십·백의 자리도 차례로 10이 되어 천의 자리로 넘어가 3000이 된다.","scoring_points":["뛰어 센 수를 차례로 바르게 썼는가","자리가 넘어가는(바뀌는) 곳을 설명했는가","몇씩 뛰었는지에 맞는 자리만 바뀐다는 것을 말했는가"]},"explanation":["뛰는 자리 숫자만 1씩 바뀌어요.","그 자리가 10이 되면 윗자리로 넘어가고, 0에서 더 작아지면 윗자리에서 빌려 와요.","숫자를 이어 붙이지 않고 자리를 넘겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#1','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C1',1,'mc','auto','900보다 100만큼 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X12','M2-2-u1-X01']::text[],false,'{"seq":1,"concept":"M2-2-u1-C1","difficulty":1,"kind":"mc","stem":"900보다 100만큼 더 큰 수는 무엇인가요?","options":[{"t":"1000","correct":true},{"t":"910","mis":"M2-2-u1-X12"},{"t":"9100","mis":"M2-2-u1-X01"}],"explanation":["900에서 100을 더 뛰어요.","900보다 100 큰 수는 1000이에요.","100만큼과 10만큼을 헷갈리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#2','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C2',1,'mc','auto','1000이 7개이면 얼마인가요?',ARRAY['M2-2-u1-X03']::text[],true,'{"seq":2,"concept":"M2-2-u1-C2","difficulty":1,"kind":"mc","stem":"1000이 7개이면 얼마인가요?","options":[{"t":"7000","correct":true},{"t":"1007","mis":"M2-2-u1-X03"},{"t":"700","mis":"M2-2-u1-X03"}],"explanation":["1000이 7개이면 7000이에요.","「칠천」이라고 읽어요.","개수는 천의 자리에 쓰고, 백·십·일의 자리는 0이에요."],"variant_rule":{"n4":{"ask":"thou"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#3','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C3',1,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X06','M2-2-u1-X05']::text[],true,'{"seq":3,"concept":"M2-2-u1-C3","difficulty":1,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"3618","correct":true},{"t":"8163","mis":"M2-2-u1-X06"},{"t":"3000600108","mis":"M2-2-u1-X05"}],"explanation":["1000이 3개, 100이 6개, 10이 1개, 1이 8개예요.","천의 자리 3, 백의 자리 6, 십의 자리 1, 일의 자리 8 — 3618이에요.","천·백·십·일 차례로 숫자를 써요."],"asset":{"type":"blocks4","th":3,"h":6,"t":1,"o":8},"variant_rule":{"n4":{"ask":"build"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#4','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C3',1,'match','auto','수와 읽기를 바르게 이어 보세요.','{}'::text[],false,'{"seq":4,"concept":"M2-2-u1-C3","difficulty":1,"kind":"match","stem":"수와 읽기를 바르게 이어 보세요.","pairs":[{"l":"3108","r":"삼천백팔"},{"l":"3018","r":"삼천십팔"},{"l":"3180","r":"삼천백팔십"}],"mis":"M2-2-u1-X07","explanation":["3108은 「삼천백팔」이에요.","3018은 「삼천십팔」, 3180은 「삼천백팔십」이에요.","0인 자리는 읽지 않고, 숫자 뒤에 자리 이름을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#5','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C4',1,'mc','auto','7361에서 천의 자리 숫자는 무엇인가요?',ARRAY['M2-2-u1-X08','M2-2-u1-X09']::text[],true,'{"seq":5,"concept":"M2-2-u1-C4","difficulty":1,"kind":"mc","stem":"7361에서 천의 자리 숫자는 무엇인가요?","options":[{"t":"7","correct":true},{"t":"1","mis":"M2-2-u1-X08"},{"t":"7000","mis":"M2-2-u1-X09"}],"explanation":["7361은 천의 자리 7, 백의 자리 3, 십의 자리 6, 일의 자리 1이에요.","천의 자리 숫자는 7이에요.","자리는 왼쪽부터 천·백·십·일 — 숫자를 물으면 값이 아니라 숫자 하나로 답해요."],"variant_rule":{"pv4":{"ask":"digit"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#6','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C5',1,'mc','auto','100씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X11']::text[],true,'{"seq":6,"concept":"M2-2-u1-C5","difficulty":1,"kind":"mc","stem":"100씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"6530","correct":true},{"t":"6440","mis":"M2-2-u1-X11"},{"t":"7430","mis":"M2-2-u1-X11"}],"explanation":["100씩 뛰면 백의 자리 숫자가 1씩 커져요.","6430에서 100만큼 뛰면 6530이에요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[6130,6230,6330,6430,null],"step":100},"variant_rule":{"skip4":{"ask":"next","step":[100]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#7','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C6',1,'mc','auto','4710과 4170 중에서 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13']::text[],true,'{"seq":7,"concept":"M2-2-u1-C6","difficulty":1,"kind":"mc","stem":"4710과 4170 중에서 더 큰 수는 무엇인가요?","options":[{"t":"4710","correct":true},{"t":"4170","mis":"M2-2-u1-X13"}],"explanation":["천의 자리가 같아요.","백의 자리를 보면 7은 1보다 커요 — 더 큰 수는 4710이에요.","높은 자리가 다르면 낮은 자리는 보지 않아도 돼요."],"variant_rule":{"cmp4d":{"ask":"big","same":"th"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#8','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C2',1,'sa','auto','4000은 1000이 몇 개인가요?','{}'::text[],true,'{"seq":8,"concept":"M2-2-u1-C2","difficulty":1,"kind":"sa","stem":"4000은 1000이 몇 개인가요?","answer":["4","4개"],"explanation":["4000은 천의 자리 숫자가 4예요.","1000이 4개예요.","천의 자리 숫자가 1000의 개수예요."],"variant_rule":{"n4":{"ask":"tcount"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#9','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C1',2,'blank','auto','1000은 999보다 (        )만큼 더 큰 수예요.',ARRAY['M2-2-u1-X12']::text[],false,'{"seq":9,"concept":"M2-2-u1-C1","difficulty":2,"kind":"blank","stem":"1000은 999보다 (        )만큼 더 큰 수예요.","options":[{"t":"1","correct":true},{"t":"10","mis":"M2-2-u1-X12"},{"t":"100","mis":"M2-2-u1-X12"}],"explanation":["999 바로 다음 수가 1000이에요.","그래서 1000은 999보다 1 커요.","바로 다음 수는 1 큰 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#10','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C3',2,'mc','auto','「팔천육십」을 수로 쓰면 무엇인가요?',ARRAY['M2-2-u1-X05','M2-2-u1-X04']::text[],true,'{"seq":10,"concept":"M2-2-u1-C3","difficulty":2,"kind":"mc","stem":"「팔천육십」을 수로 쓰면 무엇인가요?","options":[{"t":"8060","correct":true},{"t":"800060","mis":"M2-2-u1-X05"},{"t":"86","mis":"M2-2-u1-X04"}],"explanation":["「팔천육십」은 1000이 8개, 100이 0개, 10이 6개, 1이 0개예요.","수로 쓰면 8060이에요.","읽지 않은 자리에는 0을 써요."],"variant_rule":{"n4":{"ask":"write","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#11','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C4',2,'mc','auto','2638에서 숫자 6이 나타내는 값은 얼마인가요?',ARRAY['M2-2-u1-X08','M2-2-u1-X09']::text[],true,'{"seq":11,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"2638에서 숫자 6이 나타내는 값은 얼마인가요?","options":[{"t":"600","correct":true},{"t":"6000","mis":"M2-2-u1-X08"},{"t":"6","mis":"M2-2-u1-X09"}],"explanation":["숫자 6은 백의 자리에 있어요.","백의 자리 6은 600을 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"variant_rule":{"pv4":{"ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#12','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C4',2,'mc','auto','5281을 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],true,'{"seq":12,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"5281을 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"5000 + 200 + 80 + 1","correct":true},{"t":"5 + 2 + 8 + 1","mis":"M2-2-u1-X09"},{"t":"5000 + 800 + 20 + 1","mis":"M2-2-u1-X08"}],"explanation":["5281은 천의 자리 5, 백의 자리 2, 십의 자리 8, 일의 자리 1이에요.","각 자리의 값은 5000, 200, 80, 1 — 5281 = 5000 + 200 + 80 + 1.","숫자 하나하나에 자리 값을 붙여야 해요."],"variant_rule":{"pv4":{"ask":"expand"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#13','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C5',2,'mc','auto','얼마씩 거꾸로 뛰어 세었나요?',ARRAY['M2-2-u1-X12']::text[],true,'{"seq":13,"concept":"M2-2-u1-C5","difficulty":2,"kind":"mc","stem":"얼마씩 거꾸로 뛰어 세었나요?","options":[{"t":"1000씩","correct":true},{"t":"100씩","mis":"M2-2-u1-X12"},{"t":"10씩","mis":"M2-2-u1-X12"}],"explanation":["8150, 7150, 6150 … 하고 천의 자리 숫자만 1씩 작아져요.","그래서 1000씩 거꾸로 뛰어 세었어요.","어느 자리 숫자가 바뀌는지 보면 몇씩 뛰었는지 알 수 있어요."],"asset":{"type":"jump_row","cells":[8150,7150,6150,5150,4150],"step":null,"dir":"down"},"variant_rule":{"skip4":{"ask":"step","step":[1,10,100,1000],"dir":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#14','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C6',2,'mc','auto','두 수의 크기를 바르게 비교한 것은 어느 것인가요?',ARRAY['M2-2-u1-X14']::text[],true,'{"seq":14,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"두 수의 크기를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"4720 > 4270","correct":true},{"t":"4720 < 4270","mis":"M2-2-u1-X14"}],"explanation":["백의 자리에서 처음으로 달라요 — 7은 2보다 커요.","그래서 4720은 4270보다 커요 — 4720 > 4270.","> 와 < 는 벌어진 쪽이 큰 수를 향해요."],"variant_rule":{"cmp4d":{"ask":"sign"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#15','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C2',2,'error','auto','친구들이 몇천에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u1-X03','M2-2-u1-X07','M2-2-u1-X12']::text[],false,'{"seq":15,"concept":"M2-2-u1-C2","difficulty":2,"kind":"error","stem":"친구들이 몇천에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아: 1000이 4개이면 1004야.","correct":true,"mis_target":"M2-2-u1-X03"},{"t":"준우: 4000은 「사천」이라고 읽어.","mis":"M2-2-u1-X07"},{"t":"라희: 4000은 3000보다 1000 큰 수야.","mis":"M2-2-u1-X12"}],"explanation":["1000이 4개이면 4000이에요.","개수를 일의 자리에 붙여 1004로 쓰지 않아요.","서아가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#16','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C7',2,'mc','auto','100이 31개인 수는 얼마인가요?',ARRAY['M2-2-u1-X02','M2-2-u1-X10']::text[],true,'{"seq":16,"concept":"M2-2-u1-C7","difficulty":2,"kind":"mc","stem":"100이 31개인 수는 얼마인가요?","options":[{"t":"3100","correct":true},{"t":"10031","mis":"M2-2-u1-X02"},{"t":"310","mis":"M2-2-u1-X10"}],"explanation":["100이 10개면 1000이에요.","100이 31개는 1000이 3개, 100이 1개 — 3100이에요.","100이 10개 넘게 모이면 1000으로 바꿔 세요."],"variant_rule":{"n4":{"ask":"hund"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#17','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C5',3,'mc','auto','1씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X01','M2-2-u1-X11']::text[],true,'{"seq":17,"concept":"M2-2-u1-C5","difficulty":3,"kind":"mc","stem":"1씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"6000","correct":true},{"t":"59910","mis":"M2-2-u1-X01"},{"t":"6009","mis":"M2-2-u1-X11"}],"explanation":["1씩 뛰면 일의 자리 숫자가 1씩 커져요.","5999에서 1만큼 뛰면 6000이에요.","일의 자리가 10이 되면 바로 윗자리가 1 커지고 일의 자리는 0이 돼요."],"asset":{"type":"jump_row","cells":[5998,5999,null,6001,6002],"step":1},"variant_rule":{"skip4":{"ask":"blank","step":[1],"cross":true,"dir":"up"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#18','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C6',3,'mc','auto','3180, 4020, 4910 가운데 가장 작은 수는 무엇인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],true,'{"seq":18,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"3180, 4020, 4910 가운데 가장 작은 수는 무엇인가요?","options":[{"t":"3180","correct":true},{"t":"4020","mis":"M2-2-u1-X13"},{"t":"4910","mis":"M2-2-u1-X15"}],"explanation":["높은 자리(천의 자리)부터 차례로 견주어요.","가장 작은 수는 3180이에요.","뒤쪽 숫자가 크다고 큰 수가 아니에요 — 높은 자리가 먼저예요."],"variant_rule":{"cmp4d":{"ask":"min3"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#19','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C7',3,'mc','auto','돈은 모두 얼마인가요?',ARRAY['M2-2-u1-X10']::text[],true,'{"seq":19,"concept":"M2-2-u1-C7","difficulty":3,"kind":"mc","stem":"돈은 모두 얼마인가요?","options":[{"t":"3660원","correct":true},{"t":"35160원","mis":"M2-2-u1-X10"},{"t":"3560원","mis":"M2-2-u1-X10"}],"explanation":["10원짜리 16개는 100원짜리 1개와 10원짜리 6개로 바꿀 수 있어요.","천 원짜리 3장, 100원짜리 6개, 10원짜리 6개 — 3660원이에요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks4","th":3,"h":5,"t":16,"o":0,"unit":"coin"},"variant_rule":{"n4":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#20','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C3',3,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X10']::text[],true,'{"seq":20,"concept":"M2-2-u1-C3","difficulty":3,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"3552","correct":true},{"t":"34152","mis":"M2-2-u1-X10"},{"t":"3452","mis":"M2-2-u1-X10"}],"explanation":["십 모형 15개는 백 모형 1개와 십 모형 5개로 바꿀 수 있어요.","1000이 3개, 100이 5개, 10이 5개, 1이 2개 — 3552예요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks4","th":3,"h":4,"t":15,"o":2},"variant_rule":{"n4":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#21','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C4',3,'ox','auto','1991에서 두 숫자 1이 나타내는 값은 1000과 1이에요.',ARRAY['M2-2-u1-X09']::text[],false,'{"seq":21,"concept":"M2-2-u1-C4","difficulty":3,"kind":"ox","stem":"1991에서 두 숫자 1이 나타내는 값은 1000과 1이에요.","answer":"O","reason_options":[{"t":"천의 자리 1은 1000, 일의 자리 1은 1이니까","correct":true},{"t":"같은 숫자는 값도 같으니까","mis":"M2-2-u1-X09"}],"mis":"M2-2-u1-X09","explanation":["앞의 1은 천의 자리라 1000이에요.","뒤의 1은 일의 자리라 1이에요.","그래서 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#22','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C6',3,'mc','auto','수 카드 5, 0, 3, 8을 한 번씩 모두 써서 만들 수 있는 가장 작은 네 자리 수는 무엇인가요?',ARRAY['M2-2-u1-X16','M2-2-u1-X15']::text[],true,'{"seq":22,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"수 카드 5, 0, 3, 8을 한 번씩 모두 써서 만들 수 있는 가장 작은 네 자리 수는 무엇인가요?","options":[{"t":"3058","correct":true},{"t":"358","mis":"M2-2-u1-X16"},{"t":"8530","mis":"M2-2-u1-X15"}],"explanation":["0은 천의 자리에 놓을 수 없어요(그러면 세 자리 수).","천의 자리에 3, 백의 자리에 0, 그다음 5, 8 — 3058이에요.","0이 있으면 천의 자리 다음 자리에 놓아요."],"variant_rule":{"cards4":{"ask":"min","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#23','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C7',4,'mc','auto','천 원짜리 2장을 모두 100원짜리 동전으로 바꾸면 몇 개가 되나요?',ARRAY['M2-2-u1-X02','M2-2-u1-X09']::text[],false,'{"seq":23,"concept":"M2-2-u1-C7","difficulty":4,"kind":"mc","stem":"천 원짜리 2장을 모두 100원짜리 동전으로 바꾸면 몇 개가 되나요?","options":[{"t":"20","correct":true},{"t":"2","mis":"M2-2-u1-X02"},{"t":"200","mis":"M2-2-u1-X09"}],"explanation":["천 원짜리 한 장은 100원짜리 10개예요.","천 원짜리 2장은 100원짜리 20개예요.","2000원은 100이 20개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#24','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C6',4,'mc','auto','□280은 4320보다 작아요. □에 들어갈 수 있는 수는 모두 몇 개인가요? (□에는 1부터 9까지)',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],false,'{"seq":24,"concept":"M2-2-u1-C6","difficulty":4,"kind":"mc","stem":"□280은 4320보다 작아요. □에 들어갈 수 있는 수는 모두 몇 개인가요? (□에는 1부터 9까지)","options":[{"t":"4","correct":true},{"t":"3","mis":"M2-2-u1-X13"},{"t":"5","mis":"M2-2-u1-X15"}],"explanation":["□가 4이면 4280 — 백의 자리 2가 3보다 작아 4320보다 작아요.","□가 5부터는 커요. □는 1, 2, 3, 4예요.","그래서 모두 4개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#25','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C5',4,'essay','teacher','4960부터 10씩 4번 뛰어 센 수를 차례로 쓰고, 자리가 바뀌는 곳을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u1-C5","difficulty":4,"kind":"essay","stem":"4960부터 10씩 4번 뛰어 센 수를 차례로 쓰고, 자리가 바뀌는 곳을 설명해 보세요.","answer_guide":{"answer":"4970, 4980, 4990, 5000. 4990 다음에 십의 자리가 10이 되어 백의 자리로, 백의 자리도 10이 되어 천의 자리로 넘어가 5000이 된다.","scoring_points":["뛰어 센 수를 차례로 바르게 썼는가","자리가 넘어가는(바뀌는) 곳을 설명했는가","몇씩 뛰었는지에 맞는 자리만 바뀐다는 것을 말했는가"]},"explanation":["뛰는 자리 숫자만 1씩 바뀌어요.","그 자리가 10이 되면 윗자리로 넘어가고, 0에서 더 작아지면 윗자리에서 빌려 와요.","숫자를 이어 붙이지 않고 자리를 넘겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#1','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C1',1,'mc','auto','100이 10개인 수는 무엇인가요?',ARRAY['M2-2-u1-X02']::text[],false,'{"seq":1,"concept":"M2-2-u1-C1","difficulty":1,"kind":"mc","stem":"100이 10개인 수는 무엇인가요?","options":[{"t":"1000","correct":true},{"t":"10010","mis":"M2-2-u1-X02"},{"t":"200","mis":"M2-2-u1-X02"}],"explanation":["100씩 10번 세어요.","100이 10개이면 1000이에요.","100을 늘어놓아 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#2','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C2',1,'mc','auto','1000이 3개이면 얼마인가요?',ARRAY['M2-2-u1-X03']::text[],true,'{"seq":2,"concept":"M2-2-u1-C2","difficulty":1,"kind":"mc","stem":"1000이 3개이면 얼마인가요?","options":[{"t":"3000","correct":true},{"t":"1003","mis":"M2-2-u1-X03"},{"t":"300","mis":"M2-2-u1-X03"}],"explanation":["1000이 3개이면 3000이에요.","「삼천」이라고 읽어요.","개수는 천의 자리에 쓰고, 백·십·일의 자리는 0이에요."],"variant_rule":{"n4":{"ask":"thou"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#3','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C3',1,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X06','M2-2-u1-X05']::text[],true,'{"seq":3,"concept":"M2-2-u1-C3","difficulty":1,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"5284","correct":true},{"t":"4825","mis":"M2-2-u1-X06"},{"t":"5000200804","mis":"M2-2-u1-X05"}],"explanation":["1000이 5개, 100이 2개, 10이 8개, 1이 4개예요.","천의 자리 5, 백의 자리 2, 십의 자리 8, 일의 자리 4 — 5284예요.","천·백·십·일 차례로 숫자를 써요."],"asset":{"type":"blocks4","th":5,"h":2,"t":8,"o":4},"variant_rule":{"n4":{"ask":"build"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#4','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C3',1,'match','auto','수와 읽기를 바르게 이어 보세요.','{}'::text[],false,'{"seq":4,"concept":"M2-2-u1-C3","difficulty":1,"kind":"match","stem":"수와 읽기를 바르게 이어 보세요.","pairs":[{"l":"6409","r":"육천사백구"},{"l":"6049","r":"육천사십구"},{"l":"6490","r":"육천사백구십"}],"mis":"M2-2-u1-X07","explanation":["6409는 「육천사백구」예요.","6049는 「육천사십구」, 6490은 「육천사백구십」이에요.","0인 자리는 읽지 않고, 숫자 뒤에 자리 이름을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#5','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C4',1,'mc','auto','1594에서 일의 자리 숫자는 무엇인가요?',ARRAY['M2-2-u1-X08']::text[],true,'{"seq":5,"concept":"M2-2-u1-C4","difficulty":1,"kind":"mc","stem":"1594에서 일의 자리 숫자는 무엇인가요?","options":[{"t":"4","correct":true},{"t":"1","mis":"M2-2-u1-X08"},{"t":"5","mis":"M2-2-u1-X08"}],"explanation":["1594는 천의 자리 1, 백의 자리 5, 십의 자리 9, 일의 자리 4예요.","일의 자리 숫자는 4예요.","자리는 왼쪽부터 천·백·십·일 — 숫자를 물으면 값이 아니라 숫자 하나로 답해요."],"variant_rule":{"pv4":{"ask":"digit"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#6','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C5',1,'mc','auto','1씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X11']::text[],true,'{"seq":6,"concept":"M2-2-u1-C5","difficulty":1,"kind":"mc","stem":"1씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"3845","correct":true},{"t":"3944","mis":"M2-2-u1-X11"},{"t":"4844","mis":"M2-2-u1-X11"}],"explanation":["1씩 뛰면 일의 자리 숫자가 1씩 커져요.","3844에서 1만큼 뛰면 3845예요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[3841,3842,3843,3844,null],"step":1},"variant_rule":{"skip4":{"ask":"next","step":[1]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#7','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C6',1,'mc','auto','9250과 9520 중에서 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13']::text[],true,'{"seq":7,"concept":"M2-2-u1-C6","difficulty":1,"kind":"mc","stem":"9250과 9520 중에서 더 큰 수는 무엇인가요?","options":[{"t":"9520","correct":true},{"t":"9250","mis":"M2-2-u1-X13"}],"explanation":["천의 자리가 같아요.","백의 자리를 보면 5는 2보다 커요 — 더 큰 수는 9520이에요.","높은 자리가 다르면 낮은 자리는 보지 않아도 돼요."],"variant_rule":{"cmp4d":{"ask":"big","same":"th"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#8','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C2',1,'sa','auto','8000은 1000이 몇 개인가요?','{}'::text[],true,'{"seq":8,"concept":"M2-2-u1-C2","difficulty":1,"kind":"sa","stem":"8000은 1000이 몇 개인가요?","answer":["8","8개"],"explanation":["8000은 천의 자리 숫자가 8이에요.","1000이 8개예요.","천의 자리 숫자가 1000의 개수예요."],"variant_rule":{"n4":{"ask":"tcount"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#9','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C1',2,'blank','auto','1000은 100이 (        )개인 수예요.',ARRAY['M2-2-u1-X02','M2-2-u1-X09']::text[],false,'{"seq":9,"concept":"M2-2-u1-C1","difficulty":2,"kind":"blank","stem":"1000은 100이 (        )개인 수예요.","options":[{"t":"10","correct":true},{"t":"1","mis":"M2-2-u1-X02"},{"t":"100","mis":"M2-2-u1-X09"}],"explanation":["100씩 세어 1000까지 가요.","10번 세면 1000이에요.","그래서 100이 10개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#10','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C3',2,'mc','auto','「칠천이」를 수로 쓰면 무엇인가요?',ARRAY['M2-2-u1-X05','M2-2-u1-X04']::text[],true,'{"seq":10,"concept":"M2-2-u1-C3","difficulty":2,"kind":"mc","stem":"「칠천이」를 수로 쓰면 무엇인가요?","options":[{"t":"7002","correct":true},{"t":"70002","mis":"M2-2-u1-X05"},{"t":"72","mis":"M2-2-u1-X04"}],"explanation":["「칠천이」는 1000이 7개, 100이 0개, 10이 0개, 1이 2개예요.","수로 쓰면 7002예요.","읽지 않은 자리에는 0을 써요."],"variant_rule":{"n4":{"ask":"write","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#11','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C4',2,'mc','auto','5182에서 숫자 8이 나타내는 값은 얼마인가요?',ARRAY['M2-2-u1-X08','M2-2-u1-X09']::text[],true,'{"seq":11,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"5182에서 숫자 8이 나타내는 값은 얼마인가요?","options":[{"t":"80","correct":true},{"t":"8000","mis":"M2-2-u1-X08"},{"t":"8","mis":"M2-2-u1-X09"}],"explanation":["숫자 8은 십의 자리에 있어요.","십의 자리 8은 80을 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"variant_rule":{"pv4":{"ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#12','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C4',2,'mc','auto','9614를 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],true,'{"seq":12,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"9614를 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"9000 + 600 + 10 + 4","correct":true},{"t":"9 + 6 + 1 + 4","mis":"M2-2-u1-X09"},{"t":"9000 + 100 + 60 + 4","mis":"M2-2-u1-X08"}],"explanation":["9614는 천의 자리 9, 백의 자리 6, 십의 자리 1, 일의 자리 4예요.","각 자리의 값은 9000, 600, 10, 4 — 9614 = 9000 + 600 + 10 + 4.","숫자 하나하나에 자리 값을 붙여야 해요."],"variant_rule":{"pv4":{"ask":"expand"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#13','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C5',2,'mc','auto','얼마씩 뛰어 세었나요?',ARRAY['M2-2-u1-X12']::text[],true,'{"seq":13,"concept":"M2-2-u1-C5","difficulty":2,"kind":"mc","stem":"얼마씩 뛰어 세었나요?","options":[{"t":"10씩","correct":true},{"t":"1000씩","mis":"M2-2-u1-X12"},{"t":"100씩","mis":"M2-2-u1-X12"}],"explanation":["3470, 3480, 3490 … 하고 십의 자리 숫자만 1씩 커져요.","그래서 10씩 뛰어 세었어요.","어느 자리 숫자가 바뀌는지 보면 몇씩 뛰었는지 알 수 있어요."],"asset":{"type":"jump_row","cells":[3470,3480,3490,3500,3510],"step":null},"variant_rule":{"skip4":{"ask":"step","step":[1,10,100,1000],"dir":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#14','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C6',2,'mc','auto','두 수의 크기를 바르게 비교한 것은 어느 것인가요?',ARRAY['M2-2-u1-X14']::text[],true,'{"seq":14,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"두 수의 크기를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"8150 < 8510","correct":true},{"t":"8150 > 8510","mis":"M2-2-u1-X14"}],"explanation":["백의 자리에서 처음으로 달라요 — 5는 1보다 커요.","그래서 8510은 8150보다 커요 — 8150 < 8510.","> 와 < 는 벌어진 쪽이 큰 수를 향해요."],"variant_rule":{"cmp4d":{"ask":"sign"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#15','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C2',2,'error','auto','친구들이 몇천에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u1-X03','M2-2-u1-X07','M2-2-u1-X12']::text[],false,'{"seq":15,"concept":"M2-2-u1-C2","difficulty":2,"kind":"error","stem":"친구들이 몇천에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호: 천 모형 8개는 800이야.","correct":true,"mis_target":"M2-2-u1-X03"},{"t":"하윤: 8000은 「팔천」이라고 읽어.","mis":"M2-2-u1-X07"},{"t":"시우: 8000은 9000보다 1000 작은 수야.","mis":"M2-2-u1-X12"}],"explanation":["천 모형 8개는 1000이 8개 — 8000이에요.","800은 백 모형 8개예요.","지호가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#16','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C7',2,'mc','auto','100이 17개인 수는 얼마인가요?',ARRAY['M2-2-u1-X02','M2-2-u1-X10']::text[],true,'{"seq":16,"concept":"M2-2-u1-C7","difficulty":2,"kind":"mc","stem":"100이 17개인 수는 얼마인가요?","options":[{"t":"1700","correct":true},{"t":"10017","mis":"M2-2-u1-X02"},{"t":"170","mis":"M2-2-u1-X10"}],"explanation":["100이 10개면 1000이에요.","100이 17개는 1000이 1개, 100이 7개 — 1700이에요.","100이 10개 넘게 모이면 1000으로 바꿔 세요."],"variant_rule":{"n4":{"ask":"hund"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#17','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C5',3,'mc','auto','100씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X01','M2-2-u1-X11']::text[],true,'{"seq":17,"concept":"M2-2-u1-C5","difficulty":3,"kind":"mc","stem":"100씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"6900","correct":true},{"t":"7900","mis":"M2-2-u1-X01"},{"t":"6999","mis":"M2-2-u1-X11"}],"explanation":["100씩 거꾸로 뛰면 백의 자리 숫자가 1씩 작아져요.","7000에서 100만큼 거꾸로 뛰면 6900이에요.","백의 자리가 0에서 더 작아지면 바로 윗자리에서 1을 빌려 와요."],"asset":{"type":"jump_row","cells":[7200,7100,7000,null,6800],"step":100,"dir":"down"},"variant_rule":{"skip4":{"ask":"blank","step":[100],"cross":true,"dir":"down"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#18','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C6',3,'mc','auto','7500, 6990, 6570 가운데 가장 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],true,'{"seq":18,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"7500, 6990, 6570 가운데 가장 큰 수는 무엇인가요?","options":[{"t":"7500","correct":true},{"t":"6990","mis":"M2-2-u1-X13"},{"t":"6570","mis":"M2-2-u1-X15"}],"explanation":["높은 자리(천의 자리)부터 차례로 견주어요.","가장 큰 수는 7500이에요.","뒤쪽 숫자가 크다고 큰 수가 아니에요 — 높은 자리가 먼저예요."],"variant_rule":{"cmp4d":{"ask":"max3"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#19','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C7',3,'mc','auto','돈은 모두 얼마인가요?',ARRAY['M2-2-u1-X10']::text[],true,'{"seq":19,"concept":"M2-2-u1-C7","difficulty":3,"kind":"mc","stem":"돈은 모두 얼마인가요?","options":[{"t":"2400원","correct":true},{"t":"11400원","mis":"M2-2-u1-X10"},{"t":"1400원","mis":"M2-2-u1-X10"}],"explanation":["100원짜리 14개는 천 원짜리 1장과 100원짜리 4개로 바꿀 수 있어요.","천 원짜리 2장, 100원짜리 4개 — 2400원이에요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks4","th":1,"h":14,"t":0,"o":0,"unit":"coin"},"variant_rule":{"n4":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#20','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C3',3,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X10']::text[],true,'{"seq":20,"concept":"M2-2-u1-C3","difficulty":3,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"3137","correct":true},{"t":"21137","mis":"M2-2-u1-X10"},{"t":"2137","mis":"M2-2-u1-X10"}],"explanation":["백 모형 11개는 천 모형 1개와 백 모형 1개로 바꿀 수 있어요.","1000이 3개, 100이 1개, 10이 3개, 1이 7개 — 3137이에요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks4","th":2,"h":11,"t":3,"o":7},"variant_rule":{"n4":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#21','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C4',3,'ox','auto','8580에서 두 숫자 8이 나타내는 값을 모으면 16이에요.',ARRAY['M2-2-u1-X09']::text[],false,'{"seq":21,"concept":"M2-2-u1-C4","difficulty":3,"kind":"ox","stem":"8580에서 두 숫자 8이 나타내는 값을 모으면 16이에요.","answer":"X","reason_options":[{"t":"8000과 80을 모으면 8080이니까","correct":true},{"t":"8과 8을 모으면 16이니까","mis":"M2-2-u1-X09"}],"mis":"M2-2-u1-X09","explanation":["앞의 8은 8000, 뒤의 8은 80을 나타내요.","8000과 80을 모으면 8080이에요.","그래서 틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#22','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C6',3,'mc','auto','수 카드 7, 1, 4, 6을 한 번씩 모두 써서 만들 수 있는 가장 작은 네 자리 수는 무엇인가요?',ARRAY['M2-2-u1-X16','M2-2-u1-X15']::text[],true,'{"seq":22,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"수 카드 7, 1, 4, 6을 한 번씩 모두 써서 만들 수 있는 가장 작은 네 자리 수는 무엇인가요?","options":[{"t":"1467","correct":true},{"t":"1476","mis":"M2-2-u1-X16"},{"t":"7641","mis":"M2-2-u1-X15"}],"explanation":["가장 작은 1을 천의 자리에 놓아요.","남은 카드도 작은 수부터 — 1467이에요.","높은 자리일수록 작은 숫자를 놓아요."],"variant_rule":{"cards4":{"ask":"min"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#23','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C7',4,'mc','auto','100원짜리 동전 47개를 천 원짜리와 100원짜리로 바꾸어 돈의 개수를 가장 적게 하면 지폐와 동전은 모두 몇 개인가요?',ARRAY['M2-2-u1-X10','M2-2-u1-X15']::text[],false,'{"seq":23,"concept":"M2-2-u1-C7","difficulty":4,"kind":"mc","stem":"100원짜리 동전 47개를 천 원짜리와 100원짜리로 바꾸어 돈의 개수를 가장 적게 하면 지폐와 동전은 모두 몇 개인가요?","options":[{"t":"11","correct":true},{"t":"47","mis":"M2-2-u1-X10"},{"t":"4","mis":"M2-2-u1-X15"}],"explanation":["100원짜리 47개는 4700원 — 천 원짜리 4장과 100원짜리 7개로 바꿀 수 있어요.","지폐 4장과 동전 7개, 모두 11개예요.","묻는 것은 지폐와 동전 「모두」의 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#24','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C6',4,'mc','auto','73□9는 7339보다 작아요. □에 들어갈 수 있는 수는 모두 몇 개인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],false,'{"seq":24,"concept":"M2-2-u1-C6","difficulty":4,"kind":"mc","stem":"73□9는 7339보다 작아요. □에 들어갈 수 있는 수는 모두 몇 개인가요?","options":[{"t":"3","correct":true},{"t":"4","mis":"M2-2-u1-X13"},{"t":"6","mis":"M2-2-u1-X15"}],"explanation":["천·백의 자리가 같으니 십의 자리를 견주어요.","□가 3이면 7339와 같아요. □는 0, 1, 2예요.","그래서 모두 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#25','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C5',4,'essay','teacher','6200부터 100씩 거꾸로 4번 뛰어 센 수를 차례로 쓰고, 자리가 바뀌는 곳을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u1-C5","difficulty":4,"kind":"essay","stem":"6200부터 100씩 거꾸로 4번 뛰어 센 수를 차례로 쓰고, 자리가 바뀌는 곳을 설명해 보세요.","answer_guide":{"answer":"6100, 6000, 5900, 5800. 6000에서 100 작아질 때 백의 자리가 0이라 천의 자리에서 1을 빌려 와 5900이 된다.","scoring_points":["뛰어 센 수를 차례로 바르게 썼는가","자리가 넘어가는(바뀌는) 곳을 설명했는가","몇씩 뛰었는지에 맞는 자리만 바뀐다는 것을 말했는가"]},"explanation":["뛰는 자리 숫자만 1씩 바뀌어요.","그 자리가 10이 되면 윗자리로 넘어가고, 0에서 더 작아지면 윗자리에서 빌려 와요.","숫자를 이어 붙이지 않고 자리를 넘겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#1','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C1',1,'mc','auto','990보다 10만큼 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X01','M2-2-u1-X12']::text[],false,'{"seq":1,"concept":"M2-2-u1-C1","difficulty":1,"kind":"mc","stem":"990보다 10만큼 더 큰 수는 무엇인가요?","options":[{"t":"1000","correct":true},{"t":"9910","mis":"M2-2-u1-X01"},{"t":"991","mis":"M2-2-u1-X12"}],"explanation":["990에서 10을 더 뛰어요.","990보다 10 큰 수는 1000이에요.","얼마만큼 큰지 잘 세어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#2','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C2',1,'mc','auto','1000이 9개이면 얼마인가요?',ARRAY['M2-2-u1-X03']::text[],true,'{"seq":2,"concept":"M2-2-u1-C2","difficulty":1,"kind":"mc","stem":"1000이 9개이면 얼마인가요?","options":[{"t":"9000","correct":true},{"t":"1009","mis":"M2-2-u1-X03"},{"t":"900","mis":"M2-2-u1-X03"}],"explanation":["1000이 9개이면 9000이에요.","「구천」이라고 읽어요.","개수는 천의 자리에 쓰고, 백·십·일의 자리는 0이에요."],"variant_rule":{"n4":{"ask":"thou"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#3','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C3',1,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X06','M2-2-u1-X05']::text[],true,'{"seq":3,"concept":"M2-2-u1-C3","difficulty":1,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"4736","correct":true},{"t":"6374","mis":"M2-2-u1-X06"},{"t":"4000700306","mis":"M2-2-u1-X05"}],"explanation":["1000이 4개, 100이 7개, 10이 3개, 1이 6개예요.","천의 자리 4, 백의 자리 7, 십의 자리 3, 일의 자리 6 — 4736이에요.","천·백·십·일 차례로 숫자를 써요."],"asset":{"type":"blocks4","th":4,"h":7,"t":3,"o":6},"variant_rule":{"n4":{"ask":"build"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#4','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C3',1,'match','auto','수와 읽기를 바르게 이어 보세요.','{}'::text[],false,'{"seq":4,"concept":"M2-2-u1-C3","difficulty":1,"kind":"match","stem":"수와 읽기를 바르게 이어 보세요.","pairs":[{"l":"4105","r":"사천백오"},{"l":"4015","r":"사천십오"},{"l":"4150","r":"사천백오십"}],"mis":"M2-2-u1-X07","explanation":["4105는 「사천백오」예요.","4015는 「사천십오」, 4150은 「사천백오십」이에요.","0인 자리는 읽지 않고, 숫자 뒤에 자리 이름을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#5','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C4',1,'mc','auto','9273에서 십의 자리 숫자는 무엇인가요?',ARRAY['M2-2-u1-X08','M2-2-u1-X09']::text[],true,'{"seq":5,"concept":"M2-2-u1-C4","difficulty":1,"kind":"mc","stem":"9273에서 십의 자리 숫자는 무엇인가요?","options":[{"t":"7","correct":true},{"t":"2","mis":"M2-2-u1-X08"},{"t":"70","mis":"M2-2-u1-X09"}],"explanation":["9273은 천의 자리 9, 백의 자리 2, 십의 자리 7, 일의 자리 3이에요.","십의 자리 숫자는 7이에요.","자리는 왼쪽부터 천·백·십·일 — 숫자를 물으면 값이 아니라 숫자 하나로 답해요."],"variant_rule":{"pv4":{"ask":"digit"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#6','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C5',1,'mc','auto','10씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X11']::text[],true,'{"seq":6,"concept":"M2-2-u1-C5","difficulty":1,"kind":"mc","stem":"10씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"1790","correct":true},{"t":"1880","mis":"M2-2-u1-X11"},{"t":"2780","mis":"M2-2-u1-X11"}],"explanation":["10씩 뛰면 십의 자리 숫자가 1씩 커져요.","1780에서 10만큼 뛰면 1790이에요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[1750,1760,1770,1780,null],"step":10},"variant_rule":{"skip4":{"ask":"next","step":[10]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#7','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C6',1,'mc','auto','3460과 3640 중에서 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13']::text[],true,'{"seq":7,"concept":"M2-2-u1-C6","difficulty":1,"kind":"mc","stem":"3460과 3640 중에서 더 큰 수는 무엇인가요?","options":[{"t":"3640","correct":true},{"t":"3460","mis":"M2-2-u1-X13"}],"explanation":["천의 자리가 같아요.","백의 자리를 보면 6은 4보다 커요 — 더 큰 수는 3640이에요.","높은 자리가 다르면 낮은 자리는 보지 않아도 돼요."],"variant_rule":{"cmp4d":{"ask":"big","same":"th"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#8','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C2',1,'sa','auto','2000은 1000이 몇 개인가요?','{}'::text[],true,'{"seq":8,"concept":"M2-2-u1-C2","difficulty":1,"kind":"sa","stem":"2000은 1000이 몇 개인가요?","answer":["2","2개"],"explanation":["2000은 천의 자리 숫자가 2예요.","1000이 2개예요.","천의 자리 숫자가 1000의 개수예요."],"variant_rule":{"n4":{"ask":"tcount"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#9','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C1',2,'blank','auto','1000은 980보다 (        )만큼 더 큰 수예요.',ARRAY['M2-2-u1-X12']::text[],false,'{"seq":9,"concept":"M2-2-u1-C1","difficulty":2,"kind":"blank","stem":"1000은 980보다 (        )만큼 더 큰 수예요.","options":[{"t":"20","correct":true},{"t":"2","mis":"M2-2-u1-X12"},{"t":"10","mis":"M2-2-u1-X12"}],"explanation":["980, 990, 1000 — 10씩 두 번 뛰어요.","그래서 1000은 980보다 20 커요.","10씩 몇 번 뛰었는지 세어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#10','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C3',2,'mc','auto','「오천삼백」을 수로 쓰면 무엇인가요?',ARRAY['M2-2-u1-X05','M2-2-u1-X04']::text[],true,'{"seq":10,"concept":"M2-2-u1-C3","difficulty":2,"kind":"mc","stem":"「오천삼백」을 수로 쓰면 무엇인가요?","options":[{"t":"5300","correct":true},{"t":"5000300","mis":"M2-2-u1-X05"},{"t":"53","mis":"M2-2-u1-X04"}],"explanation":["「오천삼백」은 1000이 5개, 100이 3개, 10이 0개, 1이 0개예요.","수로 쓰면 5300이에요.","읽지 않은 자리에는 0을 써요."],"variant_rule":{"n4":{"ask":"write","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#11','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C4',2,'mc','auto','6957에서 숫자 9가 나타내는 값은 얼마인가요?',ARRAY['M2-2-u1-X08','M2-2-u1-X09']::text[],true,'{"seq":11,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"6957에서 숫자 9가 나타내는 값은 얼마인가요?","options":[{"t":"900","correct":true},{"t":"9000","mis":"M2-2-u1-X08"},{"t":"9","mis":"M2-2-u1-X09"}],"explanation":["숫자 9는 백의 자리에 있어요.","백의 자리 9는 900을 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"variant_rule":{"pv4":{"ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#12','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C4',2,'mc','auto','2375를 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],true,'{"seq":12,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"2375를 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"2000 + 300 + 70 + 5","correct":true},{"t":"2 + 3 + 7 + 5","mis":"M2-2-u1-X09"},{"t":"2000 + 700 + 30 + 5","mis":"M2-2-u1-X08"}],"explanation":["2375는 천의 자리 2, 백의 자리 3, 십의 자리 7, 일의 자리 5예요.","각 자리의 값은 2000, 300, 70, 5 — 2375 = 2000 + 300 + 70 + 5.","숫자 하나하나에 자리 값을 붙여야 해요."],"variant_rule":{"pv4":{"ask":"expand"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#13','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C5',2,'mc','auto','얼마씩 거꾸로 뛰어 세었나요?',ARRAY['M2-2-u1-X12']::text[],true,'{"seq":13,"concept":"M2-2-u1-C5","difficulty":2,"kind":"mc","stem":"얼마씩 거꾸로 뛰어 세었나요?","options":[{"t":"1씩","correct":true},{"t":"1000씩","mis":"M2-2-u1-X12"},{"t":"100씩","mis":"M2-2-u1-X12"}],"explanation":["6804, 6803, 6802 … 하고 일의 자리 숫자만 1씩 작아져요.","그래서 1씩 거꾸로 뛰어 세었어요.","어느 자리 숫자가 바뀌는지 보면 몇씩 뛰었는지 알 수 있어요."],"asset":{"type":"jump_row","cells":[6804,6803,6802,6801,6800],"step":null,"dir":"down"},"variant_rule":{"skip4":{"ask":"step","step":[1,10,100,1000],"dir":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#14','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C6',2,'mc','auto','두 수의 크기를 바르게 비교한 것은 어느 것인가요?',ARRAY['M2-2-u1-X14']::text[],true,'{"seq":14,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"두 수의 크기를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"2999 < 3001","correct":true},{"t":"2999 > 3001","mis":"M2-2-u1-X14"}],"explanation":["천의 자리에서 처음으로 달라요 — 3은 2보다 커요.","그래서 3001은 2999보다 커요 — 2999 < 3001.","> 와 < 는 벌어진 쪽이 큰 수를 향해요."],"variant_rule":{"cmp4d":{"ask":"sign"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#15','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C2',2,'error','auto','친구들이 몇천에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u1-X03','M2-2-u1-X07','M2-2-u1-X12']::text[],false,'{"seq":15,"concept":"M2-2-u1-C2","difficulty":2,"kind":"error","stem":"친구들이 몇천에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온: 6000은 1000이 60개야.","correct":true,"mis_target":"M2-2-u1-X03"},{"t":"나은: 6000은 「육천」이라고 읽어.","mis":"M2-2-u1-X07"},{"t":"세아: 6000은 5000보다 1000 큰 수야.","mis":"M2-2-u1-X12"}],"explanation":["6000은 천의 자리 숫자가 6이에요.","그래서 1000이 6개예요 — 60개가 아니에요.","라온이가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#16','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C7',2,'mc','auto','100이 45개인 수는 얼마인가요?',ARRAY['M2-2-u1-X02','M2-2-u1-X10']::text[],true,'{"seq":16,"concept":"M2-2-u1-C7","difficulty":2,"kind":"mc","stem":"100이 45개인 수는 얼마인가요?","options":[{"t":"4500","correct":true},{"t":"10045","mis":"M2-2-u1-X02"},{"t":"450","mis":"M2-2-u1-X10"}],"explanation":["100이 10개면 1000이에요.","100이 45개는 1000이 4개, 100이 5개 — 4500이에요.","100이 10개 넘게 모이면 1000으로 바꿔 세요."],"variant_rule":{"n4":{"ask":"hund"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#17','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C5',3,'mc','auto','1씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X01','M2-2-u1-X11']::text[],true,'{"seq":17,"concept":"M2-2-u1-C5","difficulty":3,"kind":"mc","stem":"1씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"3999","correct":true},{"t":"4009","mis":"M2-2-u1-X01"},{"t":"3990","mis":"M2-2-u1-X11"}],"explanation":["1씩 거꾸로 뛰면 일의 자리 숫자가 1씩 작아져요.","4000에서 1만큼 거꾸로 뛰면 3999예요.","일의 자리가 0에서 더 작아지면 바로 윗자리에서 1을 빌려 와요."],"asset":{"type":"jump_row","cells":[4002,4001,4000,null,3998],"step":1,"dir":"down"},"variant_rule":{"skip4":{"ask":"blank","step":[1],"cross":true,"dir":"down"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#18','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C6',3,'mc','auto','5990, 6020, 6110 가운데 가장 작은 수는 무엇인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],true,'{"seq":18,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"5990, 6020, 6110 가운데 가장 작은 수는 무엇인가요?","options":[{"t":"5990","correct":true},{"t":"6020","mis":"M2-2-u1-X13"},{"t":"6110","mis":"M2-2-u1-X15"}],"explanation":["높은 자리(천의 자리)부터 차례로 견주어요.","가장 작은 수는 5990이에요.","뒤쪽 숫자가 크다고 큰 수가 아니에요 — 높은 자리가 먼저예요."],"variant_rule":{"cmp4d":{"ask":"min3"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#19','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C7',3,'mc','auto','돈은 모두 얼마인가요?',ARRAY['M2-2-u1-X10']::text[],true,'{"seq":19,"concept":"M2-2-u1-C7","difficulty":3,"kind":"mc","stem":"돈은 모두 얼마인가요?","options":[{"t":"4920원","correct":true},{"t":"48120원","mis":"M2-2-u1-X10"},{"t":"4820원","mis":"M2-2-u1-X10"}],"explanation":["10원짜리 12개는 100원짜리 1개와 10원짜리 2개로 바꿀 수 있어요.","천 원짜리 4장, 100원짜리 9개, 10원짜리 2개 — 4920원이에요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks4","th":4,"h":8,"t":12,"o":0,"unit":"coin"},"variant_rule":{"n4":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#20','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C3',3,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X10']::text[],true,'{"seq":20,"concept":"M2-2-u1-C3","difficulty":3,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"5643","correct":true},{"t":"56313","mis":"M2-2-u1-X10"},{"t":"5633","mis":"M2-2-u1-X10"}],"explanation":["일 모형 13개는 십 모형 1개와 일 모형 3개로 바꿀 수 있어요.","1000이 5개, 100이 6개, 10이 4개, 1이 3개 — 5643이에요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks4","th":5,"h":6,"t":3,"o":13},"variant_rule":{"n4":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#21','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C4',3,'ox','auto','6262에서 두 숫자 2가 나타내는 값은 200과 2예요.',ARRAY['M2-2-u1-X09']::text[],false,'{"seq":21,"concept":"M2-2-u1-C4","difficulty":3,"kind":"ox","stem":"6262에서 두 숫자 2가 나타내는 값은 200과 2예요.","answer":"O","reason_options":[{"t":"백의 자리 2는 200, 일의 자리 2는 2니까","correct":true},{"t":"같은 숫자는 값도 같으니까","mis":"M2-2-u1-X09"}],"mis":"M2-2-u1-X09","explanation":["앞의 2는 백의 자리라 200이에요.","끝의 2는 일의 자리라 2예요.","그래서 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#22','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C6',3,'mc','auto','수 카드 0, 8, 4, 1을 한 번씩 모두 써서 만들 수 있는 가장 큰 네 자리 수는 무엇인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X16']::text[],true,'{"seq":22,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"수 카드 0, 8, 4, 1을 한 번씩 모두 써서 만들 수 있는 가장 큰 네 자리 수는 무엇인가요?","options":[{"t":"8410","correct":true},{"t":"1048","mis":"M2-2-u1-X15"},{"t":"8401","mis":"M2-2-u1-X16"}],"explanation":["가장 큰 8을 천의 자리에 놓아요.","남은 카드도 큰 수부터 — 8410이에요.","높은 자리일수록 큰 숫자를 놓아요."],"variant_rule":{"cards4":{"ask":"max","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#23','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C7',4,'mc','auto','천 원짜리 5장과 100원짜리 동전 6개를 모두 100원짜리 동전으로 바꾸면 몇 개가 되나요?',ARRAY['M2-2-u1-X03','M2-2-u1-X04']::text[],false,'{"seq":23,"concept":"M2-2-u1-C7","difficulty":4,"kind":"mc","stem":"천 원짜리 5장과 100원짜리 동전 6개를 모두 100원짜리 동전으로 바꾸면 몇 개가 되나요?","options":[{"t":"56","correct":true},{"t":"11","mis":"M2-2-u1-X03"},{"t":"506","mis":"M2-2-u1-X04"}],"explanation":["천 원짜리 한 장은 100원짜리 10개예요.","천 원짜리 5장은 100원짜리 50개 — 6개를 더하면 56개예요.","5600원은 100이 56개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#24','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C6',4,'mc','auto','2□56은 2855보다 커요. □에 들어갈 수 있는 수는 모두 몇 개인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],false,'{"seq":24,"concept":"M2-2-u1-C6","difficulty":4,"kind":"mc","stem":"2□56은 2855보다 커요. □에 들어갈 수 있는 수는 모두 몇 개인가요?","options":[{"t":"2","correct":true},{"t":"1","mis":"M2-2-u1-X13"},{"t":"7","mis":"M2-2-u1-X15"}],"explanation":["천의 자리는 2로 같으니 백의 자리를 견주어요.","□가 8이면 2856 — 2855보다 커요. □는 8, 9예요.","그래서 모두 2개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#25','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C5',4,'essay','teacher','8003부터 1씩 거꾸로 5번 뛰어 센 수를 차례로 쓰고, 자리가 바뀌는 곳을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u1-C5","difficulty":4,"kind":"essay","stem":"8003부터 1씩 거꾸로 5번 뛰어 센 수를 차례로 쓰고, 자리가 바뀌는 곳을 설명해 보세요.","answer_guide":{"answer":"8002, 8001, 8000, 7999, 7998. 8000에서 1 작아질 때 일·십·백의 자리가 0이라 천의 자리에서 빌려 와 7999가 된다.","scoring_points":["뛰어 센 수를 차례로 바르게 썼는가","자리가 넘어가는(바뀌는) 곳을 설명했는가","몇씩 뛰었는지에 맞는 자리만 바뀐다는 것을 말했는가"]},"explanation":["뛰는 자리 숫자만 1씩 바뀌어요.","그 자리가 10이 되면 윗자리로 넘어가고, 0에서 더 작아지면 윗자리에서 빌려 와요.","숫자를 이어 붙이지 않고 자리를 넘겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C1','math',2,2,'u2',2,'2단 곱셈구구 — 한 묶음이 2씩 늘어나는 상황을 곱셈식으로 나타내고, 2 × 5를 2씩 5번 더하기와 2 × 4에 2 더하기로 구하며, 곱하는 수가 1 커지면 곱이 2씩 커짐을 알기',ARRAY['2수01-10']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C2','math',2,2,'u2',3,'5단 곱셈구구 — 5씩 커지는 원리로 5단을 완성하고, 곱의 일의 자리 숫자가 5, 0으로 되풀이되는 규칙을 찾기',ARRAY['2수01-10']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C3','math',2,2,'u2',4,'3단·6단 곱셈구구 — 3씩·6씩 커지는 원리로 3단과 6단을 완성하고, 6 × 5를 5 × 6처럼 다르게 묶어 구하며, 6단의 곱이 3단의 곱의 2배임을 알기',ARRAY['2수01-10']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C4','math',2,2,'u2',5,'4단·8단 곱셈구구 — 4씩·8씩 커지는 원리로 4단과 8단을 완성하고, 8 × 6을 8 × 3 두 번 더하기 등 여러 방법으로 구하며, 8단의 곱이 4단의 곱의 2배임을 알기',ARRAY['2수01-10']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C5','math',2,2,'u2',6,'7단 곱셈구구 — 수직선에서 7씩 뛰어 세고, 7 × 5를 7 × 3과 7 × 2로 나누어 구하며, 7 × 6을 7 × 5에 7 더하기와 6 × 7로 구해 7단을 완성하기',ARRAY['2수01-10']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C6','math',2,2,'u2',7,'9단 곱셈구구 — 9씩 커지는 원리로 9단을 완성하고, 9 × 5를 9 × 2와 9 × 3의 곱을 더해 구하며, 곱의 두 숫자의 합이 9인 규칙을 찾기',ARRAY['2수01-10']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C7','math',2,2,'u2',8,'1단 곱셈구구와 0의 곱 — 1과 어떤 수의 곱은 그 수, 0과 어떤 수의 곱과 어떤 수와 0의 곱은 0임을 알고 점수 상황에 쓰기',ARRAY['2수01-10']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C8','math',2,2,'u2',9,'곱셈표 — 가로줄과 세로줄의 수가 만나는 칸에 곱을 써서 곱셈표를 만들고, 단마다 곱이 그 단의 수만큼 커지는 원리로 빈칸을 채우며, 두 수를 바꾸어 곱해도 곱이 같고 곱이 같은 곱셈구구가 여럿일 수 있음을 알기',ARRAY['2수01-10']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C9','math',2,2,'u2',10,'곱셈구구로 문제 해결하기 — 생활 속 물건의 수를 곱셈구구로 구하고, 빈자리가 있거나 두 덩이로 된 배열은 나누어 곱한 뒤 더하거나 빼서 구하기',ARRAY['2수01-10']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C10','math',2,2,'u2',12,'곱셈구구 속 규칙 찾기 — 곱의 일의 자리 숫자를 차례로 이어 단마다 생기는 무늬를 찾고, 다른 단인데 같은 무늬가 나오는 까닭을 말하기',ARRAY['2수01-10']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X01','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C2','M2-2-u2-C3','M2-2-u2-C4','M2-2-u2-C5','M2-2-u2-C6']::text[],'곱하는 수가 1 커지면 곱도 1 커진다고 여긴다(2 × 5를 2 × 4보다 1 크다고 봄)','곱하는 수가 1 커지면 그 단의 수를 한 번 더 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X02','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C2','M2-2-u2-C3','M2-2-u2-C4','M2-2-u2-C5','M2-2-u2-C6','M2-2-u2-C8']::text[],'곱셈구구의 곱을 이웃 곱(한 번 더·덜 뛴 값)과 헷갈리거나 뛰어 세기를 한 번 더·덜 한다','뛸 때마다 손가락을 하나씩 접어 곱하는 수만큼 뛰었는지 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X03','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C9']::text[],'그림에서 묶음이나 줄의 수를 하나 더·덜 센다','묶음·줄마다 번호를 붙이며 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X04','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C9']::text[],'「몇씩」(한 묶음·한 줄의 수)과 「몇 묶음·몇 줄」을 뒤바꾸어 곱셈식을 쓴다','× 앞에는 한 묶음의 수, 뒤에는 묶음의 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X05','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C7','M2-2-u2-C9']::text[],'묻는 것 대신 곱하는 수·묶음 수·맞힌 횟수 같은 다른 수를 답으로 쓴다','물음이 「모두 몇」인지 「몇 번·몇 묶음」인지 밑줄 긋기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X06','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C2','M2-2-u2-C3','M2-2-u2-C4','M2-2-u2-C5','M2-2-u2-C6','M2-2-u2-C7','M2-2-u2-C9']::text[],'곱셈구구를 두 수를 더하거나 빼서 구한다(2 × 5 = 7)','두 수를 더하지 말고 앞의 수를 뒤의 수만큼 여러 번 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X08','math',2,'u2',ARRAY['M2-2-u2-C7']::text[],'0이나 1을 곱할 때 0의 곱을 그 수로(3 × 0 = 3), 1의 곱을 1로(1 × 5 = 1) 여기거나, 한 번도 못 맞힌 점수를 그 점수로 센다','0번 더하면 아무것도 없어 0, 1을 몇 번 더하면 그 횟수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X09','math',2,'u2',ARRAY['M2-2-u2-C8']::text[],'곱셈표에서 가로줄·세로줄을 잘못 짚어 이웃 칸을 읽거나 줄과 칸을 뒤바꾼다','왼쪽 수와 위쪽 수를 손가락 두 개로 짚어 만나는 칸 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X10','math',2,'u2',ARRAY['M2-2-u2-C3','M2-2-u2-C4']::text[],'단과 단 사이의 관계를 모른다 — 6단을 3단과, 8단을 4단과 따로 외우거나, 같은 수를 곱할 때 6단의 곱이 3단의 곱의 2배임을 모른다','3씩 2묶음이 6, 4씩 2묶음이 8 — 묶음을 두 개씩 합쳐 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X11','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C9']::text[],'× 를 + 로 여기거나 곱셈식을 잘못 읽는다','× 는 「곱하기」 — 앞의 수를 뒤의 수만큼 여러 번 더한 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X13','math',2,'u2',ARRAY['M2-2-u2-C3','M2-2-u2-C5','M2-2-u2-C7','M2-2-u2-C8']::text[],'두 수를 바꾸어 곱해도 곱이 같다는 것을 모르거나, 곱이 같은 곱셈구구를 하나만 찾는다(24 = 3 × 8 = 4 × 6을 놓침)','곱셈표를 점선을 따라 접어 만나는 칸, 같은 곱이 나오는 다른 단 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X14','math',2,'u2',ARRAY['M2-2-u2-C9']::text[],'생활 속 상황에서 한 묶음의 수와 묶음의 수를 잘못 잡는다(다리 수와 마리 수를 헷갈림)','「한 ○에 몇 개씩」이 한 묶음, 「○가 몇」이 묶음 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X15','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C2','M2-2-u2-C3','M2-2-u2-C4','M2-2-u2-C5','M2-2-u2-C6','M2-2-u2-C7','M2-2-u2-C8','M2-2-u2-C9','M2-2-u2-C10']::text[],'묻는 말을 거꾸로 읽는다 — 아닌 것↔맞는 것, 잘못된↔바른','물음의 「아닌·잘못된」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X16','math',2,'u2',ARRAY['M2-2-u2-C2','M2-2-u2-C6','M2-2-u2-C8','M2-2-u2-C10']::text[],'곱의 규칙(5단 일의 자리 5·0, 9단 두 숫자의 합 9, 일의 자리 무늬)을 곱하는 수의 규칙과 헷갈리거나 곱 전체를 이어 잘못 찾는다','곱을 차례로 쓰고 일의 자리·십의 자리 숫자에 따로 동그라미 치기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X17','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C2','M2-2-u2-C3','M2-2-u2-C4','M2-2-u2-C5','M2-2-u2-C6','M2-2-u2-C9']::text[],'한 번 더 더하기·나누어 구하기에서 곱하는 수를 더하거나(2 × 4 + 5) 두 곱 대신 두 수만 더한다(9 × 2와 9 × 3에서 2 + 3)','한 번 더 더할 때는 그 단의 수를, 나누어 구할 때는 두 곱을 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X18','math',2,'u2',ARRAY['M2-2-u2-C9']::text[],'줄 맞춰 놓이지 않은 배열(빈자리·두 덩이·낱개)에서 빈자리를 빼지 않거나 한 덩이·낱개를 빠뜨린다','빈자리에 ×, 덩이마다 색을 다르게 칠하고 따로 구하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X19','math',2,'u2',ARRAY['M2-2-u2-C3','M2-2-u2-C4','M2-2-u2-C5','M2-2-u2-C6','M2-2-u2-C8','M2-2-u2-C9']::text[],'곱을 구하지 않고 앞의 수나 한 수만 보고 두 곱셈식의 크기를 견준다','두 곱셈식의 곱을 먼저 구해 옆에 쓰고 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_basic#1','math',2,2,'u2','L02','g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',1,'mc','auto','그림을 보세요. 쿠키는 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X05']::text[],true,'{"seq":1,"concept":"M2-2-u2-C1","difficulty":1,"kind":"mc","stem":"그림을 보세요. 쿠키는 모두 몇 개인가요?","explanation":["2개씩 4묶음이에요.","2씩 뛰어 세면 2, 4, 6, 8.","쿠키는 모두 8개예요."],"variant_rule":{"mul":{"ask":"total","ks":[2],"pmax":45}},"options":[{"t":"8개","correct":true},{"t":"6개","mis":"M2-2-u2-X06"},{"t":"4개","mis":"M2-2-u2-X05"}],"asset":{"type":"mul_groups","item":"🍪","k":2,"n":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_basic#2','math',2,2,'u2','L02','g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',1,'sa','auto','2씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u2-C1","difficulty":1,"kind":"sa","stem":"2씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["2씩 커지는 수예요.","8에서 2만큼 더 뛰면 10이에요.","2씩 5번 뛰어 센 수 — 2씩 5묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip","ks":[2],"pmax":45}},"answer":["10"],"asset":{"type":"jump_row","cells":[2,4,6,8,null],"step":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_basic#3','math',2,2,'u2','L02','g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',1,'mc','auto','로봇 한 대에 바퀴가 2개씩 있어요. 로봇이 한 대 더 늘어나면 바퀴는 몇 개 더 많아지나요?',ARRAY['M2-2-u2-X01','M2-2-u2-X02']::text[],true,'{"seq":3,"concept":"M2-2-u2-C1","difficulty":1,"kind":"mc","stem":"로봇 한 대에 바퀴가 2개씩 있어요. 로봇이 한 대 더 늘어나면 바퀴는 몇 개 더 많아지나요?","options":[{"t":"2개","correct":true},{"t":"1개","mis":"M2-2-u2-X01"},{"t":"4개","mis":"M2-2-u2-X02"}],"explanation":["로봇 한 대에 바퀴가 2개씩이에요.","로봇이 한 대 늘면 바퀴 2개가 더 생겨요.","그래서 2단 곱셈구구의 곱은 2씩 커져요."],"variant_rule":{"alt":[{"stem":"필통 한 개에 지우개가 2개씩 들어 있어요. 필통이 하나 더 늘어나면 지우개는 몇 개 더 많아지나요?","options":[{"t":"2개","correct":true},{"t":"1개","mis":"M2-2-u2-X01"},{"t":"3개","mis":"M2-2-u2-X02"}],"explanation":["필통 한 개에 지우개가 2개씩이에요.","필통이 하나 늘면 지우개 2개가 더 생겨요.","곱하는 수가 1 커지면 곱은 2 커져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_basic#4','math',2,2,'u2','L02','g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',1,'sa','auto','2 × 6은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M2-2-u2-C1","difficulty":1,"kind":"sa","stem":"2 × 6은 얼마인가요? 숫자로 쓰세요.","explanation":["2 × 6은 2의 6배예요.","2씩 뛰어 세면 2, 4, 6, 8, 10, 12.","그래서 2 × 6 = 12예요."],"variant_rule":{"mul":{"ask":"value","ks":[2],"pmax":81}},"answer":["12"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_basic#5','math',2,2,'u2','L02','g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',2,'mc','auto','2 × 4 = 8이에요. 이것을 이용하면 2 × 5는 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17','M2-2-u2-X02']::text[],true,'{"seq":5,"concept":"M2-2-u2-C1","difficulty":2,"kind":"mc","stem":"2 × 4 = 8이에요. 이것을 이용하면 2 × 5는 얼마인가요?","explanation":["2 × 5는 2 × 4보다 2만큼 더 커요.","8 + 2 = 10이에요.","한 번 더 더할 때는 곱하는 수 5가 아니라 2를 더해요."],"variant_rule":{"gugu":{"ask":"build","ks":[2]}},"options":[{"t":"10","correct":true},{"t":"9","mis":"M2-2-u2-X01"},{"t":"13","mis":"M2-2-u2-X17"},{"t":"12","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_basic#6','math',2,2,'u2','L02','g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',2,'ox','auto','2 × 6은 2 × 5보다 1 커요.',ARRAY['M2-2-u2-X01']::text[],true,'{"seq":6,"concept":"M2-2-u2-C1","difficulty":2,"kind":"ox","stem":"2 × 6은 2 × 5보다 1 커요.","answer":"X","reason_options":[{"t":"2를 한 번 더 더하니까 2 커져요","correct":true},{"t":"곱하는 수가 1 커졌으니 곱도 1 커지니까","mis":"M2-2-u2-X01"}],"mis":"M2-2-u2-X01","explanation":["2 × 5 = 10, 2 × 6 = 12예요.","2를 한 번 더 더했으니 2만큼 커졌어요.","곱하는 수가 1 커지면 2단의 곱은 2씩 커져요."],"variant_rule":{"alt":[{"stem":"2 × 8은 2 × 7보다 2 커요.","answer":"O","reason_options":[{"t":"2를 한 번 더 더하니까 14에서 16이 되니까","correct":true},{"t":"곱하는 수가 1 커지면 곱도 1 커지니까","mis":"M2-2-u2-X01"}],"explanation":["2 × 7 = 14, 2 × 8 = 16이에요.","2를 한 번 더 더해 2만큼 커졌어요.","그래서 바른 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_basic#7','math',2,2,'u2','L02','g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',2,'match','auto','곱셈식과 곱을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u2-C1","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 이으세요.","pairs":[{"l":"2 × 3","r":"6"},{"l":"2 × 7","r":"14"},{"l":"2 × 9","r":"18"}],"mis":"M2-2-u2-X02","explanation":["2 × 3은 2, 4, 6으로 6이에요.","2 × 7은 2씩 7번 뛰어 14예요.","2 × 9는 2씩 9번 뛰어 18이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 곱을 이으세요.","pairs":[{"l":"2 × 4","r":"8"},{"l":"2 × 6","r":"12"},{"l":"2 × 8","r":"16"}],"explanation":["2 × 4는 2, 4, 6, 8로 8이에요.","2 × 6은 2씩 6번 뛰어 12예요.","2 × 8은 2씩 8번 뛰어 16이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_basic#8','math',2,2,'u2','L02','g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',2,'mc','auto','로봇 한 대에 바퀴가 2개씩 있어요. 로봇 7대의 바퀴는 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X14']::text[],true,'{"seq":8,"concept":"M2-2-u2-C1","difficulty":2,"kind":"mc","stem":"로봇 한 대에 바퀴가 2개씩 있어요. 로봇 7대의 바퀴는 모두 몇 개인가요?","explanation":["로봇 한 대에 2개씩, 7대이면 2씩 7묶음이에요.","2 × 7 = 14예요.","바퀴는 모두 14개예요."],"variant_rule":{"mul":{"ask":"story","pmax":81,"per":[2]}},"options":[{"t":"14개","correct":true},{"t":"9개","mis":"M2-2-u2-X06"},{"t":"7개","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_basic#9','math',2,2,'u2','L02','g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',2,'mc','auto','2 × □ = 16에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02']::text[],true,'{"seq":9,"concept":"M2-2-u2-C1","difficulty":2,"kind":"mc","stem":"2 × □ = 16에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["2단 곱셈구구에서 곱이 16인 것을 찾아요.","2씩 뛰어 세면 2, 4, 6, 8, 10, 12, 14, 16 — 8번이에요.","2 × 8 = 16이라 □는 8이에요."],"variant_rule":{"gugu":{"ask":"miss","ks":[2]}},"options":[{"t":"8","correct":true},{"t":"9","mis":"M2-2-u2-X02"},{"t":"7","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_basic#10','math',2,2,'u2','L02','g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',3,'error','auto','2 × 5를 구하는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X15']::text[],true,'{"seq":10,"concept":"M2-2-u2-C1","difficulty":3,"kind":"error","stem":"2 × 5를 구하는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지우 — 「2 × 4 = 8에 5를 더하면 13이야.」","correct":true,"mis_target":"M2-2-u2-X17"},{"t":"서아 — 「2를 5번 더하면 10이야.」","mis":"M2-2-u2-X15"},{"t":"하루 — 「2 × 4 = 8에 2를 더하면 10이야.」","mis":"M2-2-u2-X15"}],"explanation":["2 × 5는 2 × 4보다 2만큼 커요.","지우는 2 대신 곱하는 수 5를 더했어요.","서아와 하루처럼 구하면 2 × 5 = 10이에요."],"variant_rule":{"alt":[{"stem":"2 × 7을 구하는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「2 × 6 = 12에 7을 더하면 19야.」","correct":true,"mis_target":"M2-2-u2-X17"},{"t":"은솔 — 「2씩 7번 뛰어 세면 14야.」","mis":"M2-2-u2-X15"},{"t":"예린 — 「2 × 6 = 12에 2를 더하면 14야.」","mis":"M2-2-u2-X15"}],"explanation":["2 × 7은 2 × 6보다 2만큼 커요.","도윤이는 2 대신 곱하는 수 7을 더했어요.","2 × 7 = 14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_challenge#1','math',2,2,'u2','L02','g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',2,'mc','auto','2 × 8은 2 × 7보다 얼마 더 큰가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17']::text[],true,'{"seq":1,"concept":"M2-2-u2-C1","difficulty":2,"kind":"mc","stem":"2 × 8은 2 × 7보다 얼마 더 큰가요?","explanation":["2 × 7은 2를 7번, 2 × 8은 2를 8번 더한 것이에요.","2를 한 번 더 더했으니 2만큼 더 커요 — 14에서 16.","곱하는 수가 1 커지면 곱은 2만큼 커져요."],"variant_rule":{"gugu":{"ask":"next","ks":[2]}},"options":[{"t":"2","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"8","mis":"M2-2-u2-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_challenge#2','math',2,2,'u2','L02','g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',2,'mc','auto','그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X03']::text[],true,'{"seq":2,"concept":"M2-2-u2-C1","difficulty":2,"kind":"mc","stem":"그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["한 줄에 2개씩 6줄이에요.","2의 6배이니 곱셈식으로 2 × 6이에요.","2 × 6 = 12, 모두 12개예요."],"variant_rule":{"mul":{"ask":"expr","look":"rows","ks":[2],"pmax":45}},"options":[{"t":"2 × 6","correct":true},{"t":"2 + 6","mis":"M2-2-u2-X11"},{"t":"2 × 7","mis":"M2-2-u2-X03"}],"asset":{"type":"mul_groups","item":"🍅","k":2,"n":6,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_challenge#3','math',2,2,'u2','L02','g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',3,'mc','auto','2단 곱셈구구의 곱이 아닌 것은 어느 것인가요?',ARRAY['M2-2-u2-X15']::text[],false,'{"seq":3,"concept":"M2-2-u2-C1","difficulty":3,"kind":"mc","stem":"2단 곱셈구구의 곱이 아닌 것은 어느 것인가요?","options":[{"t":"15","correct":true},{"t":"12","mis":"M2-2-u2-X15"},{"t":"16","mis":"M2-2-u2-X15"},{"t":"18","mis":"M2-2-u2-X15"}],"explanation":["2단 곱셈구구의 곱은 2, 4, 6, 8, 10, 12, 14, 16, 18이에요.","2씩 뛰어 센 수에 15는 없어요.","「아닌 것」을 묻는지 다시 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_challenge#4','math',2,2,'u2','L02','g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',3,'mc','auto','2 × 6을 구하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M2-2-u2-X15']::text[],false,'{"seq":4,"concept":"M2-2-u2-C1","difficulty":3,"kind":"mc","stem":"2 × 6을 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"2 × 5 = 10에 6을 더해요","correct":true},{"t":"2를 6번 더해요","mis":"M2-2-u2-X15"},{"t":"2 × 3 = 6을 두 번 더해요","mis":"M2-2-u2-X15"},{"t":"2 × 5 = 10에 2를 더해요","mis":"M2-2-u2-X15"}],"explanation":["2 × 6은 2를 6번 더한 12예요.","2 × 5에 더할 수는 6이 아니라 2예요 — 10 + 6 = 16은 틀려요.","2 × 3 = 6을 두 번 더해도 12예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_challenge#5','math',2,2,'u2','L02','g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',3,'mc','auto','□ × 7 = 14에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02','M2-2-u2-X06']::text[],true,'{"seq":5,"concept":"M2-2-u2-C1","difficulty":3,"kind":"mc","stem":"□ × 7 = 14에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["몇 단 곱셈구구에서 7번째 곱이 14인지 찾아요.","2 × 7 = 14예요 — 3 × 7 = 21이에요.","그래서 □는 2예요."],"variant_rule":{"gugu":{"ask":"miss","ks":[2]}},"options":[{"t":"2","correct":true},{"t":"3","mis":"M2-2-u2-X02"},{"t":"1","mis":"M2-2-u2-X02"},{"t":"7","mis":"M2-2-u2-X06"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_challenge#6','math',2,2,'u2','L02','g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',3,'mc','auto','신발 한 켤레는 2짝이에요. 우리 모둠 친구 7명이 신발을 한 켤레씩 신었어요. 신발은 모두 몇 짝인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02','M2-2-u2-X14']::text[],false,'{"seq":6,"concept":"M2-2-u2-C1","difficulty":3,"kind":"mc","stem":"신발 한 켤레는 2짝이에요. 우리 모둠 친구 7명이 신발을 한 켤레씩 신었어요. 신발은 모두 몇 짝인가요?","options":[{"t":"14짝","correct":true},{"t":"9짝","mis":"M2-2-u2-X06"},{"t":"12짝","mis":"M2-2-u2-X02"},{"t":"7짝","mis":"M2-2-u2-X14"}],"explanation":["한 사람이 2짝씩, 7명이에요.","2 × 7 = 14예요.","그래서 신발은 모두 14짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_challenge#7','math',2,2,'u2','L02','g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',3,'mc','auto','로봇이 8대 있어요. 바퀴가 모두 몇 개인지 구하는 곱셈식과 답이 바른 것은 어느 것인가요? (로봇 한 대에 바퀴 2개)',ARRAY['M2-2-u2-X14','M2-2-u2-X11','M2-2-u2-X02']::text[],false,'{"seq":7,"concept":"M2-2-u2-C1","difficulty":3,"kind":"mc","stem":"로봇이 8대 있어요. 바퀴가 모두 몇 개인지 구하는 곱셈식과 답이 바른 것은 어느 것인가요? (로봇 한 대에 바퀴 2개)","options":[{"t":"2 × 8 = 16","correct":true},{"t":"8 × 8 = 64","mis":"M2-2-u2-X14"},{"t":"2 + 8 = 10","mis":"M2-2-u2-X11"},{"t":"2 × 8 = 18","mis":"M2-2-u2-X02"}],"explanation":["한 대에 2개씩 — 한 묶음은 2예요.","8대이니 2 × 8이에요.","2씩 8번 뛰어 세면 16이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_challenge#8','math',2,2,'u2','L02','g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',4,'essay','teacher','2 × 7을 두 가지 방법으로 구하고, 각 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C1","difficulty":4,"kind":"essay","stem":"2 × 7을 두 가지 방법으로 구하고, 각 방법을 설명해 보세요.","answer_guide":{"answer":"예: 2를 7번 더하면 2 + 2 + 2 + 2 + 2 + 2 + 2 = 14이다. 2 × 6 = 12에 2를 한 번 더 더하면 14이다.","scoring_points":["2를 7번 더하는 방법으로 14를 구했는가","2 × 6에 2를 더하는 방법으로 14를 구했는가","두 방법 모두 2 × 7 = 14라고 썼는가"]},"explanation":["2 × 7은 2를 7번 더한 것이에요.","2 × 6 = 12보다 2만큼 더 커요.","어떤 방법으로 구해도 14예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_challenge#9','math',2,2,'u2','L02','g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',4,'essay','teacher','2 × 3, 2 × 4, 2 × 5의 곱을 구하고, 2단 곱셈구구에서 곱하는 수가 1씩 커지면 곱이 어떻게 되는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u2-C1","difficulty":4,"kind":"essay","stem":"2 × 3, 2 × 4, 2 × 5의 곱을 구하고, 2단 곱셈구구에서 곱하는 수가 1씩 커지면 곱이 어떻게 되는지 설명해 보세요.","answer_guide":{"answer":"예: 2 × 3 = 6, 2 × 4 = 8, 2 × 5 = 10이다. 곱하는 수가 1씩 커지면 곱은 2씩 커진다. 2를 한 번씩 더 더하기 때문이다.","scoring_points":["세 곱을 바르게 구했는가","곱이 2씩 커진다고 썼는가","2를 한 번 더 더하기 때문이라고 까닭을 썼는가"]},"explanation":["6, 8, 10으로 2씩 커져요.","곱하는 수가 1 커지면 2를 한 번 더 더해요.","곱이 1씩 커지는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_challenge#10','math',2,2,'u2','L02','g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',4,'mc','auto','양말 한 켤레는 2짝이에요. 하린이는 양말 6켤레, 지호는 양말 4켤레를 가지고 있어요. 두 사람의 양말은 모두 몇 짝인가요?',ARRAY['M2-2-u2-X05','M2-2-u2-X18','M2-2-u2-X02']::text[],false,'{"seq":10,"concept":"M2-2-u2-C1","difficulty":4,"kind":"mc","stem":"양말 한 켤레는 2짝이에요. 하린이는 양말 6켤레, 지호는 양말 4켤레를 가지고 있어요. 두 사람의 양말은 모두 몇 짝인가요?","options":[{"t":"20짝","correct":true},{"t":"10짝","mis":"M2-2-u2-X05"},{"t":"12짝","mis":"M2-2-u2-X18"},{"t":"22짝","mis":"M2-2-u2-X02"}],"explanation":["하린이는 2 × 6 = 12짝이에요.","지호는 2 × 4 = 8짝이에요.","12 + 8 = 20이니 모두 20짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_basic#1','math',2,2,'u2','L03','g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',1,'mc','auto','그림을 보세요. 딸기는 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X05']::text[],true,'{"seq":1,"concept":"M2-2-u2-C2","difficulty":1,"kind":"mc","stem":"그림을 보세요. 딸기는 모두 몇 개인가요?","explanation":["5개씩 3묶음이에요.","5씩 뛰어 세면 5, 10, 15.","딸기는 모두 15개예요."],"variant_rule":{"mul":{"ask":"total","ks":[5],"pmax":45}},"options":[{"t":"15개","correct":true},{"t":"8개","mis":"M2-2-u2-X06"},{"t":"3개","mis":"M2-2-u2-X05"}],"asset":{"type":"mul_groups","item":"🍓","k":5,"n":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_basic#2','math',2,2,'u2','L03','g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',1,'sa','auto','5씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u2-C2","difficulty":1,"kind":"sa","stem":"5씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["5씩 커지는 수예요.","15에서 5만큼 더 뛰면 20이에요.","5씩 4번 뛰어 센 수 — 5씩 4묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip","ks":[5],"pmax":45}},"answer":["20"],"asset":{"type":"jump_row","cells":[5,10,15,null],"step":5}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_basic#3','math',2,2,'u2','L03','g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',1,'sa','auto','5 × 6은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u2-C2","difficulty":1,"kind":"sa","stem":"5 × 6은 얼마인가요? 숫자로 쓰세요.","explanation":["5 × 6은 5의 6배예요.","5씩 뛰어 세면 5, 10, 15, 20, 25, 30.","그래서 5 × 6 = 30이에요."],"variant_rule":{"mul":{"ask":"value","ks":[5],"pmax":81}},"answer":["30"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_basic#4','math',2,2,'u2','L03','g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',1,'mc','auto','쟁반 한 개에 딸기가 5개씩 있어요. 쟁반 4개에 담긴 딸기의 수를 곱셈식으로 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u2-X04','M2-2-u2-X11']::text[],true,'{"seq":4,"concept":"M2-2-u2-C2","difficulty":1,"kind":"mc","stem":"쟁반 한 개에 딸기가 5개씩 있어요. 쟁반 4개에 담긴 딸기의 수를 곱셈식으로 나타낸 것은 어느 것인가요?","options":[{"t":"5 × 4","correct":true},{"t":"4 × 4","mis":"M2-2-u2-X04"},{"t":"5 + 4","mis":"M2-2-u2-X11"}],"explanation":["쟁반 한 개에 5개씩 — 한 묶음은 5예요.","쟁반이 4개이니 5 × 4예요.","5 × 4 = 20이에요."],"variant_rule":{"alt":[{"stem":"한 손에 손가락이 5개씩 있어요. 손 3개의 손가락 수를 곱셈식으로 나타낸 것은 어느 것인가요?","options":[{"t":"5 × 3","correct":true},{"t":"3 × 3","mis":"M2-2-u2-X04"},{"t":"5 + 3","mis":"M2-2-u2-X11"}],"explanation":["한 손에 5개씩 — 한 묶음은 5예요.","손이 3개이니 5 × 3이에요.","5 × 3 = 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_basic#5','math',2,2,'u2','L03','g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',2,'mc','auto','5 × 5 = 25예요. 이것을 이용하면 5 × 6은 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17','M2-2-u2-X02']::text[],true,'{"seq":5,"concept":"M2-2-u2-C2","difficulty":2,"kind":"mc","stem":"5 × 5 = 25예요. 이것을 이용하면 5 × 6은 얼마인가요?","explanation":["5 × 6은 5 × 5보다 5만큼 더 커요.","25 + 5 = 30이에요.","한 번 더 더할 때는 곱하는 수 6이 아니라 5를 더해요."],"variant_rule":{"gugu":{"ask":"build","ks":[5]}},"options":[{"t":"30","correct":true},{"t":"26","mis":"M2-2-u2-X01"},{"t":"31","mis":"M2-2-u2-X17"},{"t":"35","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_basic#6','math',2,2,'u2','L03','g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',2,'ox','auto','5단 곱셈구구의 곱은 일의 자리 숫자가 5, 0, 5, 0, …으로 되풀이돼요.',ARRAY['M2-2-u2-X16']::text[],true,'{"seq":6,"concept":"M2-2-u2-C2","difficulty":2,"kind":"ox","stem":"5단 곱셈구구의 곱은 일의 자리 숫자가 5, 0, 5, 0, …으로 되풀이돼요.","answer":"O","reason_options":[{"t":"5, 10, 15, 20처럼 일의 자리에 5와 0이 번갈아 나오니까","correct":true},{"t":"곱하는 수가 1, 2, 3으로 1씩 커지니까","mis":"M2-2-u2-X16"}],"mis":"M2-2-u2-X16","explanation":["5단의 곱은 5, 10, 15, 20, 25, 30, 35, 40, 45예요.","일의 자리 숫자만 보면 5, 0, 5, 0, …이에요.","그래서 바른 말이에요."],"variant_rule":{"alt":[{"stem":"5 × 7의 곱은 일의 자리 숫자가 0이에요.","answer":"X","reason_options":[{"t":"5 × 7 = 35라 일의 자리 숫자가 5니까","correct":true},{"t":"5단의 곱은 일의 자리가 늘 0이니까","mis":"M2-2-u2-X16"}],"explanation":["5 × 7 = 35예요.","5에 홀수 번을 곱하면 일의 자리가 5, 짝수 번을 곱하면 0이에요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_basic#7','math',2,2,'u2','L03','g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',2,'match','auto','곱셈식과 곱을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u2-C2","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 이으세요.","pairs":[{"l":"5 × 3","r":"15"},{"l":"5 × 6","r":"30"},{"l":"5 × 9","r":"45"}],"mis":"M2-2-u2-X02","explanation":["5 × 3은 5, 10, 15로 15예요.","5 × 6은 5씩 6번 뛰어 30이에요.","5 × 9는 5씩 9번 뛰어 45예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 곱을 이으세요.","pairs":[{"l":"5 × 2","r":"10"},{"l":"5 × 5","r":"25"},{"l":"5 × 8","r":"40"}],"explanation":["5 × 2는 5, 10으로 10이에요.","5 × 5는 5씩 5번 뛰어 25예요.","5 × 8은 5씩 8번 뛰어 40이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_basic#8','math',2,2,'u2','L03','g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',2,'mc','auto','쟁반 한 개에 딸기가 5개씩 있어요. 쟁반 6개의 딸기는 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X14']::text[],true,'{"seq":8,"concept":"M2-2-u2-C2","difficulty":2,"kind":"mc","stem":"쟁반 한 개에 딸기가 5개씩 있어요. 쟁반 6개의 딸기는 모두 몇 개인가요?","explanation":["쟁반 한 개에 5개씩, 6개이면 5씩 6묶음이에요.","5 × 6 = 30이에요.","딸기는 모두 30개예요."],"variant_rule":{"mul":{"ask":"story","pmax":81,"per":[5]}},"options":[{"t":"30개","correct":true},{"t":"11개","mis":"M2-2-u2-X06"},{"t":"6개","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_basic#9','math',2,2,'u2','L03','g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',2,'mc','auto','5 × □ = 35에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02']::text[],true,'{"seq":9,"concept":"M2-2-u2-C2","difficulty":2,"kind":"mc","stem":"5 × □ = 35에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["5단 곱셈구구에서 곱이 35인 것을 찾아요.","5씩 뛰어 세면 5, 10, 15, 20, 25, 30, 35 — 7번이에요.","5 × 7 = 35라 □는 7이에요."],"variant_rule":{"gugu":{"ask":"miss","ks":[5]}},"options":[{"t":"7","correct":true},{"t":"8","mis":"M2-2-u2-X02"},{"t":"6","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_basic#10','math',2,2,'u2','L03','g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',3,'error','auto','친구 6명이 손바닥을 하나씩 펼쳤어요. 펼친 손가락의 수를 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X15']::text[],true,'{"seq":10,"concept":"M2-2-u2-C2","difficulty":3,"kind":"error","stem":"친구 6명이 손바닥을 하나씩 펼쳤어요. 펼친 손가락의 수를 잘못 말한 친구는 누구인가요?","options":[{"t":"준우 — 「5 × 6이니까 11개야.」","correct":true,"mis_target":"M2-2-u2-X06"},{"t":"예린 — 「5씩 6번 뛰어 세면 30개야.」","mis":"M2-2-u2-X15"},{"t":"태민 — 「5 × 5 = 25에 5를 더하면 30개야.」","mis":"M2-2-u2-X15"}],"explanation":["손바닥 하나에 손가락 5개, 6명이니 5 × 6이에요.","준우는 5와 6을 더했어요.","5 × 6 = 30이니 30개예요."],"variant_rule":{"alt":[{"stem":"친구 4명이 손바닥을 하나씩 펼쳤어요. 펼친 손가락의 수를 잘못 말한 친구는 누구인가요?","options":[{"t":"아린 — 「5 × 4니까 9개야.」","correct":true,"mis_target":"M2-2-u2-X06"},{"t":"지안 — 「5, 10, 15, 20이니까 20개야.」","mis":"M2-2-u2-X15"},{"t":"하람 — 「5 × 3 = 15에 5를 더하면 20개야.」","mis":"M2-2-u2-X15"}],"explanation":["손바닥 하나에 손가락 5개, 4명이니 5 × 4예요.","아린이는 5와 4를 더했어요.","5 × 4 = 20이니 20개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_challenge#1','math',2,2,'u2','L03','g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',2,'mc','auto','5 × 4는 5 × 3보다 얼마 더 큰가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17']::text[],true,'{"seq":1,"concept":"M2-2-u2-C2","difficulty":2,"kind":"mc","stem":"5 × 4는 5 × 3보다 얼마 더 큰가요?","explanation":["5 × 3은 5를 3번, 5 × 4는 5를 4번 더한 것이에요.","5를 한 번 더 더했으니 5만큼 더 커요 — 15에서 20.","곱하는 수가 1 커지면 곱은 5만큼 커져요."],"variant_rule":{"gugu":{"ask":"next","ks":[5]}},"options":[{"t":"5","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"4","mis":"M2-2-u2-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_challenge#2','math',2,2,'u2','L03','g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',2,'mc','auto','그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X03']::text[],true,'{"seq":2,"concept":"M2-2-u2-C2","difficulty":2,"kind":"mc","stem":"그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["한 줄에 5송이씩 3줄이에요.","5의 3배이니 곱셈식으로 5 × 3이에요.","5 × 3 = 15, 모두 15송이예요."],"variant_rule":{"mul":{"ask":"expr","look":"rows","ks":[5],"pmax":45}},"options":[{"t":"5 × 3","correct":true},{"t":"5 + 3","mis":"M2-2-u2-X11"},{"t":"5 × 4","mis":"M2-2-u2-X03"}],"asset":{"type":"mul_groups","item":"🌷","k":5,"n":3,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_challenge#3','math',2,2,'u2','L03','g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',3,'mc','auto','5단 곱셈구구의 곱이 될 수 없는 수는 어느 것인가요?',ARRAY['M2-2-u2-X15']::text[],false,'{"seq":3,"concept":"M2-2-u2-C2","difficulty":3,"kind":"mc","stem":"5단 곱셈구구의 곱이 될 수 없는 수는 어느 것인가요?","options":[{"t":"32","correct":true},{"t":"35","mis":"M2-2-u2-X15"},{"t":"40","mis":"M2-2-u2-X15"},{"t":"20","mis":"M2-2-u2-X15"}],"explanation":["5단의 곱은 일의 자리 숫자가 5 아니면 0이에요.","32는 일의 자리 숫자가 2라 5단의 곱이 아니에요.","35 = 5 × 7, 40 = 5 × 8, 20 = 5 × 4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_challenge#4','math',2,2,'u2','L03','g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',3,'mc','auto','5 × 8은 5 × 4를 몇 번 더한 것과 같은가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X04']::text[],false,'{"seq":4,"concept":"M2-2-u2-C2","difficulty":3,"kind":"mc","stem":"5 × 8은 5 × 4를 몇 번 더한 것과 같은가요?","options":[{"t":"2번","correct":true},{"t":"4번","mis":"M2-2-u2-X17"},{"t":"8번","mis":"M2-2-u2-X04"}],"explanation":["5 × 4 = 20이에요.","20 + 20 = 40 = 5 × 8이에요.","5씩 8묶음은 5씩 4묶음이 두 개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_challenge#5','math',2,2,'u2','L03','g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',3,'mc','auto','□ × 9 = 45에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02','M2-2-u2-X06']::text[],true,'{"seq":5,"concept":"M2-2-u2-C2","difficulty":3,"kind":"mc","stem":"□ × 9 = 45에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["몇 단 곱셈구구에서 9번째 곱이 45인지 찾아요.","5 × 9 = 45예요 — 6 × 9 = 54예요.","그래서 □는 5예요."],"variant_rule":{"gugu":{"ask":"miss","ks":[5]}},"options":[{"t":"5","correct":true},{"t":"6","mis":"M2-2-u2-X02"},{"t":"4","mis":"M2-2-u2-X02"},{"t":"36","mis":"M2-2-u2-X06"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_challenge#6','math',2,2,'u2','L03','g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',3,'mc','auto','한 묶음에 연필이 5자루씩 있어요. 7묶음 있으면 연필은 모두 몇 자루인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":6,"concept":"M2-2-u2-C2","difficulty":3,"kind":"mc","stem":"한 묶음에 연필이 5자루씩 있어요. 7묶음 있으면 연필은 모두 몇 자루인가요?","options":[{"t":"35자루","correct":true},{"t":"12자루","mis":"M2-2-u2-X06"},{"t":"30자루","mis":"M2-2-u2-X02"},{"t":"40자루","mis":"M2-2-u2-X02"}],"explanation":["한 묶음에 5자루씩, 7묶음이에요.","5 × 7 = 35예요.","5 × 6 = 30, 5 × 8 = 40과 헷갈리지 않게 7번인지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_challenge#7','math',2,2,'u2','L03','g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',3,'mc','auto','두 곱의 크기를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_challenge#8','math',2,2,'u2','L03','g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',4,'essay','teacher','5 × 6을 두 가지 방법으로 구하고, 각 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C2","difficulty":4,"kind":"essay","stem":"5 × 6을 두 가지 방법으로 구하고, 각 방법을 설명해 보세요.","answer_guide":{"answer":"예: 5씩 6번 뛰어 세면 5, 10, 15, 20, 25, 30이다. 5 × 5 = 25에 5를 한 번 더 더하면 30이다. 그래서 5 × 6 = 30이다.","scoring_points":["한 가지 방법(뛰어 세기·여러 번 더하기)으로 30을 구했는가","다른 방법(5 × 5에 5 더하기 등)으로 30을 구했는가","5 × 6 = 30이라고 썼는가"]},"explanation":["5 × 6은 5를 6번 더한 것이에요.","5 × 5 = 25보다 5만큼 더 커요.","어느 방법으로든 30이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_challenge#9','math',2,2,'u2','L03','g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',4,'essay','teacher','5단 곱셈구구의 곱을 모두 쓰고, 곱에서 찾을 수 있는 규칙을 두 가지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u2-C2","difficulty":4,"kind":"essay","stem":"5단 곱셈구구의 곱을 모두 쓰고, 곱에서 찾을 수 있는 규칙을 두 가지 써 보세요.","answer_guide":{"answer":"예: 5, 10, 15, 20, 25, 30, 35, 40, 45. 곱이 5씩 커진다. 일의 자리 숫자가 5, 0, 5, 0으로 되풀이된다.","scoring_points":["5단의 곱을 바르게 썼는가","곱이 5씩 커진다는 규칙을 썼는가","일의 자리 숫자가 5와 0으로 되풀이된다는 규칙을 썼는가"]},"explanation":["5단의 곱은 5씩 커져요.","일의 자리 숫자만 보면 5와 0이 번갈아 나와요.","이 규칙으로 5단의 곱을 쉽게 알아볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_challenge#10','math',2,2,'u2','L03','g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',4,'mc','auto','한 손에 손가락이 5개씩 있어요. 친구 4명의 두 손 손가락은 모두 몇 개인가요?',ARRAY['M2-2-u2-X14','M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":10,"concept":"M2-2-u2-C2","difficulty":4,"kind":"mc","stem":"한 손에 손가락이 5개씩 있어요. 친구 4명의 두 손 손가락은 모두 몇 개인가요?","options":[{"t":"40개","correct":true},{"t":"20개","mis":"M2-2-u2-X14"},{"t":"9개","mis":"M2-2-u2-X06"},{"t":"45개","mis":"M2-2-u2-X02"}],"explanation":["친구 4명의 손은 2 × 4 = 8개예요.","손 하나에 5개씩, 손 8개이니 5 × 8 = 40이에요.","한 손씩만 세면 20개가 되어 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_basic#1','math',2,2,'u2','L04','g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',1,'mc','auto','그림을 보세요. 물고기는 모두 몇 마리인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X05']::text[],true,'{"seq":1,"concept":"M2-2-u2-C3","difficulty":1,"kind":"mc","stem":"그림을 보세요. 물고기는 모두 몇 마리인가요?","explanation":["한 줄에 3마리씩 4줄이에요.","3씩 뛰어 세면 3, 6, 9, 12.","물고기는 모두 12마리예요."],"variant_rule":{"mul":{"ask":"total","look":"rows","ks":[3,6],"pmax":45}},"options":[{"t":"12마리","correct":true},{"t":"7마리","mis":"M2-2-u2-X06"},{"t":"4마리","mis":"M2-2-u2-X05"}],"asset":{"type":"mul_groups","item":"🐟","k":3,"n":4,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_basic#2','math',2,2,'u2','L04','g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',1,'sa','auto','3씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u2-C3","difficulty":1,"kind":"sa","stem":"3씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["3씩 커지는 수예요.","12에서 3만큼 더 뛰면 15예요.","3씩 5번 뛰어 센 수 — 3씩 5묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip","ks":[3,6],"pmax":45}},"answer":["15"],"asset":{"type":"jump_row","cells":[3,6,9,12,null],"step":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_basic#3','math',2,2,'u2','L04','g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',1,'sa','auto','6 × 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u2-C3","difficulty":1,"kind":"sa","stem":"6 × 3은 얼마인가요? 숫자로 쓰세요.","explanation":["6 × 3은 6의 3배예요.","6씩 뛰어 세면 6, 12, 18.","그래서 6 × 3 = 18이에요."],"variant_rule":{"mul":{"ask":"value","ks":[3,6],"pmax":81}},"answer":["18"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_basic#4','math',2,2,'u2','L04','g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',1,'mc','auto','노란색 물고기가 한 줄에 3마리씩 5줄 있어요. 물고기는 모두 몇 마리인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],true,'{"seq":4,"concept":"M2-2-u2-C3","difficulty":1,"kind":"mc","stem":"노란색 물고기가 한 줄에 3마리씩 5줄 있어요. 물고기는 모두 몇 마리인가요?","options":[{"t":"15마리","correct":true},{"t":"8마리","mis":"M2-2-u2-X06"},{"t":"18마리","mis":"M2-2-u2-X02"}],"explanation":["한 줄에 3마리씩, 5줄이에요.","3 × 5 = 15예요.","3, 6, 9, 12, 15로 뛰어 세어도 15마리예요."],"variant_rule":{"alt":[{"stem":"구슬이 한 봉지에 6개씩 3봉지 있어요. 구슬은 모두 몇 개인가요?","options":[{"t":"18개","correct":true},{"t":"9개","mis":"M2-2-u2-X06"},{"t":"24개","mis":"M2-2-u2-X02"}],"explanation":["한 봉지에 6개씩, 3봉지예요.","6 × 3 = 18이에요.","6, 12, 18로 뛰어 세어도 18개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_basic#5','math',2,2,'u2','L04','g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',2,'mc','auto','6 × 3 = 18이에요. 이것을 이용하면 6 × 4는 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17','M2-2-u2-X02']::text[],true,'{"seq":5,"concept":"M2-2-u2-C3","difficulty":2,"kind":"mc","stem":"6 × 3 = 18이에요. 이것을 이용하면 6 × 4는 얼마인가요?","explanation":["6 × 4는 6 × 3보다 6만큼 더 커요.","18 + 6 = 24예요.","한 번 더 더할 때는 곱하는 수 4가 아니라 6을 더해요."],"variant_rule":{"gugu":{"ask":"build","ks":[3,6]}},"options":[{"t":"24","correct":true},{"t":"19","mis":"M2-2-u2-X01"},{"t":"22","mis":"M2-2-u2-X17"},{"t":"30","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_basic#6','math',2,2,'u2','L04','g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',2,'ox','auto','6 × 5와 5 × 6은 곱이 같아요.',ARRAY['M2-2-u2-X13']::text[],true,'{"seq":6,"concept":"M2-2-u2-C3","difficulty":2,"kind":"ox","stem":"6 × 5와 5 × 6은 곱이 같아요.","answer":"O","reason_options":[{"t":"6씩 5묶음과 5씩 6묶음은 같은 30개를 다르게 묶은 것이니까","correct":true},{"t":"앞의 수가 크면 곱도 크니까","mis":"M2-2-u2-X13"}],"mis":"M2-2-u2-X13","explanation":["6 × 5 = 30이에요.","5 × 6 = 30이에요.","두 수를 바꾸어 곱해도 곱은 같아요 — 6 × 5를 5단으로 구할 수 있어요."],"variant_rule":{"alt":[{"stem":"3 × 4를 두 번 더하면 6 × 4와 같아요.","answer":"O","reason_options":[{"t":"3씩 8묶음은 6씩 4묶음과 같아서 12 + 12 = 24니까","correct":true},{"t":"3단과 6단은 서로 관계가 없으니까","mis":"M2-2-u2-X10"}],"explanation":["3 × 4 = 12예요.","12 + 12 = 24 = 6 × 4예요.","6단의 곱은 같은 수를 곱한 3단의 곱의 2배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_basic#7','math',2,2,'u2','L04','g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',2,'match','auto','곱셈식과 곱을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u2-C3","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 이으세요.","pairs":[{"l":"3 × 4","r":"12"},{"l":"6 × 4","r":"24"},{"l":"6 × 7","r":"42"}],"mis":"M2-2-u2-X02","explanation":["3 × 4는 3씩 4번 뛰어 12예요.","6 × 4는 12의 2배, 24예요.","6 × 7은 6씩 7번 뛰어 42예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 곱을 이으세요.","pairs":[{"l":"3 × 8","r":"24"},{"l":"6 × 3","r":"18"},{"l":"6 × 9","r":"54"}],"explanation":["3 × 8은 3씩 8번 뛰어 24예요.","6 × 3은 6, 12, 18로 18이에요.","6 × 9는 6씩 9번 뛰어 54예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_basic#8','math',2,2,'u2','L04','g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',2,'mc','auto','어항 한 개에 물고기가 3마리씩 있어요. 어항 4개의 물고기는 모두 몇 마리인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X14']::text[],true,'{"seq":8,"concept":"M2-2-u2-C3","difficulty":2,"kind":"mc","stem":"어항 한 개에 물고기가 3마리씩 있어요. 어항 4개의 물고기는 모두 몇 마리인가요?","explanation":["어항 한 개에 3마리씩, 4개이면 3씩 4묶음이에요.","3 × 4 = 12예요.","물고기는 모두 12마리예요."],"variant_rule":{"mul":{"ask":"story","pmax":81,"per":[3,6]}},"options":[{"t":"12마리","correct":true},{"t":"7마리","mis":"M2-2-u2-X06"},{"t":"4마리","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_basic#9','math',2,2,'u2','L04','g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',2,'mc','auto','3 × □ = 24에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02']::text[],true,'{"seq":9,"concept":"M2-2-u2-C3","difficulty":2,"kind":"mc","stem":"3 × □ = 24에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["3단 곱셈구구에서 곱이 24인 것을 찾아요.","3씩 뛰어 세면 3, 6, 9, 12, 15, 18, 21, 24 — 8번이에요.","3 × 8 = 24라 □는 8이에요."],"variant_rule":{"gugu":{"ask":"miss","ks":[3,6]}},"options":[{"t":"8","correct":true},{"t":"9","mis":"M2-2-u2-X02"},{"t":"7","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_basic#10','math',2,2,'u2','L04','g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',3,'mc','auto','장난감이 6개씩 4묶음 있어요. 같은 장난감을 3개씩 묶으면 몇 묶음이 될까요?',ARRAY['M2-2-u2-X10','M2-2-u2-X05']::text[],true,'{"seq":10,"concept":"M2-2-u2-C3","difficulty":3,"kind":"mc","stem":"장난감이 6개씩 4묶음 있어요. 같은 장난감을 3개씩 묶으면 몇 묶음이 될까요?","options":[{"t":"8묶음","correct":true},{"t":"4묶음","mis":"M2-2-u2-X10"},{"t":"24묶음","mis":"M2-2-u2-X05"}],"explanation":["6 × 4 = 24이니 장난감은 24개예요.","6개씩 한 묶음은 3개씩 두 묶음이에요.","그래서 3개씩 8묶음 — 3 × 8 = 24예요."],"variant_rule":{"alt":[{"stem":"구슬이 3개씩 6묶음 있어요. 같은 구슬을 6개씩 묶으면 몇 묶음이 될까요?","options":[{"t":"3묶음","correct":true},{"t":"6묶음","mis":"M2-2-u2-X10"},{"t":"18묶음","mis":"M2-2-u2-X05"}],"explanation":["3 × 6 = 18이니 구슬은 18개예요.","3개씩 두 묶음이 6개씩 한 묶음이에요.","그래서 6개씩 3묶음 — 6 × 3 = 18이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_challenge#1','math',2,2,'u2','L04','g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',2,'mc','auto','6 × 7은 6 × 6보다 얼마 더 큰가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17']::text[],true,'{"seq":1,"concept":"M2-2-u2-C3","difficulty":2,"kind":"mc","stem":"6 × 7은 6 × 6보다 얼마 더 큰가요?","explanation":["6 × 6은 6을 6번, 6 × 7은 6을 7번 더한 것이에요.","6을 한 번 더 더했으니 6만큼 더 커요 — 36에서 42.","곱하는 수가 1 커지면 곱은 6만큼 커져요."],"variant_rule":{"gugu":{"ask":"next","ks":[3,6]}},"options":[{"t":"6","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"7","mis":"M2-2-u2-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_challenge#2','math',2,2,'u2','L04','g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',2,'mc','auto','그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X03']::text[],true,'{"seq":2,"concept":"M2-2-u2-C3","difficulty":2,"kind":"mc","stem":"그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["한 줄에 6개씩 3줄이에요.","6의 3배이니 곱셈식으로 6 × 3이에요.","6 × 3 = 18, 모두 18개예요."],"variant_rule":{"mul":{"ask":"expr","look":"rows","ks":[3,6],"pmax":45}},"options":[{"t":"6 × 3","correct":true},{"t":"6 + 3","mis":"M2-2-u2-X11"},{"t":"6 × 4","mis":"M2-2-u2-X03"}],"asset":{"type":"mul_groups","item":"🍬","k":6,"n":3,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_challenge#3','math',2,2,'u2','L04','g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',3,'mc','auto','3 × 6과 6 × 3을 바르게 설명한 것은 어느 것인가요?',ARRAY['M2-2-u2-X13','M2-2-u2-X06']::text[],false,'{"seq":3,"concept":"M2-2-u2-C3","difficulty":3,"kind":"mc","stem":"3 × 6과 6 × 3을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"곱이 18로 같아요","correct":true},{"t":"6 × 3이 더 커요","mis":"M2-2-u2-X13"},{"t":"곱이 9로 같아요","mis":"M2-2-u2-X06"}],"explanation":["3 × 6은 3씩 6묶음, 6 × 3은 6씩 3묶음이에요.","둘 다 18이에요.","두 수를 바꾸어 곱해도 곱은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_challenge#4','math',2,2,'u2','L04','g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',3,'mc','auto','6 × 6을 구하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M2-2-u2-X15']::text[],false,'{"seq":4,"concept":"M2-2-u2-C3","difficulty":3,"kind":"mc","stem":"6 × 6을 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"6 × 5 = 30에 5를 더해요","correct":true},{"t":"6 × 5 = 30에 6을 더해요","mis":"M2-2-u2-X15"},{"t":"3 × 6 = 18을 두 번 더해요","mis":"M2-2-u2-X15"},{"t":"6을 6번 더해요","mis":"M2-2-u2-X15"}],"explanation":["6 × 6 = 36이에요.","6 × 5에 더할 수는 6이에요 — 30 + 5 = 35는 틀려요.","18 + 18 = 36, 6을 6번 더해도 36이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_challenge#5','math',2,2,'u2','L04','g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',3,'mc','auto','두 곱의 크기를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_challenge#6','math',2,2,'u2','L04','g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',3,'mc','auto','같은 수를 곱할 때 6단 곱셈구구의 곱은 3단 곱셈구구의 곱의 몇 배인가요?',ARRAY['M2-2-u2-X10']::text[],false,'{"seq":6,"concept":"M2-2-u2-C3","difficulty":3,"kind":"mc","stem":"같은 수를 곱할 때 6단 곱셈구구의 곱은 3단 곱셈구구의 곱의 몇 배인가요?","options":[{"t":"2배","correct":true},{"t":"3배","mis":"M2-2-u2-X10"},{"t":"6배","mis":"M2-2-u2-X10"}],"explanation":["3 × 4 = 12, 6 × 4 = 24예요.","24는 12의 2배예요.","6씩 한 묶음은 3씩 두 묶음이라 6단의 곱은 3단의 곱의 2배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_challenge#7','math',2,2,'u2','L04','g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',3,'mc','auto','□ × 7 = 42에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02','M2-2-u2-X06']::text[],true,'{"seq":7,"concept":"M2-2-u2-C3","difficulty":3,"kind":"mc","stem":"□ × 7 = 42에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["몇 단 곱셈구구에서 7번째 곱이 42인지 찾아요.","6 × 7 = 42예요 — 7 × 7 = 49예요.","그래서 □는 6이에요."],"variant_rule":{"gugu":{"ask":"miss","ks":[3,6]}},"options":[{"t":"6","correct":true},{"t":"7","mis":"M2-2-u2-X02"},{"t":"5","mis":"M2-2-u2-X02"},{"t":"35","mis":"M2-2-u2-X06"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_challenge#8','math',2,2,'u2','L04','g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',4,'essay','teacher','6 × 5를 두 가지 방법으로 구하고, 각 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C3","difficulty":4,"kind":"essay","stem":"6 × 5를 두 가지 방법으로 구하고, 각 방법을 설명해 보세요.","answer_guide":{"answer":"예: 6 × 4 = 24에 6을 한 번 더 더하면 30이다. 6씩 5묶음은 5씩 6묶음으로 다르게 묶을 수 있으니 5 × 6 = 30이다.","scoring_points":["6 × 4에 6을 더하는 방법으로 30을 구했는가","5 × 6처럼 다르게 묶거나 다른 방법으로 30을 구했는가","6 × 5 = 30이라고 썼는가"]},"explanation":["6 × 5는 6 × 4보다 6만큼 커요.","6씩 5묶음을 5씩 6묶음으로 보면 5단으로 구할 수 있어요.","어느 방법으로든 30이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_challenge#9','math',2,2,'u2','L04','g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',4,'essay','teacher','3단 곱셈구구와 6단 곱셈구구가 어떻게 이어져 있는지 3 × 4와 6 × 4를 예로 들어 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u2-C3","difficulty":4,"kind":"essay","stem":"3단 곱셈구구와 6단 곱셈구구가 어떻게 이어져 있는지 3 × 4와 6 × 4를 예로 들어 설명해 보세요.","answer_guide":{"answer":"예: 3 × 4 = 12, 6 × 4 = 24이다. 6씩 한 묶음은 3씩 두 묶음이므로 6 × 4는 3 × 4를 두 번 더한 것과 같다. 6단의 곱은 3단의 곱의 2배이다.","scoring_points":["두 곱을 바르게 구했는가","6씩 한 묶음이 3씩 두 묶음이라는 것을 썼는가","6단의 곱이 3단의 곱의 2배라고 썼는가"]},"explanation":["3 × 4 = 12, 6 × 4 = 24예요.","24는 12 + 12예요.","그래서 6단은 3단을 두 번 더한 것과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_challenge#10','math',2,2,'u2','L04','g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',4,'mc','auto','한 상자에 컵케이크가 6개씩 들어 있어요. 5상자 가운데 3개를 먹었어요. 남은 컵케이크는 몇 개인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X06']::text[],false,'{"seq":10,"concept":"M2-2-u2-C3","difficulty":4,"kind":"mc","stem":"한 상자에 컵케이크가 6개씩 들어 있어요. 5상자 가운데 3개를 먹었어요. 남은 컵케이크는 몇 개인가요?","options":[{"t":"27개","correct":true},{"t":"30개","mis":"M2-2-u2-X18"},{"t":"8개","mis":"M2-2-u2-X06"},{"t":"33개","mis":"M2-2-u2-X06"}],"explanation":["6 × 5 = 30이니 처음에 30개였어요.","그중 3개를 먹었어요.","30 − 3 = 27이니 27개가 남았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_basic#1','math',2,2,'u2','L05','g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',1,'mc','auto','그림을 보세요. 당근은 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X05']::text[],true,'{"seq":1,"concept":"M2-2-u2-C4","difficulty":1,"kind":"mc","stem":"그림을 보세요. 당근은 모두 몇 개인가요?","explanation":["4개씩 5묶음이에요.","4씩 뛰어 세면 4, 8, 12, 16, 20.","당근은 모두 20개예요."],"variant_rule":{"mul":{"ask":"total","ks":[4,8],"pmax":45}},"options":[{"t":"20개","correct":true},{"t":"9개","mis":"M2-2-u2-X06"},{"t":"5개","mis":"M2-2-u2-X05"}],"asset":{"type":"mul_groups","item":"🥕","k":4,"n":5}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_basic#2','math',2,2,'u2','L05','g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',1,'sa','auto','4씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u2-C4","difficulty":1,"kind":"sa","stem":"4씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["4씩 커지는 수예요.","20에서 4만큼 더 뛰면 24예요.","4씩 6번 뛰어 센 수 — 4씩 6묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip","ks":[4,8],"pmax":45}},"answer":["24"],"asset":{"type":"jump_row","cells":[4,8,12,16,20,null],"step":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_basic#3','math',2,2,'u2','L05','g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',1,'sa','auto','8 × 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u2-C4","difficulty":1,"kind":"sa","stem":"8 × 3은 얼마인가요? 숫자로 쓰세요.","explanation":["8 × 3은 8의 3배예요.","8씩 뛰어 세면 8, 16, 24.","그래서 8 × 3 = 24예요."],"variant_rule":{"mul":{"ask":"value","ks":[4,8],"pmax":81}},"answer":["24"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_basic#4','math',2,2,'u2','L05','g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',1,'mc','auto','로봇이 한 줄에 4대씩 서 있어요. 6줄이면 로봇은 모두 몇 대인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],true,'{"seq":4,"concept":"M2-2-u2-C4","difficulty":1,"kind":"mc","stem":"로봇이 한 줄에 4대씩 서 있어요. 6줄이면 로봇은 모두 몇 대인가요?","options":[{"t":"24대","correct":true},{"t":"10대","mis":"M2-2-u2-X06"},{"t":"28대","mis":"M2-2-u2-X02"}],"explanation":["한 줄에 4대씩, 6줄이에요.","4 × 6 = 24예요.","4 × 7 = 28과 헷갈리지 않게 줄 수를 확인해요."],"variant_rule":{"alt":[{"stem":"우유가 한 줄에 8갑씩 3줄 있어요. 우유는 모두 몇 갑인가요?","options":[{"t":"24갑","correct":true},{"t":"11갑","mis":"M2-2-u2-X06"},{"t":"32갑","mis":"M2-2-u2-X02"}],"explanation":["한 줄에 8갑씩, 3줄이에요.","8 × 3 = 24예요.","8 × 4 = 32와 헷갈리지 않게 줄 수를 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_basic#5','math',2,2,'u2','L05','g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',2,'mc','auto','8 × 3 = 24예요. 이것을 이용하면 8 × 4는 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17','M2-2-u2-X02']::text[],true,'{"seq":5,"concept":"M2-2-u2-C4","difficulty":2,"kind":"mc","stem":"8 × 3 = 24예요. 이것을 이용하면 8 × 4는 얼마인가요?","explanation":["8 × 4는 8 × 3보다 8만큼 더 커요.","24 + 8 = 32예요.","한 번 더 더할 때는 곱하는 수 4가 아니라 8을 더해요."],"variant_rule":{"gugu":{"ask":"build","ks":[4,8]}},"options":[{"t":"32","correct":true},{"t":"25","mis":"M2-2-u2-X01"},{"t":"28","mis":"M2-2-u2-X17"},{"t":"40","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_basic#6','math',2,2,'u2','L05','g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',2,'ox','auto','8 × 6은 8 × 3을 두 번 더한 것과 같아요.',ARRAY['M2-2-u2-X17']::text[],true,'{"seq":6,"concept":"M2-2-u2-C4","difficulty":2,"kind":"ox","stem":"8 × 6은 8 × 3을 두 번 더한 것과 같아요.","answer":"O","reason_options":[{"t":"8씩 6묶음은 8씩 3묶음이 두 개니까","correct":true},{"t":"8 × 3에 3을 더하면 8 × 6이 되니까","mis":"M2-2-u2-X17"}],"mis":"M2-2-u2-X17","explanation":["8 × 3 = 24예요.","24 + 24 = 48 = 8 × 6이에요.","8 × 6을 8 × 3 두 번으로 나누어 구할 수 있어요."],"variant_rule":{"alt":[{"stem":"8 × 4는 4 × 4의 2배예요.","answer":"O","reason_options":[{"t":"8씩 한 묶음은 4씩 두 묶음이라 16의 2배 32니까","correct":true},{"t":"4단과 8단은 서로 관계가 없으니까","mis":"M2-2-u2-X10"}],"explanation":["4 × 4 = 16, 8 × 4 = 32예요.","32는 16의 2배예요.","같은 수를 곱할 때 8단의 곱은 4단의 곱의 2배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_basic#7','math',2,2,'u2','L05','g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',2,'match','auto','곱셈식과 곱을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u2-C4","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 이으세요.","pairs":[{"l":"4 × 5","r":"20"},{"l":"8 × 5","r":"40"},{"l":"4 × 9","r":"36"}],"mis":"M2-2-u2-X02","explanation":["4 × 5는 4씩 5번 뛰어 20이에요.","8 × 5는 20의 2배, 40이에요.","4 × 9는 4씩 9번 뛰어 36이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 곱을 이으세요.","pairs":[{"l":"8 × 7","r":"56"},{"l":"4 × 7","r":"28"},{"l":"8 × 2","r":"16"}],"explanation":["8 × 7은 28의 2배, 56이에요.","4 × 7은 4씩 7번 뛰어 28이에요.","8 × 2는 8, 16으로 16이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_basic#8','math',2,2,'u2','L05','g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',2,'mc','auto','봉투 한 개에 색종이가 4장씩 있어요. 봉투 6개의 색종이는 모두 몇 장인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X14']::text[],true,'{"seq":8,"concept":"M2-2-u2-C4","difficulty":2,"kind":"mc","stem":"봉투 한 개에 색종이가 4장씩 있어요. 봉투 6개의 색종이는 모두 몇 장인가요?","explanation":["봉투 한 개에 4장씩, 6개이면 4씩 6묶음이에요.","4 × 6 = 24예요.","색종이는 모두 24장이에요."],"variant_rule":{"mul":{"ask":"story","pmax":81,"per":[4,8]}},"options":[{"t":"24장","correct":true},{"t":"10장","mis":"M2-2-u2-X06"},{"t":"6장","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_basic#9','math',2,2,'u2','L05','g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',2,'mc','auto','8 × □ = 56에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02']::text[],true,'{"seq":9,"concept":"M2-2-u2-C4","difficulty":2,"kind":"mc","stem":"8 × □ = 56에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["8단 곱셈구구에서 곱이 56인 것을 찾아요.","8씩 뛰어 세면 8, 16, 24, 32, 40, 48, 56 — 7번이에요.","8 × 7 = 56이라 □는 7이에요."],"variant_rule":{"gugu":{"ask":"miss","ks":[4,8]}},"options":[{"t":"7","correct":true},{"t":"8","mis":"M2-2-u2-X02"},{"t":"6","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_basic#10','math',2,2,'u2','L05','g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',3,'mc','auto','우유가 4갑씩 6줄 있어요. 같은 우유를 8갑씩 놓으면 몇 줄이 될까요?',ARRAY['M2-2-u2-X10']::text[],true,'{"seq":10,"concept":"M2-2-u2-C4","difficulty":3,"kind":"mc","stem":"우유가 4갑씩 6줄 있어요. 같은 우유를 8갑씩 놓으면 몇 줄이 될까요?","options":[{"t":"3줄","correct":true},{"t":"6줄","mis":"M2-2-u2-X10"},{"t":"12줄","mis":"M2-2-u2-X10"}],"explanation":["4 × 6 = 24이니 우유는 24갑이에요.","4갑씩 두 줄이 8갑씩 한 줄이에요.","그래서 8갑씩 3줄 — 8 × 3 = 24예요."],"variant_rule":{"alt":[{"stem":"구슬이 8개씩 2줄 있어요. 같은 구슬을 4개씩 놓으면 몇 줄이 될까요?","options":[{"t":"4줄","correct":true},{"t":"2줄","mis":"M2-2-u2-X10"},{"t":"8줄","mis":"M2-2-u2-X10"}],"explanation":["8 × 2 = 16이니 구슬은 16개예요.","8개씩 한 줄은 4개씩 두 줄이에요.","그래서 4개씩 4줄 — 4 × 4 = 16이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_challenge#1','math',2,2,'u2','L05','g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',2,'mc','auto','8 × 6은 8 × 5보다 얼마 더 큰가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17']::text[],true,'{"seq":1,"concept":"M2-2-u2-C4","difficulty":2,"kind":"mc","stem":"8 × 6은 8 × 5보다 얼마 더 큰가요?","explanation":["8 × 5는 8을 5번, 8 × 6은 8을 6번 더한 것이에요.","8을 한 번 더 더했으니 8만큼 더 커요 — 40에서 48.","곱하는 수가 1 커지면 곱은 8만큼 커져요."],"variant_rule":{"gugu":{"ask":"next","ks":[4,8]}},"options":[{"t":"8","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"6","mis":"M2-2-u2-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_challenge#2','math',2,2,'u2','L05','g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',2,'mc','auto','그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X03']::text[],true,'{"seq":2,"concept":"M2-2-u2-C4","difficulty":2,"kind":"mc","stem":"그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["한 줄에 4개씩 7줄이에요.","4의 7배이니 곱셈식으로 4 × 7이에요.","4 × 7 = 28, 모두 28개예요."],"variant_rule":{"mul":{"ask":"expr","look":"rows","ks":[4,8],"pmax":45}},"options":[{"t":"4 × 7","correct":true},{"t":"4 + 7","mis":"M2-2-u2-X11"},{"t":"4 × 8","mis":"M2-2-u2-X03"}],"asset":{"type":"mul_groups","item":"🍪","k":4,"n":7,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_challenge#3','math',2,2,'u2','L05','g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',3,'mc','auto','8 × 5를 구하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X11']::text[],false,'{"seq":3,"concept":"M2-2-u2-C4","difficulty":3,"kind":"mc","stem":"8 × 5를 구하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"5개씩 8묶음으로 보아 5 × 8을 구해요","correct":true},{"t":"8 × 4 = 32에 5를 더해요","mis":"M2-2-u2-X17"},{"t":"8과 5를 더해요","mis":"M2-2-u2-X11"}],"explanation":["8씩 5묶음은 5씩 8묶음으로 다르게 묶을 수 있어요.","5 × 8 = 40이에요.","8 × 4 = 32에 더할 수는 5가 아니라 8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_challenge#4','math',2,2,'u2','L05','g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',3,'mc','auto','4단 곱셈구구의 곱도 되고 8단 곱셈구구의 곱도 되는 수는 어느 것인가요?',ARRAY['M2-2-u2-X10']::text[],false,'{"seq":4,"concept":"M2-2-u2-C4","difficulty":3,"kind":"mc","stem":"4단 곱셈구구의 곱도 되고 8단 곱셈구구의 곱도 되는 수는 어느 것인가요?","options":[{"t":"24","correct":true},{"t":"20","mis":"M2-2-u2-X10"},{"t":"28","mis":"M2-2-u2-X10"},{"t":"12","mis":"M2-2-u2-X10"}],"explanation":["24 = 4 × 6이고 24 = 8 × 3이에요.","20 = 4 × 5, 28 = 4 × 7, 12 = 4 × 3은 8단의 곱이 아니에요.","8단의 곱은 모두 4단의 곱이기도 해요(8 × 1부터 8 × 4까지)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_challenge#5','math',2,2,'u2','L05','g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',3,'mc','auto','두 곱의 크기를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_challenge#6','math',2,2,'u2','L05','g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',3,'mc','auto','□ × 9 = 36에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02','M2-2-u2-X06']::text[],true,'{"seq":6,"concept":"M2-2-u2-C4","difficulty":3,"kind":"mc","stem":"□ × 9 = 36에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["몇 단 곱셈구구에서 9번째 곱이 36인지 찾아요.","4 × 9 = 36이에요 — 5 × 9 = 45예요.","그래서 □는 4예요."],"variant_rule":{"gugu":{"ask":"miss","ks":[4,8]}},"options":[{"t":"4","correct":true},{"t":"5","mis":"M2-2-u2-X02"},{"t":"3","mis":"M2-2-u2-X02"},{"t":"27","mis":"M2-2-u2-X06"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_challenge#7','math',2,2,'u2','L05','g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',3,'mc','auto','거미 한 마리의 다리는 8개예요. 거미 4마리의 다리는 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":7,"concept":"M2-2-u2-C4","difficulty":3,"kind":"mc","stem":"거미 한 마리의 다리는 8개예요. 거미 4마리의 다리는 모두 몇 개인가요?","options":[{"t":"32개","correct":true},{"t":"12개","mis":"M2-2-u2-X06"},{"t":"24개","mis":"M2-2-u2-X02"},{"t":"36개","mis":"M2-2-u2-X02"}],"explanation":["한 마리에 8개씩, 4마리예요.","8 × 4 = 32예요.","8 × 3 = 24, 8 × 4 = 32 — 마리 수만큼 곱했는지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_challenge#8','math',2,2,'u2','L05','g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',4,'essay','teacher','8 × 6을 두 가지 방법으로 구하고, 각 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C4","difficulty":4,"kind":"essay","stem":"8 × 6을 두 가지 방법으로 구하고, 각 방법을 설명해 보세요.","answer_guide":{"answer":"예: 8 × 5 = 40에 8을 한 번 더 더하면 48이다. 8 × 3 = 24를 두 번 더하면 24 + 24 = 48이다.","scoring_points":["한 가지 방법(8 × 5에 8 더하기 등)으로 48을 구했는가","다른 방법(8 × 3 두 번 더하기·4 × 6의 2배 등)으로 48을 구했는가","8 × 6 = 48이라고 썼는가"]},"explanation":["8 × 6은 8 × 5보다 8만큼 커요.","8씩 6묶음은 8씩 3묶음이 두 개예요.","어느 방법으로든 48이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_challenge#9','math',2,2,'u2','L05','g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',4,'essay','teacher','우유가 4갑씩 6줄 놓여 있어요. 이것을 8갑씩 다시 놓으면 몇 줄인지 구하고, 4단과 8단이 어떻게 이어져 있는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u2-C4","difficulty":4,"kind":"essay","stem":"우유가 4갑씩 6줄 놓여 있어요. 이것을 8갑씩 다시 놓으면 몇 줄인지 구하고, 4단과 8단이 어떻게 이어져 있는지 설명해 보세요.","answer_guide":{"answer":"예: 4 × 6 = 24갑이다. 4갑씩 두 줄을 합치면 8갑씩 한 줄이 되므로 8갑씩 3줄, 8 × 3 = 24이다. 8단의 곱은 같은 수를 곱한 4단의 곱의 2배이다.","scoring_points":["우유가 24갑임을 구했는가","8갑씩 3줄이 된다고 썼는가","4갑씩 두 줄이 8갑씩 한 줄이라는 관계를 썼는가"]},"explanation":["4 × 6 = 24예요.","4씩 두 묶음이 8이에요.","그래서 4갑씩 6줄은 8갑씩 3줄과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_challenge#10','math',2,2,'u2','L05','g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',4,'mc','auto','구슬을 하린이는 4개씩 7묶음, 지호는 8개씩 3묶음 가지고 있어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u2-X19','M2-2-u2-X13','M2-2-u2-X02']::text[],false,'{"seq":10,"concept":"M2-2-u2-C4","difficulty":4,"kind":"mc","stem":"구슬을 하린이는 4개씩 7묶음, 지호는 8개씩 3묶음 가지고 있어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"하린이가 4개 더 많아요","correct":true},{"t":"지호가 4개 더 많아요","mis":"M2-2-u2-X19"},{"t":"두 사람의 구슬 수가 같아요","mis":"M2-2-u2-X13"},{"t":"하린이가 2개 더 많아요","mis":"M2-2-u2-X02"}],"explanation":["하린이는 4 × 7 = 28개예요.","지호는 8 × 3 = 24개예요.","28 − 24 = 4이니 하린이가 4개 더 많아요 — 8이 크다고 지호가 많은 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_basic#1','math',2,2,'u2','L06','g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',1,'sa','auto','7씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u2-C5","difficulty":1,"kind":"sa","stem":"7씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["7씩 커지는 수예요.","21에서 7만큼 더 뛰면 28이에요.","7씩 4번 뛰어 센 수 — 7씩 4묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip","ks":[7],"pmax":45}},"answer":["28"],"asset":{"type":"jump_row","cells":[7,14,21,null],"step":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_basic#2','math',2,2,'u2','L06','g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',1,'sa','auto','7 × 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u2-C5","difficulty":1,"kind":"sa","stem":"7 × 2는 얼마인가요? 숫자로 쓰세요.","explanation":["7 × 2는 7의 2배예요.","7씩 뛰어 세면 7, 14.","그래서 7 × 2 = 14예요."],"variant_rule":{"mul":{"ask":"value","ks":[7],"pmax":81}},"answer":["14"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_basic#3','math',2,2,'u2','L06','g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',1,'mc','auto','그림을 보세요. 별은 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X05']::text[],true,'{"seq":3,"concept":"M2-2-u2-C5","difficulty":1,"kind":"mc","stem":"그림을 보세요. 별은 모두 몇 개인가요?","explanation":["7개씩 3묶음이에요.","7씩 뛰어 세면 7, 14, 21.","별은 모두 21개예요."],"variant_rule":{"mul":{"ask":"total","ks":[7],"pmax":45}},"options":[{"t":"21개","correct":true},{"t":"10개","mis":"M2-2-u2-X06"},{"t":"3개","mis":"M2-2-u2-X05"}],"asset":{"type":"mul_groups","item":"⭐","k":7,"n":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_basic#4','math',2,2,'u2','L06','g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',1,'mc','auto','로봇이 한 번 움직일 때마다 7칸씩 가요. 로봇이 3번 움직이면 모두 몇 칸 가나요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],true,'{"seq":4,"concept":"M2-2-u2-C5","difficulty":1,"kind":"mc","stem":"로봇이 한 번 움직일 때마다 7칸씩 가요. 로봇이 3번 움직이면 모두 몇 칸 가나요?","options":[{"t":"21칸","correct":true},{"t":"10칸","mis":"M2-2-u2-X06"},{"t":"14칸","mis":"M2-2-u2-X02"}],"explanation":["한 번에 7칸씩, 3번이에요.","7 × 3 = 21이에요.","7, 14, 21로 뛰어 세어도 21칸이에요."],"variant_rule":{"alt":[{"stem":"로봇이 한 번 움직일 때마다 7칸씩 가요. 로봇이 4번 움직이면 모두 몇 칸 가나요?","options":[{"t":"28칸","correct":true},{"t":"11칸","mis":"M2-2-u2-X06"},{"t":"21칸","mis":"M2-2-u2-X02"}],"explanation":["한 번에 7칸씩, 4번이에요.","7 × 4 = 28이에요.","7, 14, 21, 28로 뛰어 세어도 28칸이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_basic#5','math',2,2,'u2','L06','g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',2,'mc','auto','7 × 5 = 35예요. 이것을 이용하면 7 × 6은 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17','M2-2-u2-X02']::text[],true,'{"seq":5,"concept":"M2-2-u2-C5","difficulty":2,"kind":"mc","stem":"7 × 5 = 35예요. 이것을 이용하면 7 × 6은 얼마인가요?","explanation":["7 × 6은 7 × 5보다 7만큼 더 커요.","35 + 7 = 42예요.","한 번 더 더할 때는 곱하는 수 6이 아니라 7을 더해요."],"variant_rule":{"gugu":{"ask":"build","ks":[7]}},"options":[{"t":"42","correct":true},{"t":"36","mis":"M2-2-u2-X01"},{"t":"41","mis":"M2-2-u2-X17"},{"t":"49","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_basic#6','math',2,2,'u2','L06','g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',2,'ox','auto','7 × 6과 6 × 7은 곱이 같아요.',ARRAY['M2-2-u2-X13']::text[],true,'{"seq":6,"concept":"M2-2-u2-C5","difficulty":2,"kind":"ox","stem":"7 × 6과 6 × 7은 곱이 같아요.","answer":"O","reason_options":[{"t":"7씩 6줄과 6씩 7줄은 같은 42개를 다르게 묶은 것이니까","correct":true},{"t":"곱하는 두 수의 순서가 바뀌면 곱도 바뀌니까","mis":"M2-2-u2-X13"}],"mis":"M2-2-u2-X13","explanation":["7 × 6 = 42예요.","6 × 7 = 42예요.","그래서 7 × 6은 6단으로도 구할 수 있어요."],"variant_rule":{"alt":[{"stem":"7 × 5 = 35에 5를 더하면 7 × 6이에요.","answer":"X","reason_options":[{"t":"35에 7을 더해야 7 × 6 = 42가 되니까","correct":true},{"t":"곱하는 수만큼 더하면 되니까","mis":"M2-2-u2-X17"}],"explanation":["7 × 6은 7 × 5보다 7만큼 커요.","35 + 7 = 42예요.","35 + 5 = 40은 7 × 6이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_basic#7','math',2,2,'u2','L06','g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',2,'match','auto','곱셈식과 곱을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u2-C5","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 이으세요.","pairs":[{"l":"7 × 3","r":"21"},{"l":"7 × 5","r":"35"},{"l":"7 × 8","r":"56"}],"mis":"M2-2-u2-X02","explanation":["7 × 3은 7, 14, 21로 21이에요.","7 × 5는 7씩 5번 뛰어 35예요.","7 × 8은 7씩 8번 뛰어 56이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 곱을 이으세요.","pairs":[{"l":"7 × 4","r":"28"},{"l":"7 × 6","r":"42"},{"l":"7 × 9","r":"63"}],"explanation":["7 × 4는 7씩 4번 뛰어 28이에요.","7 × 6은 7씩 6번 뛰어 42예요.","7 × 9는 7씩 9번 뛰어 63이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_basic#8','math',2,2,'u2','L06','g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',2,'mc','auto','주머니 한 개에 구슬이 7개씩 있어요. 주머니 5개의 구슬은 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X14']::text[],true,'{"seq":8,"concept":"M2-2-u2-C5","difficulty":2,"kind":"mc","stem":"주머니 한 개에 구슬이 7개씩 있어요. 주머니 5개의 구슬은 모두 몇 개인가요?","explanation":["주머니 한 개에 7개씩, 5개이면 7씩 5묶음이에요.","7 × 5 = 35예요.","구슬은 모두 35개예요."],"variant_rule":{"mul":{"ask":"story","pmax":81,"per":[7]}},"options":[{"t":"35개","correct":true},{"t":"12개","mis":"M2-2-u2-X06"},{"t":"5개","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_basic#9','math',2,2,'u2','L06','g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',2,'mc','auto','7 × □ = 56에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02']::text[],true,'{"seq":9,"concept":"M2-2-u2-C5","difficulty":2,"kind":"mc","stem":"7 × □ = 56에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["7단 곱셈구구에서 곱이 56인 것을 찾아요.","7씩 뛰어 세면 7, 14, 21, 28, 35, 42, 49, 56 — 8번이에요.","7 × 8 = 56이라 □는 8이에요."],"variant_rule":{"gugu":{"ask":"miss","ks":[7]}},"options":[{"t":"8","correct":true},{"t":"9","mis":"M2-2-u2-X02"},{"t":"7","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_basic#10','math',2,2,'u2','L06','g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',3,'error','auto','7씩 뛰는 로봇이 수직선에서 7 × 3인 21까지 왔어요. 7 × 5까지 가려면 얼마나 더 가야 하는지 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X15']::text[],true,'{"seq":10,"concept":"M2-2-u2-C5","difficulty":3,"kind":"error","stem":"7씩 뛰는 로봇이 수직선에서 7 × 3인 21까지 왔어요. 7 × 5까지 가려면 얼마나 더 가야 하는지 잘못 말한 친구는 누구인가요?","options":[{"t":"다예 — 「21에서 2만큼 더 가면 돼.」","correct":true,"mis_target":"M2-2-u2-X17"},{"t":"곰이 — 「7 × 2만큼, 14만큼 더 가야 해.」","mis":"M2-2-u2-X15"},{"t":"펭이 — 「7 × 5 = 35니까 35까지 가야 해.」","mis":"M2-2-u2-X15"}],"explanation":["3번 간 로봇이 5번까지 가려면 2번 더 가야 해요.","한 번에 7칸씩이니 7 × 2 = 14만큼 더 가요 — 21 + 14 = 35예요.","다예는 7 × 2 대신 2만 더했어요."],"variant_rule":{"alt":[{"stem":"7씩 뛰는 로봇이 수직선에서 7 × 4인 28까지 왔어요. 7 × 6까지 가려면 얼마나 더 가야 하는지 잘못 말한 친구는 누구인가요?","options":[{"t":"하루 — 「28에서 2만큼 더 가면 돼.」","correct":true,"mis_target":"M2-2-u2-X17"},{"t":"서아 — 「7 × 2만큼, 14만큼 더 가야 해.」","mis":"M2-2-u2-X15"},{"t":"지우 — 「7 × 6 = 42니까 42까지 가야 해.」","mis":"M2-2-u2-X15"}],"explanation":["4번 간 로봇이 6번까지 가려면 2번 더 가야 해요.","7 × 2 = 14만큼 더 가요 — 28 + 14 = 42예요.","하루는 7 × 2 대신 2만 더했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_challenge#1','math',2,2,'u2','L06','g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',2,'mc','auto','7 × 9는 7 × 8보다 얼마 더 큰가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17']::text[],true,'{"seq":1,"concept":"M2-2-u2-C5","difficulty":2,"kind":"mc","stem":"7 × 9는 7 × 8보다 얼마 더 큰가요?","explanation":["7 × 8은 7을 8번, 7 × 9는 7을 9번 더한 것이에요.","7을 한 번 더 더했으니 7만큼 더 커요 — 56에서 63.","곱하는 수가 1 커지면 곱은 7만큼 커져요."],"variant_rule":{"gugu":{"ask":"next","ks":[7]}},"options":[{"t":"7","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"9","mis":"M2-2-u2-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_challenge#2','math',2,2,'u2','L06','g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',2,'mc','auto','그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X03']::text[],true,'{"seq":2,"concept":"M2-2-u2-C5","difficulty":2,"kind":"mc","stem":"그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["한 줄에 7송이씩 4줄이에요.","7의 4배이니 곱셈식으로 7 × 4예요.","7 × 4 = 28, 모두 28송이예요."],"variant_rule":{"mul":{"ask":"expr","look":"rows","ks":[7],"pmax":45}},"options":[{"t":"7 × 4","correct":true},{"t":"7 + 4","mis":"M2-2-u2-X11"},{"t":"7 × 5","mis":"M2-2-u2-X03"}],"asset":{"type":"mul_groups","item":"🌷","k":7,"n":4,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_challenge#3','math',2,2,'u2','L06','g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',3,'mc','auto','사탕이 7개씩 6봉지 있어요. 사탕의 수를 바르게 구한 것은 어느 것인가요?',ARRAY['M2-2-u2-X03','M2-2-u2-X11']::text[],false,'{"seq":3,"concept":"M2-2-u2-C5","difficulty":3,"kind":"mc","stem":"사탕이 7개씩 6봉지 있어요. 사탕의 수를 바르게 구한 것은 어느 것인가요?","options":[{"t":"7 × 6 = 42","correct":true},{"t":"7 × 5 = 35","mis":"M2-2-u2-X03"},{"t":"7 + 6 = 13","mis":"M2-2-u2-X11"}],"explanation":["한 봉지에 7개씩, 6봉지예요.","7 × 6이에요.","7 × 5 = 35에 7을 더하면 42예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_challenge#4','math',2,2,'u2','L06','g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',3,'mc','auto','의자가 한 줄에 6개씩 7줄 있어요. 의자의 수를 구하는 곱셈식으로 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X03']::text[],false,'{"seq":4,"concept":"M2-2-u2-C5","difficulty":3,"kind":"mc","stem":"의자가 한 줄에 6개씩 7줄 있어요. 의자의 수를 구하는 곱셈식으로 알맞은 것은 어느 것인가요?","options":[{"t":"7 × 6","correct":true},{"t":"6 + 7","mis":"M2-2-u2-X11"},{"t":"6 × 6","mis":"M2-2-u2-X03"},{"t":"7 × 7","mis":"M2-2-u2-X03"}],"explanation":["한 줄에 6개씩 7줄이니 6 × 7 = 42예요.","두 수를 바꾸어 곱해도 곱이 같아요 — 7 × 6 = 42예요.","그래서 7 × 6으로도 구할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_challenge#5','math',2,2,'u2','L06','g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',3,'mc','auto','두 곱의 크기를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_challenge#6','math',2,2,'u2','L06','g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',3,'mc','auto','□ × 6 = 42에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02','M2-2-u2-X06']::text[],true,'{"seq":6,"concept":"M2-2-u2-C5","difficulty":3,"kind":"mc","stem":"□ × 6 = 42에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["몇 단 곱셈구구에서 6번째 곱이 42인지 찾아요.","7 × 6 = 42예요 — 8 × 6 = 48이에요.","그래서 □는 7이에요."],"variant_rule":{"gugu":{"ask":"miss","ks":[7]}},"options":[{"t":"7","correct":true},{"t":"8","mis":"M2-2-u2-X02"},{"t":"6","mis":"M2-2-u2-X02"},{"t":"36","mis":"M2-2-u2-X06"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_challenge#7','math',2,2,'u2','L06','g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',3,'mc','auto','일주일은 7일이에요. 3주와 2일은 모두 며칠인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":7,"concept":"M2-2-u2-C5","difficulty":3,"kind":"mc","stem":"일주일은 7일이에요. 3주와 2일은 모두 며칠인가요?","options":[{"t":"23일","correct":true},{"t":"21일","mis":"M2-2-u2-X18"},{"t":"12일","mis":"M2-2-u2-X06"},{"t":"28일","mis":"M2-2-u2-X02"}],"explanation":["3주는 7 × 3 = 21일이에요.","거기에 2일이 더 있어요.","21 + 2 = 23이니 23일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_challenge#8','math',2,2,'u2','L06','g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',4,'essay','teacher','7 × 6을 두 가지 방법으로 구하고, 각 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C5","difficulty":4,"kind":"essay","stem":"7 × 6을 두 가지 방법으로 구하고, 각 방법을 설명해 보세요.","answer_guide":{"answer":"예: 7 × 5 = 35에 7을 한 번 더 더하면 42이다. 7씩 6줄을 6씩 7줄로 보면 6 × 7 = 42이다.","scoring_points":["7 × 5에 7을 더하는 방법으로 42를 구했는가","6 × 7로 바꾸어 보거나 다른 방법으로 42를 구했는가","7 × 6 = 42라고 썼는가"]},"explanation":["7 × 6은 7 × 5보다 7만큼 커요.","7 × 6과 6 × 7은 곱이 같아요.","어느 방법으로든 42예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_challenge#9','math',2,2,'u2','L06','g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',4,'essay','teacher','로봇이 한 번에 7칸씩 가요. 3번 움직인 로봇이 모두 5번 움직이려면 얼마나 더 가야 하는지 곱셈구구로 구하고 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u2-C5","difficulty":4,"kind":"essay","stem":"로봇이 한 번에 7칸씩 가요. 3번 움직인 로봇이 모두 5번 움직이려면 얼마나 더 가야 하는지 곱셈구구로 구하고 설명해 보세요.","answer_guide":{"answer":"예: 2번 더 움직여야 하므로 7 × 2 = 14만큼 더 가야 한다. 7 × 3 = 21에 14를 더하면 35 = 7 × 5이다.","scoring_points":["2번 더 움직여야 한다고 썼는가","7 × 2 = 14만큼 더 가야 한다고 구했는가","21 + 14 = 35 = 7 × 5임을 확인했는가"]},"explanation":["5번 − 3번 = 2번 더 움직여요.","한 번에 7칸이니 7 × 2 = 14칸이에요.","7 × 5는 7 × 3과 7 × 2를 더한 것과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_challenge#10','math',2,2,'u2','L06','g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',4,'mc','auto','7단 곱셈구구의 곱 가운데 30보다 크고 50보다 작은 수는 모두 몇 개인가요?',ARRAY['M2-2-u2-X02','M2-2-u2-X15']::text[],false,'{"seq":10,"concept":"M2-2-u2-C5","difficulty":4,"kind":"mc","stem":"7단 곱셈구구의 곱 가운데 30보다 크고 50보다 작은 수는 모두 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"2개","mis":"M2-2-u2-X02"},{"t":"4개","mis":"M2-2-u2-X02"},{"t":"5개","mis":"M2-2-u2-X15"}],"explanation":["7단의 곱은 7, 14, 21, 28, 35, 42, 49, 56, 63이에요.","30보다 크고 50보다 작은 수는 35, 42, 49예요.","그래서 모두 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_basic#1','math',2,2,'u2','L07','g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',1,'sa','auto','9씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u2-C6","difficulty":1,"kind":"sa","stem":"9씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["9씩 커지는 수예요.","27에서 9만큼 더 뛰면 36이에요.","9씩 4번 뛰어 센 수 — 9씩 4묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip","ks":[9],"pmax":45}},"answer":["36"],"asset":{"type":"jump_row","cells":[9,18,27,null],"step":9}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_basic#2','math',2,2,'u2','L07','g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',1,'sa','auto','9 × 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u2-C6","difficulty":1,"kind":"sa","stem":"9 × 3은 얼마인가요? 숫자로 쓰세요.","explanation":["9 × 3은 9의 3배예요.","9씩 뛰어 세면 9, 18, 27.","그래서 9 × 3 = 27이에요."],"variant_rule":{"mul":{"ask":"value","ks":[9],"pmax":81}},"answer":["27"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_basic#3','math',2,2,'u2','L07','g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',1,'mc','auto','상자 한 개에 야구공이 9개씩 있어요. 상자 4개의 야구공은 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X14']::text[],true,'{"seq":3,"concept":"M2-2-u2-C6","difficulty":1,"kind":"mc","stem":"상자 한 개에 야구공이 9개씩 있어요. 상자 4개의 야구공은 모두 몇 개인가요?","explanation":["상자 한 개에 9개씩, 4개이면 9씩 4묶음이에요.","9 × 4 = 36이에요.","야구공은 모두 36개예요."],"variant_rule":{"mul":{"ask":"story","pmax":81,"per":[9]}},"options":[{"t":"36개","correct":true},{"t":"13개","mis":"M2-2-u2-X06"},{"t":"4개","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_basic#4','math',2,2,'u2','L07','g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',1,'mc','auto','9단 곱셈구구에서 곱하는 수가 1 커지면 곱은 얼마씩 커지나요?',ARRAY['M2-2-u2-X01','M2-2-u2-X02']::text[],true,'{"seq":4,"concept":"M2-2-u2-C6","difficulty":1,"kind":"mc","stem":"9단 곱셈구구에서 곱하는 수가 1 커지면 곱은 얼마씩 커지나요?","options":[{"t":"9","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"10","mis":"M2-2-u2-X02"}],"explanation":["9단의 곱은 9, 18, 27, 36, …이에요.","곱하는 수가 1 커질 때마다 9를 한 번 더 더해요.","그래서 곱은 9씩 커져요."],"variant_rule":{"alt":[{"stem":"야구공이 한 상자에 9개씩 있어요. 상자가 한 개 늘어나면 야구공은 몇 개 더 많아지나요?","options":[{"t":"9개","correct":true},{"t":"1개","mis":"M2-2-u2-X01"},{"t":"10개","mis":"M2-2-u2-X02"}],"explanation":["상자 한 개에 9개씩이에요.","상자가 하나 늘면 9개가 더 생겨요.","9단 곱셈구구의 곱은 9씩 커져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_basic#5','math',2,2,'u2','L07','g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',2,'mc','auto','9 × 4 = 36이에요. 이것을 이용하면 9 × 5는 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17','M2-2-u2-X02']::text[],true,'{"seq":5,"concept":"M2-2-u2-C6","difficulty":2,"kind":"mc","stem":"9 × 4 = 36이에요. 이것을 이용하면 9 × 5는 얼마인가요?","explanation":["9 × 5는 9 × 4보다 9만큼 더 커요.","36 + 9 = 45예요.","한 번 더 더할 때는 곱하는 수 5가 아니라 9를 더해요."],"variant_rule":{"gugu":{"ask":"build","ks":[9]}},"options":[{"t":"45","correct":true},{"t":"37","mis":"M2-2-u2-X01"},{"t":"41","mis":"M2-2-u2-X17"},{"t":"54","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_basic#6','math',2,2,'u2','L07','g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',2,'ox','auto','9 × 2부터 9 × 9까지의 곱은 십의 자리 숫자와 일의 자리 숫자를 더하면 9예요.',ARRAY['M2-2-u2-X16']::text[],true,'{"seq":6,"concept":"M2-2-u2-C6","difficulty":2,"kind":"ox","stem":"9 × 2부터 9 × 9까지의 곱은 십의 자리 숫자와 일의 자리 숫자를 더하면 9예요.","answer":"O","reason_options":[{"t":"18, 27, 36처럼 1 + 8, 2 + 7, 3 + 6이 모두 9니까","correct":true},{"t":"곱하는 수가 1씩 커지니까","mis":"M2-2-u2-X16"}],"mis":"M2-2-u2-X16","explanation":["9단의 곱은 18, 27, 36, 45, 54, 63, 72, 81이에요.","두 숫자를 더하면 모두 9예요.","십의 자리는 1씩 커지고 일의 자리는 1씩 작아져요."],"variant_rule":{"alt":[{"stem":"9 × 6의 곱 54는 십의 자리 숫자가 6이에요.","answer":"X","reason_options":[{"t":"54의 십의 자리 숫자는 5니까 — 곱하는 수보다 1 작아요","correct":true},{"t":"곱하는 수와 십의 자리 숫자가 같으니까","mis":"M2-2-u2-X16"}],"explanation":["9 × 6 = 54예요.","십의 자리 숫자는 5, 일의 자리 숫자는 4예요.","9단에서 곱의 십의 자리 숫자는 곱하는 수보다 1 작아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_basic#7','math',2,2,'u2','L07','g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',2,'match','auto','곱셈식과 곱을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u2-C6","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 이으세요.","pairs":[{"l":"9 × 2","r":"18"},{"l":"9 × 5","r":"45"},{"l":"9 × 7","r":"63"}],"mis":"M2-2-u2-X02","explanation":["9 × 2는 9, 18로 18이에요.","9 × 5는 9씩 5번 뛰어 45예요.","9 × 7은 9씩 7번 뛰어 63이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 곱을 이으세요.","pairs":[{"l":"9 × 3","r":"27"},{"l":"9 × 6","r":"54"},{"l":"9 × 8","r":"72"}],"explanation":["9 × 3은 9, 18, 27로 27이에요.","9 × 6은 9씩 6번 뛰어 54예요.","9 × 8은 9씩 8번 뛰어 72예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_basic#8','math',2,2,'u2','L07','g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',2,'mc','auto','9 × □ = 54에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02']::text[],true,'{"seq":8,"concept":"M2-2-u2-C6","difficulty":2,"kind":"mc","stem":"9 × □ = 54에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["9단 곱셈구구에서 곱이 54인 것을 찾아요.","9씩 뛰어 세면 9, 18, 27, 36, 45, 54 — 6번이에요.","9 × 6 = 54라 □는 6이에요."],"variant_rule":{"gugu":{"ask":"miss","ks":[9]}},"options":[{"t":"6","correct":true},{"t":"7","mis":"M2-2-u2-X02"},{"t":"5","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_basic#9','math',2,2,'u2','L07','g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',2,'mc','auto','9 × 8은 9 × 7보다 얼마 더 큰가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17']::text[],true,'{"seq":9,"concept":"M2-2-u2-C6","difficulty":2,"kind":"mc","stem":"9 × 8은 9 × 7보다 얼마 더 큰가요?","explanation":["9 × 7은 9를 7번, 9 × 8은 9를 8번 더한 것이에요.","9를 한 번 더 더했으니 9만큼 더 커요 — 63에서 72.","곱하는 수가 1 커지면 곱은 9만큼 커져요."],"variant_rule":{"gugu":{"ask":"next","ks":[9]}},"options":[{"t":"9","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"8","mis":"M2-2-u2-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_basic#10','math',2,2,'u2','L07','g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',3,'error','auto','9 × 5를 9 × 2와 9 × 3을 이용해 구했어요. 잘못 구한 친구는 누구인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X15']::text[],true,'{"seq":10,"concept":"M2-2-u2-C6","difficulty":3,"kind":"error","stem":"9 × 5를 9 × 2와 9 × 3을 이용해 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"서윤 — 「2와 3을 더하면 5니까 9 × 5 = 5야.」","correct":true,"mis_target":"M2-2-u2-X17"},{"t":"도윤 — 「18 + 27 = 45니까 9 × 5 = 45야.」","mis":"M2-2-u2-X15"},{"t":"은솔 — 「9 × 4 = 36에 9를 더해도 45야.」","mis":"M2-2-u2-X15"}],"explanation":["9 × 5는 9 × 2와 9 × 3의 곱을 더한 것과 같아요.","18 + 27 = 45예요.","서윤이는 두 곱 대신 2와 3만 더했어요."],"variant_rule":{"alt":[{"stem":"9 × 6을 9 × 3과 9 × 3을 이용해 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"예린 — 「3과 3을 더하면 6이니까 9 × 6 = 6이야.」","correct":true,"mis_target":"M2-2-u2-X17"},{"t":"태민 — 「27 + 27 = 54니까 9 × 6 = 54야.」","mis":"M2-2-u2-X15"},{"t":"아린 — 「9 × 5 = 45에 9를 더해도 54야.」","mis":"M2-2-u2-X15"}],"explanation":["9 × 6은 9 × 3의 곱을 두 번 더한 것과 같아요.","27 + 27 = 54예요.","예린이는 두 곱 대신 3과 3만 더했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_challenge#1','math',2,2,'u2','L07','g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',2,'mc','auto','그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X03']::text[],true,'{"seq":1,"concept":"M2-2-u2-C6","difficulty":2,"kind":"mc","stem":"그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["9개씩 3묶음이에요.","9의 3배이니 곱셈식으로 9 × 3이에요.","9 × 3 = 27, 모두 27개예요."],"variant_rule":{"mul":{"ask":"expr","ks":[9],"pmax":45}},"options":[{"t":"9 × 3","correct":true},{"t":"9 + 3","mis":"M2-2-u2-X11"},{"t":"9 × 4","mis":"M2-2-u2-X03"}],"asset":{"type":"mul_groups","item":"⚽","k":9,"n":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_challenge#2','math',2,2,'u2','L07','g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',2,'mc','auto','두 곱의 크기를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_challenge#3','math',2,2,'u2','L07','g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',3,'mc','auto','곱의 십의 자리 숫자가 4, 일의 자리 숫자가 5인 9단 곱셈구구는 어느 것인가요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":3,"concept":"M2-2-u2-C6","difficulty":3,"kind":"mc","stem":"곱의 십의 자리 숫자가 4, 일의 자리 숫자가 5인 9단 곱셈구구는 어느 것인가요?","options":[{"t":"9 × 5","correct":true},{"t":"9 × 4","mis":"M2-2-u2-X16"},{"t":"9 × 6","mis":"M2-2-u2-X16"}],"explanation":["십의 자리 숫자가 4, 일의 자리 숫자가 5인 수는 45예요.","9 × 5 = 45예요.","9 × 4 = 36, 9 × 6 = 54예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_challenge#4','math',2,2,'u2','L07','g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',3,'mc','auto','□ × 7 = 63에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02','M2-2-u2-X06']::text[],true,'{"seq":4,"concept":"M2-2-u2-C6","difficulty":3,"kind":"mc","stem":"□ × 7 = 63에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["몇 단 곱셈구구에서 7번째 곱이 63인지 찾아요.","9 × 7 = 63이에요 — 8 × 7 = 56이에요.","그래서 □는 9예요."],"variant_rule":{"gugu":{"ask":"miss","ks":[9]}},"options":[{"t":"9","correct":true},{"t":"7","mis":"M2-2-u2-X02"},{"t":"8","mis":"M2-2-u2-X02"},{"t":"56","mis":"M2-2-u2-X06"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_challenge#5','math',2,2,'u2','L07','g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',3,'mc','auto','야구공이 한 상자에 9개씩 7상자 있어요. 그중 2상자를 친구에게 주었어요. 남은 야구공은 몇 개인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X05','M2-2-u2-X02']::text[],false,'{"seq":5,"concept":"M2-2-u2-C6","difficulty":3,"kind":"mc","stem":"야구공이 한 상자에 9개씩 7상자 있어요. 그중 2상자를 친구에게 주었어요. 남은 야구공은 몇 개인가요?","options":[{"t":"45개","correct":true},{"t":"63개","mis":"M2-2-u2-X18"},{"t":"18개","mis":"M2-2-u2-X05"},{"t":"54개","mis":"M2-2-u2-X02"}],"explanation":["남은 상자는 7 − 2 = 5상자예요.","9 × 5 = 45예요.","63개는 처음에 있던 야구공의 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_challenge#6','math',2,2,'u2','L07','g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',3,'mc','auto','9단 곱셈구구의 곱이 아닌 것은 어느 것인가요?',ARRAY['M2-2-u2-X15']::text[],false,'{"seq":6,"concept":"M2-2-u2-C6","difficulty":3,"kind":"mc","stem":"9단 곱셈구구의 곱이 아닌 것은 어느 것인가요?","options":[{"t":"56","correct":true},{"t":"54","mis":"M2-2-u2-X15"},{"t":"63","mis":"M2-2-u2-X15"},{"t":"81","mis":"M2-2-u2-X15"}],"explanation":["9단의 곱은 9, 18, 27, 36, 45, 54, 63, 72, 81이에요.","56은 5 + 6 = 11로 두 숫자의 합이 9가 아니에요.","56 = 7 × 8은 7단·8단의 곱이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_challenge#7','math',2,2,'u2','L07','g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',3,'ox','auto','9 × 4의 곱은 9 × 3의 곱보다 1 커요.',ARRAY['M2-2-u2-X01']::text[],false,'{"seq":7,"concept":"M2-2-u2-C6","difficulty":3,"kind":"ox","stem":"9 × 4의 곱은 9 × 3의 곱보다 1 커요.","answer":"X","reason_options":[{"t":"9를 한 번 더 더하니 27에서 36으로 9 커지니까","correct":true},{"t":"곱하는 수가 1 커졌으니 곱도 1 커지니까","mis":"M2-2-u2-X01"}],"mis":"M2-2-u2-X01","explanation":["9 × 3 = 27, 9 × 4 = 36이에요.","36 − 27 = 9예요.","곱하는 수가 1 커지면 9단의 곱은 9씩 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_challenge#8','math',2,2,'u2','L07','g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',4,'essay','teacher','9 × 5를 두 가지 방법으로 구하고, 각 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C6","difficulty":4,"kind":"essay","stem":"9 × 5를 두 가지 방법으로 구하고, 각 방법을 설명해 보세요.","answer_guide":{"answer":"예: 9 × 4 = 36에 9를 한 번 더 더하면 45이다. 9 × 2 = 18과 9 × 3 = 27을 더하면 45이다.","scoring_points":["9 × 4에 9를 더하는 방법으로 45를 구했는가","9 × 2와 9 × 3의 곱을 더하는 등 다른 방법으로 45를 구했는가","9 × 5 = 45라고 썼는가"]},"explanation":["9 × 5는 9 × 4보다 9만큼 커요.","9씩 5묶음은 9씩 2묶음과 9씩 3묶음을 합친 것이에요.","두 곱을 더해야지 2와 3을 더하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_challenge#9','math',2,2,'u2','L07','g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',4,'essay','teacher','9단 곱셈구구의 곱을 모두 쓰고, 곱에서 찾을 수 있는 규칙을 두 가지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u2-C6","difficulty":4,"kind":"essay","stem":"9단 곱셈구구의 곱을 모두 쓰고, 곱에서 찾을 수 있는 규칙을 두 가지 써 보세요.","answer_guide":{"answer":"예: 9, 18, 27, 36, 45, 54, 63, 72, 81. 곱이 9씩 커진다. 십의 자리 숫자는 1씩 커지고 일의 자리 숫자는 1씩 작아지며, 두 숫자를 더하면 9이다.","scoring_points":["9단의 곱을 바르게 썼는가","곱이 9씩 커진다는 규칙을 썼는가","십의 자리·일의 자리 숫자의 규칙이나 두 숫자의 합이 9라는 규칙을 썼는가"]},"explanation":["9단의 곱은 9씩 커져요.","십의 자리는 1씩 커지고 일의 자리는 1씩 작아져요.","18부터는 두 숫자의 합이 늘 9예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_challenge#10','math',2,2,'u2','L07','g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',4,'mc','auto','9 × □의 곱은 50보다 크고 60보다 작아요. □에 알맞은 수는 어느 것인가요?',ARRAY['M2-2-u2-X02','M2-2-u2-X05']::text[],false,'{"seq":10,"concept":"M2-2-u2-C6","difficulty":4,"kind":"mc","stem":"9 × □의 곱은 50보다 크고 60보다 작아요. □에 알맞은 수는 어느 것인가요?","options":[{"t":"6","correct":true},{"t":"5","mis":"M2-2-u2-X02"},{"t":"7","mis":"M2-2-u2-X02"},{"t":"54","mis":"M2-2-u2-X05"}],"explanation":["9 × 5 = 45, 9 × 6 = 54, 9 × 7 = 63이에요.","50보다 크고 60보다 작은 곱은 54예요.","□는 곱 54가 아니라 곱하는 수 6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_basic#1','math',2,2,'u2','L08','g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',1,'sa','auto','1 × 6은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u2-C7","difficulty":1,"kind":"sa","stem":"1 × 6은 얼마인가요? 숫자로 쓰세요.","explanation":["1 × 6은 1을 6번 더한 것이에요.","1과 어떤 수의 곱, 어떤 수와 1의 곱은 늘 그 수예요.","그래서 1 × 6 = 6이에요."],"variant_rule":{"gugu":{"ask":"zero","forms":["o1","n1"]}},"answer":["6"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_basic#2','math',2,2,'u2','L08','g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',1,'mc','auto','0 × 4는 얼마인가요?',ARRAY['M2-2-u2-X08']::text[],true,'{"seq":2,"concept":"M2-2-u2-C7","difficulty":1,"kind":"mc","stem":"0 × 4는 얼마인가요?","explanation":["0 × 4는 0을 4번 더한 것이에요.","0과 어떤 수의 곱, 어떤 수와 0의 곱은 늘 0이에요.","그래서 0 × 4 = 0이에요."],"variant_rule":{"gugu":{"ask":"zero","forms":["z0","n0"]}},"options":[{"t":"0","correct":true},{"t":"4","mis":"M2-2-u2-X08"},{"t":"1","mis":"M2-2-u2-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_basic#3','math',2,2,'u2','L08','g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',1,'mc','auto','상자 한 개에 인형이 1개씩 들어 있어요. 상자 7개에 든 인형은 모두 몇 개인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X06']::text[],true,'{"seq":3,"concept":"M2-2-u2-C7","difficulty":1,"kind":"mc","stem":"상자 한 개에 인형이 1개씩 들어 있어요. 상자 7개에 든 인형은 모두 몇 개인가요?","options":[{"t":"7개","correct":true},{"t":"1개","mis":"M2-2-u2-X08"},{"t":"8개","mis":"M2-2-u2-X06"}],"explanation":["상자 한 개에 1개씩, 7상자예요.","1 × 7 = 7이에요.","1을 7번 더하면 7이에요."],"variant_rule":{"alt":[{"stem":"상자 한 개에 인형이 1개씩 들어 있어요. 상자 5개에 든 인형은 모두 몇 개인가요?","options":[{"t":"5개","correct":true},{"t":"1개","mis":"M2-2-u2-X08"},{"t":"6개","mis":"M2-2-u2-X06"}],"explanation":["상자 한 개에 1개씩, 5상자예요.","1 × 5 = 5예요.","1을 5번 더하면 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_basic#4','math',2,2,'u2','L08','g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',1,'mc','auto','8 × 0은 얼마인가요?',ARRAY['M2-2-u2-X08']::text[],true,'{"seq":4,"concept":"M2-2-u2-C7","difficulty":1,"kind":"mc","stem":"8 × 0은 얼마인가요?","explanation":["8 × 0은 8을 0번 더한 것 — 하나도 없어요.","0과 어떤 수의 곱, 어떤 수와 0의 곱은 늘 0이에요.","그래서 8 × 0 = 0이에요."],"variant_rule":{"gugu":{"ask":"zero","forms":["z0","n0"]}},"options":[{"t":"0","correct":true},{"t":"8","mis":"M2-2-u2-X08"},{"t":"1","mis":"M2-2-u2-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_basic#5','math',2,2,'u2','L08','g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',2,'ox','auto','5 × 1 = 1입니다.',ARRAY['M2-2-u2-X08']::text[],true,'{"seq":5,"concept":"M2-2-u2-C7","difficulty":2,"kind":"ox","stem":"5 × 1 = 1입니다.","explanation":["5 × 1은 5를 한 번 더한 것이에요.","1과 어떤 수의 곱, 어떤 수와 1의 곱은 늘 그 수예요.","그래서 5 × 1 = 5예요."],"variant_rule":{"gugu":{"ask":"zero","forms":["o1","n1"]}},"answer":"X","reason_options":[{"t":"5 × 1은 1이 아니라 5가 되니까","correct":true},{"t":"1을 곱하면 1이 되니까","mis":"M2-2-u2-X08"}],"mis":"M2-2-u2-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_basic#6','math',2,2,'u2','L08','g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',2,'mc','auto','과녁 맞히기에서 0점에 3번 맞혔어요. 얻은 점수를 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u2-X08']::text[],true,'{"seq":6,"concept":"M2-2-u2-C7","difficulty":2,"kind":"mc","stem":"과녁 맞히기에서 0점에 3번 맞혔어요. 얻은 점수를 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"0 × 3 = 0","correct":true},{"t":"0 × 3 = 3","mis":"M2-2-u2-X08"},{"t":"3 × 0 = 3","mis":"M2-2-u2-X08"}],"explanation":["0점을 3번 — 0을 3번 더한 것이에요.","0 + 0 + 0 = 0이에요.","그래서 0 × 3 = 0이에요."],"variant_rule":{"alt":[{"stem":"과녁 맞히기에서 3점에는 한 번도 못 맞혔어요. 3점에서 얻은 점수를 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"3 × 0 = 0","correct":true},{"t":"3 × 0 = 3","mis":"M2-2-u2-X08"},{"t":"0 × 3 = 3","mis":"M2-2-u2-X08"}],"explanation":["3점을 0번 — 한 번도 더하지 않았어요.","그래서 얻은 점수는 0점이에요.","3 × 0 = 0이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_basic#7','math',2,2,'u2','L08','g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',2,'match','auto','곱셈식과 곱을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u2-C7","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 이으세요.","pairs":[{"l":"1 × 6","r":"6"},{"l":"3 × 0","r":"0"},{"l":"1 × 1","r":"1"}],"mis":"M2-2-u2-X08","explanation":["1 × 6은 1을 6번 더한 6이에요.","3 × 0은 3을 한 번도 더하지 않아 0이에요.","1 × 1은 1이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 곱을 이으세요.","pairs":[{"l":"8 × 1","r":"8"},{"l":"0 × 5","r":"0"},{"l":"1 × 3","r":"3"}],"explanation":["8 × 1은 8을 한 번 더한 8이에요.","0 × 5는 0을 5번 더해 0이에요.","1 × 3은 1을 3번 더한 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_basic#8','math',2,2,'u2','L08','g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',2,'ox','auto','0 × 7 = 0입니다.',ARRAY['M2-2-u2-X08']::text[],true,'{"seq":8,"concept":"M2-2-u2-C7","difficulty":2,"kind":"ox","stem":"0 × 7 = 0입니다.","explanation":["0 × 7은 0을 7번 더한 것이에요.","0과 어떤 수의 곱, 어떤 수와 0의 곱은 늘 0이에요.","그래서 0 × 7 = 0이에요."],"variant_rule":{"gugu":{"ask":"zero","forms":["z0","n0"]}},"answer":"O","reason_options":[{"t":"0을 7번 더해도 0이니까","correct":true},{"t":"0을 곱하면 그 수가 그대로 남으니까","mis":"M2-2-u2-X08"}],"mis":"M2-2-u2-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_basic#9','math',2,2,'u2','L08','g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',2,'ox','auto','1단 곱셈구구의 곱은 1씩 커져요.',ARRAY['M2-2-u2-X08']::text[],true,'{"seq":9,"concept":"M2-2-u2-C7","difficulty":2,"kind":"ox","stem":"1단 곱셈구구의 곱은 1씩 커져요.","answer":"O","reason_options":[{"t":"1 × 1 = 1, 1 × 2 = 2, 1 × 3 = 3처럼 1을 한 번씩 더 더하니까","correct":true},{"t":"1을 곱하면 언제나 1이니까","mis":"M2-2-u2-X08"}],"mis":"M2-2-u2-X08","explanation":["1단의 곱은 1, 2, 3, 4, 5, 6, 7, 8, 9예요.","1을 한 번 더 더할 때마다 1씩 커져요.","1과 어떤 수의 곱은 그 수예요."],"variant_rule":{"alt":[{"stem":"어떤 수에 0을 곱하면 그 수가 그대로예요.","answer":"X","reason_options":[{"t":"0번 더하면 아무것도 없어 0이니까","correct":true},{"t":"0은 아무것도 아니라 곱해도 그대로니까","mis":"M2-2-u2-X08"}],"explanation":["5 × 0은 5를 한 번도 더하지 않은 것이에요.","그래서 0이에요.","어떤 수와 0의 곱은 늘 0이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_basic#10','math',2,2,'u2','L08','g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',3,'mc','auto','과녁 맞히기에서 0점에 3번, 1점에 4번, 2점에 2번 맞혔어요. 얻은 점수는 모두 몇 점인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X05']::text[],true,'{"seq":10,"concept":"M2-2-u2-C7","difficulty":3,"kind":"mc","stem":"과녁 맞히기에서 0점에 3번, 1점에 4번, 2점에 2번 맞혔어요. 얻은 점수는 모두 몇 점인가요?","options":[{"t":"8점","correct":true},{"t":"11점","mis":"M2-2-u2-X08"},{"t":"9점","mis":"M2-2-u2-X05"}],"explanation":["0 × 3 = 0, 1 × 4 = 4, 2 × 2 = 4예요.","0 + 4 + 4 = 8이에요.","9는 맞힌 횟수를 더한 수예요 — 점수가 아니에요."],"variant_rule":{"alt":[{"stem":"과녁 맞히기에서 0점에 3번, 1점에 2번, 4점에 2번 맞혔어요. 얻은 점수는 모두 몇 점인가요?","options":[{"t":"10점","correct":true},{"t":"13점","mis":"M2-2-u2-X08"},{"t":"7점","mis":"M2-2-u2-X05"}],"explanation":["0 × 3 = 0, 1 × 2 = 2, 4 × 2 = 8이에요.","0 + 2 + 8 = 10이에요.","7은 맞힌 횟수를 더한 수예요 — 점수가 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_challenge#1','math',2,2,'u2','L08','g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',2,'sa','auto','9 × 0은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u2-C7","difficulty":2,"kind":"sa","stem":"9 × 0은 얼마인가요? 숫자로 쓰세요.","explanation":["9 × 0은 9를 0번 더한 것 — 하나도 없어요.","0과 어떤 수의 곱, 어떤 수와 0의 곱은 늘 0이에요.","그래서 9 × 0 = 0이에요."],"variant_rule":{"gugu":{"ask":"zero","forms":["z0","n0"]}},"answer":["0"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_challenge#2','math',2,2,'u2','L08','g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',2,'mc','auto','곱이 다른 하나는 어느 것인가요?',ARRAY['M2-2-u2-X15']::text[],false,'{"seq":2,"concept":"M2-2-u2-C7","difficulty":2,"kind":"mc","stem":"곱이 다른 하나는 어느 것인가요?","options":[{"t":"1 × 5","correct":true},{"t":"0 × 5","mis":"M2-2-u2-X15"},{"t":"5 × 0","mis":"M2-2-u2-X15"},{"t":"0 × 9","mis":"M2-2-u2-X15"}],"explanation":["1 × 5 = 5예요.","0 × 5, 5 × 0, 0 × 9는 모두 0이에요.","그래서 곱이 다른 하나는 1 × 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_challenge#3','math',2,2,'u2','L08','g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',3,'mc','auto','공 꺼내기 놀이에서 1이 적힌 공을 5번, 0이 적힌 공을 3번 꺼냈어요. 꺼낸 공에 적힌 수만큼 점수를 얻어요. 모두 몇 점인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X18']::text[],false,'{"seq":3,"concept":"M2-2-u2-C7","difficulty":3,"kind":"mc","stem":"공 꺼내기 놀이에서 1이 적힌 공을 5번, 0이 적힌 공을 3번 꺼냈어요. 꺼낸 공에 적힌 수만큼 점수를 얻어요. 모두 몇 점인가요?","options":[{"t":"5점","correct":true},{"t":"8점","mis":"M2-2-u2-X08"},{"t":"0점","mis":"M2-2-u2-X08"},{"t":"3점","mis":"M2-2-u2-X18"}],"explanation":["1 × 5 = 5, 0 × 3 = 0이에요.","5 + 0 = 5예요.","0이 적힌 공은 몇 번 꺼내도 0점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_challenge#4','math',2,2,'u2','L08','g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',3,'mc','auto','□ × 6 = 0에서 □ 안에 알맞은 수는 어느 것인가요?',ARRAY['M2-2-u2-X08']::text[],false,'{"seq":4,"concept":"M2-2-u2-C7","difficulty":3,"kind":"mc","stem":"□ × 6 = 0에서 □ 안에 알맞은 수는 어느 것인가요?","options":[{"t":"0","correct":true},{"t":"6","mis":"M2-2-u2-X08"},{"t":"1","mis":"M2-2-u2-X08"}],"explanation":["곱이 0이 되려면 0을 곱해야 해요.","0 × 6 = 0이에요.","1 × 6 = 6, 6 × 6 = 36이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_challenge#5','math',2,2,'u2','L08','g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',3,'mc','auto','1 × □ = 8에서 □ 안에 알맞은 수는 어느 것인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X06']::text[],false,'{"seq":5,"concept":"M2-2-u2-C7","difficulty":3,"kind":"mc","stem":"1 × □ = 8에서 □ 안에 알맞은 수는 어느 것인가요?","options":[{"t":"8","correct":true},{"t":"1","mis":"M2-2-u2-X08"},{"t":"7","mis":"M2-2-u2-X06"}],"explanation":["1과 어떤 수의 곱은 그 수예요.","1 × 8 = 8이에요.","8에서 1을 빼면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_challenge#6','math',2,2,'u2','L08','g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',3,'error','auto','0의 곱에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X15']::text[],false,'{"seq":6,"concept":"M2-2-u2-C7","difficulty":3,"kind":"error","stem":"0의 곱에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「6 × 0은 6이야. 6이 그대로 있으니까.」","correct":true,"mis_target":"M2-2-u2-X08"},{"t":"서윤 — 「0 × 6은 0이야.」","mis":"M2-2-u2-X15"},{"t":"준우 — 「6을 한 번도 더하지 않으면 0이야.」","mis":"M2-2-u2-X15"}],"explanation":["6 × 0은 6을 한 번도 더하지 않은 것이에요.","그래서 0이에요.","하람이의 말이 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_challenge#7','math',2,2,'u2','L08','g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',3,'ox','auto','1 × 9와 9 × 1은 곱이 같아요.',ARRAY['M2-2-u2-X08']::text[],false,'{"seq":7,"concept":"M2-2-u2-C7","difficulty":3,"kind":"ox","stem":"1 × 9와 9 × 1은 곱이 같아요.","answer":"O","reason_options":[{"t":"둘 다 9니까 — 두 수를 바꾸어 곱해도 곱이 같아요","correct":true},{"t":"1을 곱하면 언제나 1이 되니까","mis":"M2-2-u2-X08"}],"mis":"M2-2-u2-X08","explanation":["1 × 9는 1을 9번 더한 9예요.","9 × 1은 9를 한 번 더한 9예요.","그래서 곱이 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_challenge#8','math',2,2,'u2','L08','g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',4,'essay','teacher','과녁 맞히기에서 0점에 2번, 1점에 3번 맞혔고 3점에는 한 번도 못 맞혔어요. 점수마다 곱셈식으로 나타내 구하고, 모두 몇 점인지 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C7","difficulty":4,"kind":"essay","stem":"과녁 맞히기에서 0점에 2번, 1점에 3번 맞혔고 3점에는 한 번도 못 맞혔어요. 점수마다 곱셈식으로 나타내 구하고, 모두 몇 점인지 써 보세요.","answer_guide":{"answer":"예: 0 × 2 = 0, 1 × 3 = 3, 3 × 0 = 0이다. 0 + 3 + 0 = 3이므로 모두 3점이다.","scoring_points":["0 × 2 = 0을 썼는가","1 × 3 = 3과 3 × 0 = 0을 썼는가","모두 3점이라고 구했는가"]},"explanation":["맞힌 점수 × 맞힌 횟수로 써요.","0점은 몇 번 맞혀도 0, 한 번도 못 맞힌 점수도 0이에요.","0 + 3 + 0 = 3점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_challenge#9','math',2,2,'u2','L08','g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',4,'essay','teacher','0 × 4와 4 × 0이 모두 0인 까닭을 덧셈을 써서 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u2-C7","difficulty":4,"kind":"essay","stem":"0 × 4와 4 × 0이 모두 0인 까닭을 덧셈을 써서 설명해 보세요.","answer_guide":{"answer":"예: 0 × 4는 0을 4번 더한 것으로 0 + 0 + 0 + 0 = 0이다. 4 × 0은 4를 한 번도 더하지 않은 것이므로 0이다.","scoring_points":["0 × 4를 0을 4번 더한 것으로 설명했는가","4 × 0을 4를 한 번도 더하지 않은 것으로 설명했는가","둘 다 0이라고 썼는가"]},"explanation":["0을 여러 번 더해도 0이에요.","어떤 수를 0번 더하면 아무것도 없어요.","그래서 0과 어떤 수의 곱, 어떤 수와 0의 곱은 0이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_challenge#10','math',2,2,'u2','L08','g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',4,'mc','auto','지호는 1점짜리 문제를 7개, 0점짜리 문제를 2개 맞혔어요. 하린이는 1점짜리 문제를 5개 맞혔어요. 지호는 하린이보다 몇 점 더 얻었나요?',ARRAY['M2-2-u2-X08','M2-2-u2-X05','M2-2-u2-X06']::text[],false,'{"seq":10,"concept":"M2-2-u2-C7","difficulty":4,"kind":"mc","stem":"지호는 1점짜리 문제를 7개, 0점짜리 문제를 2개 맞혔어요. 하린이는 1점짜리 문제를 5개 맞혔어요. 지호는 하린이보다 몇 점 더 얻었나요?","options":[{"t":"2점","correct":true},{"t":"4점","mis":"M2-2-u2-X08"},{"t":"7점","mis":"M2-2-u2-X05"},{"t":"12점","mis":"M2-2-u2-X06"}],"explanation":["지호는 1 × 7 + 0 × 2 = 7점이에요.","하린이는 1 × 5 = 5점이에요.","7 − 5 = 2이니 2점 더 얻었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_basic#1','math',2,2,'u2','L09','g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',1,'mc','auto','곱셈표의 ?에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X09']::text[],true,'{"seq":1,"concept":"M2-2-u2-C8","difficulty":1,"kind":"mc","stem":"곱셈표의 ?에 알맞은 수는 얼마인가요?","explanation":["?는 왼쪽 3과 위쪽 4가 만나는 칸이에요.","그래서 3 × 4의 곱을 써요 — 3 × 3 = 9에 3을 더해도 돼요.","3 × 4 = 12예요."],"variant_rule":{"gugu":{"ask":"cell","ks":[2,3,4,5]}},"options":[{"t":"12","correct":true},{"t":"15","mis":"M2-2-u2-X09"},{"t":"9","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[3,4,5,6],"cols":[1,2,3,4,5],"q":[3,4],"blank":[[5,4],[3,5]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_basic#2','math',2,2,'u2','L09','g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',1,'sa','auto','곱셈표의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u2-C8","difficulty":1,"kind":"sa","stem":"곱셈표의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["?는 왼쪽 5와 위쪽 6이 만나는 칸이에요.","그래서 5 × 6의 곱을 써요 — 5 × 5 = 25에 5를 더해도 돼요.","5 × 6 = 30이에요."],"variant_rule":{"gugu":{"ask":"cell","ks":[2,3,4,5]}},"answer":["30"],"asset":{"type":"gugu_table","rows":[4,5,6,7],"cols":[5,6,7,8,9],"q":[5,6],"blank":[[5,5],[7,6]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_basic#3','math',2,2,'u2','L09','g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',1,'mc','auto','곱셈표에서 색칠한 4단 곱셈구구의 곱은 오른쪽으로 한 칸 갈 때마다 얼마씩 커지나요?',ARRAY['M2-2-u2-X01','M2-2-u2-X09']::text[],true,'{"seq":3,"concept":"M2-2-u2-C8","difficulty":1,"kind":"mc","stem":"곱셈표에서 색칠한 4단 곱셈구구의 곱은 오른쪽으로 한 칸 갈 때마다 얼마씩 커지나요?","explanation":["4단의 곱은 4, 8, 12, …예요.","곱하는 수가 1 커질 때마다 4씩 커져요.","그래서 4단 곱셈구구의 곱은 4씩 커져요 — 1씩이 아니에요."],"variant_rule":{"gugu":{"ask":"step"}},"options":[{"t":"4","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"5","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[2,3,4],"cols":[1,2,3,4,5,6,7,8,9],"hrow":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_basic#4','math',2,2,'u2','L09','g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',1,'mc','auto','4 × 7과 곱이 같은 곱셈식은 어느 것인가요?',ARRAY['M2-2-u2-X13']::text[],true,'{"seq":4,"concept":"M2-2-u2-C8","difficulty":1,"kind":"mc","stem":"4 × 7과 곱이 같은 곱셈식은 어느 것인가요?","explanation":["4 × 7은 4씩 7묶음, 7 × 4는 7씩 4묶음이에요.","같은 28개를 가로로 묶느냐 세로로 묶느냐의 차이예요.","그래서 4 × 7과 7 × 4의 곱은 28로 같아요."],"variant_rule":{"mul":{"ask":"same","pmax":81}},"options":[{"t":"7 × 4","correct":true},{"t":"4 × 4","mis":"M2-2-u2-X13"},{"t":"7 × 7","mis":"M2-2-u2-X13"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_basic#5','math',2,2,'u2','L09','g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',2,'mc','auto','곱셈표의 ?에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X09']::text[],true,'{"seq":5,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표의 ?에 알맞은 수는 얼마인가요?","explanation":["?는 왼쪽 7과 위쪽 6이 만나는 칸이에요.","그래서 7 × 6의 곱을 써요 — 7 × 5 = 35에 7을 더해도 돼요.","7 × 6 = 42예요."],"variant_rule":{"gugu":{"ask":"cell","ks":[6,7,8,9]}},"options":[{"t":"42","correct":true},{"t":"49","mis":"M2-2-u2-X09"},{"t":"35","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[4,5,6,7],"cols":[4,5,6,7,8],"q":[7,6],"blank":[[7,7],[6,6]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_basic#6','math',2,2,'u2','L09','g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',2,'ox','auto','곱셈표를 같은 수끼리 만나는 칸을 이은 점선을 따라 접으면 만나는 수가 서로 같아요.',ARRAY['M2-2-u2-X09']::text[],true,'{"seq":6,"concept":"M2-2-u2-C8","difficulty":2,"kind":"ox","stem":"곱셈표를 같은 수끼리 만나는 칸을 이은 점선을 따라 접으면 만나는 수가 서로 같아요.","answer":"O","reason_options":[{"t":"3 × 5와 5 × 3처럼 두 수를 바꾸어 곱한 칸끼리 만나니까","correct":true},{"t":"접으면 늘 같은 단끼리 만나니까","mis":"M2-2-u2-X09"}],"mis":"M2-2-u2-X09","explanation":["점선은 1 × 1, 2 × 2, 3 × 3, …처럼 같은 수끼리 만나는 칸이에요.","접으면 4 × 6과 6 × 4처럼 두 수를 바꾼 칸이 만나요.","두 수를 바꾸어 곱해도 곱이 같으니 만나는 수가 같아요."],"asset":{"type":"gugu_table","rows":[1,2,3,4,5,6],"cols":[1,2,3,4,5,6],"diag":true},"variant_rule":{"alt":[{"stem":"곱셈표에서 6단 곱셈구구의 곱은 오른쪽으로 갈수록 6씩 커져요.","answer":"O","reason_options":[{"t":"6단은 6을 한 번씩 더 더하니까","correct":true},{"t":"곱셈표의 수는 오른쪽으로 갈 때 1씩 커지니까","mis":"M2-2-u2-X01"}],"explanation":["6단의 곱은 6, 12, 18, 24, …예요.","오른쪽으로 한 칸 가면 곱하는 수가 1 커져요.","그래서 곱은 6씩 커져요."],"asset":{"type":"gugu_table","rows":[5,6,7],"cols":[1,2,3,4,5,6,7,8,9],"hrow":6}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_basic#7','math',2,2,'u2','L09','g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',2,'mc','auto','1단부터 9단까지의 곱셈구구 가운데 곱이 24인 것은 모두 몇 개인가요?',ARRAY['M2-2-u2-X13','M2-2-u2-X09']::text[],true,'{"seq":7,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"1단부터 9단까지의 곱셈구구 가운데 곱이 24인 것은 모두 몇 개인가요?","explanation":["곱이 24인 곱셈구구는 3 × 8, 4 × 6, 6 × 4, 8 × 3이에요.","두 수를 바꾸어 곱한 것도 따로 세어요.","그래서 모두 4개예요."],"variant_rule":{"gugu":{"ask":"tfind"}},"options":[{"t":"4","correct":true},{"t":"3","mis":"M2-2-u2-X13"},{"t":"5","mis":"M2-2-u2-X09"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_basic#8','math',2,2,'u2','L09','g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',2,'mc','auto','곱이 24인 곱셈식이 아닌 것은 어느 것인가요?',ARRAY['M2-2-u2-X15']::text[],true,'{"seq":8,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱이 24인 곱셈식이 아닌 것은 어느 것인가요?","explanation":["5 × 5 = 25예요.","나머지 곱셈식의 곱은 모두 24예요.","「아닌 것」을 묻는지 다시 읽어요 — 같은 수도 여러 곱셈식으로 나타낼 수 있어요."],"variant_rule":{"mul":{"ask":"notx","pmax":81}},"options":[{"t":"5 × 5","correct":true},{"t":"8 × 3","mis":"M2-2-u2-X15"},{"t":"6 × 4","mis":"M2-2-u2-X15"},{"t":"3 × 8","mis":"M2-2-u2-X15"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_basic#9','math',2,2,'u2','L09','g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',2,'mc','auto','곱셈표에서 곱이 16인 곱셈구구를 모두 찾은 것은 어느 것인가요?',ARRAY['M2-2-u2-X13']::text[],true,'{"seq":9,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표에서 곱이 16인 곱셈구구를 모두 찾은 것은 어느 것인가요?","options":[{"t":"2 × 8, 4 × 4, 8 × 2","correct":true},{"t":"4 × 4","mis":"M2-2-u2-X13"},{"t":"2 × 8, 8 × 2","mis":"M2-2-u2-X13"}],"explanation":["곱이 16인 칸은 2단, 4단, 8단에 있어요.","2 × 8 = 16, 4 × 4 = 16, 8 × 2 = 16이에요.","곱이 같은 곱셈구구는 여러 개일 수 있어요."],"variant_rule":{"alt":[{"stem":"곱셈표에서 곱이 9인 곱셈구구를 모두 찾은 것은 어느 것인가요?","options":[{"t":"1 × 9, 3 × 3, 9 × 1","correct":true},{"t":"3 × 3","mis":"M2-2-u2-X13"},{"t":"1 × 9, 9 × 1","mis":"M2-2-u2-X13"}],"explanation":["곱이 9인 칸은 1단, 3단, 9단에 있어요.","1 × 9 = 9, 3 × 3 = 9, 9 × 1 = 9예요.","곱이 같은 곱셈구구는 여러 개일 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_basic#10','math',2,2,'u2','L09','g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',3,'mc','auto','곱셈표의 ?에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X09']::text[],true,'{"seq":10,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"곱셈표의 ?에 알맞은 수는 얼마인가요?","explanation":["?는 왼쪽 8과 위쪽 7이 만나는 칸이에요.","그래서 8 × 7의 곱을 써요 — 8 × 6 = 48에 8을 더해도 돼요.","8 × 7 = 56이에요."],"variant_rule":{"gugu":{"ask":"cell","ks":[6,7,8,9]}},"options":[{"t":"56","correct":true},{"t":"64","mis":"M2-2-u2-X09"},{"t":"48","mis":"M2-2-u2-X09"},{"t":"63","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[6,7,8,9],"cols":[5,6,7,8,9],"q":[8,7],"blank":[[8,8],[7,7]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_challenge#1','math',2,2,'u2','L09','g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',2,'mc','auto','곱셈표에서 색칠한 7단 곱셈구구의 곱은 오른쪽으로 한 칸 갈 때마다 얼마씩 커지나요?',ARRAY['M2-2-u2-X01','M2-2-u2-X09']::text[],true,'{"seq":1,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표에서 색칠한 7단 곱셈구구의 곱은 오른쪽으로 한 칸 갈 때마다 얼마씩 커지나요?","explanation":["7단의 곱은 7, 14, 21, …예요.","곱하는 수가 1 커질 때마다 7씩 커져요.","그래서 7단 곱셈구구의 곱은 7씩 커져요 — 1씩이 아니에요."],"variant_rule":{"gugu":{"ask":"step"}},"options":[{"t":"7","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"8","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[6,7,8],"cols":[1,2,3,4,5,6,7,8,9],"hrow":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_challenge#2','math',2,2,'u2','L09','g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',2,'sa','auto','1단부터 9단까지의 곱셈구구 가운데 곱이 12인 것은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u2-C8","difficulty":2,"kind":"sa","stem":"1단부터 9단까지의 곱셈구구 가운데 곱이 12인 것은 모두 몇 개인가요? 숫자로 쓰세요.","explanation":["곱이 12인 곱셈구구는 2 × 6, 3 × 4, 4 × 3, 6 × 2예요.","두 수를 바꾸어 곱한 것도 따로 세어요.","그래서 모두 4개예요."],"variant_rule":{"gugu":{"ask":"tfind"}},"answer":["4"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_challenge#3','math',2,2,'u2','L09','g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',3,'mc','auto','곱셈표의 ?에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X09','M2-2-u2-X11']::text[],true,'{"seq":3,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"곱셈표의 ?에 알맞은 수는 얼마인가요?","explanation":["?는 왼쪽 9와 위쪽 8이 만나는 칸이에요.","그래서 9 × 8의 곱을 써요 — 9 × 7 = 63에 9를 더해도 돼요.","9 × 8 = 72예요."],"variant_rule":{"gugu":{"ask":"cell","ks":[6,7,8,9]}},"options":[{"t":"72","correct":true},{"t":"81","mis":"M2-2-u2-X09"},{"t":"63","mis":"M2-2-u2-X09"},{"t":"17","mis":"M2-2-u2-X11"}],"asset":{"type":"gugu_table","rows":[6,7,8,9],"cols":[5,6,7,8,9],"q":[9,8],"blank":[[9,5],[7,8]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_challenge#4','math',2,2,'u2','L09','g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',3,'mc','auto','곱셈표의 5단 줄에서 5 × 1부터 5 × 9까지의 곱 가운데 일의 자리 숫자가 0인 칸은 모두 몇 개인가요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":4,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"곱셈표의 5단 줄에서 5 × 1부터 5 × 9까지의 곱 가운데 일의 자리 숫자가 0인 칸은 모두 몇 개인가요?","options":[{"t":"4개","correct":true},{"t":"5개","mis":"M2-2-u2-X16"},{"t":"9개","mis":"M2-2-u2-X16"}],"explanation":["5단의 곱은 5, 10, 15, 20, 25, 30, 35, 40, 45예요.","일의 자리 숫자가 0인 것은 10, 20, 30, 40이에요.","그래서 4개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_challenge#5','math',2,2,'u2','L09','g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',3,'mc','auto','곱셈표에서 3 × 8과 곱이 같은 곱셈구구를 모두 찾은 친구는 누구인가요?',ARRAY['M2-2-u2-X13']::text[],false,'{"seq":5,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"곱셈표에서 3 × 8과 곱이 같은 곱셈구구를 모두 찾은 친구는 누구인가요?","options":[{"t":"지안 — 「8 × 3, 4 × 6, 6 × 4」","correct":true},{"t":"아린 — 「8 × 3」","mis":"M2-2-u2-X13"},{"t":"태민 — 「8 × 3, 4 × 6」","mis":"M2-2-u2-X13"}],"explanation":["3 × 8 = 24예요.","곱이 24인 칸은 8 × 3, 4 × 6, 6 × 4에도 있어요.","두 수를 바꾼 것과 다른 단의 곱까지 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_challenge#6','math',2,2,'u2','L09','g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',3,'mc','auto','곱셈표의 같은 가로줄에서 이웃한 두 칸이 35와 42예요. 몇 단의 줄인가요?',ARRAY['M2-2-u2-X09']::text[],false,'{"seq":6,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"곱셈표의 같은 가로줄에서 이웃한 두 칸이 35와 42예요. 몇 단의 줄인가요?","options":[{"t":"7단","correct":true},{"t":"5단","mis":"M2-2-u2-X09"},{"t":"6단","mis":"M2-2-u2-X09"}],"explanation":["이웃한 칸의 곱은 그 단의 수만큼 커져요.","42 − 35 = 7이에요.","35 = 7 × 5, 42 = 7 × 6 — 7단의 줄이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_challenge#7','math',2,2,'u2','L09','g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',3,'mc','auto','1단부터 9단까지의 곱셈구구 가운데 곱이 36인 것은 모두 몇 개인가요?',ARRAY['M2-2-u2-X13','M2-2-u2-X09']::text[],true,'{"seq":7,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"1단부터 9단까지의 곱셈구구 가운데 곱이 36인 것은 모두 몇 개인가요?","explanation":["곱이 36인 곱셈구구는 4 × 9, 6 × 6, 9 × 4예요.","두 수를 바꾸어 곱한 것도 따로 세어요.","그래서 모두 3개예요."],"variant_rule":{"gugu":{"ask":"tfind"}},"options":[{"t":"3","correct":true},{"t":"2","mis":"M2-2-u2-X13"},{"t":"4","mis":"M2-2-u2-X09"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_challenge#8','math',2,2,'u2','L09','g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',4,'essay','teacher','곱셈표에서 4 × 6과 곱이 같은 곱셈구구를 모두 찾고, 어떻게 찾았는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C8","difficulty":4,"kind":"essay","stem":"곱셈표에서 4 × 6과 곱이 같은 곱셈구구를 모두 찾고, 어떻게 찾았는지 설명해 보세요.","answer_guide":{"answer":"예: 4 × 6 = 24이다. 곱셈표에서 24가 있는 칸을 찾으면 6 × 4, 3 × 8, 8 × 3이 있다. 두 수를 바꾸어 곱해도 곱이 같고, 다른 단에도 24가 있다.","scoring_points":["4 × 6 = 24를 구했는가","6 × 4, 3 × 8, 8 × 3을 모두 찾았는가","곱셈표에서 24인 칸을 찾았다고 방법을 썼는가"]},"explanation":["4 × 6 = 24예요.","곱셈표에서 24는 3단, 4단, 6단, 8단에 있어요.","6 × 4만 찾으면 3 × 8, 8 × 3을 놓쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_challenge#9','math',2,2,'u2','L09','g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',4,'essay','teacher','곱셈표의 6 × 5 칸이 비어 있어요. 바로 왼쪽 칸 6 × 4 = 24를 이용하는 방법과 5 × 6을 이용하는 방법으로 빈칸을 채우고 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u2-C8","difficulty":4,"kind":"essay","stem":"곱셈표의 6 × 5 칸이 비어 있어요. 바로 왼쪽 칸 6 × 4 = 24를 이용하는 방법과 5 × 6을 이용하는 방법으로 빈칸을 채우고 설명해 보세요.","answer_guide":{"answer":"예: 6 × 5는 6 × 4보다 6 크므로 24 + 6 = 30이다. 6 × 5와 5 × 6은 곱이 같으므로 5단에서 5 × 6 = 30을 찾아도 30이다.","scoring_points":["6 × 4에 6을 더해 30을 구했는가","5 × 6과 곱이 같음을 이용해 30을 구했는가","빈칸에 30을 썼는가"]},"explanation":["곱셈표에서 오른쪽으로 한 칸 가면 그 단의 수만큼 커져요.","두 수를 바꾸어 곱해도 곱이 같아요.","두 방법 모두 30이에요."],"asset":{"type":"gugu_table","rows":[5,6,7],"cols":[3,4,5,6],"blank":[[6,5]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_challenge#10','math',2,2,'u2','L09','g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',4,'mc','auto','1단부터 9단까지의 곱셈표에서 곱이 8인 칸과 곱이 9인 칸은 모두 몇 개인가요?',ARRAY['M2-2-u2-X13','M2-2-u2-X09']::text[],false,'{"seq":10,"concept":"M2-2-u2-C8","difficulty":4,"kind":"mc","stem":"1단부터 9단까지의 곱셈표에서 곱이 8인 칸과 곱이 9인 칸은 모두 몇 개인가요?","options":[{"t":"7개","correct":true},{"t":"4개","mis":"M2-2-u2-X13"},{"t":"6개","mis":"M2-2-u2-X13"},{"t":"8개","mis":"M2-2-u2-X09"}],"explanation":["곱이 8인 칸: 1 × 8, 2 × 4, 4 × 2, 8 × 1 — 4개예요.","곱이 9인 칸: 1 × 9, 3 × 3, 9 × 1 — 3개예요.","4 + 3 = 7이니 모두 7개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_basic#1','math',2,2,'u2','L10','g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',1,'mc','auto','해마가 한 줄에 5마리씩 3줄 있어요. 해마는 모두 몇 마리인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X03']::text[],true,'{"seq":1,"concept":"M2-2-u2-C9","difficulty":1,"kind":"mc","stem":"해마가 한 줄에 5마리씩 3줄 있어요. 해마는 모두 몇 마리인가요?","options":[{"t":"15마리","correct":true},{"t":"8마리","mis":"M2-2-u2-X06"},{"t":"20마리","mis":"M2-2-u2-X03"}],"explanation":["한 줄에 5마리씩, 3줄이에요.","5 × 3 = 15예요.","하나씩 세지 않고 곱셈구구로 빠르게 구했어요."],"variant_rule":{"alt":[{"stem":"해마가 한 줄에 6마리씩 4줄 있어요. 해마는 모두 몇 마리인가요?","options":[{"t":"24마리","correct":true},{"t":"10마리","mis":"M2-2-u2-X06"},{"t":"30마리","mis":"M2-2-u2-X03"}],"explanation":["한 줄에 6마리씩, 4줄이에요.","6 × 4 = 24예요.","하나씩 세지 않고 곱셈구구로 빠르게 구했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_basic#2','math',2,2,'u2','L10','g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',1,'mc','auto','로봇이 한 줄에 8대씩 2줄 있어요. 로봇의 수를 구하는 곱셈식으로 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X04']::text[],true,'{"seq":2,"concept":"M2-2-u2-C9","difficulty":1,"kind":"mc","stem":"로봇이 한 줄에 8대씩 2줄 있어요. 로봇의 수를 구하는 곱셈식으로 알맞은 것은 어느 것인가요?","options":[{"t":"8 × 2","correct":true},{"t":"8 + 2","mis":"M2-2-u2-X11"},{"t":"2 × 2","mis":"M2-2-u2-X04"}],"explanation":["한 줄에 8대씩 — 한 묶음은 8이에요.","2줄이니 8 × 2예요.","8 × 2 = 16이니 로봇은 16대예요."],"variant_rule":{"alt":[{"stem":"로봇이 한 줄에 7대씩 3줄 있어요. 로봇의 수를 구하는 곱셈식으로 알맞은 것은 어느 것인가요?","options":[{"t":"7 × 3","correct":true},{"t":"7 + 3","mis":"M2-2-u2-X11"},{"t":"3 × 3","mis":"M2-2-u2-X04"}],"explanation":["한 줄에 7대씩 — 한 묶음은 7이에요.","3줄이니 7 × 3이에요.","7 × 3 = 21이니 로봇은 21대예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_basic#3','math',2,2,'u2','L10','g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',1,'mc','auto','필통 한 개에 연필이 6자루씩 있어요. 필통 5개의 연필 수를 구하는 곱셈식은 어느 것인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X14']::text[],true,'{"seq":3,"concept":"M2-2-u2-C9","difficulty":1,"kind":"mc","stem":"필통 한 개에 연필이 6자루씩 있어요. 필통 5개의 연필 수를 구하는 곱셈식은 어느 것인가요?","explanation":["한 개에 6자루씩 — 한 묶음은 6이에요.","필통이 5개이니 6씩 5묶음, 6의 5배예요.","곱셈식은 6 × 5 = 30이에요."],"variant_rule":{"mul":{"ask":"sexpr","pmax":81,"per":[4,6,8]}},"options":[{"t":"6 × 5","correct":true},{"t":"6 + 5","mis":"M2-2-u2-X11"},{"t":"6 × 6","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_basic#4','math',2,2,'u2','L10','g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',1,'sa','auto','거미 한 마리에 다리가 8개씩 있어요. 거미 4마리의 다리는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M2-2-u2-C9","difficulty":1,"kind":"sa","stem":"거미 한 마리에 다리가 8개씩 있어요. 거미 4마리의 다리는 모두 몇 개인가요? 숫자로 쓰세요.","explanation":["거미 한 마리에 8개씩, 4마리이면 8씩 4묶음이에요.","8 × 4 = 32예요.","다리는 모두 32개예요."],"variant_rule":{"mul":{"ask":"story","pmax":81,"per":[4,6,8]}},"answer":["32","32개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_basic#5','math',2,2,'u2','L10','g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',2,'mc','auto','책상이 한 줄에 5개씩 4줄로 놓여 있는데, 한 자리가 비어 있어요. 책상은 모두 몇 개인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X06']::text[],true,'{"seq":5,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"책상이 한 줄에 5개씩 4줄로 놓여 있는데, 한 자리가 비어 있어요. 책상은 모두 몇 개인가요?","options":[{"t":"19개","correct":true},{"t":"20개","mis":"M2-2-u2-X18"},{"t":"9개","mis":"M2-2-u2-X06"}],"explanation":["빈자리까지 채우면 5 × 4 = 20개예요.","한 자리가 비었으니 20 − 1 = 19예요.","빈자리를 빼는 것을 잊지 않아요."],"variant_rule":{"alt":[{"stem":"책상이 한 줄에 6개씩 3줄로 놓여 있는데, 두 자리가 비어 있어요. 책상은 모두 몇 개인가요?","options":[{"t":"16개","correct":true},{"t":"18개","mis":"M2-2-u2-X18"},{"t":"9개","mis":"M2-2-u2-X06"}],"explanation":["빈자리까지 채우면 6 × 3 = 18개예요.","두 자리가 비었으니 18 − 2 = 16이에요.","빈자리를 빼는 것을 잊지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_basic#6','math',2,2,'u2','L10','g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',2,'mc','auto','사탕이 한 봉지에 6개씩 3봉지 있고, 낱개로 2개가 더 있어요. 사탕은 모두 몇 개인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X06']::text[],true,'{"seq":6,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"사탕이 한 봉지에 6개씩 3봉지 있고, 낱개로 2개가 더 있어요. 사탕은 모두 몇 개인가요?","options":[{"t":"20개","correct":true},{"t":"18개","mis":"M2-2-u2-X18"},{"t":"11개","mis":"M2-2-u2-X06"}],"explanation":["봉지에 든 사탕은 6 × 3 = 18개예요.","낱개 2개를 더해요.","18 + 2 = 20이니 모두 20개예요."],"variant_rule":{"alt":[{"stem":"구슬이 한 주머니에 4개씩 5주머니 있고, 낱개로 3개가 더 있어요. 구슬은 모두 몇 개인가요?","options":[{"t":"23개","correct":true},{"t":"20개","mis":"M2-2-u2-X18"},{"t":"12개","mis":"M2-2-u2-X06"}],"explanation":["주머니에 든 구슬은 4 × 5 = 20개예요.","낱개 3개를 더해요.","20 + 3 = 23이니 모두 23개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_basic#7','math',2,2,'u2','L10','g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',2,'match','auto','상황과 곱셈식을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u2-C9","difficulty":2,"kind":"match","stem":"상황과 곱셈식을 이으세요.","pairs":[{"l":"자동차 3대의 바퀴","r":"4 × 3"},{"l":"세발자전거 4대의 바퀴","r":"3 × 4"},{"l":"거미 2마리의 다리","r":"8 × 2"}],"mis":"M2-2-u2-X14","explanation":["자동차 한 대에 바퀴 4개씩, 3대 → 4 × 3","세발자전거 한 대에 바퀴 3개씩, 4대 → 3 × 4","거미 한 마리에 다리 8개씩, 2마리 → 8 × 2"],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 상황과 곱셈식을 이으세요.","pairs":[{"l":"문어 3마리의 다리","r":"8 × 3"},{"l":"개미 4마리의 다리","r":"6 × 4"},{"l":"오리 5마리의 다리","r":"2 × 5"}],"explanation":["문어 한 마리에 다리 8개씩, 3마리 → 8 × 3","개미 한 마리에 다리 6개씩, 4마리 → 6 × 4","오리 한 마리에 다리 2개씩, 5마리 → 2 × 5"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_basic#8','math',2,2,'u2','L10','g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',2,'mc','auto','연결 모형이 왼쪽에 3개씩 2줄, 오른쪽에 5개씩 4줄 붙어 있어요. 연결 모형은 모두 몇 개인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X18']::text[],true,'{"seq":8,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"연결 모형이 왼쪽에 3개씩 2줄, 오른쪽에 5개씩 4줄 붙어 있어요. 연결 모형은 모두 몇 개인가요?","options":[{"t":"26개","correct":true},{"t":"14개","mis":"M2-2-u2-X17"},{"t":"20개","mis":"M2-2-u2-X18"}],"explanation":["왼쪽은 3 × 2 = 6개예요.","오른쪽은 5 × 4 = 20개예요.","6 + 20 = 26이니 모두 26개예요."],"variant_rule":{"alt":[{"stem":"연결 모형이 왼쪽에 2개씩 4줄, 오른쪽에 6개씩 3줄 붙어 있어요. 연결 모형은 모두 몇 개인가요?","options":[{"t":"26개","correct":true},{"t":"15개","mis":"M2-2-u2-X17"},{"t":"18개","mis":"M2-2-u2-X18"}],"explanation":["왼쪽은 2 × 4 = 8개예요.","오른쪽은 6 × 3 = 18개예요.","8 + 18 = 26이니 모두 26개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_basic#9','math',2,2,'u2','L10','g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',2,'mc','auto','주머니 한 개에 구슬이 7개씩 있어요. 주머니 4개의 구슬은 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X14']::text[],true,'{"seq":9,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"주머니 한 개에 구슬이 7개씩 있어요. 주머니 4개의 구슬은 모두 몇 개인가요?","explanation":["주머니 한 개에 7개씩, 4개이면 7씩 4묶음이에요.","7 × 4 = 28이에요.","구슬은 모두 28개예요."],"variant_rule":{"mul":{"ask":"story","pmax":81,"per":[3,5,7,9]}},"options":[{"t":"28개","correct":true},{"t":"11개","mis":"M2-2-u2-X06"},{"t":"4개","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_basic#10','math',2,2,'u2','L10','g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',3,'error','auto','의자가 한 줄에 4개씩 5줄로 놓여 있는데 한 자리에 의자가 없어요. 의자의 수를 잘못 구한 친구는 누구인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X15']::text[],true,'{"seq":10,"concept":"M2-2-u2-C9","difficulty":3,"kind":"error","stem":"의자가 한 줄에 4개씩 5줄로 놓여 있는데 한 자리에 의자가 없어요. 의자의 수를 잘못 구한 친구는 누구인가요?","options":[{"t":"곰이 — 「4 × 5 = 20이니까 20개야.」","correct":true,"mis_target":"M2-2-u2-X18"},{"t":"펭이 — 「4 × 5 = 20에서 1을 빼면 19개야.」","mis":"M2-2-u2-X15"},{"t":"다예 — 「4 × 4 = 16에 3을 더하면 19개야.」","mis":"M2-2-u2-X15"}],"explanation":["빈자리까지 채우면 4 × 5 = 20개예요.","빈자리 하나를 빼면 19개예요.","곰이는 빈자리를 빼지 않았어요."],"variant_rule":{"alt":[{"stem":"의자가 한 줄에 6개씩 4줄로 놓여 있는데 두 자리에 의자가 없어요. 의자의 수를 잘못 구한 친구는 누구인가요?","options":[{"t":"지우 — 「6 × 4 = 24이니까 24개야.」","correct":true,"mis_target":"M2-2-u2-X18"},{"t":"서아 — 「6 × 4 = 24에서 2를 빼면 22개야.」","mis":"M2-2-u2-X15"},{"t":"하루 — 「6 × 3 = 18에 4를 더하면 22개야.」","mis":"M2-2-u2-X15"}],"explanation":["빈자리까지 채우면 6 × 4 = 24개예요.","빈자리 둘을 빼면 22개예요.","지우는 빈자리를 빼지 않았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_challenge#1','math',2,2,'u2','L10','g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',2,'mc','auto','야구공이 한 상자에 9개씩 2상자, 테니스공이 한 상자에 6개씩 3상자 있어요. 공은 모두 몇 개인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X18']::text[],false,'{"seq":1,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"야구공이 한 상자에 9개씩 2상자, 테니스공이 한 상자에 6개씩 3상자 있어요. 공은 모두 몇 개인가요?","options":[{"t":"36개","correct":true},{"t":"20개","mis":"M2-2-u2-X17"},{"t":"18개","mis":"M2-2-u2-X18"}],"explanation":["야구공은 9 × 2 = 18개예요.","테니스공은 6 × 3 = 18개예요.","18 + 18 = 36이니 모두 36개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_challenge#2','math',2,2,'u2','L10','g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',2,'mc','auto','문어 한 마리에 다리가 8개씩 있어요. 문어 6마리의 다리 수를 구하는 곱셈식은 어느 것인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X14']::text[],true,'{"seq":2,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"문어 한 마리에 다리가 8개씩 있어요. 문어 6마리의 다리 수를 구하는 곱셈식은 어느 것인가요?","explanation":["한 마리에 8개씩 — 한 묶음은 8이에요.","문어가 6마리이니 8씩 6묶음, 8의 6배예요.","곱셈식은 8 × 6 = 48이에요."],"variant_rule":{"mul":{"ask":"sexpr","pmax":81,"per":[6,8]}},"options":[{"t":"8 × 6","correct":true},{"t":"8 + 6","mis":"M2-2-u2-X11"},{"t":"8 × 8","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_challenge#3','math',2,2,'u2','L10','g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',3,'mc','auto','꽃잎이 5장인 꽃이 6송이, 꽃잎이 4장인 꽃이 3송이 있어요. 꽃잎은 모두 몇 장인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X17','M2-2-u2-X02']::text[],false,'{"seq":3,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"꽃잎이 5장인 꽃이 6송이, 꽃잎이 4장인 꽃이 3송이 있어요. 꽃잎은 모두 몇 장인가요?","options":[{"t":"42장","correct":true},{"t":"30장","mis":"M2-2-u2-X18"},{"t":"18장","mis":"M2-2-u2-X17"},{"t":"36장","mis":"M2-2-u2-X02"}],"explanation":["꽃잎이 5장인 꽃은 5 × 6 = 30장이에요.","꽃잎이 4장인 꽃은 4 × 3 = 12장이에요.","30 + 12 = 42이니 모두 42장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_challenge#4','math',2,2,'u2','L10','g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',3,'mc','auto','연필이 한 묶음에 6자루씩 4묶음 있어요. 친구 3명에게 2자루씩 나누어 주면 남는 연필은 몇 자루인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X06']::text[],false,'{"seq":4,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"연필이 한 묶음에 6자루씩 4묶음 있어요. 친구 3명에게 2자루씩 나누어 주면 남는 연필은 몇 자루인가요?","options":[{"t":"18자루","correct":true},{"t":"24자루","mis":"M2-2-u2-X18"},{"t":"22자루","mis":"M2-2-u2-X06"},{"t":"19자루","mis":"M2-2-u2-X06"}],"explanation":["연필은 6 × 4 = 24자루예요.","나누어 준 연필은 2 × 3 = 6자루예요.","24 − 6 = 18이니 18자루가 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_challenge#5','math',2,2,'u2','L10','g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',3,'mc','auto','닭 3마리와 강아지 4마리가 있어요. 다리는 모두 몇 개인가요?',ARRAY['M2-2-u2-X14','M2-2-u2-X05']::text[],false,'{"seq":5,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"닭 3마리와 강아지 4마리가 있어요. 다리는 모두 몇 개인가요?","options":[{"t":"22개","correct":true},{"t":"28개","mis":"M2-2-u2-X14"},{"t":"14개","mis":"M2-2-u2-X14"},{"t":"7개","mis":"M2-2-u2-X05"}],"explanation":["닭의 다리는 2 × 3 = 6개예요.","강아지의 다리는 4 × 4 = 16개예요.","6 + 16 = 22이니 모두 22개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_challenge#6','math',2,2,'u2','L10','g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',3,'mc','auto','두 곱의 크기를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_challenge#7','math',2,2,'u2','L10','g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',3,'mc','auto','색종이가 한 봉투에 4장씩 들어 있어요. 색종이 32장을 모두 담으려면 봉투가 몇 개 있어야 하나요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":7,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"색종이가 한 봉투에 4장씩 들어 있어요. 색종이 32장을 모두 담으려면 봉투가 몇 개 있어야 하나요?","options":[{"t":"8개","correct":true},{"t":"28개","mis":"M2-2-u2-X06"},{"t":"7개","mis":"M2-2-u2-X02"},{"t":"9개","mis":"M2-2-u2-X02"}],"explanation":["4단 곱셈구구에서 곱이 32인 것을 찾아요.","4 × 8 = 32예요.","그래서 봉투가 8개 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_challenge#8','math',2,2,'u2','L10','g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',4,'essay','teacher','책상이 한 줄에 4개씩 5줄로 놓여 있는데 한 자리가 비어 있어요. 책상의 수를 두 가지 방법으로 구하고 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C9","difficulty":4,"kind":"essay","stem":"책상이 한 줄에 4개씩 5줄로 놓여 있는데 한 자리가 비어 있어요. 책상의 수를 두 가지 방법으로 구하고 설명해 보세요.","answer_guide":{"answer":"예: 빈자리까지 채우면 4 × 5 = 20개이고 빈자리 1개를 빼면 19개이다. 꽉 찬 4줄은 4 × 4 = 16개이고 남은 줄의 3개를 더하면 19개이다.","scoring_points":["4 × 5에서 1을 빼는 방법으로 19를 구했는가","4 × 4에 3을 더하는 등 다른 방법으로 19를 구했는가","책상이 19개라고 썼는가"]},"explanation":["빈자리까지 채워 곱한 뒤 빈자리를 빼요.","꽉 찬 줄과 덜 찬 줄을 나누어 구한 뒤 더해도 돼요.","두 방법 모두 19개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_challenge#9','math',2,2,'u2','L10','g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',4,'essay','teacher','우리 반 사물함이나 학용품처럼 곱셈구구로 수를 구할 수 있는 상황을 하나 만들고, 곱셈식으로 해결해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u2-C9","difficulty":4,"kind":"essay","stem":"우리 반 사물함이나 학용품처럼 곱셈구구로 수를 구할 수 있는 상황을 하나 만들고, 곱셈식으로 해결해 보세요.","answer_guide":{"answer":"예: 사물함이 한 줄에 6칸씩 4줄 있다. 사물함은 6 × 4 = 24칸이다.","scoring_points":["같은 수씩 여러 묶음이 있는 상황을 만들었는가","한 묶음의 수와 묶음의 수로 곱셈식을 바르게 썼는가","곱을 바르게 구했는가"]},"explanation":["「한 줄에 몇 개씩」 놓인 것을 찾아요.","한 묶음의 수 × 묶음의 수로 써요.","곱셈구구로 곱을 구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_challenge#10','math',2,2,'u2','L10','g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',4,'mc','auto','사과가 한 상자에 8개씩 3상자, 귤이 한 봉지에 7개씩 4봉지 있어요. 귤은 사과보다 몇 개 더 많은가요?',ARRAY['M2-2-u2-X15','M2-2-u2-X19','M2-2-u2-X02']::text[],false,'{"seq":10,"concept":"M2-2-u2-C9","difficulty":4,"kind":"mc","stem":"사과가 한 상자에 8개씩 3상자, 귤이 한 봉지에 7개씩 4봉지 있어요. 귤은 사과보다 몇 개 더 많은가요?","options":[{"t":"4개","correct":true},{"t":"52개","mis":"M2-2-u2-X15"},{"t":"1개","mis":"M2-2-u2-X19"},{"t":"5개","mis":"M2-2-u2-X02"}],"explanation":["사과는 8 × 3 = 24개예요.","귤은 7 × 4 = 28개예요.","28 − 24 = 4이니 귤이 4개 더 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#1','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C1',1,'sa','auto','2씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u2-C1","difficulty":1,"kind":"sa","stem":"2씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["2씩 커지는 수예요.","6에서 2만큼 더 뛰면 8이에요.","2씩 4번 뛰어 센 수 — 2씩 4묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip","ks":[2],"pmax":45}},"answer":["8"],"asset":{"type":"jump_row","cells":[2,4,6,null],"step":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#2','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C2',1,'sa','auto','5 × 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u2-C2","difficulty":1,"kind":"sa","stem":"5 × 3은 얼마인가요? 숫자로 쓰세요.","explanation":["5 × 3은 5의 3배예요.","5씩 뛰어 세면 5, 10, 15.","그래서 5 × 3 = 15예요."],"variant_rule":{"mul":{"ask":"value","ks":[5],"pmax":81}},"answer":["15"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#3','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C3',1,'sa','auto','3 × 7은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u2-C3","difficulty":1,"kind":"sa","stem":"3 × 7은 얼마인가요? 숫자로 쓰세요.","explanation":["3 × 7은 3의 7배예요.","3씩 뛰어 세면 3, 6, 9, 12, 15, 18, 21.","그래서 3 × 7 = 21이에요."],"variant_rule":{"mul":{"ask":"value","ks":[3,6],"pmax":81}},"answer":["21"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#4','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C4',1,'mc','auto','4 × 6은 얼마인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X02']::text[],true,'{"seq":4,"concept":"M2-2-u2-C4","difficulty":1,"kind":"mc","stem":"4 × 6은 얼마인가요?","explanation":["4 × 6은 4의 6배예요.","4씩 뛰어 세면 4, 8, 12, 16, 20, 24.","그래서 4 × 6 = 24예요."],"variant_rule":{"mul":{"ask":"value","ks":[4,8],"pmax":81}},"options":[{"t":"24","correct":true},{"t":"10","mis":"M2-2-u2-X11"},{"t":"28","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#5','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C5',1,'mc','auto','7 × 4는 얼마인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X02']::text[],true,'{"seq":5,"concept":"M2-2-u2-C5","difficulty":1,"kind":"mc","stem":"7 × 4는 얼마인가요?","explanation":["7 × 4는 7의 4배예요.","7씩 뛰어 세면 7, 14, 21, 28.","그래서 7 × 4 = 28이에요."],"variant_rule":{"mul":{"ask":"value","ks":[7],"pmax":81}},"options":[{"t":"28","correct":true},{"t":"11","mis":"M2-2-u2-X11"},{"t":"35","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#6','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C6',1,'mc','auto','9 × 2는 얼마인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X02']::text[],true,'{"seq":6,"concept":"M2-2-u2-C6","difficulty":1,"kind":"mc","stem":"9 × 2는 얼마인가요?","explanation":["9 × 2는 9의 2배예요.","9씩 뛰어 세면 9, 18.","그래서 9 × 2 = 18이에요."],"variant_rule":{"mul":{"ask":"value","ks":[9],"pmax":81}},"options":[{"t":"18","correct":true},{"t":"11","mis":"M2-2-u2-X11"},{"t":"27","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#7','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C7',1,'mc','auto','0 × 6은 얼마인가요?',ARRAY['M2-2-u2-X08']::text[],true,'{"seq":7,"concept":"M2-2-u2-C7","difficulty":1,"kind":"mc","stem":"0 × 6은 얼마인가요?","explanation":["0 × 6은 0을 6번 더한 것이에요.","0과 어떤 수의 곱, 어떤 수와 0의 곱은 늘 0이에요.","그래서 0 × 6 = 0이에요."],"variant_rule":{"gugu":{"ask":"zero"}},"options":[{"t":"0","correct":true},{"t":"6","mis":"M2-2-u2-X08"},{"t":"1","mis":"M2-2-u2-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#8','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C8',1,'mc','auto','곱셈표의 ?에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X09']::text[],true,'{"seq":8,"concept":"M2-2-u2-C8","difficulty":1,"kind":"mc","stem":"곱셈표의 ?에 알맞은 수는 얼마인가요?","explanation":["?는 왼쪽 3과 위쪽 7이 만나는 칸이에요.","그래서 3 × 7의 곱을 써요 — 3 × 6 = 18에 3을 더해도 돼요.","3 × 7 = 21이에요."],"variant_rule":{"gugu":{"ask":"cell"}},"options":[{"t":"21","correct":true},{"t":"24","mis":"M2-2-u2-X09"},{"t":"18","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[1,2,3,4],"cols":[3,4,5,6,7],"q":[3,7],"blank":[[4,7],[3,4]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#9','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C8',2,'mc','auto','곱셈표에서 색칠한 6단 곱셈구구의 곱은 오른쪽으로 한 칸 갈 때마다 얼마씩 커지나요?',ARRAY['M2-2-u2-X01','M2-2-u2-X09']::text[],true,'{"seq":9,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표에서 색칠한 6단 곱셈구구의 곱은 오른쪽으로 한 칸 갈 때마다 얼마씩 커지나요?","explanation":["6단의 곱은 6, 12, 18, …예요.","곱하는 수가 1 커질 때마다 6씩 커져요.","그래서 6단 곱셈구구의 곱은 6씩 커져요 — 1씩이 아니에요."],"variant_rule":{"gugu":{"ask":"step"}},"options":[{"t":"6","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"7","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[5,6,7],"cols":[1,2,3,4,5,6,7,8,9],"hrow":6}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#10','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C4',2,'mc','auto','4 × 6 = 24예요. 이것을 이용하면 4 × 7은 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17','M2-2-u2-X02']::text[],true,'{"seq":10,"concept":"M2-2-u2-C4","difficulty":2,"kind":"mc","stem":"4 × 6 = 24예요. 이것을 이용하면 4 × 7은 얼마인가요?","explanation":["4 × 7은 4 × 6보다 4만큼 더 커요.","24 + 4 = 28이에요.","한 번 더 더할 때는 곱하는 수 7이 아니라 4를 더해요."],"variant_rule":{"gugu":{"ask":"build","ks":[4,8]}},"options":[{"t":"28","correct":true},{"t":"25","mis":"M2-2-u2-X01"},{"t":"31","mis":"M2-2-u2-X17"},{"t":"32","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#11','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C5',2,'mc','auto','7 × 5는 7 × 4보다 얼마 더 큰가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17']::text[],true,'{"seq":11,"concept":"M2-2-u2-C5","difficulty":2,"kind":"mc","stem":"7 × 5는 7 × 4보다 얼마 더 큰가요?","explanation":["7 × 4는 7을 4번, 7 × 5는 7을 5번 더한 것이에요.","7을 한 번 더 더했으니 7만큼 더 커요 — 28에서 35.","곱하는 수가 1 커지면 곱은 7만큼 커져요."],"variant_rule":{"gugu":{"ask":"next","ks":[7]}},"options":[{"t":"7","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"5","mis":"M2-2-u2-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#12','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C6',2,'mc','auto','9 × □ = 36에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02']::text[],true,'{"seq":12,"concept":"M2-2-u2-C6","difficulty":2,"kind":"mc","stem":"9 × □ = 36에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["9단 곱셈구구에서 곱이 36인 것을 찾아요.","9씩 뛰어 세면 9, 18, 27, 36 — 4번이에요.","9 × 4 = 36이라 □는 4예요."],"variant_rule":{"gugu":{"ask":"miss","ks":[9]}},"options":[{"t":"4","correct":true},{"t":"5","mis":"M2-2-u2-X02"},{"t":"3","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#13','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C9',2,'mc','auto','필통 한 개에 연필이 6자루씩 있어요. 필통 4개의 연필은 모두 몇 자루인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X14']::text[],true,'{"seq":13,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"필통 한 개에 연필이 6자루씩 있어요. 필통 4개의 연필은 모두 몇 자루인가요?","explanation":["필통 한 개에 6자루씩, 4개이면 6씩 4묶음이에요.","6 × 4 = 24예요.","연필은 모두 24자루예요."],"variant_rule":{"mul":{"ask":"story","pmax":81}},"options":[{"t":"24자루","correct":true},{"t":"10자루","mis":"M2-2-u2-X06"},{"t":"4자루","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#14','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C3',2,'ox','auto','6 × 4는 3 × 4를 두 번 더한 것과 같아요.',ARRAY['M2-2-u2-X10']::text[],false,'{"seq":14,"concept":"M2-2-u2-C3","difficulty":2,"kind":"ox","stem":"6 × 4는 3 × 4를 두 번 더한 것과 같아요.","answer":"O","reason_options":[{"t":"6씩 4묶음은 3씩 8묶음과 같아서 12 + 12 = 24니까","correct":true},{"t":"3단과 6단은 서로 관계가 없으니까","mis":"M2-2-u2-X10"}],"mis":"M2-2-u2-X10","explanation":["3 × 4 = 12예요.","12 + 12 = 24 = 6 × 4예요.","6단의 곱은 같은 수를 곱한 3단의 곱의 2배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#15','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C8',2,'mc','auto','1단부터 9단까지의 곱셈구구 가운데 곱이 6인 것은 모두 몇 개인가요?',ARRAY['M2-2-u2-X13','M2-2-u2-X09']::text[],true,'{"seq":15,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"1단부터 9단까지의 곱셈구구 가운데 곱이 6인 것은 모두 몇 개인가요?","explanation":["곱이 6인 곱셈구구는 1 × 6, 2 × 3, 3 × 2, 6 × 1이에요.","두 수를 바꾸어 곱한 것도 따로 세어요.","그래서 모두 4개예요."],"variant_rule":{"gugu":{"ask":"tfind"}},"options":[{"t":"4","correct":true},{"t":"3","mis":"M2-2-u2-X13"},{"t":"5","mis":"M2-2-u2-X09"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#16','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C7',2,'ox','auto','5 × 0 = 5입니다.',ARRAY['M2-2-u2-X08']::text[],true,'{"seq":16,"concept":"M2-2-u2-C7","difficulty":2,"kind":"ox","stem":"5 × 0 = 5입니다.","explanation":["5 × 0은 5를 0번 더한 것 — 하나도 없어요.","0과 어떤 수의 곱, 어떤 수와 0의 곱은 늘 0이에요.","그래서 5 × 0 = 0이에요."],"variant_rule":{"gugu":{"ask":"zero"}},"answer":"X","reason_options":[{"t":"5 × 0은 5가 아니라 0이 되니까","correct":true},{"t":"0을 곱하면 그 수가 그대로 남으니까","mis":"M2-2-u2-X08"}],"mis":"M2-2-u2-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#17','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C9',3,'mc','auto','연결 모형이 왼쪽에 6개씩 2줄, 오른쪽에 3개씩 4줄 붙어 있어요. 연결 모형은 모두 몇 개인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X18']::text[],false,'{"seq":17,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"연결 모형이 왼쪽에 6개씩 2줄, 오른쪽에 3개씩 4줄 붙어 있어요. 연결 모형은 모두 몇 개인가요?","options":[{"t":"24개","correct":true},{"t":"15개","mis":"M2-2-u2-X17"},{"t":"12개","mis":"M2-2-u2-X18"}],"explanation":["왼쪽은 6 × 2 = 12개예요.","오른쪽은 3 × 4 = 12개예요.","12 + 12 = 24이니 모두 24개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#18','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C8',3,'mc','auto','두 곱의 크기를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#19','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C10',3,'mc','auto','2단 곱셈구구의 곱 2, 4, 6, 8, 10, 12, 14, 16, 18에서 일의 자리 숫자만 차례로 보면 어떤 규칙이 있나요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":19,"concept":"M2-2-u2-C10","difficulty":3,"kind":"mc","stem":"2단 곱셈구구의 곱 2, 4, 6, 8, 10, 12, 14, 16, 18에서 일의 자리 숫자만 차례로 보면 어떤 규칙이 있나요?","options":[{"t":"2, 4, 6, 8, 0이 되풀이돼요","correct":true},{"t":"1씩 커져요","mis":"M2-2-u2-X16"},{"t":"2, 4, 6, 8, 10이 되풀이돼요","mis":"M2-2-u2-X16"}],"explanation":["일의 자리 숫자만 쓰면 2, 4, 6, 8, 0, 2, 4, 6, 8이에요.","2, 4, 6, 8, 0이 되풀이돼요.","10은 일의 자리 숫자가 아니라 곱 전체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#20','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C7',3,'mc','auto','과녁 맞히기에서 0점에 4번, 1점에 3번, 2점에 2번 맞혔어요. 얻은 점수는 모두 몇 점인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X05']::text[],false,'{"seq":20,"concept":"M2-2-u2-C7","difficulty":3,"kind":"mc","stem":"과녁 맞히기에서 0점에 4번, 1점에 3번, 2점에 2번 맞혔어요. 얻은 점수는 모두 몇 점인가요?","options":[{"t":"7점","correct":true},{"t":"11점","mis":"M2-2-u2-X08"},{"t":"9점","mis":"M2-2-u2-X05"}],"explanation":["0 × 4 = 0, 1 × 3 = 3, 2 × 2 = 4예요.","0 + 3 + 4 = 7이에요.","9는 맞힌 횟수를 더한 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#21','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C6',3,'mc','auto','9 × 2부터 9 × 9까지 9단 곱셈구구의 곱에서 십의 자리 숫자와 일의 자리 숫자를 더하면 얼마인가요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":21,"concept":"M2-2-u2-C6","difficulty":3,"kind":"mc","stem":"9 × 2부터 9 × 9까지 9단 곱셈구구의 곱에서 십의 자리 숫자와 일의 자리 숫자를 더하면 얼마인가요?","options":[{"t":"9","correct":true},{"t":"10","mis":"M2-2-u2-X16"},{"t":"곱하는 수와 같아요","mis":"M2-2-u2-X16"}],"explanation":["18은 1 + 8, 27은 2 + 7, 36은 3 + 6이에요.","모두 9예요.","9단의 곱은 두 숫자의 합이 9예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#22','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C4',3,'error','auto','4단과 8단에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u2-X10','M2-2-u2-X15']::text[],false,'{"seq":22,"concept":"M2-2-u2-C4","difficulty":3,"kind":"error","stem":"4단과 8단에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지우 — 「4단과 8단은 서로 관계가 없어.」","correct":true,"mis_target":"M2-2-u2-X10"},{"t":"서아 — 「8 × 3은 4 × 3을 두 번 더한 것과 같아.」","mis":"M2-2-u2-X15"},{"t":"하루 — 「4 × 6과 8 × 3은 곱이 24로 같아.」","mis":"M2-2-u2-X15"}],"explanation":["8씩 한 묶음은 4씩 두 묶음이에요.","그래서 8단의 곱은 같은 수를 곱한 4단의 곱의 2배예요.","지우의 말이 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#23','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C10',4,'essay','teacher','2단 곱셈구구의 곱을 쓰고, 곱의 일의 자리 숫자를 차례로 써서 어떤 규칙이 있는지 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u2-C10","difficulty":4,"kind":"essay","stem":"2단 곱셈구구의 곱을 쓰고, 곱의 일의 자리 숫자를 차례로 써서 어떤 규칙이 있는지 설명해 보세요.","answer_guide":{"answer":"예: 2, 4, 6, 8, 10, 12, 14, 16, 18. 일의 자리 숫자는 2, 4, 6, 8, 0, 2, 4, 6, 8로 2, 4, 6, 8, 0이 되풀이된다.","scoring_points":["곱을 바르게 구했는가","일의 자리 숫자를 차례로 바르게 썼는가","되풀이되는 규칙이나 같은 무늬가 나오는 까닭을 썼는가"]},"explanation":["곱의 일의 자리 숫자만 따로 써요.","같은 숫자가 되풀이되는지 살펴요.","되풀이되는 숫자를 둥근 판에 이으면 무늬가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#24','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C9',4,'essay','teacher','의자가 한 줄에 5개씩 6줄로 놓여 있는데 두 자리가 비어 있어요. 의자의 수를 곱셈구구로 구하고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u2-C9","difficulty":4,"kind":"essay","stem":"의자가 한 줄에 5개씩 6줄로 놓여 있는데 두 자리가 비어 있어요. 의자의 수를 곱셈구구로 구하고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 빈자리까지 채우면 5 × 6 = 30개이다. 두 자리가 비었으므로 30 − 2 = 28개이다.","scoring_points":["곱셈구구로 나누어 곱하거나 빈자리를 채워 곱했는가","더하거나 빼는 과정을 바르게 썼는가","답을 바르게 구했는가"]},"explanation":["같은 수씩 놓인 덩이를 찾아 곱해요.","빈자리는 빼고, 덩이가 둘이면 두 곱을 더해요.","하나씩 세는 것보다 빠르고 정확해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#25','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C8',4,'essay','teacher','곱셈표에서 곱이 12인 곱셈구구를 모두 찾아 쓰고, 어떻게 찾았는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u2-C8","difficulty":4,"kind":"essay","stem":"곱셈표에서 곱이 12인 곱셈구구를 모두 찾아 쓰고, 어떻게 찾았는지 설명해 보세요.","answer_guide":{"answer":"예: 2 × 6, 3 × 4, 4 × 3, 6 × 2. 곱셈표에서 12가 있는 칸을 모두 찾고, 두 수를 바꾼 것도 함께 썼다.","scoring_points":["곱이 12인 곱셈구구를 하나 이상 찾았는가","두 수를 바꾼 것과 다른 단의 것까지 모두 찾았는가","곱셈표에서 12인 칸을 찾았다는 등 방법을 썼는가"]},"explanation":["곱셈표에서 같은 수가 있는 칸을 모두 찾아요.","두 수를 바꾸어 곱해도 곱이 같아요.","곱이 같은 곱셈구구는 여러 개일 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#1','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C1',1,'sa','auto','2씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u2-C1","difficulty":1,"kind":"sa","stem":"2씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["2씩 커지는 수예요.","8에서 2만큼 더 뛰면 10이에요.","2씩 5번 뛰어 센 수 — 2씩 5묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip","ks":[2],"pmax":45}},"answer":["10"],"asset":{"type":"jump_row","cells":[2,4,6,8,null],"step":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#2','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C2',1,'sa','auto','5 × 7은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u2-C2","difficulty":1,"kind":"sa","stem":"5 × 7은 얼마인가요? 숫자로 쓰세요.","explanation":["5 × 7은 5의 7배예요.","5씩 뛰어 세면 5, 10, 15, 20, 25, 30, 35.","그래서 5 × 7 = 35예요."],"variant_rule":{"mul":{"ask":"value","ks":[5],"pmax":81}},"answer":["35"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#3','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C3',1,'sa','auto','6 × 4는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u2-C3","difficulty":1,"kind":"sa","stem":"6 × 4는 얼마인가요? 숫자로 쓰세요.","explanation":["6 × 4는 6의 4배예요.","6씩 뛰어 세면 6, 12, 18, 24.","그래서 6 × 4 = 24예요."],"variant_rule":{"mul":{"ask":"value","ks":[3,6],"pmax":81}},"answer":["24"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#4','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C4',1,'mc','auto','8 × 3은 얼마인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X02']::text[],true,'{"seq":4,"concept":"M2-2-u2-C4","difficulty":1,"kind":"mc","stem":"8 × 3은 얼마인가요?","explanation":["8 × 3은 8의 3배예요.","8씩 뛰어 세면 8, 16, 24.","그래서 8 × 3 = 24예요."],"variant_rule":{"mul":{"ask":"value","ks":[4,8],"pmax":81}},"options":[{"t":"24","correct":true},{"t":"11","mis":"M2-2-u2-X11"},{"t":"32","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#5','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C5',1,'mc','auto','7 × 6은 얼마인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X02']::text[],true,'{"seq":5,"concept":"M2-2-u2-C5","difficulty":1,"kind":"mc","stem":"7 × 6은 얼마인가요?","explanation":["7 × 6은 7의 6배예요.","7씩 뛰어 세면 7, 14, 21, 28, 35, 42.","그래서 7 × 6 = 42예요."],"variant_rule":{"mul":{"ask":"value","ks":[7],"pmax":81}},"options":[{"t":"42","correct":true},{"t":"13","mis":"M2-2-u2-X11"},{"t":"49","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#6','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C6',1,'mc','auto','9 × 5는 얼마인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X02']::text[],true,'{"seq":6,"concept":"M2-2-u2-C6","difficulty":1,"kind":"mc","stem":"9 × 5는 얼마인가요?","explanation":["9 × 5는 9의 5배예요.","9씩 뛰어 세면 9, 18, 27, 36, 45.","그래서 9 × 5 = 45예요."],"variant_rule":{"mul":{"ask":"value","ks":[9],"pmax":81}},"options":[{"t":"45","correct":true},{"t":"14","mis":"M2-2-u2-X11"},{"t":"54","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#7','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C7',1,'mc','auto','3 × 0은 얼마인가요?',ARRAY['M2-2-u2-X08']::text[],true,'{"seq":7,"concept":"M2-2-u2-C7","difficulty":1,"kind":"mc","stem":"3 × 0은 얼마인가요?","explanation":["3 × 0은 3을 0번 더한 것 — 하나도 없어요.","0과 어떤 수의 곱, 어떤 수와 0의 곱은 늘 0이에요.","그래서 3 × 0 = 0이에요."],"variant_rule":{"gugu":{"ask":"zero"}},"options":[{"t":"0","correct":true},{"t":"3","mis":"M2-2-u2-X08"},{"t":"1","mis":"M2-2-u2-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#8','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C8',1,'mc','auto','곱셈표의 ?에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X09']::text[],true,'{"seq":8,"concept":"M2-2-u2-C8","difficulty":1,"kind":"mc","stem":"곱셈표의 ?에 알맞은 수는 얼마인가요?","explanation":["?는 왼쪽 6과 위쪽 4가 만나는 칸이에요.","그래서 6 × 4의 곱을 써요 — 6 × 3 = 18에 6을 더해도 돼요.","6 × 4 = 24예요."],"variant_rule":{"gugu":{"ask":"cell"}},"options":[{"t":"24","correct":true},{"t":"30","mis":"M2-2-u2-X09"},{"t":"18","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[4,5,6,7],"cols":[1,2,3,4,5],"q":[6,4],"blank":[[7,4],[6,2]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#9','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C8',2,'mc','auto','곱셈표에서 색칠한 8단 곱셈구구의 곱은 오른쪽으로 한 칸 갈 때마다 얼마씩 커지나요?',ARRAY['M2-2-u2-X01','M2-2-u2-X09']::text[],true,'{"seq":9,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표에서 색칠한 8단 곱셈구구의 곱은 오른쪽으로 한 칸 갈 때마다 얼마씩 커지나요?","explanation":["8단의 곱은 8, 16, 24, …예요.","곱하는 수가 1 커질 때마다 8씩 커져요.","그래서 8단 곱셈구구의 곱은 8씩 커져요 — 1씩이 아니에요."],"variant_rule":{"gugu":{"ask":"step"}},"options":[{"t":"8","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"9","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[7,8,9],"cols":[1,2,3,4,5,6,7,8,9],"hrow":8}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#10','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C4',2,'mc','auto','8 × 4 = 32예요. 이것을 이용하면 8 × 5는 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17','M2-2-u2-X02']::text[],true,'{"seq":10,"concept":"M2-2-u2-C4","difficulty":2,"kind":"mc","stem":"8 × 4 = 32예요. 이것을 이용하면 8 × 5는 얼마인가요?","explanation":["8 × 5는 8 × 4보다 8만큼 더 커요.","32 + 8 = 40이에요.","한 번 더 더할 때는 곱하는 수 5가 아니라 8을 더해요."],"variant_rule":{"gugu":{"ask":"build","ks":[4,8]}},"options":[{"t":"40","correct":true},{"t":"33","mis":"M2-2-u2-X01"},{"t":"37","mis":"M2-2-u2-X17"},{"t":"48","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#11','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C5',2,'mc','auto','7 × 8은 7 × 7보다 얼마 더 큰가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17']::text[],true,'{"seq":11,"concept":"M2-2-u2-C5","difficulty":2,"kind":"mc","stem":"7 × 8은 7 × 7보다 얼마 더 큰가요?","explanation":["7 × 7은 7을 7번, 7 × 8은 7을 8번 더한 것이에요.","7을 한 번 더 더했으니 7만큼 더 커요 — 49에서 56.","곱하는 수가 1 커지면 곱은 7만큼 커져요."],"variant_rule":{"gugu":{"ask":"next","ks":[7]}},"options":[{"t":"7","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"8","mis":"M2-2-u2-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#12','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C6',2,'mc','auto','9 × □ = 63에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02']::text[],true,'{"seq":12,"concept":"M2-2-u2-C6","difficulty":2,"kind":"mc","stem":"9 × □ = 63에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["9단 곱셈구구에서 곱이 63인 것을 찾아요.","9씩 뛰어 세면 9, 18, 27, 36, 45, 54, 63 — 7번이에요.","9 × 7 = 63이라 □는 7이에요."],"variant_rule":{"gugu":{"ask":"miss","ks":[9]}},"options":[{"t":"7","correct":true},{"t":"8","mis":"M2-2-u2-X02"},{"t":"6","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#13','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C9',2,'mc','auto','쟁반 한 개에 딸기가 5개씩 있어요. 쟁반 6개의 딸기는 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X14']::text[],true,'{"seq":13,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"쟁반 한 개에 딸기가 5개씩 있어요. 쟁반 6개의 딸기는 모두 몇 개인가요?","explanation":["쟁반 한 개에 5개씩, 6개이면 5씩 6묶음이에요.","5 × 6 = 30이에요.","딸기는 모두 30개예요."],"variant_rule":{"mul":{"ask":"story","pmax":81}},"options":[{"t":"30개","correct":true},{"t":"11개","mis":"M2-2-u2-X06"},{"t":"6개","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#14','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C3',2,'ox','auto','3 × 7은 7 × 3보다 커요.',ARRAY['M2-2-u2-X13']::text[],false,'{"seq":14,"concept":"M2-2-u2-C3","difficulty":2,"kind":"ox","stem":"3 × 7은 7 × 3보다 커요.","answer":"X","reason_options":[{"t":"두 수를 바꾸어 곱해도 곱은 21로 같으니까","correct":true},{"t":"곱하는 수가 크면 곱도 크니까","mis":"M2-2-u2-X13"}],"mis":"M2-2-u2-X13","explanation":["3 × 7 = 21이에요.","7 × 3 = 21이에요.","그래서 두 곱은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#15','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C8',2,'mc','auto','1단부터 9단까지의 곱셈구구 가운데 곱이 18인 것은 모두 몇 개인가요?',ARRAY['M2-2-u2-X13','M2-2-u2-X09']::text[],true,'{"seq":15,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"1단부터 9단까지의 곱셈구구 가운데 곱이 18인 것은 모두 몇 개인가요?","explanation":["곱이 18인 곱셈구구는 2 × 9, 3 × 6, 6 × 3, 9 × 2예요.","두 수를 바꾸어 곱한 것도 따로 세어요.","그래서 모두 4개예요."],"variant_rule":{"gugu":{"ask":"tfind"}},"options":[{"t":"4","correct":true},{"t":"3","mis":"M2-2-u2-X13"},{"t":"5","mis":"M2-2-u2-X09"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#16','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C7',2,'ox','auto','1 × 7 = 7입니다.',ARRAY['M2-2-u2-X08']::text[],true,'{"seq":16,"concept":"M2-2-u2-C7","difficulty":2,"kind":"ox","stem":"1 × 7 = 7입니다.","explanation":["1 × 7은 1을 7번 더한 것이에요.","1과 어떤 수의 곱, 어떤 수와 1의 곱은 늘 그 수예요.","그래서 1 × 7 = 7이에요."],"variant_rule":{"gugu":{"ask":"zero"}},"answer":"O","reason_options":[{"t":"1을 7번 더하면 7이 되니까","correct":true},{"t":"1을 곱하면 1이 되니까","mis":"M2-2-u2-X08"}],"mis":"M2-2-u2-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#17','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C9',3,'mc','auto','책상이 한 줄에 6개씩 4줄로 놓여 있는데, 두 자리가 비어 있어요. 책상은 모두 몇 개인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X06']::text[],false,'{"seq":17,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"책상이 한 줄에 6개씩 4줄로 놓여 있는데, 두 자리가 비어 있어요. 책상은 모두 몇 개인가요?","options":[{"t":"22개","correct":true},{"t":"24개","mis":"M2-2-u2-X18"},{"t":"10개","mis":"M2-2-u2-X06"}],"explanation":["빈자리까지 채우면 6 × 4 = 24개예요.","두 자리가 비었어요.","24 − 2 = 22이니 22개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#18','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C8',3,'mc','auto','두 곱의 크기를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#19','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C10',3,'mc','auto','5단 곱셈구구의 곱의 일의 자리 숫자를 0부터 9까지 둥글게 적힌 판에 차례로 이으면 어떤 모양이 나올까요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":19,"concept":"M2-2-u2-C10","difficulty":3,"kind":"mc","stem":"5단 곱셈구구의 곱의 일의 자리 숫자를 0부터 9까지 둥글게 적힌 판에 차례로 이으면 어떤 모양이 나올까요?","options":[{"t":"5와 0을 오가는 한 줄","correct":true},{"t":"별 모양","mis":"M2-2-u2-X16"},{"t":"오각형","mis":"M2-2-u2-X16"}],"explanation":["5단의 곱은 5, 10, 15, 20, …이에요.","일의 자리 숫자는 5와 0뿐이에요.","그래서 5와 0을 오가는 한 줄이 나와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#20','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C7',3,'mc','auto','과녁 맞히기에서 0점에 3번, 1점에 5번, 3점에 2번 맞혔어요. 얻은 점수는 모두 몇 점인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X05']::text[],false,'{"seq":20,"concept":"M2-2-u2-C7","difficulty":3,"kind":"mc","stem":"과녁 맞히기에서 0점에 3번, 1점에 5번, 3점에 2번 맞혔어요. 얻은 점수는 모두 몇 점인가요?","options":[{"t":"11점","correct":true},{"t":"14점","mis":"M2-2-u2-X08"},{"t":"10점","mis":"M2-2-u2-X05"}],"explanation":["0 × 3 = 0, 1 × 5 = 5, 3 × 2 = 6이에요.","0 + 5 + 6 = 11이에요.","10은 맞힌 횟수를 더한 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#21','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C6',3,'mc','auto','9 × 7의 곱에서 십의 자리 숫자는 얼마인가요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":21,"concept":"M2-2-u2-C6","difficulty":3,"kind":"mc","stem":"9 × 7의 곱에서 십의 자리 숫자는 얼마인가요?","options":[{"t":"6","correct":true},{"t":"7","mis":"M2-2-u2-X16"},{"t":"3","mis":"M2-2-u2-X16"}],"explanation":["9 × 7 = 63이에요.","십의 자리 숫자는 6이에요.","9단에서 곱의 십의 자리 숫자는 곱하는 수보다 1 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#22','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C4',3,'error','auto','4단과 8단에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u2-X10','M2-2-u2-X15']::text[],false,'{"seq":22,"concept":"M2-2-u2-C4","difficulty":3,"kind":"error","stem":"4단과 8단에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「4 × 5가 20이니까 8 × 5는 28이야.」","correct":true,"mis_target":"M2-2-u2-X10"},{"t":"은솔 — 「8 × 5는 4 × 5의 2배라서 40이야.」","mis":"M2-2-u2-X15"},{"t":"예린 — 「우유 4갑씩 6줄은 8갑씩 3줄과 같아.」","mis":"M2-2-u2-X15"}],"explanation":["8 × 5는 4 × 5의 2배예요.","20의 2배는 40이에요.","도윤이는 2배 하지 않고 8만 더했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#23','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C10',4,'essay','teacher','5단 곱셈구구의 곱을 쓰고, 곱의 일의 자리 숫자를 차례로 써서 어떤 규칙이 있는지 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u2-C10","difficulty":4,"kind":"essay","stem":"5단 곱셈구구의 곱을 쓰고, 곱의 일의 자리 숫자를 차례로 써서 어떤 규칙이 있는지 설명해 보세요.","answer_guide":{"answer":"예: 5, 10, 15, 20, 25, 30, 35, 40, 45. 일의 자리 숫자는 5, 0, 5, 0, …으로 5와 0이 번갈아 되풀이된다.","scoring_points":["곱을 바르게 구했는가","일의 자리 숫자를 차례로 바르게 썼는가","되풀이되는 규칙이나 같은 무늬가 나오는 까닭을 썼는가"]},"explanation":["곱의 일의 자리 숫자만 따로 써요.","같은 숫자가 되풀이되는지 살펴요.","되풀이되는 숫자를 둥근 판에 이으면 무늬가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#24','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C9',4,'essay','teacher','연결 모형이 4개씩 3줄과 2개씩 5줄로 붙어 있어요. 연결 모형의 수를 곱셈구구로 구하고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u2-C9","difficulty":4,"kind":"essay","stem":"연결 모형이 4개씩 3줄과 2개씩 5줄로 붙어 있어요. 연결 모형의 수를 곱셈구구로 구하고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 4 × 3 = 12, 2 × 5 = 10이다. 두 덩이를 더하면 12 + 10 = 22개이다.","scoring_points":["곱셈구구로 나누어 곱하거나 빈자리를 채워 곱했는가","더하거나 빼는 과정을 바르게 썼는가","답을 바르게 구했는가"]},"explanation":["같은 수씩 놓인 덩이를 찾아 곱해요.","빈자리는 빼고, 덩이가 둘이면 두 곱을 더해요.","하나씩 세는 것보다 빠르고 정확해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#25','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C8',4,'essay','teacher','곱셈표에서 곱이 18인 곱셈구구를 모두 찾아 쓰고, 어떻게 찾았는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u2-C8","difficulty":4,"kind":"essay","stem":"곱셈표에서 곱이 18인 곱셈구구를 모두 찾아 쓰고, 어떻게 찾았는지 설명해 보세요.","answer_guide":{"answer":"예: 2 × 9, 3 × 6, 6 × 3, 9 × 2. 곱셈표에서 18이 있는 칸을 모두 찾고, 두 수를 바꾼 것도 함께 썼다.","scoring_points":["곱이 18인 곱셈구구를 하나 이상 찾았는가","두 수를 바꾼 것과 다른 단의 것까지 모두 찾았는가","곱셈표에서 18인 칸을 찾았다는 등 방법을 썼는가"]},"explanation":["곱셈표에서 같은 수가 있는 칸을 모두 찾아요.","두 수를 바꾸어 곱해도 곱이 같아요.","곱이 같은 곱셈구구는 여러 개일 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#1','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C1',1,'sa','auto','2씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u2-C1","difficulty":1,"kind":"sa","stem":"2씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["2씩 커지는 수예요.","10에서 2만큼 더 뛰면 12예요.","2씩 6번 뛰어 센 수 — 2씩 6묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip","ks":[2],"pmax":45}},"answer":["12"],"asset":{"type":"jump_row","cells":[2,4,6,8,10,null],"step":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#2','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C2',1,'sa','auto','5 × 8은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u2-C2","difficulty":1,"kind":"sa","stem":"5 × 8은 얼마인가요? 숫자로 쓰세요.","explanation":["5 × 8은 5의 8배예요.","5씩 뛰어 세면 5, 10, 15, 20, 25, 30, 35, 40.","그래서 5 × 8 = 40이에요."],"variant_rule":{"mul":{"ask":"value","ks":[5],"pmax":81}},"answer":["40"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#3','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C3',1,'sa','auto','3 × 9는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u2-C3","difficulty":1,"kind":"sa","stem":"3 × 9는 얼마인가요? 숫자로 쓰세요.","explanation":["3 × 9는 3의 9배예요.","3씩 뛰어 세면 3, 6, 9, 12, 15, 18, 21, 24, 27.","그래서 3 × 9 = 27이에요."],"variant_rule":{"mul":{"ask":"value","ks":[3,6],"pmax":81}},"answer":["27"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#4','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C4',1,'mc','auto','4 × 8은 얼마인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X02']::text[],true,'{"seq":4,"concept":"M2-2-u2-C4","difficulty":1,"kind":"mc","stem":"4 × 8은 얼마인가요?","explanation":["4 × 8은 4의 8배예요.","4씩 뛰어 세면 4, 8, 12, 16, 20, 24, 28, 32.","그래서 4 × 8 = 32예요."],"variant_rule":{"mul":{"ask":"value","ks":[4,8],"pmax":81}},"options":[{"t":"32","correct":true},{"t":"12","mis":"M2-2-u2-X11"},{"t":"36","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#5','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C5',1,'mc','auto','7 × 8은 얼마인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X02']::text[],true,'{"seq":5,"concept":"M2-2-u2-C5","difficulty":1,"kind":"mc","stem":"7 × 8은 얼마인가요?","explanation":["7 × 8은 7의 8배예요.","7씩 뛰어 세면 7, 14, 21, 28, 35, 42, 49, 56.","그래서 7 × 8 = 56이에요."],"variant_rule":{"mul":{"ask":"value","ks":[7],"pmax":81}},"options":[{"t":"56","correct":true},{"t":"15","mis":"M2-2-u2-X11"},{"t":"63","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#6','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C6',1,'mc','auto','9 × 7은 얼마인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X02']::text[],true,'{"seq":6,"concept":"M2-2-u2-C6","difficulty":1,"kind":"mc","stem":"9 × 7은 얼마인가요?","explanation":["9 × 7은 9의 7배예요.","9씩 뛰어 세면 9, 18, 27, 36, 45, 54, 63.","그래서 9 × 7 = 63이에요."],"variant_rule":{"mul":{"ask":"value","ks":[9],"pmax":81}},"options":[{"t":"63","correct":true},{"t":"16","mis":"M2-2-u2-X11"},{"t":"72","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#7','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C7',1,'mc','auto','1 × 8은 얼마인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X06']::text[],true,'{"seq":7,"concept":"M2-2-u2-C7","difficulty":1,"kind":"mc","stem":"1 × 8은 얼마인가요?","explanation":["1 × 8은 1을 8번 더한 것이에요.","1과 어떤 수의 곱, 어떤 수와 1의 곱은 늘 그 수예요.","그래서 1 × 8 = 8이에요."],"variant_rule":{"gugu":{"ask":"zero"}},"options":[{"t":"8","correct":true},{"t":"1","mis":"M2-2-u2-X08"},{"t":"9","mis":"M2-2-u2-X06"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#8','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C8',1,'mc','auto','곱셈표의 ?에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X09']::text[],true,'{"seq":8,"concept":"M2-2-u2-C8","difficulty":1,"kind":"mc","stem":"곱셈표의 ?에 알맞은 수는 얼마인가요?","explanation":["?는 왼쪽 4와 위쪽 8이 만나는 칸이에요.","그래서 4 × 8의 곱을 써요 — 4 × 7 = 28에 4를 더해도 돼요.","4 × 8 = 32예요."],"variant_rule":{"gugu":{"ask":"cell"}},"options":[{"t":"32","correct":true},{"t":"36","mis":"M2-2-u2-X09"},{"t":"28","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[2,3,4,5],"cols":[4,5,6,7,8],"q":[4,8],"blank":[[5,8],[4,5]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#9','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C8',2,'mc','auto','곱셈표에서 색칠한 3단 곱셈구구의 곱은 오른쪽으로 한 칸 갈 때마다 얼마씩 커지나요?',ARRAY['M2-2-u2-X01','M2-2-u2-X09']::text[],true,'{"seq":9,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표에서 색칠한 3단 곱셈구구의 곱은 오른쪽으로 한 칸 갈 때마다 얼마씩 커지나요?","explanation":["3단의 곱은 3, 6, 9, …예요.","곱하는 수가 1 커질 때마다 3씩 커져요.","그래서 3단 곱셈구구의 곱은 3씩 커져요 — 1씩이 아니에요."],"variant_rule":{"gugu":{"ask":"step"}},"options":[{"t":"3","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"4","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[2,3,4],"cols":[1,2,3,4,5,6,7,8,9],"hrow":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#10','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C4',2,'mc','auto','4 × 8 = 32예요. 이것을 이용하면 4 × 9는 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17','M2-2-u2-X02']::text[],true,'{"seq":10,"concept":"M2-2-u2-C4","difficulty":2,"kind":"mc","stem":"4 × 8 = 32예요. 이것을 이용하면 4 × 9는 얼마인가요?","explanation":["4 × 9는 4 × 8보다 4만큼 더 커요.","32 + 4 = 36이에요.","한 번 더 더할 때는 곱하는 수 9가 아니라 4를 더해요."],"variant_rule":{"gugu":{"ask":"build","ks":[4,8]}},"options":[{"t":"36","correct":true},{"t":"33","mis":"M2-2-u2-X01"},{"t":"41","mis":"M2-2-u2-X17"},{"t":"40","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#11','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C5',2,'mc','auto','7 × 3은 7 × 2보다 얼마 더 큰가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17']::text[],true,'{"seq":11,"concept":"M2-2-u2-C5","difficulty":2,"kind":"mc","stem":"7 × 3은 7 × 2보다 얼마 더 큰가요?","explanation":["7 × 2는 7을 2번, 7 × 3은 7을 3번 더한 것이에요.","7을 한 번 더 더했으니 7만큼 더 커요 — 14에서 21.","곱하는 수가 1 커지면 곱은 7만큼 커져요."],"variant_rule":{"gugu":{"ask":"next","ks":[7]}},"options":[{"t":"7","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"3","mis":"M2-2-u2-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#12','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C6',2,'mc','auto','9 × □ = 27에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02']::text[],true,'{"seq":12,"concept":"M2-2-u2-C6","difficulty":2,"kind":"mc","stem":"9 × □ = 27에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["9단 곱셈구구에서 곱이 27인 것을 찾아요.","9씩 뛰어 세면 9, 18, 27 — 3번이에요.","9 × 3 = 27이라 □는 3이에요."],"variant_rule":{"gugu":{"ask":"miss","ks":[9]}},"options":[{"t":"3","correct":true},{"t":"4","mis":"M2-2-u2-X02"},{"t":"2","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#13','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C9',2,'mc','auto','주머니 한 개에 구슬이 7개씩 있어요. 주머니 3개의 구슬은 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X14']::text[],true,'{"seq":13,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"주머니 한 개에 구슬이 7개씩 있어요. 주머니 3개의 구슬은 모두 몇 개인가요?","explanation":["주머니 한 개에 7개씩, 3개이면 7씩 3묶음이에요.","7 × 3 = 21이에요.","구슬은 모두 21개예요."],"variant_rule":{"mul":{"ask":"story","pmax":81}},"options":[{"t":"21개","correct":true},{"t":"10개","mis":"M2-2-u2-X06"},{"t":"3개","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#14','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C3',2,'ox','auto','6 × 6은 6 × 5에 6을 더한 것이에요.',ARRAY['M2-2-u2-X17']::text[],false,'{"seq":14,"concept":"M2-2-u2-C3","difficulty":2,"kind":"ox","stem":"6 × 6은 6 × 5에 6을 더한 것이에요.","answer":"O","reason_options":[{"t":"6을 한 번 더 더하면 되니까 30 + 6 = 36","correct":true},{"t":"6 × 5에 5를 더해야 하니까","mis":"M2-2-u2-X17"}],"mis":"M2-2-u2-X17","explanation":["6 × 5 = 30이에요.","6 × 6은 6 × 5보다 6만큼 커요.","30 + 6 = 36이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#15','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C8',2,'mc','auto','1단부터 9단까지의 곱셈구구 가운데 곱이 16인 것은 모두 몇 개인가요?',ARRAY['M2-2-u2-X13','M2-2-u2-X09']::text[],true,'{"seq":15,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"1단부터 9단까지의 곱셈구구 가운데 곱이 16인 것은 모두 몇 개인가요?","explanation":["곱이 16인 곱셈구구는 2 × 8, 4 × 4, 8 × 2예요.","두 수를 바꾸어 곱한 것도 따로 세어요.","그래서 모두 3개예요."],"variant_rule":{"gugu":{"ask":"tfind"}},"options":[{"t":"3","correct":true},{"t":"2","mis":"M2-2-u2-X13"},{"t":"4","mis":"M2-2-u2-X09"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#16','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C7',2,'ox','auto','0 × 9 = 0입니다.',ARRAY['M2-2-u2-X08']::text[],true,'{"seq":16,"concept":"M2-2-u2-C7","difficulty":2,"kind":"ox","stem":"0 × 9 = 0입니다.","explanation":["0 × 9는 0을 9번 더한 것이에요.","0과 어떤 수의 곱, 어떤 수와 0의 곱은 늘 0이에요.","그래서 0 × 9 = 0이에요."],"variant_rule":{"gugu":{"ask":"zero"}},"answer":"O","reason_options":[{"t":"0을 9번 더해도 0이니까","correct":true},{"t":"0을 곱하면 그 수가 그대로 남으니까","mis":"M2-2-u2-X08"}],"mis":"M2-2-u2-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#17','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C9',3,'mc','auto','의자가 한 줄에 7개씩 3줄 있고, 따로 4개가 더 있어요. 의자는 모두 몇 개인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X06']::text[],false,'{"seq":17,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"의자가 한 줄에 7개씩 3줄 있고, 따로 4개가 더 있어요. 의자는 모두 몇 개인가요?","options":[{"t":"25개","correct":true},{"t":"21개","mis":"M2-2-u2-X18"},{"t":"14개","mis":"M2-2-u2-X06"}],"explanation":["줄에 놓인 의자는 7 × 3 = 21개예요.","따로 있는 4개를 더해요.","21 + 4 = 25이니 모두 25개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#18','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C8',3,'mc','auto','두 곱의 크기를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#19','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C10',3,'mc','auto','8단 곱셈구구의 곱 8, 16, 24, 32, 40의 일의 자리 숫자를 차례로 쓴 것은 어느 것인가요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":19,"concept":"M2-2-u2-C10","difficulty":3,"kind":"mc","stem":"8단 곱셈구구의 곱 8, 16, 24, 32, 40의 일의 자리 숫자를 차례로 쓴 것은 어느 것인가요?","options":[{"t":"8, 6, 4, 2, 0","correct":true},{"t":"8, 16, 24, 32, 40","mis":"M2-2-u2-X16"},{"t":"8, 7, 6, 5, 4","mis":"M2-2-u2-X16"}],"explanation":["일의 자리 숫자만 써요.","8, 6, 4, 2, 0이에요.","2단(2, 4, 6, 8, 0)과 같은 숫자를 거꾸로 이어 같은 무늬가 나와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#20','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C7',3,'mc','auto','과녁 맞히기에서 0점에 5번, 1점에 1번, 4점에 2번 맞혔어요. 얻은 점수는 모두 몇 점인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X05']::text[],false,'{"seq":20,"concept":"M2-2-u2-C7","difficulty":3,"kind":"mc","stem":"과녁 맞히기에서 0점에 5번, 1점에 1번, 4점에 2번 맞혔어요. 얻은 점수는 모두 몇 점인가요?","options":[{"t":"9점","correct":true},{"t":"14점","mis":"M2-2-u2-X08"},{"t":"8점","mis":"M2-2-u2-X05"}],"explanation":["0 × 5 = 0, 1 × 1 = 1, 4 × 2 = 8이에요.","0 + 1 + 8 = 9예요.","8은 맞힌 횟수를 더한 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#21','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C6',3,'mc','auto','9단 곱셈구구에서 곱하는 수가 1 커지면 곱의 일의 자리 숫자는 어떻게 되나요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":21,"concept":"M2-2-u2-C6","difficulty":3,"kind":"mc","stem":"9단 곱셈구구에서 곱하는 수가 1 커지면 곱의 일의 자리 숫자는 어떻게 되나요?","options":[{"t":"1씩 작아져요","correct":true},{"t":"1씩 커져요","mis":"M2-2-u2-X16"},{"t":"9씩 작아져요","mis":"M2-2-u2-X16"}],"explanation":["9, 18, 27, 36, …에서 일의 자리 숫자는 9, 8, 7, 6, …이에요.","1씩 작아져요.","십의 자리 숫자는 1씩 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#22','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C4',3,'error','auto','4단과 8단에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X15']::text[],false,'{"seq":22,"concept":"M2-2-u2-C4","difficulty":3,"kind":"error","stem":"4단과 8단에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「8 × 6은 8 × 3에 3을 더한 27이야.」","correct":true,"mis_target":"M2-2-u2-X17"},{"t":"아린 — 「8 × 6은 8 × 3을 두 번 더한 48이야.」","mis":"M2-2-u2-X15"},{"t":"지안 — 「8 × 6은 8 × 5에 8을 더한 48이야.」","mis":"M2-2-u2-X15"}],"explanation":["8 × 6은 8 × 3을 두 번 더한 것이에요.","24 + 24 = 48이에요.","태민이는 8 × 3에 곱 대신 3을 더했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#23','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C10',4,'essay','teacher','4단 곱셈구구의 곱을 쓰고, 곱의 일의 자리 숫자를 차례로 써서 어떤 규칙이 있는지 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u2-C10","difficulty":4,"kind":"essay","stem":"4단 곱셈구구의 곱을 쓰고, 곱의 일의 자리 숫자를 차례로 써서 어떤 규칙이 있는지 설명해 보세요.","answer_guide":{"answer":"예: 4, 8, 12, 16, 20, 24, 28, 32, 36. 일의 자리 숫자는 4, 8, 2, 6, 0, 4, 8, 2, 6으로 4, 8, 2, 6, 0이 되풀이된다.","scoring_points":["곱을 바르게 구했는가","일의 자리 숫자를 차례로 바르게 썼는가","되풀이되는 규칙이나 같은 무늬가 나오는 까닭을 썼는가"]},"explanation":["곱의 일의 자리 숫자만 따로 써요.","같은 숫자가 되풀이되는지 살펴요.","되풀이되는 숫자를 둥근 판에 이으면 무늬가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#24','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C9',4,'essay','teacher','닭 4마리와 강아지 5마리가 있어요. 다리의 수를 곱셈구구로 구하고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u2-C9","difficulty":4,"kind":"essay","stem":"닭 4마리와 강아지 5마리가 있어요. 다리의 수를 곱셈구구로 구하고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 닭의 다리는 2 × 4 = 8개, 강아지의 다리는 4 × 5 = 20개이다. 8 + 20 = 28개이다.","scoring_points":["곱셈구구로 나누어 곱하거나 빈자리를 채워 곱했는가","더하거나 빼는 과정을 바르게 썼는가","답을 바르게 구했는가"]},"explanation":["같은 수씩 놓인 덩이를 찾아 곱해요.","빈자리는 빼고, 덩이가 둘이면 두 곱을 더해요.","하나씩 세는 것보다 빠르고 정확해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#25','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C8',4,'essay','teacher','곱셈표에서 곱이 16인 곱셈구구를 모두 찾아 쓰고, 어떻게 찾았는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u2-C8","difficulty":4,"kind":"essay","stem":"곱셈표에서 곱이 16인 곱셈구구를 모두 찾아 쓰고, 어떻게 찾았는지 설명해 보세요.","answer_guide":{"answer":"예: 2 × 8, 4 × 4, 8 × 2. 곱셈표에서 16이 있는 칸을 모두 찾았다. 4 × 4는 두 수가 같아 하나뿐이다.","scoring_points":["곱이 16인 곱셈구구를 하나 이상 찾았는가","두 수를 바꾼 것과 다른 단의 것까지 모두 찾았는가","곱셈표에서 16인 칸을 찾았다는 등 방법을 썼는가"]},"explanation":["곱셈표에서 같은 수가 있는 칸을 모두 찾아요.","두 수를 바꾸어 곱해도 곱이 같아요.","곱이 같은 곱셈구구는 여러 개일 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#1','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C1',1,'sa','auto','2씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u2-C1","difficulty":1,"kind":"sa","stem":"2씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["2씩 커지는 수예요.","4에서 2만큼 더 뛰면 6이에요.","2씩 3번 뛰어 센 수 — 2씩 3묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip","ks":[2],"pmax":45}},"answer":["6"],"asset":{"type":"jump_row","cells":[2,4,null],"step":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#2','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C2',1,'sa','auto','5 × 4는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u2-C2","difficulty":1,"kind":"sa","stem":"5 × 4는 얼마인가요? 숫자로 쓰세요.","explanation":["5 × 4는 5의 4배예요.","5씩 뛰어 세면 5, 10, 15, 20.","그래서 5 × 4 = 20이에요."],"variant_rule":{"mul":{"ask":"value","ks":[5],"pmax":81}},"answer":["20"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#3','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C3',1,'sa','auto','6 × 8은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u2-C3","difficulty":1,"kind":"sa","stem":"6 × 8은 얼마인가요? 숫자로 쓰세요.","explanation":["6 × 8은 6의 8배예요.","6씩 뛰어 세면 6, 12, 18, 24, 30, 36, 42, 48.","그래서 6 × 8 = 48이에요."],"variant_rule":{"mul":{"ask":"value","ks":[3,6],"pmax":81}},"answer":["48"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#4','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C4',1,'mc','auto','8 × 7은 얼마인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X02']::text[],true,'{"seq":4,"concept":"M2-2-u2-C4","difficulty":1,"kind":"mc","stem":"8 × 7은 얼마인가요?","explanation":["8 × 7은 8의 7배예요.","8씩 뛰어 세면 8, 16, 24, 32, 40, 48, 56.","그래서 8 × 7 = 56이에요."],"variant_rule":{"mul":{"ask":"value","ks":[4,8],"pmax":81}},"options":[{"t":"56","correct":true},{"t":"15","mis":"M2-2-u2-X11"},{"t":"64","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#5','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C5',1,'mc','auto','7 × 3은 얼마인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X02']::text[],true,'{"seq":5,"concept":"M2-2-u2-C5","difficulty":1,"kind":"mc","stem":"7 × 3은 얼마인가요?","explanation":["7 × 3은 7의 3배예요.","7씩 뛰어 세면 7, 14, 21.","그래서 7 × 3 = 21이에요."],"variant_rule":{"mul":{"ask":"value","ks":[7],"pmax":81}},"options":[{"t":"21","correct":true},{"t":"10","mis":"M2-2-u2-X11"},{"t":"28","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#6','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C6',1,'mc','auto','9 × 4는 얼마인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X02']::text[],true,'{"seq":6,"concept":"M2-2-u2-C6","difficulty":1,"kind":"mc","stem":"9 × 4는 얼마인가요?","explanation":["9 × 4는 9의 4배예요.","9씩 뛰어 세면 9, 18, 27, 36.","그래서 9 × 4 = 36이에요."],"variant_rule":{"mul":{"ask":"value","ks":[9],"pmax":81}},"options":[{"t":"36","correct":true},{"t":"13","mis":"M2-2-u2-X11"},{"t":"45","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#7','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C7',1,'mc','auto','7 × 1은 얼마인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X06']::text[],true,'{"seq":7,"concept":"M2-2-u2-C7","difficulty":1,"kind":"mc","stem":"7 × 1은 얼마인가요?","explanation":["7 × 1은 7을 한 번 더한 것이에요.","1과 어떤 수의 곱, 어떤 수와 1의 곱은 늘 그 수예요.","그래서 7 × 1 = 7이에요."],"variant_rule":{"gugu":{"ask":"zero"}},"options":[{"t":"7","correct":true},{"t":"1","mis":"M2-2-u2-X08"},{"t":"8","mis":"M2-2-u2-X06"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#8','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C8',1,'mc','auto','곱셈표의 ?에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X09']::text[],true,'{"seq":8,"concept":"M2-2-u2-C8","difficulty":1,"kind":"mc","stem":"곱셈표의 ?에 알맞은 수는 얼마인가요?","explanation":["?는 왼쪽 7과 위쪽 5가 만나는 칸이에요.","그래서 7 × 5의 곱을 써요 — 7 × 4 = 28에 7을 더해도 돼요.","7 × 5 = 35예요."],"variant_rule":{"gugu":{"ask":"cell"}},"options":[{"t":"35","correct":true},{"t":"42","mis":"M2-2-u2-X09"},{"t":"28","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[5,6,7,8],"cols":[1,2,3,4,5],"q":[7,5],"blank":[[8,5],[7,2]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#9','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C8',2,'mc','auto','곱셈표에서 색칠한 9단 곱셈구구의 곱은 오른쪽으로 한 칸 갈 때마다 얼마씩 커지나요?',ARRAY['M2-2-u2-X01','M2-2-u2-X09']::text[],true,'{"seq":9,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표에서 색칠한 9단 곱셈구구의 곱은 오른쪽으로 한 칸 갈 때마다 얼마씩 커지나요?","explanation":["9단의 곱은 9, 18, 27, …예요.","곱하는 수가 1 커질 때마다 9씩 커져요.","그래서 9단 곱셈구구의 곱은 9씩 커져요 — 1씩이 아니에요."],"variant_rule":{"gugu":{"ask":"step"}},"options":[{"t":"9","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"10","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[7,8,9],"cols":[1,2,3,4,5,6,7,8,9],"hrow":9}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#10','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C4',2,'mc','auto','8 × 5 = 40이에요. 이것을 이용하면 8 × 6은 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17','M2-2-u2-X02']::text[],true,'{"seq":10,"concept":"M2-2-u2-C4","difficulty":2,"kind":"mc","stem":"8 × 5 = 40이에요. 이것을 이용하면 8 × 6은 얼마인가요?","explanation":["8 × 6은 8 × 5보다 8만큼 더 커요.","40 + 8 = 48이에요.","한 번 더 더할 때는 곱하는 수 6이 아니라 8을 더해요."],"variant_rule":{"gugu":{"ask":"build","ks":[4,8]}},"options":[{"t":"48","correct":true},{"t":"41","mis":"M2-2-u2-X01"},{"t":"46","mis":"M2-2-u2-X17"},{"t":"56","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#11','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C5',2,'mc','auto','7 × 9는 7 × 8보다 얼마 더 큰가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17']::text[],true,'{"seq":11,"concept":"M2-2-u2-C5","difficulty":2,"kind":"mc","stem":"7 × 9는 7 × 8보다 얼마 더 큰가요?","explanation":["7 × 8은 7을 8번, 7 × 9는 7을 9번 더한 것이에요.","7을 한 번 더 더했으니 7만큼 더 커요 — 56에서 63.","곱하는 수가 1 커지면 곱은 7만큼 커져요."],"variant_rule":{"gugu":{"ask":"next","ks":[7]}},"options":[{"t":"7","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"9","mis":"M2-2-u2-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#12','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C6',2,'mc','auto','9 × □ = 54에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02']::text[],true,'{"seq":12,"concept":"M2-2-u2-C6","difficulty":2,"kind":"mc","stem":"9 × □ = 54에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["9단 곱셈구구에서 곱이 54인 것을 찾아요.","9씩 뛰어 세면 9, 18, 27, 36, 45, 54 — 6번이에요.","9 × 6 = 54라 □는 6이에요."],"variant_rule":{"gugu":{"ask":"miss","ks":[9]}},"options":[{"t":"6","correct":true},{"t":"7","mis":"M2-2-u2-X02"},{"t":"5","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#13','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C9',2,'mc','auto','거미 한 마리에 다리가 8개씩 있어요. 거미 5마리의 다리는 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X14']::text[],true,'{"seq":13,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"거미 한 마리에 다리가 8개씩 있어요. 거미 5마리의 다리는 모두 몇 개인가요?","explanation":["거미 한 마리에 8개씩, 5마리이면 8씩 5묶음이에요.","8 × 5 = 40이에요.","다리는 모두 40개예요."],"variant_rule":{"mul":{"ask":"story","pmax":81}},"options":[{"t":"40개","correct":true},{"t":"13개","mis":"M2-2-u2-X06"},{"t":"5개","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#14','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C3',2,'ox','auto','3 × 1부터 3 × 9까지의 곱 가운데 6단의 곱도 되는 수는 6, 12, 18, 24예요.',ARRAY['M2-2-u2-X10']::text[],false,'{"seq":14,"concept":"M2-2-u2-C3","difficulty":2,"kind":"ox","stem":"3 × 1부터 3 × 9까지의 곱 가운데 6단의 곱도 되는 수는 6, 12, 18, 24예요.","answer":"O","reason_options":[{"t":"6단의 곱은 6씩 커지고, 3단의 곱 가운데 6씩 커지는 수가 6, 12, 18, 24니까","correct":true},{"t":"3단의 곱과 6단의 곱은 겹치는 수가 없으니까","mis":"M2-2-u2-X10"}],"mis":"M2-2-u2-X10","explanation":["3단의 곱: 3, 6, 9, 12, 15, 18, 21, 24, 27","6단의 곱: 6, 12, 18, 24, 30, …","겹치는 수는 6, 12, 18, 24예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#15','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C8',2,'mc','auto','1단부터 9단까지의 곱셈구구 가운데 곱이 8인 것은 모두 몇 개인가요?',ARRAY['M2-2-u2-X13','M2-2-u2-X09']::text[],true,'{"seq":15,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"1단부터 9단까지의 곱셈구구 가운데 곱이 8인 것은 모두 몇 개인가요?","explanation":["곱이 8인 곱셈구구는 1 × 8, 2 × 4, 4 × 2, 8 × 1이에요.","두 수를 바꾸어 곱한 것도 따로 세어요.","그래서 모두 4개예요."],"variant_rule":{"gugu":{"ask":"tfind"}},"options":[{"t":"4","correct":true},{"t":"3","mis":"M2-2-u2-X13"},{"t":"5","mis":"M2-2-u2-X09"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#16','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C7',2,'ox','auto','4 × 1 = 1입니다.',ARRAY['M2-2-u2-X08']::text[],true,'{"seq":16,"concept":"M2-2-u2-C7","difficulty":2,"kind":"ox","stem":"4 × 1 = 1입니다.","explanation":["4 × 1은 4를 한 번 더한 것이에요.","1과 어떤 수의 곱, 어떤 수와 1의 곱은 늘 그 수예요.","그래서 4 × 1 = 4예요."],"variant_rule":{"gugu":{"ask":"zero"}},"answer":"X","reason_options":[{"t":"4 × 1은 1이 아니라 4가 되니까","correct":true},{"t":"1을 곱하면 1이 되니까","mis":"M2-2-u2-X08"}],"mis":"M2-2-u2-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#17','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C9',3,'mc','auto','쿠키가 한 접시에 8개씩 4접시 있었는데, 3개를 먹었어요. 남은 쿠키는 몇 개인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X06']::text[],false,'{"seq":17,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"쿠키가 한 접시에 8개씩 4접시 있었는데, 3개를 먹었어요. 남은 쿠키는 몇 개인가요?","options":[{"t":"29개","correct":true},{"t":"32개","mis":"M2-2-u2-X18"},{"t":"35개","mis":"M2-2-u2-X06"}],"explanation":["처음 쿠키는 8 × 4 = 32개예요.","그중 3개를 먹었어요.","32 − 3 = 29이니 29개가 남았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#18','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C8',3,'mc','auto','두 곱의 크기를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#19','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C10',3,'mc','auto','4단 곱셈구구의 곱 4, 8, 12, 16, 20의 일의 자리 숫자를 차례로 쓴 것은 어느 것인가요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":19,"concept":"M2-2-u2-C10","difficulty":3,"kind":"mc","stem":"4단 곱셈구구의 곱 4, 8, 12, 16, 20의 일의 자리 숫자를 차례로 쓴 것은 어느 것인가요?","options":[{"t":"4, 8, 2, 6, 0","correct":true},{"t":"4, 8, 1, 1, 2","mis":"M2-2-u2-X16"},{"t":"4, 5, 6, 7, 8","mis":"M2-2-u2-X16"}],"explanation":["일의 자리 숫자만 써요.","4, 8, 2, 6, 0이에요.","십의 자리 숫자(1, 1, 2)를 쓰면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#20','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C7',3,'mc','auto','과녁 맞히기에서 1점에 6번, 0점에 2번 맞혔고 5점에는 한 번도 못 맞혔어요. 얻은 점수는 모두 몇 점인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X05']::text[],false,'{"seq":20,"concept":"M2-2-u2-C7","difficulty":3,"kind":"mc","stem":"과녁 맞히기에서 1점에 6번, 0점에 2번 맞혔고 5점에는 한 번도 못 맞혔어요. 얻은 점수는 모두 몇 점인가요?","options":[{"t":"6점","correct":true},{"t":"11점","mis":"M2-2-u2-X08"},{"t":"8점","mis":"M2-2-u2-X05"}],"explanation":["1 × 6 = 6, 0 × 2 = 0, 5 × 0 = 0이에요.","6 + 0 + 0 = 6이에요.","한 번도 못 맞힌 5점은 0점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#21','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C6',3,'mc','auto','9 × 4 = 36이에요. 9 × 6의 곱을 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u2-X16','M2-2-u2-X02']::text[],false,'{"seq":21,"concept":"M2-2-u2-C6","difficulty":3,"kind":"mc","stem":"9 × 4 = 36이에요. 9 × 6의 곱을 바르게 말한 것은 어느 것인가요?","options":[{"t":"54 — 십의 자리 5, 일의 자리 4","correct":true},{"t":"63 — 십의 자리 6, 일의 자리 3","mis":"M2-2-u2-X16"},{"t":"45 — 십의 자리 4, 일의 자리 5","mis":"M2-2-u2-X02"}],"explanation":["9 × 6은 9 × 4보다 9씩 두 번 커요 — 36 + 18 = 54예요.","십의 자리 5는 곱하는 수 6보다 1 작아요.","5 + 4 = 9로 9단의 규칙에도 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#22','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C4',3,'error','auto','4단과 8단에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u2-X10','M2-2-u2-X15']::text[],false,'{"seq":22,"concept":"M2-2-u2-C4","difficulty":3,"kind":"error","stem":"4단과 8단에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"곰이 — 「4 × 2와 8 × 2는 곱이 같아.」","correct":true,"mis_target":"M2-2-u2-X10"},{"t":"펭이 — 「4 × 8과 8 × 4는 곱이 같아.」","mis":"M2-2-u2-X15"},{"t":"다예 — 「4 × 4를 두 번 더하면 8 × 4야.」","mis":"M2-2-u2-X15"}],"explanation":["4 × 2 = 8, 8 × 2 = 16이에요.","8 × 2는 4 × 2의 2배예요.","곰이의 말이 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#23','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C10',4,'essay','teacher','2단과 8단 곱셈구구의 곱의 일의 자리 숫자를 각각 다섯 개씩 차례로 쓰고, 둥근 판에 이으면 같은 무늬가 나오는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u2-C10","difficulty":4,"kind":"essay","stem":"2단과 8단 곱셈구구의 곱의 일의 자리 숫자를 각각 다섯 개씩 차례로 쓰고, 둥근 판에 이으면 같은 무늬가 나오는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 2단은 2, 4, 6, 8, 0이고 8단은 8, 6, 4, 2, 0이다. 같은 숫자들을 순서만 거꾸로 이으므로 같은 무늬가 나온다.","scoring_points":["곱을 바르게 구했는가","일의 자리 숫자를 차례로 바르게 썼는가","되풀이되는 규칙이나 같은 무늬가 나오는 까닭을 썼는가"]},"explanation":["곱의 일의 자리 숫자만 따로 써요.","같은 숫자가 되풀이되는지 살펴요.","되풀이되는 숫자를 둥근 판에 이으면 무늬가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#24','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C9',4,'essay','teacher','사물함이 한 줄에 6칸씩 4줄 있는데 3칸이 비어 있어요. 물건이 든 사물함의 수를 곱셈구구로 구하고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u2-C9","difficulty":4,"kind":"essay","stem":"사물함이 한 줄에 6칸씩 4줄 있는데 3칸이 비어 있어요. 물건이 든 사물함의 수를 곱셈구구로 구하고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 사물함은 6 × 4 = 24칸이다. 3칸이 비었으므로 24 − 3 = 21칸에 물건이 들어 있다.","scoring_points":["곱셈구구로 나누어 곱하거나 빈자리를 채워 곱했는가","더하거나 빼는 과정을 바르게 썼는가","답을 바르게 구했는가"]},"explanation":["같은 수씩 놓인 덩이를 찾아 곱해요.","빈자리는 빼고, 덩이가 둘이면 두 곱을 더해요.","하나씩 세는 것보다 빠르고 정확해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#25','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C8',4,'essay','teacher','곱셈표에서 곱이 36인 곱셈구구를 모두 찾아 쓰고, 어떻게 찾았는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u2-C8","difficulty":4,"kind":"essay","stem":"곱셈표에서 곱이 36인 곱셈구구를 모두 찾아 쓰고, 어떻게 찾았는지 설명해 보세요.","answer_guide":{"answer":"예: 4 × 9, 6 × 6, 9 × 4. 곱셈표에서 36이 있는 칸을 모두 찾았다. 6 × 6은 두 수가 같아 하나뿐이다.","scoring_points":["곱이 36인 곱셈구구를 하나 이상 찾았는가","두 수를 바꾼 것과 다른 단의 것까지 모두 찾았는가","곱셈표에서 36인 칸을 찾았다는 등 방법을 썼는가"]},"explanation":["곱셈표에서 같은 수가 있는 칸을 모두 찾아요.","두 수를 바꾸어 곱해도 곱이 같아요.","곱이 같은 곱셈구구는 여러 개일 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C1','math',2,2,'u3',2,'1 m 알기 — 100 cm가 1 m임을 알고, 1 m를 쓰고 「1 미터」로 읽으며, 몇백 cm와 몇 m를 서로 바꾸기',ARRAY['2수03-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C2','math',2,2,'u3',2,'길이를 두 가지로 나타내기 — 몇 cm를 몇 m 몇 cm로 가르고, 몇 m 몇 cm를 몇 cm로 모으며(cm가 한 자리면 0으로 자리 지키기), 단위가 다른 두 길이를 같은 단위로 바꾸어 견주기',ARRAY['2수03-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C3','math',2,2,'u3',2,'알맞은 단위 고르기 — 짧은 길이는 cm로, 긴 길이는 m로 나타내면 편함을 알고 상황에 알맞은 단위 고르기',ARRAY['2수03-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C4','math',2,2,'u3',3,'줄자로 길이 재기 — 물건에 알맞은 자(곧은자·줄자)를 고르고, 한끝을 눈금 0에 맞추어 다른 끝의 눈금을 읽으며, 잰 길이를 몇 cm와 몇 m 몇 cm로 나타내기',ARRAY['2수03-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C5','math',2,2,'u3',4,'길이의 합 — 색 테이프를 이어 붙이는 상황에서 m는 m끼리, cm는 cm끼리 더해 길이의 합을 구하고, 같은 단위끼리 맞추어 세로셈으로 쓰기',ARRAY['2수03-04']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C6','math',2,2,'u3',5,'길이의 차 — 잘라 쓰고 남은 길이·두 도막·두 길이의 차를 m는 m끼리, cm는 cm끼리 빼서 구하고, 구한 차에 뺀 길이를 더해 다시 확인하기',ARRAY['2수03-04']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C7','math',2,2,'u3',6,'1 m를 기준으로 어림하기 — 양팔·뼘·걸음 등 몸의 부분으로 1 m를 재어 보고, 1 m를 기준 삼아 2 m·3 m를 어림하며, 어림한 길이에 「약」을 붙이고 자로 재어 확인하기',ARRAY['2수03-03']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C8','math',2,2,'u3',7,'긴 거리 어림하기 — 5 m·10 m를 기준 삼거나, 몇 부분으로 나누어 어림한 뒤 더하거나, 같은 간격이 몇 개인지 세어 긴 거리를 어림하기',ARRAY['2수03-03']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u3-C9','math',2,2,'u3',9,'길이 재기로 문제 해결하기 — 동물 몸길이 사전을 만들며 몸길이를 견주고 합과 차를 구하며, 조사한 길이를 몇 m 몇 cm로 바르게 적기',ARRAY['2수03-04']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X01','math',2,'u3',ARRAY['M2-2-u3-C1','M2-2-u3-C2','M2-2-u3-C4']::text[],'1 m와 100 cm의 관계를 모른다 — 1 m를 10 cm나 1000 cm로 여기거나, 수는 그대로 두고 단위 글자만 바꿔 쓴다(300 cm = 300 m)','1 m 막대에 1 cm가 100번 들어간다 — 100 cm마다 1 m') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X02','math',2,'u3',ARRAY['M2-2-u3-C2','M2-2-u3-C4']::text[],'몇 m 몇 cm를 몇 cm로 바꿀 때 두 수를 그냥 이어 붙여 0을 빠뜨리거나(3 m 4 cm → 34 cm), m와 cm의 수를 뒤바꾼다','m 자리는 백의 자리 — cm가 한 자리면 십의 자리에 0') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X03','math',2,'u3',ARRAY['M2-2-u3-C2','M2-2-u3-C4','M2-2-u3-C9']::text[],'몇 cm를 몇 m 몇 cm로 가를 때 자리를 잘못 가른다(248 cm → 24 m 8 cm)','백의 자리 숫자만 m — 뒤의 두 자리는 cm') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X04','math',2,'u3',ARRAY['M2-2-u3-C2','M2-2-u3-C5']::text[],'m의 수와 cm의 수를 더해 버리거나 m와 cm를 한꺼번에 계산한다(5 m 73 cm → 78 cm)','m는 m끼리, cm는 cm끼리 따로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X05','math',2,'u3',ARRAY['M2-2-u3-C3','M2-2-u3-C9']::text[],'길이에 알맞지 않은 단위를 고르거나 단위를 빠뜨린다(필통 약 15 m, 몸길이 「약 240」)','손에 쥐는 것은 cm, 몸보다 긴 것은 m — 수 뒤에 단위') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X06','math',2,'u3',ARRAY['M2-2-u3-C4']::text[],'줄자의 한끝을 0에 맞추지 않거나, 0이 아닌 곳에서 시작했는데 다른 끝의 눈금 숫자를 그대로 길이로 읽는다','한끝을 0에 — 아니면 끝 눈금에서 시작 눈금을 빼기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X07','math',2,'u3',ARRAY['M2-2-u3-C4']::text[],'줄자의 눈금을 이웃 눈금으로 잘못 읽는다(140 대신 139·141)','물건 끝에서 줄자까지 선을 내려 긋고 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X08','math',2,'u3',ARRAY['M2-2-u3-C5','M2-2-u3-C6','M2-2-u3-C9']::text[],'m끼리·cm끼리 계산하면서 한 자리를 잘못 센다(1 m·10 cm 차이)','m 자리, cm 자리를 따로 한 번 더 셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X09','math',2,'u3',ARRAY['M2-2-u3-C2','M2-2-u3-C5','M2-2-u3-C6']::text[],'cm가 한 자리 수일 때 자리를 맞추지 않고 몇십으로 본다(7 m 5 cm의 5를 50처럼 계산)','세로셈에서 cm 수의 일의 자리끼리 줄 맞추기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X10','math',2,'u3',ARRAY['M2-2-u3-C5','M2-2-u3-C6','M2-2-u3-C9']::text[],'더해야 할 때 빼거나 빼야 할 때 더한다 — 이어 붙인 길이·남은 길이·다른 도막 상황을 거꾸로 읽는다','「이어 붙이면」은 합, 「남은·다른 도막·차」는 차') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X11','math',2,'u3',ARRAY['M2-2-u3-C2','M2-2-u3-C5','M2-2-u3-C6']::text[],'cm의 끝자리 0을 떼고 쓴다(70 cm → 7 cm, 2 m 40 cm → 2 m 4 cm)','cm 자리는 두 자리 — 0도 자리를 지킨다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X12','math',2,'u3',ARRAY['M2-2-u3-C7','M2-2-u3-C8']::text[],'어림한 길이에 「약」을 빼거나, 어림한 길이는 잰 길이와 반드시 같아야 한다고 여긴다','짐작한 길이 앞에는 「약」 — 잰 길이와 조금 달라도 괜찮다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X13','math',2,'u3',ARRAY['M2-2-u3-C7']::text[],'몸의 부분으로 잴 때 단위가 클수록 잰 횟수가 많다고 여기거나, 사람마다 잰 횟수가 같다고 여긴다','큰 걸음은 적게, 작은 뼘은 많이 — 사람마다 크기가 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X14','math',2,'u3',ARRAY['M2-2-u3-C7','M2-2-u3-C8']::text[],'기준 길이를 늘려 어림하거나 나누어 어림한 뒤 더할 때 배수·합을 잘못 구한다(약 5 m의 두 배를 약 7 m로, 기준과 횟수를 더함)','기준이 몇 번인지 세어 그만큼 여러 번 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X15','math',2,'u3',ARRAY['M2-2-u3-C8']::text[],'줄 선 사람·놓인 물건의 수와 그 사이 간격의 수를 같다고 여긴다(8명이 1 m 간격 → 8 m)','맨 앞과 맨 뒤 사이의 간격만 세기 — 사람 수보다 하나 적다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X16','math',2,'u3',ARRAY['M2-2-u3-C1','M2-2-u3-C2','M2-2-u3-C3','M2-2-u3-C4','M2-2-u3-C5','M2-2-u3-C6','M2-2-u3-C7','M2-2-u3-C8','M2-2-u3-C9']::text[],'묻는 말을 거꾸로 읽는다 — 아닌 것↔맞는 것, 잘못된↔바른, 긴↔짧은','물음의 「아닌·잘못된·짧은」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X17','math',2,'u3',ARRAY['M2-2-u3-C3','M2-2-u3-C7','M2-2-u3-C8']::text[],'길이에 대한 양감이 없어 터무니없는 길이로 어림한다(칠판의 긴 쪽 약 3 cm, 연필 약 1 m)','1 cm는 손톱 너비, 1 m는 양팔 — 떠올려 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X18','math',2,'u3',ARRAY['M2-2-u3-C2','M2-2-u3-C4','M2-2-u3-C7','M2-2-u3-C9']::text[],'단위가 다른 두 길이를 같은 단위로 바꾸지 않고 보이는 수만 견준다(130 cm > 1 m 50 cm)','둘 다 cm로 바꾼 뒤 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u3-X19','math',2,'u3',ARRAY['M2-2-u3-C4']::text[],'곧은자와 줄자의 쓰임을 모른다 — 1 m보다 긴 것이나 둥근 것을 곧은자로 재려 하거나 줄자를 구부려 곧은 길이를 잰다','짧고 곧으면 곧은자, 길거나 둥글면 줄자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_basic#1','math',2,2,'u3','L02','g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C1',1,'mc','auto','100 cm는 몇 m인가요?',ARRAY['M2-2-u3-X01']::text[],true,'{"seq":1,"concept":"M2-2-u3-C1","difficulty":1,"kind":"mc","stem":"100 cm는 몇 m인가요?","explanation":["100 cm는 1 m예요.","1 cm가 100번 모이면 100 cm — 이 길이를 1 m라고 해요.","그래서 100 cm = 1 m예요."],"variant_rule":{"mcm":{"ask":"m100","form":"tom"}},"options":[{"t":"1 m","correct":true},{"t":"10 m","mis":"M2-2-u3-X01"},{"t":"100 m","mis":"M2-2-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_basic#2','math',2,2,'u3','L02','g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C1',1,'mc','auto','1 m를 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u3-X01','M2-2-u3-X05']::text[],true,'{"seq":2,"concept":"M2-2-u3-C1","difficulty":1,"kind":"mc","stem":"1 m를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"1 미터","correct":true},{"t":"1 센티미터","mis":"M2-2-u3-X01"},{"t":"1 엠","mis":"M2-2-u3-X05"}],"explanation":["m는 「미터」라고 읽어요.","cm는 「센티미터」라고 읽어요.","그래서 1 m는 「1 미터」예요."],"variant_rule":{"alt":[{"stem":"3 m를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"3 미터","correct":true},{"t":"3 센티미터","mis":"M2-2-u3-X01"},{"t":"3 엠","mis":"M2-2-u3-X05"}],"explanation":["m는 「미터」라고 읽어요.","3 m는 1 m가 3번인 길이예요.","그래서 3 m는 「3 미터」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_basic#3','math',2,2,'u3','L02','g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C1',1,'sa','auto','3 m는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u3-C1","difficulty":1,"kind":"sa","stem":"3 m는 몇 cm인가요? 숫자로 쓰세요.","explanation":["1 m는 100 cm예요.","3 m는 100 cm가 3번이에요.","그래서 3 m = 300 cm예요."],"variant_rule":{"mcm":{"ask":"m100","form":"tocm"}},"answer":["300"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_basic#4','math',2,2,'u3','L02','g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C2',1,'mc','auto','1 m 20 cm는 몇 cm인가요?',ARRAY['M2-2-u3-X01','M2-2-u3-X04']::text[],true,'{"seq":4,"concept":"M2-2-u3-C2","difficulty":1,"kind":"mc","stem":"1 m 20 cm는 몇 cm인가요?","explanation":["1 m는 100 cm예요.","100 cm와 20 cm를 모으면 120 cm예요.","m를 100 cm씩으로 바꾸어 cm와 모아요."],"variant_rule":{"mcm":{"ask":"tocm"}},"options":[{"t":"120 cm","correct":true},{"t":"30 cm","mis":"M2-2-u3-X01"},{"t":"21 cm","mis":"M2-2-u3-X04"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_basic#5','math',2,2,'u3','L02','g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C2',2,'mc','auto','405 cm를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X09','M2-2-u3-X02']::text[],true,'{"seq":5,"concept":"M2-2-u3-C2","difficulty":2,"kind":"mc","stem":"405 cm를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["405 cm는 400 cm와 5 cm예요.","400 cm는 4 m예요.","그래서 405 cm = 4 m 5 cm예요."],"variant_rule":{"mcm":{"ask":"tomcm"}},"options":[{"t":"4 m 5 cm","correct":true},{"t":"40 m 5 cm","mis":"M2-2-u3-X03"},{"t":"4 m 50 cm","mis":"M2-2-u3-X09"},{"t":"5 m 4 cm","mis":"M2-2-u3-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_basic#6','math',2,2,'u3','L02','g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C2',2,'sa','auto','5 m 73 cm는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M2-2-u3-C2","difficulty":2,"kind":"sa","stem":"5 m 73 cm는 몇 cm인가요? 숫자로 쓰세요.","explanation":["5 m는 500 cm예요.","500 cm와 73 cm를 모으면 573 cm예요.","m를 100 cm씩으로 바꾸어 cm와 모아요."],"variant_rule":{"mcm":{"ask":"tocm"}},"answer":["573"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_basic#7','math',2,2,'u3','L02','g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C3',2,'mc','auto','교실 문의 높이는 약 2 ▢예요. ▢에 알맞은 단위는 무엇인가요?',ARRAY['M2-2-u3-X05']::text[],true,'{"seq":7,"concept":"M2-2-u3-C3","difficulty":2,"kind":"mc","stem":"교실 문의 높이는 약 2 ▢예요. ▢에 알맞은 단위는 무엇인가요?","options":[{"t":"m","correct":true},{"t":"cm","mis":"M2-2-u3-X05"}],"explanation":["교실 문은 어른 키보다 높아요.","약 2 cm는 손톱 두 개만큼이라 너무 짧아요.","그래서 교실 문의 높이는 약 2 m예요."],"variant_rule":{"alt":[{"stem":"필통의 길이는 약 15 ▢예요. ▢에 알맞은 단위는 무엇인가요?","options":[{"t":"cm","correct":true},{"t":"m","mis":"M2-2-u3-X05"}],"explanation":["필통은 손에 쥘 만큼 짧아요.","약 15 m는 교실 두 칸만큼이라 너무 길어요.","그래서 필통의 길이는 약 15 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_basic#8','math',2,2,'u3','L02','g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C2',2,'match','auto','같은 길이를 두 가지 방법으로 나타낸 것끼리 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M2-2-u3-C2","difficulty":2,"kind":"match","stem":"같은 길이를 두 가지 방법으로 나타낸 것끼리 이으세요.","pairs":[{"l":"130 cm","r":"1 m 30 cm"},{"l":"305 cm","r":"3 m 5 cm"},{"l":"250 cm","r":"2 m 50 cm"}],"mis":"M2-2-u3-X03","explanation":["130 cm = 100 cm + 30 cm = 1 m 30 cm예요.","305 cm = 300 cm + 5 cm = 3 m 5 cm예요.","250 cm = 200 cm + 50 cm = 2 m 50 cm예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 같은 길이를 두 가지 방법으로 나타낸 것끼리 이으세요.","pairs":[{"l":"160 cm","r":"1 m 60 cm"},{"l":"408 cm","r":"4 m 8 cm"},{"l":"520 cm","r":"5 m 20 cm"}],"explanation":["160 cm = 100 cm + 60 cm = 1 m 60 cm예요.","408 cm = 400 cm + 8 cm = 4 m 8 cm예요.","520 cm = 500 cm + 20 cm = 5 m 20 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_basic#9','math',2,2,'u3','L02','g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C2',2,'ox','auto','248 cm는 24 m 8 cm와 같은 길이예요.',ARRAY['M2-2-u3-X03']::text[],true,'{"seq":9,"concept":"M2-2-u3-C2","difficulty":2,"kind":"ox","stem":"248 cm는 24 m 8 cm와 같은 길이예요.","answer":"X","reason_options":[{"t":"248 cm는 200 cm와 48 cm라서 2 m 48 cm니까","correct":true},{"t":"앞의 두 숫자를 m로 읽으면 되니까","mis":"M2-2-u3-X03"}],"mis":"M2-2-u3-X03","explanation":["248 cm = 200 cm + 48 cm예요.","200 cm는 2 m예요.","그래서 248 cm = 2 m 48 cm — 24 m 8 cm가 아니에요."],"variant_rule":{"alt":[{"stem":"365 cm는 3 m 65 cm와 같은 길이예요.","answer":"O","reason_options":[{"t":"365 cm는 300 cm와 65 cm라서 3 m 65 cm니까","correct":true},{"t":"앞의 두 숫자를 m로 읽어 36 m 5 cm니까","mis":"M2-2-u3-X03"}],"explanation":["365 cm = 300 cm + 65 cm예요.","300 cm는 3 m예요.","그래서 365 cm = 3 m 65 cm로 바른 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_basic#10','math',2,2,'u3','L02','g2_2_math_u3_L02_basic','lesson_basic','M2-2-u3-C2',3,'error','auto','5 m 6 cm를 몇 cm로 나타냈어요. 잘못 나타낸 친구는 누구인가요?',ARRAY['M2-2-u3-X02','M2-2-u3-X16']::text[],true,'{"seq":10,"concept":"M2-2-u3-C2","difficulty":3,"kind":"error","stem":"5 m 6 cm를 몇 cm로 나타냈어요. 잘못 나타낸 친구는 누구인가요?","options":[{"t":"지우 — 「5와 6을 이어서 56 cm야.」","correct":true,"mis_target":"M2-2-u3-X02"},{"t":"서아 — 「500 cm와 6 cm를 모으면 506 cm야.」","mis":"M2-2-u3-X16"},{"t":"하루 — 「cm가 한 자리라 0을 넣어 506 cm야.」","mis":"M2-2-u3-X16"}],"explanation":["5 m는 500 cm예요.","500 cm와 6 cm를 모으면 506 cm예요.","지우는 0을 빠뜨리고 이어 붙였어요 — 56 cm는 1 m도 안 돼요."],"variant_rule":{"alt":[{"stem":"7 m 3 cm를 몇 cm로 나타냈어요. 잘못 나타낸 친구는 누구인가요?","options":[{"t":"도윤 — 「7과 3을 이어서 73 cm야.」","correct":true,"mis_target":"M2-2-u3-X02"},{"t":"은솔 — 「700 cm와 3 cm를 모으면 703 cm야.」","mis":"M2-2-u3-X16"},{"t":"예린 — 「cm가 한 자리라 0을 넣어 703 cm야.」","mis":"M2-2-u3-X16"}],"explanation":["7 m는 700 cm예요.","700 cm와 3 cm를 모으면 703 cm예요.","도윤이는 0을 빠뜨리고 이어 붙였어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_challenge#1','math',2,2,'u3','L02','g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C2',2,'mc','auto','730 cm를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X11','M2-2-u3-X02']::text[],true,'{"seq":1,"concept":"M2-2-u3-C2","difficulty":2,"kind":"mc","stem":"730 cm를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["730 cm는 700 cm와 30 cm예요.","700 cm는 7 m예요.","그래서 730 cm = 7 m 30 cm예요."],"variant_rule":{"mcm":{"ask":"tomcm"}},"options":[{"t":"7 m 30 cm","correct":true},{"t":"73 m","mis":"M2-2-u3-X03"},{"t":"7 m 3 cm","mis":"M2-2-u3-X11"},{"t":"30 m 7 cm","mis":"M2-2-u3-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_challenge#2','math',2,2,'u3','L02','g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C1',2,'mc','auto','600 cm는 몇 m인가요?',ARRAY['M2-2-u3-X01']::text[],true,'{"seq":2,"concept":"M2-2-u3-C1","difficulty":2,"kind":"mc","stem":"600 cm는 몇 m인가요?","explanation":["100 cm는 1 m예요.","600 cm는 100 cm가 6번이에요.","그래서 600 cm = 6 m예요."],"variant_rule":{"mcm":{"ask":"m100","form":"tom"}},"options":[{"t":"6 m","correct":true},{"t":"60 m","mis":"M2-2-u3-X01"},{"t":"600 m","mis":"M2-2-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_challenge#3','math',2,2,'u3','L02','g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C2',3,'mc','auto','두 길이를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_challenge#4','math',2,2,'u3','L02','g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C2',3,'mc','auto','길이가 가장 긴 것은 어느 것인가요?',ARRAY['M2-2-u3-X18']::text[],false,'{"seq":4,"concept":"M2-2-u3-C2","difficulty":3,"kind":"mc","stem":"길이가 가장 긴 것은 어느 것인가요?","options":[{"t":"3 m 5 cm","correct":true},{"t":"298 cm","mis":"M2-2-u3-X18"},{"t":"2 m 99 cm","mis":"M2-2-u3-X18"},{"t":"300 cm","mis":"M2-2-u3-X18"}],"explanation":["모두 cm로 바꾸면 305 cm, 298 cm, 299 cm, 300 cm예요.","305 cm가 가장 길어요.","그래서 3 m 5 cm가 가장 길어요 — 보이는 수 298만 보면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_challenge#5','math',2,2,'u3','L02','g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C3',3,'mc','auto','cm보다 m로 나타내기에 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u3-X05']::text[],false,'{"seq":5,"concept":"M2-2-u3-C3","difficulty":3,"kind":"mc","stem":"cm보다 m로 나타내기에 알맞은 것은 어느 것인가요?","options":[{"t":"운동장의 긴 쪽의 길이","correct":true},{"t":"연필의 길이","mis":"M2-2-u3-X05"},{"t":"지우개의 길이","mis":"M2-2-u3-X05"},{"t":"공책의 짧은 쪽의 길이","mis":"M2-2-u3-X05"}],"explanation":["m는 1 m보다 긴 길이를 나타내기 편해요.","연필·지우개·공책은 1 m보다 훨씬 짧아 cm가 알맞아요.","운동장의 긴 쪽은 아주 길어서 m로 나타내면 편해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_challenge#6','math',2,2,'u3','L02','g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C2',3,'mc','auto','6 m 8 cm = □ cm에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u3-X02','M2-2-u3-X09','M2-2-u3-X04']::text[],false,'{"seq":6,"concept":"M2-2-u3-C2","difficulty":3,"kind":"mc","stem":"6 m 8 cm = □ cm에서 □ 안에 알맞은 수는 얼마인가요?","options":[{"t":"608","correct":true},{"t":"68","mis":"M2-2-u3-X02"},{"t":"680","mis":"M2-2-u3-X09"},{"t":"14","mis":"M2-2-u3-X04"}],"explanation":["6 m는 600 cm예요.","600 cm와 8 cm를 모으면 608 cm예요.","cm가 한 자리 수라 십의 자리에 0을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_challenge#7','math',2,2,'u3','L02','g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C1',3,'error','auto','1 m에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u3-X01','M2-2-u3-X16']::text[],false,'{"seq":7,"concept":"M2-2-u3-C1","difficulty":3,"kind":"error","stem":"1 m에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「1 m는 10 cm와 같아.」","correct":true,"mis_target":"M2-2-u3-X01"},{"t":"아린 — 「1 m는 100 cm와 같아.」","mis":"M2-2-u3-X16"},{"t":"지안 — 「1 m는 1 cm가 100번이야.」","mis":"M2-2-u3-X16"}],"explanation":["1 cm가 100번이면 100 cm예요.","100 cm는 1 m와 같아요.","태민이는 1 m를 10 cm로 잘못 알았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_challenge#8','math',2,2,'u3','L02','g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C2',4,'essay','teacher','352 cm를 「몇 m 몇 cm」로 나타내는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u3-C2","difficulty":4,"kind":"essay","stem":"352 cm를 「몇 m 몇 cm」로 나타내는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 352 cm는 300 cm와 52 cm로 가를 수 있다. 300 cm는 3 m이므로 352 cm = 3 m 52 cm이다.","scoring_points":["352 cm를 300 cm와 52 cm로 갈랐는가","300 cm가 3 m임을 썼는가","3 m 52 cm라고 바르게 나타냈는가"]},"explanation":["352 cm를 100 cm씩 묶음과 나머지로 갈라요.","300 cm는 3 m예요.","그래서 352 cm = 3 m 52 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_challenge#9','math',2,2,'u3','L02','g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C3',4,'essay','teacher','교실 문의 높이와 필통의 길이를 나타낼 때 각각 알맞은 단위를 고르고, 그렇게 고른 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u3-C3","difficulty":4,"kind":"essay","stem":"교실 문의 높이와 필통의 길이를 나타낼 때 각각 알맞은 단위를 고르고, 그렇게 고른 까닭을 써 보세요.","answer_guide":{"answer":"예: 교실 문의 높이는 m가 알맞다. 1 m보다 훨씬 길어서 cm로 나타내면 수가 커지기 때문이다. 필통의 길이는 cm가 알맞다. 1 m보다 짧기 때문이다.","scoring_points":["교실 문의 높이에 m를 골랐는가","필통의 길이에 cm를 골랐는가","길이가 1 m보다 긴지 짧은지로 까닭을 썼는가"]},"explanation":["긴 길이를 cm로 나타내면 수가 너무 커요.","짧은 길이는 cm로 나타내야 정확해요.","길이에 따라 알맞은 단위를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L02_challenge#10','math',2,2,'u3','L02','g2_2_math_u3_L02_challenge','lesson_challenge','M2-2-u3-C2',4,'mc','auto','가 2 m 7 cm, 나 270 cm, 다 2 m 17 cm예요. 짧은 것부터 차례로 늘어놓은 것은 어느 것인가요?',ARRAY['M2-2-u3-X18','M2-2-u3-X16']::text[],false,'{"seq":10,"concept":"M2-2-u3-C2","difficulty":4,"kind":"mc","stem":"가 2 m 7 cm, 나 270 cm, 다 2 m 17 cm예요. 짧은 것부터 차례로 늘어놓은 것은 어느 것인가요?","options":[{"t":"가, 다, 나","correct":true},{"t":"가, 나, 다","mis":"M2-2-u3-X18"},{"t":"나, 가, 다","mis":"M2-2-u3-X18"},{"t":"다, 나, 가","mis":"M2-2-u3-X16"}],"explanation":["모두 cm로 바꾸면 가 207 cm, 나 270 cm, 다 217 cm예요.","207 < 217 < 270이에요.","그래서 짧은 것부터 가, 다, 나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_basic#1','math',2,2,'u3','L03','g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',1,'mc','auto','줄자로 길이를 재는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u3-X06','M2-2-u3-X19']::text[],true,'{"seq":1,"concept":"M2-2-u3-C4","difficulty":1,"kind":"mc","stem":"줄자로 길이를 재는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"물건의 한끝을 줄자의 눈금 0에 맞춰요","correct":true},{"t":"물건의 한끝을 눈금 1에 맞춰요","mis":"M2-2-u3-X06"},{"t":"줄자를 구부려서 재요","mis":"M2-2-u3-X19"}],"explanation":["한끝을 눈금 0에 맞추어야 다른 끝의 눈금이 곧 길이가 돼요.","눈금 1에 맞추면 1 cm만큼 길게 읽어요.","곧은 길이는 줄자를 곧게 펴서 재요."],"variant_rule":{"alt":[{"stem":"줄자로 책장의 길이를 재요. 가장 먼저 할 일은 무엇인가요?","options":[{"t":"책장의 한끝을 줄자의 눈금 0에 맞춰요","correct":true},{"t":"책장의 가운데에 줄자를 대요","mis":"M2-2-u3-X06"},{"t":"줄자를 둥글게 말아 대요","mis":"M2-2-u3-X19"}],"explanation":["먼저 한끝을 눈금 0에 맞춰요.","그다음 다른 끝이 닿은 눈금을 읽어요.","줄자는 곧게 펴서 대요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_basic#2','math',2,2,'u3','L03','g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',1,'sa','auto','책상의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u3-C4","difficulty":1,"kind":"sa","stem":"책상의 길이는 몇 cm인가요? 숫자로 쓰세요.","explanation":["책상의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 140이니 140 cm예요.","140 cm는 1 m 40 cm라고도 나타내요."],"variant_rule":{"mcm":{"ask":"read"}},"answer":["140"],"asset":{"type":"tape","len":140,"label":"책상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_basic#3','math',2,2,'u3','L03','g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',1,'mc','auto','책장의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X07']::text[],true,'{"seq":3,"concept":"M2-2-u3-C4","difficulty":1,"kind":"mc","stem":"책장의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["책장의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 130이니 130 cm예요.","130 cm = 100 cm + 30 cm = 1 m 30 cm예요."],"variant_rule":{"mcm":{"ask":"read","form":"mcm"}},"options":[{"t":"1 m 30 cm","correct":true},{"t":"13 m","mis":"M2-2-u3-X03"},{"t":"1 m 31 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":130,"label":"책장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_basic#4','math',2,2,'u3','L03','g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',1,'ox','auto','둥근 나무의 둘레는 줄자로 재면 좋아요.',ARRAY['M2-2-u3-X19']::text[],true,'{"seq":4,"concept":"M2-2-u3-C4","difficulty":1,"kind":"ox","stem":"둥근 나무의 둘레는 줄자로 재면 좋아요.","answer":"O","reason_options":[{"t":"줄자는 휘어져서 둥근 곳도 감아 잴 수 있으니까","correct":true},{"t":"둥근 것은 곧은자로만 잴 수 있으니까","mis":"M2-2-u3-X19"}],"mis":"M2-2-u3-X19","explanation":["줄자는 부드럽게 휘어요.","그래서 둥근 나무의 둘레에 감아 잴 수 있어요.","곧은자는 휘지 않아 둘레를 재기 어려워요."],"variant_rule":{"alt":[{"stem":"교실의 긴 쪽은 15 cm 곧은자로 재면 좋아요.","answer":"X","reason_options":[{"t":"교실의 긴 쪽은 1 m보다 훨씬 길어서 줄자가 알맞으니까","correct":true},{"t":"곧은자는 무엇이든 잴 수 있으니까","mis":"M2-2-u3-X19"}],"explanation":["교실의 긴 쪽은 몇 m나 돼요.","15 cm 곧은자로는 수십 번 옮겨 대야 해요.","긴 길이는 줄자로 재는 것이 알맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_basic#5','math',2,2,'u3','L03','g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',2,'mc','auto','사물함의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X07']::text[],true,'{"seq":5,"concept":"M2-2-u3-C4","difficulty":2,"kind":"mc","stem":"사물함의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["사물함의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 520이니 520 cm예요.","520 cm = 500 cm + 20 cm = 5 m 20 cm예요."],"variant_rule":{"mcm":{"ask":"read","form":"mcm"}},"options":[{"t":"5 m 20 cm","correct":true},{"t":"52 m","mis":"M2-2-u3-X03"},{"t":"5 m 21 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":520,"label":"사물함"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_basic#6','math',2,2,'u3','L03','g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',2,'sa','auto','매트의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M2-2-u3-C4","difficulty":2,"kind":"sa","stem":"매트의 길이는 몇 cm인가요? 숫자로 쓰세요.","explanation":["매트의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 187이니 187 cm예요.","187 cm는 1 m 87 cm라고도 나타내요."],"variant_rule":{"mcm":{"ask":"read"}},"answer":["187"],"asset":{"type":"tape","len":187,"label":"매트"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_basic#7','math',2,2,'u3','L03','g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',2,'mc','auto','탁자의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 탁자의 길이는 몇 cm인가요?',ARRAY['M2-2-u3-X06','M2-2-u3-X07']::text[],true,'{"seq":7,"concept":"M2-2-u3-C4","difficulty":2,"kind":"mc","stem":"탁자의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 탁자의 길이는 몇 cm인가요?","explanation":["탁자의 한끝은 눈금 2, 다른 끝은 눈금 120에 있어요.","120 − 2 = 118이니 118 cm예요.","끝 눈금 120을 그대로 읽으면 안 돼요 — 한끝을 0에 맞추어 재요."],"variant_rule":{"mcm":{"ask":"off"}},"options":[{"t":"118 cm","correct":true},{"t":"120 cm","mis":"M2-2-u3-X06"},{"t":"119 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":118,"label":"탁자","s":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_basic#8','math',2,2,'u3','L03','g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',2,'match','auto','멀리 던지기에서 잰 거리를 「몇 m 몇 cm」로 나타낸 것과 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M2-2-u3-C4","difficulty":2,"kind":"match","stem":"멀리 던지기에서 잰 거리를 「몇 m 몇 cm」로 나타낸 것과 이으세요.","pairs":[{"l":"210 cm","r":"2 m 10 cm"},{"l":"350 cm","r":"3 m 50 cm"},{"l":"430 cm","r":"4 m 30 cm"}],"mis":"M2-2-u3-X03","explanation":["210 cm = 200 cm + 10 cm = 2 m 10 cm예요.","350 cm = 300 cm + 50 cm = 3 m 50 cm예요.","430 cm = 400 cm + 30 cm = 4 m 30 cm예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 멀리 던지기에서 잰 거리를 「몇 m 몇 cm」로 나타낸 것과 이으세요.","pairs":[{"l":"190 cm","r":"1 m 90 cm"},{"l":"305 cm","r":"3 m 5 cm"},{"l":"260 cm","r":"2 m 60 cm"}],"explanation":["190 cm = 100 cm + 90 cm = 1 m 90 cm예요.","305 cm = 300 cm + 5 cm = 3 m 5 cm예요.","260 cm = 200 cm + 60 cm = 2 m 60 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_basic#9','math',2,2,'u3','L03','g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',2,'mc','auto','교실의 긴 쪽의 길이를 재려고 해요. 어느 자로 재면 좋을까요?',ARRAY['M2-2-u3-X19']::text[],true,'{"seq":9,"concept":"M2-2-u3-C4","difficulty":2,"kind":"mc","stem":"교실의 긴 쪽의 길이를 재려고 해요. 어느 자로 재면 좋을까요?","options":[{"t":"줄자","correct":true},{"t":"15 cm 곧은자","mis":"M2-2-u3-X19"},{"t":"30 cm 곧은자","mis":"M2-2-u3-X19"}],"explanation":["교실의 긴 쪽은 1 m보다 훨씬 길어요.","곧은자는 짧아서 여러 번 옮겨 대야 해요.","긴 길이는 줄자로 한 번에 재요."],"variant_rule":{"alt":[{"stem":"지우개의 길이를 재려고 해요. 어느 자로 재면 좋을까요?","options":[{"t":"15 cm 곧은자","correct":true},{"t":"10 m 줄자","mis":"M2-2-u3-X19"},{"t":"운동장 줄자","mis":"M2-2-u3-X19"}],"explanation":["지우개는 짧고 곧아요.","짧고 곧은 물건은 곧은자로 재기 좋아요.","긴 줄자는 펴고 감기 번거로워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_basic#10','math',2,2,'u3','L03','g2_2_math_u3_L03_basic','lesson_basic','M2-2-u3-C4',3,'error','auto','줄자로 막대의 길이를 재었어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u3-X06','M2-2-u3-X16']::text[],true,'{"seq":10,"concept":"M2-2-u3-C4","difficulty":3,"kind":"error","stem":"줄자로 막대의 길이를 재었어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지우 — 「끝 눈금이 122니까 막대는 122 cm야.」","correct":true,"mis_target":"M2-2-u3-X06"},{"t":"서아 — 「2부터 122까지니까 120 cm야.」","mis":"M2-2-u3-X16"},{"t":"하루 — 「120 cm는 1 m 20 cm라고도 해.」","mis":"M2-2-u3-X16"}],"explanation":["막대의 한끝이 눈금 0이 아니라 2에 있어요.","122 − 2 = 120이니 막대는 120 cm예요.","지우는 끝 눈금을 그대로 읽었어요."],"asset":{"type":"tape","len":120,"label":"막대","s":2},"variant_rule":{"alt":[{"stem":"줄자로 끈의 길이를 재었어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「끝 눈금이 138이니까 끈은 138 cm야.」","correct":true,"mis_target":"M2-2-u3-X06"},{"t":"은솔 — 「3부터 138까지니까 135 cm야.」","mis":"M2-2-u3-X16"},{"t":"예린 — 「135 cm는 1 m 35 cm라고도 해.」","mis":"M2-2-u3-X16"}],"explanation":["끈의 한끝이 눈금 0이 아니라 3에 있어요.","138 − 3 = 135이니 끈은 135 cm예요.","도윤이는 끝 눈금을 그대로 읽었어요."],"asset":{"type":"tape","len":135,"label":"끈","s":3}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_challenge#1','math',2,2,'u3','L03','g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',2,'mc','auto','현수막의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X07','M2-2-u3-X09']::text[],true,'{"seq":1,"concept":"M2-2-u3-C4","difficulty":2,"kind":"mc","stem":"현수막의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["현수막의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 209이니 209 cm예요.","209 cm = 200 cm + 9 cm = 2 m 9 cm예요."],"variant_rule":{"mcm":{"ask":"read","form":"mcm"}},"options":[{"t":"2 m 9 cm","correct":true},{"t":"20 m 9 cm","mis":"M2-2-u3-X03"},{"t":"2 m 10 cm","mis":"M2-2-u3-X07"},{"t":"2 m 90 cm","mis":"M2-2-u3-X09"}],"asset":{"type":"tape","len":209,"label":"현수막"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_challenge#2','math',2,2,'u3','L03','g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',2,'sa','auto','소파의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 소파의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u3-C4","difficulty":2,"kind":"sa","stem":"소파의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 소파의 길이는 몇 cm인가요? 숫자로 쓰세요.","explanation":["소파의 한끝은 눈금 3, 다른 끝은 눈금 149에 있어요.","149 − 3 = 146이니 146 cm예요.","끝 눈금 149를 그대로 읽으면 안 돼요 — 한끝을 0에 맞추어 재요."],"variant_rule":{"mcm":{"ask":"off"}},"answer":["146"],"asset":{"type":"tape","len":146,"label":"소파","s":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_challenge#3','math',2,2,'u3','L03','g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',3,'mc','auto','멀리 던지기에서 제기를 던진 거리를 재는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u3-X19','M2-2-u3-X06']::text[],false,'{"seq":3,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"멀리 던지기에서 제기를 던진 거리를 재는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"출발선에서 제기가 바닥에 떨어진 곳까지 곧게 재요","correct":true},{"t":"제기가 날아간 길을 따라 구불구불하게 재요","mis":"M2-2-u3-X19"},{"t":"던진 사람의 발끝에서 아무 곳까지 재요","mis":"M2-2-u3-X06"}],"explanation":["거리는 출발선에서 시작해요.","제기가 처음 바닥에 떨어진 곳까지 재요.","거리는 반드시 곧게 재요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_challenge#4','math',2,2,'u3','L03','g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',3,'mc','auto','줄자로 잰 사물함의 길이가 520 cm예요. 이 길이를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X11','M2-2-u3-X01']::text[],false,'{"seq":4,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"줄자로 잰 사물함의 길이가 520 cm예요. 이 길이를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"5 m 20 cm","correct":true},{"t":"52 m","mis":"M2-2-u3-X03"},{"t":"5 m 2 cm","mis":"M2-2-u3-X11"},{"t":"50 m 20 cm","mis":"M2-2-u3-X01"}],"explanation":["520 cm = 500 cm + 20 cm예요.","500 cm는 5 m예요.","그래서 520 cm = 5 m 20 cm예요 — 20의 0을 떼면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_challenge#5','math',2,2,'u3','L03','g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',3,'mc','auto','칠판의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X07','M2-2-u3-X09']::text[],true,'{"seq":5,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"칠판의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["칠판의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 304이니 304 cm예요.","304 cm = 300 cm + 4 cm = 3 m 4 cm예요."],"variant_rule":{"mcm":{"ask":"read","form":"mcm"}},"options":[{"t":"3 m 4 cm","correct":true},{"t":"30 m 4 cm","mis":"M2-2-u3-X03"},{"t":"3 m 5 cm","mis":"M2-2-u3-X07"},{"t":"3 m 40 cm","mis":"M2-2-u3-X09"}],"asset":{"type":"tape","len":304,"label":"칠판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_challenge#6','math',2,2,'u3','L03','g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',3,'mc','auto','같은 책상을 지아는 140 cm, 세미는 1 m 40 cm라고 했어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u3-X01','M2-2-u3-X18']::text[],false,'{"seq":6,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"같은 책상을 지아는 140 cm, 세미는 1 m 40 cm라고 했어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"둘 다 맞아요 — 140 cm와 1 m 40 cm는 같은 길이예요","correct":true},{"t":"지아만 맞아요 — 줄자는 cm로만 읽으니까","mis":"M2-2-u3-X01"},{"t":"세미만 맞아요 — 수가 더 작으니까","mis":"M2-2-u3-X18"}],"explanation":["140 cm = 100 cm + 40 cm예요.","100 cm는 1 m라서 140 cm = 1 m 40 cm예요.","같은 길이를 두 가지 방법으로 나타낸 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_challenge#7','math',2,2,'u3','L03','g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',3,'mc','auto','길이가 1 m보다 긴 것은 어느 것인가요?',ARRAY['M2-2-u3-X17']::text[],false,'{"seq":7,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"길이가 1 m보다 긴 것은 어느 것인가요?","options":[{"t":"교실 문의 높이","correct":true},{"t":"필통의 길이","mis":"M2-2-u3-X17"},{"t":"연필의 길이","mis":"M2-2-u3-X17"},{"t":"공책의 긴 쪽의 길이","mis":"M2-2-u3-X17"}],"explanation":["1 m는 양팔을 벌린 길이쯤이에요.","필통·연필·공책은 1 m보다 훨씬 짧아요.","교실 문의 높이는 약 2 m라 1 m보다 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_challenge#8','math',2,2,'u3','L03','g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',4,'essay','teacher','줄자로 사물함의 길이를 재는 방법을 차례로 설명하고, 잰 길이 520 cm를 두 가지 방법으로 나타내 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u3-C4","difficulty":4,"kind":"essay","stem":"줄자로 사물함의 길이를 재는 방법을 차례로 설명하고, 잰 길이 520 cm를 두 가지 방법으로 나타내 보세요.","answer_guide":{"answer":"예: 사물함의 한끝을 줄자의 눈금 0에 맞춘다. 줄자를 곧게 펴서 다른 끝이 닿은 눈금을 읽는다. 520 cm는 5 m 20 cm라고도 나타낸다.","scoring_points":["한끝을 눈금 0에 맞춘다고 썼는가","다른 끝의 눈금을 읽는다고 썼는가","520 cm = 5 m 20 cm로 나타냈는가"]},"explanation":["한끝을 눈금 0에 맞춰요.","다른 끝이 닿은 눈금 520을 읽어요.","520 cm = 5 m 20 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_challenge#9','math',2,2,'u3','L03','g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',4,'essay','teacher','세미는 줄자로 막대를 재고 128 cm라고 했어요. 무엇이 잘못되었는지 설명하고, 막대의 바른 길이를 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u3-C4","difficulty":4,"kind":"essay","stem":"세미는 줄자로 막대를 재고 128 cm라고 했어요. 무엇이 잘못되었는지 설명하고, 막대의 바른 길이를 구해 보세요.","answer_guide":{"answer":"예: 막대의 한끝이 눈금 0이 아니라 3에 있는데 끝 눈금 128을 그대로 읽었다. 128 − 3 = 125이므로 막대의 길이는 125 cm(1 m 25 cm)이다.","scoring_points":["한끝이 0에 있지 않다는 점을 찾았는가","128 − 3을 계산했는가","125 cm라고 바르게 구했는가"]},"explanation":["한끝이 눈금 3에 있어요.","128 − 3 = 125예요.","막대는 125 cm = 1 m 25 cm예요."],"asset":{"type":"tape","len":125,"label":"막대","s":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L03_challenge#10','math',2,2,'u3','L03','g2_2_math_u3_L03_challenge','lesson_challenge','M2-2-u3-C4',4,'mc','auto','슬기는 제기를 2 m 10 cm, 배드민턴공을 3 m 50 cm 던졌어요. 수찬이는 공을 290 cm 던졌어요. 멀리 던진 것부터 차례로 쓴 것은 어느 것인가요?',ARRAY['M2-2-u3-X18','M2-2-u3-X16']::text[],false,'{"seq":10,"concept":"M2-2-u3-C4","difficulty":4,"kind":"mc","stem":"슬기는 제기를 2 m 10 cm, 배드민턴공을 3 m 50 cm 던졌어요. 수찬이는 공을 290 cm 던졌어요. 멀리 던진 것부터 차례로 쓴 것은 어느 것인가요?","options":[{"t":"배드민턴공, 수찬이의 공, 제기","correct":true},{"t":"수찬이의 공, 배드민턴공, 제기","mis":"M2-2-u3-X18"},{"t":"제기, 수찬이의 공, 배드민턴공","mis":"M2-2-u3-X16"}],"explanation":["모두 cm로 바꾸면 제기 210 cm, 배드민턴공 350 cm, 수찬이의 공 290 cm예요.","350 > 290 > 210이에요.","그래서 배드민턴공, 수찬이의 공, 제기 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_basic#1','math',2,2,'u3','L04','g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',1,'mc','auto','3 m 40 cm + 5 m 50 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X11']::text[],true,'{"seq":1,"concept":"M2-2-u3-C5","difficulty":1,"kind":"mc","stem":"3 m 40 cm + 5 m 50 cm는 얼마인가요?","explanation":["m는 m끼리 더해요 — 3 + 5 = 8.","cm는 cm끼리 더해요 — 40 + 50 = 90.","그래서 3 m 40 cm + 5 m 50 cm = 8 m 90 cm예요."],"variant_rule":{"mcm":{"ask":"add"}},"options":[{"t":"8 m 90 cm","correct":true},{"t":"2 m 10 cm","mis":"M2-2-u3-X10"},{"t":"8 m 9 cm","mis":"M2-2-u3-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_basic#2','math',2,2,'u3','L04','g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',1,'sa','auto','세로셈에서 cm 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u3-C5","difficulty":1,"kind":"sa","stem":"세로셈에서 cm 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["m는 m끼리 더해요 — 4 + 1 = 5.","cm는 cm끼리 더해요 — 26 + 60 = 86.","그래서 4 m 26 cm + 1 m 60 cm = 5 m 86 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"calc","calc":"cm"}},"answer":["86"],"asset":{"type":"mcm_calc","a":[4,26],"b":[1,60],"op":"+","ask":"cm"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_basic#3','math',2,2,'u3','L04','g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',1,'sa','auto','세로셈에서 m 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u3-C5","difficulty":1,"kind":"sa","stem":"세로셈에서 m 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["m는 m끼리 더해요 — 2 + 7 = 9.","cm는 cm끼리 더해요 — 24 + 5 = 29.","그래서 2 m 24 cm + 7 m 5 cm = 9 m 29 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"calc","calc":"m"}},"answer":["9"],"asset":{"type":"mcm_calc","a":[2,24],"b":[7,5],"op":"+","ask":"m"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_basic#4','math',2,2,'u3','L04','g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',1,'ox','auto','길이의 합을 구할 때는 m는 m끼리, cm는 cm끼리 더해요.',ARRAY['M2-2-u3-X04']::text[],true,'{"seq":4,"concept":"M2-2-u3-C5","difficulty":1,"kind":"ox","stem":"길이의 합을 구할 때는 m는 m끼리, cm는 cm끼리 더해요.","answer":"O","reason_options":[{"t":"같은 단위끼리 맞추어 더해야 하니까","correct":true},{"t":"m와 cm의 수를 모두 한꺼번에 더해도 되니까","mis":"M2-2-u3-X04"}],"mis":"M2-2-u3-X04","explanation":["m와 cm는 단위가 달라요.","그래서 같은 단위끼리 맞추어 써요.","m는 m끼리, cm는 cm끼리 더해요."],"variant_rule":{"alt":[{"stem":"1 m 70 cm + 1 m 20 cm를 구할 때 1 + 70 + 1 + 20을 계산하면 돼요.","answer":"X","reason_options":[{"t":"m는 m끼리, cm는 cm끼리 따로 더해야 하니까","correct":true},{"t":"수를 모두 더하면 길이의 합이 되니까","mis":"M2-2-u3-X04"}],"explanation":["1 m + 1 m = 2 m예요.","70 cm + 20 cm = 90 cm예요.","그래서 2 m 90 cm — 수를 한꺼번에 더하면 안 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_basic#5','math',2,2,'u3','L04','g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',2,'mc','auto','굴렁쇠가 5 m 35 cm를 굴러간 뒤 7 m 40 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":5,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"굴렁쇠가 5 m 35 cm를 굴러간 뒤 7 m 40 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?","explanation":["m는 m끼리 더해요 — 5 + 7 = 12.","cm는 cm끼리 더해요 — 35 + 40 = 75.","그래서 5 m 35 cm + 7 m 40 cm = 12 m 75 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"roll"}},"options":[{"t":"12 m 75 cm","correct":true},{"t":"2 m 5 cm","mis":"M2-2-u3-X10"},{"t":"13 m 75 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_basic#6','math',2,2,'u3','L04','g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',2,'mc','auto','색 테이프 두 장을 겹치지 않게 이어 붙였어요. 이은 색 테이프의 길이는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":6,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"색 테이프 두 장을 겹치지 않게 이어 붙였어요. 이은 색 테이프의 길이는 얼마인가요?","explanation":["m는 m끼리 더해요 — 2 + 1 = 3.","cm는 cm끼리 더해요 — 45 + 32 = 77.","그래서 2 m 45 cm + 1 m 32 cm = 3 m 77 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"tape"}},"options":[{"t":"3 m 77 cm","correct":true},{"t":"1 m 13 cm","mis":"M2-2-u3-X10"},{"t":"4 m 77 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mbar","parts":[[2,45],[1,32]],"op":"+"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_basic#7','math',2,2,'u3','L04','g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',2,'mc','auto','세로셈을 계산하면 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":7,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"세로셈을 계산하면 얼마인가요?","explanation":["m는 m끼리 더해요 — 11 + 7 = 18.","cm는 cm끼리 더해요 — 35 + 23 = 58.","그래서 11 m 35 cm + 7 m 23 cm = 18 m 58 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"calc"}},"options":[{"t":"18 m 58 cm","correct":true},{"t":"4 m 12 cm","mis":"M2-2-u3-X10"},{"t":"19 m 58 cm","mis":"M2-2-u3-X08"},{"t":"18 m 68 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mcm_calc","a":[11,35],"b":[7,23],"op":"+","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_basic#8','math',2,2,'u3','L04','g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',2,'error','auto','어떤 친구가 2 m 30 cm + 1 m 40 cm를 이렇게 계산했어요. 잘못 계산한 곳은 어디인가요?',ARRAY['M2-2-u3-X11','M2-2-u3-X08','M2-2-u3-X10']::text[],true,'{"seq":8,"concept":"M2-2-u3-C5","difficulty":2,"kind":"error","stem":"어떤 친구가 2 m 30 cm + 1 m 40 cm를 이렇게 계산했어요. 잘못 계산한 곳은 어디인가요?","options":[{"t":"cm끼리 더한 70을 7이라고 썼어요","correct":true,"mis_target":"M2-2-u3-X11"},{"t":"m끼리 더한 것이 틀렸어요","mis":"M2-2-u3-X08"},{"t":"더해야 하는데 뺐어요","mis":"M2-2-u3-X10"}],"explanation":["m끼리 2 + 1 = 3, cm끼리 30 + 40 = 70이에요.","바른 답은 3 m 70 cm예요.","70의 0을 떼고 7 cm로 쓰면 안 돼요."],"asset":{"type":"mcm_calc","a":[2,30],"b":[1,40],"op":"+","ask":"both","said":[3,7]},"variant_rule":{"alt":[{"stem":"어떤 친구가 3 m 50 cm + 2 m 20 cm를 이렇게 계산했어요. 잘못 계산한 곳은 어디인가요?","options":[{"t":"cm끼리 더한 70을 7이라고 썼어요","correct":true,"mis_target":"M2-2-u3-X11"},{"t":"m끼리 더한 것이 틀렸어요","mis":"M2-2-u3-X08"},{"t":"더해야 하는데 뺐어요","mis":"M2-2-u3-X10"}],"explanation":["m끼리 3 + 2 = 5, cm끼리 50 + 20 = 70이에요.","바른 답은 5 m 70 cm예요.","70의 0을 떼고 7 cm로 쓰면 안 돼요."],"asset":{"type":"mcm_calc","a":[3,50],"b":[2,20],"op":"+","ask":"both","said":[5,7]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_basic#9','math',2,2,'u3','L04','g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',2,'mc','auto','3 m 52 cm + 4 m 6 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":9,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"3 m 52 cm + 4 m 6 cm는 얼마인가요?","explanation":["m는 m끼리 더해요 — 3 + 4 = 7.","cm는 cm끼리 더해요 — 52 + 6 = 58.","그래서 3 m 52 cm + 4 m 6 cm = 7 m 58 cm예요."],"variant_rule":{"mcm":{"ask":"add"}},"options":[{"t":"7 m 58 cm","correct":true},{"t":"1 m 46 cm","mis":"M2-2-u3-X10"},{"t":"8 m 58 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_basic#10','math',2,2,'u3','L04','g2_2_math_u3_L04_basic','lesson_basic','M2-2-u3-C5',3,'mc','auto','표지판을 만들려고 가로 나무 1 m 70 cm와 세로 나무 1 m 20 cm를 이어요. 필요한 나무는 모두 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X11']::text[],true,'{"seq":10,"concept":"M2-2-u3-C5","difficulty":3,"kind":"mc","stem":"표지판을 만들려고 가로 나무 1 m 70 cm와 세로 나무 1 m 20 cm를 이어요. 필요한 나무는 모두 얼마인가요?","options":[{"t":"2 m 90 cm","correct":true},{"t":"50 cm","mis":"M2-2-u3-X10"},{"t":"2 m 9 cm","mis":"M2-2-u3-X11"}],"explanation":["필요한 나무는 두 나무의 길이의 합이에요.","m끼리 1 + 1 = 2, cm끼리 70 + 20 = 90이에요.","그래서 2 m 90 cm가 필요해요."],"variant_rule":{"alt":[{"stem":"의자를 만들려고 나무 1 m 40 cm와 2 m 30 cm를 이어요. 필요한 나무는 모두 얼마인가요?","options":[{"t":"3 m 70 cm","correct":true},{"t":"1 m 10 cm","mis":"M2-2-u3-X10"},{"t":"3 m 7 cm","mis":"M2-2-u3-X11"}],"explanation":["필요한 나무는 두 나무의 길이의 합이에요.","m끼리 1 + 2 = 3, cm끼리 40 + 30 = 70이에요.","그래서 3 m 70 cm가 필요해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_challenge#1','math',2,2,'u3','L04','g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',2,'mc','auto','6 m 52 cm인 나무와 2 m 7 cm인 나무를 겹치지 않게 이었어요. 이은 나무의 길이는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":1,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"6 m 52 cm인 나무와 2 m 7 cm인 나무를 겹치지 않게 이었어요. 이은 나무의 길이는 얼마인가요?","explanation":["m는 m끼리 더해요 — 6 + 2 = 8.","cm는 cm끼리 더해요 — 52 + 7 = 59.","그래서 6 m 52 cm + 2 m 7 cm = 8 m 59 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"join"}},"options":[{"t":"8 m 59 cm","correct":true},{"t":"4 m 45 cm","mis":"M2-2-u3-X10"},{"t":"9 m 59 cm","mis":"M2-2-u3-X08"},{"t":"8 m 69 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_challenge#2','math',2,2,'u3','L04','g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',2,'mc','auto','세로셈에서 cm 자리의 ?에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":2,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"세로셈에서 cm 자리의 ?에 알맞은 수는 얼마인가요?","explanation":["m는 m끼리 더해요 — 4 + 2 = 6.","cm는 cm끼리 더해요 — 35 + 43 = 78.","그래서 4 m 35 cm + 2 m 43 cm = 6 m 78 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"calc","calc":"cm"}},"options":[{"t":"78","correct":true},{"t":"8","mis":"M2-2-u3-X10"},{"t":"88","mis":"M2-2-u3-X08"}],"asset":{"type":"mcm_calc","a":[4,35],"b":[2,43],"op":"+","ask":"cm"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_challenge#3','math',2,2,'u3','L04','g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',3,'mc','auto','3 m 25 cm + □ m 42 cm = 7 m 67 cm에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":3,"concept":"M2-2-u3-C5","difficulty":3,"kind":"mc","stem":"3 m 25 cm + □ m 42 cm = 7 m 67 cm에서 □ 안에 알맞은 수는 얼마인가요?","options":[{"t":"4","correct":true},{"t":"10","mis":"M2-2-u3-X10"},{"t":"3","mis":"M2-2-u3-X08"}],"explanation":["cm끼리 25 + 42 = 67로 맞아요.","m끼리 3 + □ = 7이에요.","7 − 3 = 4이니 □는 4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_challenge#4','math',2,2,'u3','L04','g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',3,'mc','auto','두 길이의 합이 5 m 80 cm인 것은 어느 것인가요?',ARRAY['M2-2-u3-X09','M2-2-u3-X08']::text[],false,'{"seq":4,"concept":"M2-2-u3-C5","difficulty":3,"kind":"mc","stem":"두 길이의 합이 5 m 80 cm인 것은 어느 것인가요?","options":[{"t":"2 m 50 cm와 3 m 30 cm","correct":true},{"t":"2 m 50 cm와 3 m 3 cm","mis":"M2-2-u3-X09"},{"t":"3 m 50 cm와 2 m 50 cm","mis":"M2-2-u3-X08"},{"t":"2 m 30 cm와 3 m 30 cm","mis":"M2-2-u3-X08"}],"explanation":["2 m 50 cm + 3 m 30 cm에서 m끼리 5, cm끼리 80이에요.","2 m 50 cm + 3 m 3 cm는 5 m 53 cm예요.","그래서 2 m 50 cm와 3 m 30 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_challenge#5','math',2,2,'u3','L04','g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',3,'mc','auto','색 테이프 세 장 1 m 20 cm, 2 m 35 cm, 3 m 4 cm를 겹치지 않게 이었어요. 이은 길이는 얼마인가요?',ARRAY['M2-2-u3-X09','M2-2-u3-X08']::text[],false,'{"seq":5,"concept":"M2-2-u3-C5","difficulty":3,"kind":"mc","stem":"색 테이프 세 장 1 m 20 cm, 2 m 35 cm, 3 m 4 cm를 겹치지 않게 이었어요. 이은 길이는 얼마인가요?","options":[{"t":"6 m 59 cm","correct":true},{"t":"6 m 95 cm","mis":"M2-2-u3-X09"},{"t":"5 m 59 cm","mis":"M2-2-u3-X08"}],"explanation":["m끼리 1 + 2 + 3 = 6이에요.","cm끼리 20 + 35 + 4 = 59예요.","4 cm를 40 cm로 보면 안 돼요 — 6 m 59 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_challenge#6','math',2,2,'u3','L04','g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',3,'error','auto','2 m 24 cm + 7 m 5 cm를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M2-2-u3-X09','M2-2-u3-X16']::text[],false,'{"seq":6,"concept":"M2-2-u3-C5","difficulty":3,"kind":"error","stem":"2 m 24 cm + 7 m 5 cm를 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"도윤 — 「cm끼리 24 + 50 = 74니까 9 m 74 cm야.」","correct":true,"mis_target":"M2-2-u3-X09"},{"t":"은솔 — 「m끼리 9, cm끼리 29니까 9 m 29 cm야.」","mis":"M2-2-u3-X16"},{"t":"예린 — 「224 cm + 705 cm = 929 cm = 9 m 29 cm야.」","mis":"M2-2-u3-X16"}],"explanation":["7 m 5 cm의 cm는 5예요.","cm끼리 24 + 5 = 29예요.","도윤이는 5를 50처럼 더했어요 — 9 m 29 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_challenge#7','math',2,2,'u3','L04','g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',3,'mc','auto','굴렁쇠가 12 m 45 cm를 굴러간 뒤 6 m 32 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":7,"concept":"M2-2-u3-C5","difficulty":3,"kind":"mc","stem":"굴렁쇠가 12 m 45 cm를 굴러간 뒤 6 m 32 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?","explanation":["m는 m끼리 더해요 — 12 + 6 = 18.","cm는 cm끼리 더해요 — 45 + 32 = 77.","그래서 12 m 45 cm + 6 m 32 cm = 18 m 77 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"roll"}},"options":[{"t":"18 m 77 cm","correct":true},{"t":"6 m 13 cm","mis":"M2-2-u3-X10"},{"t":"19 m 77 cm","mis":"M2-2-u3-X08"},{"t":"18 m 87 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_challenge#8','math',2,2,'u3','L04','g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',4,'essay','teacher','4 m 26 cm + 1 m 60 cm를 세로셈으로 계산하는 방법을 차례로 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u3-C5","difficulty":4,"kind":"essay","stem":"4 m 26 cm + 1 m 60 cm를 세로셈으로 계산하는 방법을 차례로 설명해 보세요.","answer_guide":{"answer":"예: 같은 단위끼리 맞추어 쓴다. cm끼리 26 + 60 = 86, m끼리 4 + 1 = 5를 더한다. 두 길이의 합은 5 m 86 cm이다.","scoring_points":["같은 단위끼리 맞추어 쓴다고 했는가","cm끼리·m끼리 더했는가","5 m 86 cm라고 바르게 구했는가"]},"explanation":["m는 m 아래, cm는 cm 아래에 맞추어 써요.","cm끼리 86, m끼리 5예요.","두 길이의 합은 5 m 86 cm예요."],"asset":{"type":"mcm_calc","a":[4,26],"b":[1,60],"op":"+","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_challenge#9','math',2,2,'u3','L04','g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',4,'essay','teacher','2 m 30 cm + 1 m 40 cm를 3 m 7 cm라고 계산한 친구가 있어요. 무엇이 잘못되었는지 설명하고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u3-C5","difficulty":4,"kind":"essay","stem":"2 m 30 cm + 1 m 40 cm를 3 m 7 cm라고 계산한 친구가 있어요. 무엇이 잘못되었는지 설명하고 바르게 계산해 보세요.","answer_guide":{"answer":"예: cm끼리 더한 30 + 40 = 70을 7이라고 썼다. 바르게 계산하면 m끼리 3, cm끼리 70이므로 3 m 70 cm이다.","scoring_points":["70을 7로 쓴 잘못을 찾았는가","cm끼리 70, m끼리 3을 구했는가","3 m 70 cm라고 바르게 썼는가"]},"explanation":["cm끼리 30 + 40 = 70이에요.","70의 0을 떼면 7 cm가 되어 10배나 짧아져요.","바른 답은 3 m 70 cm예요."],"asset":{"type":"mcm_calc","a":[2,30],"b":[1,40],"op":"+","ask":"both","said":[3,7]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L04_challenge#10','math',2,2,'u3','L04','g2_2_math_u3_L04_challenge','lesson_challenge','M2-2-u3-C5',4,'mc','auto','달리기 길은 세 구간이에요. 첫째 15 m 40 cm, 둘째 12 m 35 cm, 셋째 21 m 10 cm예요. 달리기 길은 모두 얼마인가요?',ARRAY['M2-2-u3-X08','M2-2-u3-X16']::text[],false,'{"seq":10,"concept":"M2-2-u3-C5","difficulty":4,"kind":"mc","stem":"달리기 길은 세 구간이에요. 첫째 15 m 40 cm, 둘째 12 m 35 cm, 셋째 21 m 10 cm예요. 달리기 길은 모두 얼마인가요?","options":[{"t":"48 m 85 cm","correct":true},{"t":"47 m 85 cm","mis":"M2-2-u3-X08"},{"t":"48 m 75 cm","mis":"M2-2-u3-X08"},{"t":"27 m 75 cm","mis":"M2-2-u3-X16"}],"explanation":["m끼리 15 + 12 + 21 = 48이에요.","cm끼리 40 + 35 + 10 = 85예요.","그래서 모두 48 m 85 cm예요 — 두 구간만 더하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_basic#1','math',2,2,'u3','L05','g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',1,'mc','auto','6 m 80 cm − 4 m 50 cm는 얼마인가요?',ARRAY['M2-2-u3-X11','M2-2-u3-X08']::text[],true,'{"seq":1,"concept":"M2-2-u3-C6","difficulty":1,"kind":"mc","stem":"6 m 80 cm − 4 m 50 cm는 얼마인가요?","explanation":["m는 m끼리 빼요 — 6 − 4 = 2.","cm는 cm끼리 빼요 — 80 − 50 = 30.","그래서 6 m 80 cm − 4 m 50 cm = 2 m 30 cm예요."],"variant_rule":{"mcm":{"ask":"sub"}},"options":[{"t":"2 m 30 cm","correct":true},{"t":"2 m 3 cm","mis":"M2-2-u3-X11"},{"t":"3 m 30 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_basic#2','math',2,2,'u3','L05','g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',1,'sa','auto','세로셈에서 cm 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u3-C6","difficulty":1,"kind":"sa","stem":"세로셈에서 cm 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["m는 m끼리 빼요 — 7 − 5 = 2.","cm는 cm끼리 빼요 — 74 − 32 = 42.","그래서 7 m 74 cm − 5 m 32 cm = 2 m 42 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"calc","calc":"cm"}},"answer":["42"],"asset":{"type":"mcm_calc","a":[7,74],"b":[5,32],"op":"-","ask":"cm"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_basic#3','math',2,2,'u3','L05','g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',1,'sa','auto','세로셈에서 m 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u3-C6","difficulty":1,"kind":"sa","stem":"세로셈에서 m 자리의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["m는 m끼리 빼요 — 4 − 1 = 3.","cm는 cm끼리 빼요 — 29 − 6 = 23.","그래서 4 m 29 cm − 1 m 6 cm = 3 m 23 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"calc","calc":"m"}},"answer":["3"],"asset":{"type":"mcm_calc","a":[4,29],"b":[1,6],"op":"-","ask":"m"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_basic#4','math',2,2,'u3','L05','g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',1,'ox','auto','길이의 차를 구한 뒤 뺀 길이를 다시 더하면 처음 길이가 나와요.',ARRAY['M2-2-u3-X10']::text[],true,'{"seq":4,"concept":"M2-2-u3-C6","difficulty":1,"kind":"ox","stem":"길이의 차를 구한 뒤 뺀 길이를 다시 더하면 처음 길이가 나와요.","answer":"O","reason_options":[{"t":"남은 길이와 뺀 길이를 모으면 처음 길이가 되니까","correct":true},{"t":"빼고 나서 더하면 늘 다른 길이가 되니까","mis":"M2-2-u3-X10"}],"mis":"M2-2-u3-X10","explanation":["2 m 50 cm − 1 m 40 cm = 1 m 10 cm예요.","1 m 10 cm + 1 m 40 cm = 2 m 50 cm예요.","그래서 더해 보면 차가 맞는지 확인할 수 있어요."],"variant_rule":{"alt":[{"stem":"7 m 74 cm − 5 m 32 cm = 2 m 42 cm가 맞는지 보려면 2 m 42 cm + 5 m 32 cm를 계산해요.","answer":"O","reason_options":[{"t":"차에 뺀 길이를 더하면 처음 길이가 나와야 하니까","correct":true},{"t":"차를 확인할 때는 처음 길이를 한 번 더 빼야 하니까","mis":"M2-2-u3-X10"}],"explanation":["2 m 42 cm + 5 m 32 cm를 계산해요.","m끼리 7, cm끼리 74 — 7 m 74 cm예요.","처음 길이가 나왔으니 차가 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_basic#5','math',2,2,'u3','L05','g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',2,'mc','auto','2 m 50 cm인 색 테이프에서 1 m 40 cm를 잘라 썼어요. 남은 색 테이프의 길이는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X11']::text[],true,'{"seq":5,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"2 m 50 cm인 색 테이프에서 1 m 40 cm를 잘라 썼어요. 남은 색 테이프의 길이는 얼마인가요?","explanation":["m는 m끼리 빼요 — 2 − 1 = 1.","cm는 cm끼리 빼요 — 50 − 40 = 10.","그래서 2 m 50 cm − 1 m 40 cm = 1 m 10 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"cut"}},"options":[{"t":"1 m 10 cm","correct":true},{"t":"3 m 90 cm","mis":"M2-2-u3-X10"},{"t":"1 m 1 cm","mis":"M2-2-u3-X11"}],"asset":{"type":"mbar","parts":[[2,50],[1,40]],"op":"-"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_basic#6','math',2,2,'u3','L05','g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',2,'mc','auto','3 m 75 cm인 색 테이프에서 1 m 52 cm를 잘라 썼어요. 남은 색 테이프의 길이는 얼마인가요?',ARRAY['M2-2-u3-X08']::text[],true,'{"seq":6,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"3 m 75 cm인 색 테이프에서 1 m 52 cm를 잘라 썼어요. 남은 색 테이프의 길이는 얼마인가요?","explanation":["m는 m끼리 빼요 — 3 − 1 = 2.","cm는 cm끼리 빼요 — 75 − 52 = 23.","그래서 3 m 75 cm − 1 m 52 cm = 2 m 23 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"cut"}},"options":[{"t":"2 m 23 cm","correct":true},{"t":"3 m 23 cm","mis":"M2-2-u3-X08"},{"t":"2 m 33 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mbar","parts":[[3,75],[1,52]],"op":"-"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_basic#7','math',2,2,'u3','L05','g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',2,'mc','auto','두 막대의 길이는 9 m 48 cm와 1 m 3 cm예요. 두 막대의 길이의 차는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X09','M2-2-u3-X08']::text[],true,'{"seq":7,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"두 막대의 길이는 9 m 48 cm와 1 m 3 cm예요. 두 막대의 길이의 차는 얼마인가요?","explanation":["m는 m끼리 빼요 — 9 − 1 = 8.","cm는 cm끼리 빼요 — 48 − 3 = 45.","그래서 9 m 48 cm − 1 m 3 cm = 8 m 45 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"diff"}},"options":[{"t":"8 m 45 cm","correct":true},{"t":"10 m 51 cm","mis":"M2-2-u3-X10"},{"t":"8 m 18 cm","mis":"M2-2-u3-X09"},{"t":"9 m 45 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_basic#8','math',2,2,'u3','L05','g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',2,'error','auto','어떤 친구가 5 m 64 cm − 3 m 22 cm를 이렇게 계산했어요. 잘못 계산한 까닭은 무엇인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":8,"concept":"M2-2-u3-C6","difficulty":2,"kind":"error","stem":"어떤 친구가 5 m 64 cm − 3 m 22 cm를 이렇게 계산했어요. 잘못 계산한 까닭은 무엇인가요?","options":[{"t":"빼야 하는데 더했어요","correct":true,"mis_target":"M2-2-u3-X10"},{"t":"cm 자리만 계산했어요","mis":"M2-2-u3-X08"},{"t":"m 자리를 잘못 읽었어요","mis":"M2-2-u3-X08"}],"explanation":["5 m 64 cm − 3 m 22 cm는 차를 구하는 식이에요.","8 m 86 cm는 두 길이를 더한 값이에요.","바르게 빼면 m끼리 2, cm끼리 42 — 2 m 42 cm예요."],"asset":{"type":"mcm_calc","a":[5,64],"b":[3,22],"op":"-","ask":"both","said":[8,86]},"variant_rule":{"alt":[{"stem":"어떤 친구가 6 m 45 cm − 2 m 31 cm를 이렇게 계산했어요. 잘못 계산한 까닭은 무엇인가요?","options":[{"t":"빼야 하는데 더했어요","correct":true,"mis_target":"M2-2-u3-X10"},{"t":"cm 자리만 계산했어요","mis":"M2-2-u3-X08"},{"t":"m 자리를 잘못 읽었어요","mis":"M2-2-u3-X08"}],"explanation":["6 m 45 cm − 2 m 31 cm는 차를 구하는 식이에요.","8 m 76 cm는 두 길이를 더한 값이에요.","바르게 빼면 m끼리 4, cm끼리 14 — 4 m 14 cm예요."],"asset":{"type":"mcm_calc","a":[6,45],"b":[2,31],"op":"-","ask":"both","said":[8,76]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_basic#9','math',2,2,'u3','L05','g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',2,'mc','auto','8 m 47 cm − 2 m 5 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":9,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"8 m 47 cm − 2 m 5 cm는 얼마인가요?","explanation":["m는 m끼리 빼요 — 8 − 2 = 6.","cm는 cm끼리 빼요 — 47 − 5 = 42.","그래서 8 m 47 cm − 2 m 5 cm = 6 m 42 cm예요."],"variant_rule":{"mcm":{"ask":"sub"}},"options":[{"t":"6 m 42 cm","correct":true},{"t":"10 m 52 cm","mis":"M2-2-u3-X10"},{"t":"7 m 42 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_basic#10','math',2,2,'u3','L05','g2_2_math_u3_L05_basic','lesson_basic','M2-2-u3-C6',3,'mc','auto','나무 2 m 50 cm에서 1 m 40 cm를 사용했어요. 남은 나무로 1 m 20 cm짜리 다리를 만들 수 있나요?',ARRAY['M2-2-u3-X10','M2-2-u3-X16']::text[],true,'{"seq":10,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"나무 2 m 50 cm에서 1 m 40 cm를 사용했어요. 남은 나무로 1 m 20 cm짜리 다리를 만들 수 있나요?","options":[{"t":"아니요 — 남은 나무가 1 m 10 cm라 10 cm 모자라요","correct":true},{"t":"네 — 남은 나무가 3 m 90 cm예요","mis":"M2-2-u3-X10"},{"t":"네 — 1 m 40 cm가 1 m 20 cm보다 기니까","mis":"M2-2-u3-X16"}],"explanation":["남은 나무는 2 m 50 cm − 1 m 40 cm = 1 m 10 cm예요.","1 m 10 cm는 1 m 20 cm보다 10 cm 짧아요.","그래서 다리를 만들 수 없어요."],"variant_rule":{"alt":[{"stem":"끈 3 m 60 cm에서 2 m 10 cm를 사용했어요. 남은 끈으로 1 m 30 cm짜리 줄을 만들 수 있나요?","options":[{"t":"네 — 남은 끈이 1 m 50 cm라 20 cm 남아요","correct":true},{"t":"아니요 — 남은 끈이 5 m 70 cm예요","mis":"M2-2-u3-X10"},{"t":"아니요 — 2 m 10 cm가 더 기니까","mis":"M2-2-u3-X16"}],"explanation":["남은 끈은 3 m 60 cm − 2 m 10 cm = 1 m 50 cm예요.","1 m 50 cm는 1 m 30 cm보다 20 cm 길어요.","그래서 줄을 만들 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_challenge#1','math',2,2,'u3','L05','g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',2,'mc','auto','길이가 6 m 88 cm인 막대를 두 도막으로 잘랐어요. 한 도막이 4 m 26 cm일 때 다른 도막의 길이는 얼마인가요?',ARRAY['M2-2-u3-X08']::text[],true,'{"seq":1,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"길이가 6 m 88 cm인 막대를 두 도막으로 잘랐어요. 한 도막이 4 m 26 cm일 때 다른 도막의 길이는 얼마인가요?","explanation":["m는 m끼리 빼요 — 6 − 4 = 2.","cm는 cm끼리 빼요 — 88 − 26 = 62.","그래서 6 m 88 cm − 4 m 26 cm = 2 m 62 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"two"}},"options":[{"t":"2 m 62 cm","correct":true},{"t":"3 m 62 cm","mis":"M2-2-u3-X08"},{"t":"2 m 72 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_challenge#2','math',2,2,'u3','L05','g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',2,'mc','auto','세로셈을 계산하면 얼마인가요?',ARRAY['M2-2-u3-X08']::text[],true,'{"seq":2,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"세로셈을 계산하면 얼마인가요?","explanation":["m는 m끼리 빼요 — 8 − 3 = 5.","cm는 cm끼리 빼요 — 65 − 40 = 25.","그래서 8 m 65 cm − 3 m 40 cm = 5 m 25 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"calc"}},"options":[{"t":"5 m 25 cm","correct":true},{"t":"6 m 25 cm","mis":"M2-2-u3-X08"},{"t":"5 m 35 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mcm_calc","a":[8,65],"b":[3,40],"op":"-","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_challenge#3','math',2,2,'u3','L05','g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',3,'mc','auto','9 m 76 cm − □ m 34 cm = 4 m 42 cm에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":3,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"9 m 76 cm − □ m 34 cm = 4 m 42 cm에서 □ 안에 알맞은 수는 얼마인가요?","options":[{"t":"5","correct":true},{"t":"13","mis":"M2-2-u3-X10"},{"t":"4","mis":"M2-2-u3-X08"}],"explanation":["cm끼리 76 − 34 = 42로 맞아요.","m끼리 9 − □ = 4예요.","9 − 5 = 4이니 □는 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_challenge#4','math',2,2,'u3','L05','g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',3,'mc','auto','두 막대의 길이는 9 m 87 cm와 1 m 22 cm예요. 두 막대의 길이의 차는 8 m 45 cm보다 긴가요?',ARRAY['M2-2-u3-X08','M2-2-u3-X10']::text[],false,'{"seq":4,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"두 막대의 길이는 9 m 87 cm와 1 m 22 cm예요. 두 막대의 길이의 차는 8 m 45 cm보다 긴가요?","options":[{"t":"네 — 차가 8 m 65 cm라 더 길어요","correct":true},{"t":"아니요 — 차가 8 m 45 cm와 같아요","mis":"M2-2-u3-X08"},{"t":"아니요 — 차가 11 m 9 cm예요","mis":"M2-2-u3-X10"}],"explanation":["m끼리 9 − 1 = 8, cm끼리 87 − 22 = 65예요.","차는 8 m 65 cm예요.","8 m 65 cm는 8 m 45 cm보다 20 cm 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_challenge#5','math',2,2,'u3','L05','g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',3,'mc','auto','막대 가는 3 m 85 cm, 나는 2 m 40 cm, 다는 5 m 96 cm예요. 가장 긴 막대와 가장 짧은 막대의 길이의 차는 얼마인가요?',ARRAY['M2-2-u3-X16','M2-2-u3-X10']::text[],false,'{"seq":5,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"막대 가는 3 m 85 cm, 나는 2 m 40 cm, 다는 5 m 96 cm예요. 가장 긴 막대와 가장 짧은 막대의 길이의 차는 얼마인가요?","options":[{"t":"3 m 56 cm","correct":true},{"t":"2 m 11 cm","mis":"M2-2-u3-X16"},{"t":"8 m 36 cm","mis":"M2-2-u3-X10"}],"explanation":["가장 긴 막대는 다(5 m 96 cm), 가장 짧은 막대는 나(2 m 40 cm)예요.","m끼리 5 − 2 = 3, cm끼리 96 − 40 = 56이에요.","그래서 차는 3 m 56 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_challenge#6','math',2,2,'u3','L05','g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',3,'error','auto','4 m 29 cm − 1 m 6 cm를 친구들이 계산했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u3-X09','M2-2-u3-X16']::text[],false,'{"seq":6,"concept":"M2-2-u3-C6","difficulty":3,"kind":"error","stem":"4 m 29 cm − 1 m 6 cm를 친구들이 계산했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「29에서 60은 뺄 수 없으니 계산할 수 없어.」","correct":true,"mis_target":"M2-2-u3-X09"},{"t":"아린 — 「m끼리 3, cm끼리 23이니 3 m 23 cm야.」","mis":"M2-2-u3-X16"},{"t":"지안 — 「3 m 23 cm에 1 m 6 cm를 더하면 4 m 29 cm라 맞아.」","mis":"M2-2-u3-X16"}],"explanation":["1 m 6 cm의 cm는 6이에요.","cm끼리 29 − 6 = 23이에요.","태민이는 6을 60으로 보았어요 — 답은 3 m 23 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_challenge#7','math',2,2,'u3','L05','g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',3,'mc','auto','색 테이프 7 m 58 cm 가운데 2 m 15 cm는 상자 포장에, 3 m 21 cm는 리본에 썼어요. 남은 색 테이프는 얼마인가요?',ARRAY['M2-2-u3-X08','M2-2-u3-X10']::text[],false,'{"seq":7,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"색 테이프 7 m 58 cm 가운데 2 m 15 cm는 상자 포장에, 3 m 21 cm는 리본에 썼어요. 남은 색 테이프는 얼마인가요?","options":[{"t":"2 m 22 cm","correct":true},{"t":"5 m 43 cm","mis":"M2-2-u3-X08"},{"t":"12 m 94 cm","mis":"M2-2-u3-X10"}],"explanation":["상자 포장에 쓰고 남은 것은 7 m 58 cm − 2 m 15 cm = 5 m 43 cm예요.","리본에 쓰고 남은 것은 5 m 43 cm − 3 m 21 cm = 2 m 22 cm예요.","두 번 빼야 해요 — 한 번만 빼면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_challenge#8','math',2,2,'u3','L05','g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',4,'essay','teacher','7 m 74 cm − 5 m 32 cm를 계산하고, 구한 답이 맞는지 덧셈으로 확인하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u3-C6","difficulty":4,"kind":"essay","stem":"7 m 74 cm − 5 m 32 cm를 계산하고, 구한 답이 맞는지 덧셈으로 확인하는 방법을 설명해 보세요.","answer_guide":{"answer":"예: m끼리 7 − 5 = 2, cm끼리 74 − 32 = 42이므로 2 m 42 cm이다. 2 m 42 cm + 5 m 32 cm = 7 m 74 cm가 되어 처음 길이가 나오므로 맞다.","scoring_points":["2 m 42 cm를 바르게 구했는가","차에 뺀 길이를 더해 확인했는가","처음 길이 7 m 74 cm가 나오는지 말했는가"]},"explanation":["m끼리, cm끼리 빼면 2 m 42 cm예요.","2 m 42 cm + 5 m 32 cm = 7 m 74 cm예요.","처음 길이가 나오면 차가 맞아요."],"asset":{"type":"mcm_calc","a":[7,74],"b":[5,32],"op":"-","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_challenge#9','math',2,2,'u3','L05','g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',4,'essay','teacher','길이가 6 m 88 cm인 막대를 두 도막으로 잘랐더니 한 도막이 4 m 26 cm였어요. 다른 도막의 길이를 구하고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u3-C6","difficulty":4,"kind":"essay","stem":"길이가 6 m 88 cm인 막대를 두 도막으로 잘랐더니 한 도막이 4 m 26 cm였어요. 다른 도막의 길이를 구하고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 다른 도막은 전체에서 한 도막을 뺀 길이이다. 6 m 88 cm − 4 m 26 cm에서 m끼리 2, cm끼리 62이므로 2 m 62 cm이다.","scoring_points":["뺄셈으로 구해야 함을 썼는가","m끼리·cm끼리 뺐는가","2 m 62 cm라고 바르게 구했는가"]},"explanation":["두 도막을 이으면 처음 막대가 돼요.","그래서 다른 도막은 6 m 88 cm − 4 m 26 cm예요.","2 m 62 cm예요."],"asset":{"type":"mbar","parts":[[6,88],[4,26]],"op":"-"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L05_challenge#10','math',2,2,'u3','L05','g2_2_math_u3_L05_challenge','lesson_challenge','M2-2-u3-C6',4,'mc','auto','빨간 끈은 4 m 35 cm이고, 파란 끈은 빨간 끈보다 1 m 20 cm 짧아요. 두 끈의 길이의 합은 얼마인가요?',ARRAY['M2-2-u3-X16','M2-2-u3-X10']::text[],false,'{"seq":10,"concept":"M2-2-u3-C6","difficulty":4,"kind":"mc","stem":"빨간 끈은 4 m 35 cm이고, 파란 끈은 빨간 끈보다 1 m 20 cm 짧아요. 두 끈의 길이의 합은 얼마인가요?","options":[{"t":"7 m 50 cm","correct":true},{"t":"3 m 15 cm","mis":"M2-2-u3-X16"},{"t":"9 m 90 cm","mis":"M2-2-u3-X10"}],"explanation":["파란 끈은 4 m 35 cm − 1 m 20 cm = 3 m 15 cm예요.","두 끈의 합은 4 m 35 cm + 3 m 15 cm예요.","m끼리 7, cm끼리 50 — 7 m 50 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_basic#1','math',2,2,'u3','L06','g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',1,'mc','auto','교실 문의 짧은 쪽을 자로 재지 않고 1 m쯤으로 짐작했어요. 어림한 길이를 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u3-X12','M2-2-u3-X17']::text[],true,'{"seq":1,"concept":"M2-2-u3-C7","difficulty":1,"kind":"mc","stem":"교실 문의 짧은 쪽을 자로 재지 않고 1 m쯤으로 짐작했어요. 어림한 길이를 바르게 말한 것은 어느 것인가요?","options":[{"t":"약 1 m","correct":true},{"t":"1 m","mis":"M2-2-u3-X12"},{"t":"약 1 cm","mis":"M2-2-u3-X17"}],"explanation":["자로 재지 않고 짐작한 것을 어림이라고 해요.","어림한 길이 앞에는 「약」을 붙여요.","그래서 약 1 m라고 말해요."],"variant_rule":{"alt":[{"stem":"책꽂이의 긴 쪽을 자로 재지 않고 2 m쯤으로 짐작했어요. 어림한 길이를 바르게 말한 것은 어느 것인가요?","options":[{"t":"약 2 m","correct":true},{"t":"2 m","mis":"M2-2-u3-X12"},{"t":"약 2 cm","mis":"M2-2-u3-X17"}],"explanation":["자로 재지 않고 짐작한 것을 어림이라고 해요.","어림한 길이 앞에는 「약」을 붙여요.","그래서 약 2 m라고 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_basic#2','math',2,2,'u3','L06','g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',1,'mc','auto','양팔을 벌린 길이는 약 몇 m인가요?',ARRAY['M2-2-u3-X17']::text[],true,'{"seq":2,"concept":"M2-2-u3-C7","difficulty":1,"kind":"mc","stem":"양팔을 벌린 길이는 약 몇 m인가요?","options":[{"t":"약 1 m","correct":true},{"t":"약 10 m","mis":"M2-2-u3-X17"},{"t":"약 1 cm","mis":"M2-2-u3-X17"}],"explanation":["양팔을 쭉 벌린 길이는 1 m쯤이에요.","그래서 1 m를 어림할 때 양팔을 벌려 봐요.","약 1 cm는 손톱 너비, 약 10 m는 교실보다 길어요."],"variant_rule":{"alt":[{"stem":"교실 문의 높이는 약 몇 m인가요?","options":[{"t":"약 2 m","correct":true},{"t":"약 20 m","mis":"M2-2-u3-X17"},{"t":"약 2 cm","mis":"M2-2-u3-X17"}],"explanation":["교실 문은 어른 키보다 조금 높아요.","1 m의 두 배쯤이에요.","그래서 약 2 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_basic#3','math',2,2,'u3','L06','g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',1,'sa','auto','한 칸이 약 1 m인 간격이 3개 있어요. 모두 약 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u3-C7","difficulty":1,"kind":"sa","stem":"한 칸이 약 1 m인 간격이 3개 있어요. 모두 약 몇 m인가요? 숫자로 쓰세요.","explanation":["약 1 m가 3번 있어요.","1 + 1 + 1 = 3이에요.","그래서 모두 약 3 m예요."],"variant_rule":{"mcm":{"ask":"est"}},"answer":["3"],"asset":{"type":"est_row","seg":1,"n":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_basic#4','math',2,2,'u3','L06','g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',1,'ox','auto','어림한 길이는 자로 잰 길이와 반드시 같아야 해요.',ARRAY['M2-2-u3-X12']::text[],true,'{"seq":4,"concept":"M2-2-u3-C7","difficulty":1,"kind":"ox","stem":"어림한 길이는 자로 잰 길이와 반드시 같아야 해요.","answer":"X","reason_options":[{"t":"어림은 짐작한 것이라 잰 길이와 조금 다를 수 있으니까","correct":true},{"t":"어림한 길이가 잰 길이와 다르면 틀린 것이니까","mis":"M2-2-u3-X12"}],"mis":"M2-2-u3-X12","explanation":["어림은 자로 재지 않고 짐작하는 거예요.","그래서 잰 길이와 조금 다를 수 있어요.","어림한 뒤 자로 재어 확인하면 다음엔 더 가깝게 어림해요."],"variant_rule":{"alt":[{"stem":"어림한 길이 앞에는 「약」을 붙여요.","answer":"O","reason_options":[{"t":"자로 재지 않고 짐작한 길이라서","correct":true},{"t":"「약」은 잰 길이 앞에만 붙이니까","mis":"M2-2-u3-X12"}],"explanation":["어림은 짐작한 길이예요.","짐작한 길이에는 「약」을 붙여요.","그래서 「약 1 m」처럼 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_basic#5','math',2,2,'u3','L06','g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',2,'mc','auto','신발장의 길이를 지아는 양팔을 벌린 길이로, 세미는 걸음으로, 슬기는 뼘으로 재었어요. 잰 횟수가 가장 많은 사람은 누구인가요?',ARRAY['M2-2-u3-X13']::text[],true,'{"seq":5,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"신발장의 길이를 지아는 양팔을 벌린 길이로, 세미는 걸음으로, 슬기는 뼘으로 재었어요. 잰 횟수가 가장 많은 사람은 누구인가요?","options":[{"t":"슬기","correct":true},{"t":"지아","mis":"M2-2-u3-X13"},{"t":"모두 같다","mis":"M2-2-u3-X13"}],"explanation":["뼘이 양팔이나 걸음보다 짧아요.","짧은 단위로 재면 더 여러 번 재야 해요.","그래서 뼘으로 잰 슬기의 횟수가 가장 많아요."],"variant_rule":{"alt":[{"stem":"복도의 길이를 도윤이는 걸음으로, 은솔이는 뼘으로 재었어요. 잰 횟수가 더 적은 사람은 누구인가요?","options":[{"t":"도윤","correct":true},{"t":"은솔","mis":"M2-2-u3-X13"},{"t":"둘이 같다","mis":"M2-2-u3-X13"}],"explanation":["걸음이 뼘보다 길어요.","긴 단위로 재면 더 적게 재요.","그래서 걸음으로 잰 도윤이의 횟수가 더 적어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_basic#6','math',2,2,'u3','L06','g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',2,'mc','auto','1 m가 약 3걸음인 친구가 있어요. 이 친구가 약 4 m를 걸으면 몇 걸음쯤일까요?',ARRAY['M2-2-u3-X14','M2-2-u3-X13']::text[],true,'{"seq":6,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"1 m가 약 3걸음인 친구가 있어요. 이 친구가 약 4 m를 걸으면 몇 걸음쯤일까요?","explanation":["1 m가 약 3걸음이에요.","약 4 m는 1 m가 4번이니 3걸음씩 4번 — 3 + 3 + 3 + 3 = 12예요.","그래서 약 12걸음쯤이에요."],"variant_rule":{"mcm":{"ask":"pace"}},"options":[{"t":"약 12걸음","correct":true},{"t":"약 7걸음","mis":"M2-2-u3-X14"},{"t":"약 4걸음","mis":"M2-2-u3-X13"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_basic#7','math',2,2,'u3','L06','g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',2,'match','auto','어림한 길이에 알맞은 잰 길이를 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u3-C7","difficulty":2,"kind":"match","stem":"어림한 길이에 알맞은 잰 길이를 이으세요.","pairs":[{"l":"약 1 m","r":"96 cm"},{"l":"약 2 m","r":"1 m 90 cm"},{"l":"약 3 m","r":"3 m 10 cm"}],"mis":"M2-2-u3-X12","explanation":["96 cm는 1 m에 가까워요.","1 m 90 cm는 2 m에 가까워요.","3 m 10 cm는 3 m에 가까워요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 어림한 길이에 알맞은 잰 길이를 이으세요.","pairs":[{"l":"약 1 m","r":"1 m 2 cm"},{"l":"약 2 m","r":"2 m 10 cm"},{"l":"약 3 m","r":"2 m 80 cm"}],"explanation":["1 m 2 cm는 1 m에 가까워요.","2 m 10 cm는 2 m에 가까워요.","2 m 80 cm는 3 m에 가까워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_basic#8','math',2,2,'u3','L06','g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',2,'mc','auto','칠판의 긴 쪽은 얼마쯤일까요? 알맞게 어림한 것을 고르세요.',ARRAY['M2-2-u3-X17']::text[],true,'{"seq":8,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"칠판의 긴 쪽은 얼마쯤일까요? 알맞게 어림한 것을 고르세요.","options":[{"t":"약 3 m","correct":true},{"t":"약 3 cm","mis":"M2-2-u3-X17"},{"t":"약 30 m","mis":"M2-2-u3-X17"}],"explanation":["칠판의 긴 쪽은 양팔을 세 번쯤 벌린 길이예요.","1 m가 세 번쯤이니 약 3 m예요.","약 3 cm는 너무 짧고, 약 30 m는 너무 길어요."],"variant_rule":{"alt":[{"stem":"교실 책상의 긴 쪽은 얼마쯤일까요? 알맞게 어림한 것을 고르세요.","options":[{"t":"약 60 cm","correct":true},{"t":"약 6 m","mis":"M2-2-u3-X17"},{"t":"약 6 cm","mis":"M2-2-u3-X17"}],"explanation":["책상의 긴 쪽은 양팔을 벌린 길이보다 짧아요.","1 m보다 짧으니 cm로 어림해요.","약 60 cm가 알맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_basic#9','math',2,2,'u3','L06','g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',2,'mc','auto','한 칸이 약 1 m인 간격이 4개 있어요. 모두 약 몇 m인가요?',ARRAY['M2-2-u3-X14','M2-2-u3-X15']::text[],true,'{"seq":9,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"한 칸이 약 1 m인 간격이 4개 있어요. 모두 약 몇 m인가요?","explanation":["약 1 m가 4번 있어요.","1 + 1 + 1 + 1 = 4예요.","그래서 모두 약 4 m예요."],"variant_rule":{"mcm":{"ask":"est"}},"options":[{"t":"약 4 m","correct":true},{"t":"약 5 m","mis":"M2-2-u3-X14"},{"t":"약 3 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":1,"n":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_basic#10','math',2,2,'u3','L06','g2_2_math_u3_L06_basic','lesson_basic','M2-2-u3-C7',3,'error','auto','1 m를 걸음으로 재어 보았어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u3-X13','M2-2-u3-X16']::text[],true,'{"seq":10,"concept":"M2-2-u3-C7","difficulty":3,"kind":"error","stem":"1 m를 걸음으로 재어 보았어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「나는 2걸음이니까 세미도 꼭 2걸음일 거야.」","correct":true,"mis_target":"M2-2-u3-X13"},{"t":"세미 — 「나는 3걸음이야. 사람마다 다를 수 있어.」","mis":"M2-2-u3-X16"},{"t":"슬기 — 「잴 때마다 걸음의 크기를 같게 해야 해.」","mis":"M2-2-u3-X16"}],"explanation":["사람마다 걸음의 크기가 달라요.","그래서 같은 1 m도 잰 걸음 수가 다를 수 있어요.","지아의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"1 m를 뼘으로 재어 보았어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「누가 재어도 1 m는 꼭 7뼘이야.」","correct":true,"mis_target":"M2-2-u3-X13"},{"t":"곰이 — 「손이 큰 사람은 뼘 수가 적을 거야.」","mis":"M2-2-u3-X16"},{"t":"펭이 — 「잴 때마다 뼘을 똑같이 벌려야 해.」","mis":"M2-2-u3-X16"}],"explanation":["사람마다 뼘의 크기가 달라요.","손이 크면 뼘 수가 적어요.","하람이의 말이 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_challenge#1','math',2,2,'u3','L06','g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',2,'mc','auto','1 m가 약 2걸음인 친구가 있어요. 이 친구가 약 5 m를 걸으면 몇 걸음쯤일까요?',ARRAY['M2-2-u3-X14','M2-2-u3-X13']::text[],true,'{"seq":1,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"1 m가 약 2걸음인 친구가 있어요. 이 친구가 약 5 m를 걸으면 몇 걸음쯤일까요?","explanation":["1 m가 약 2걸음이에요.","약 5 m는 1 m가 5번이니 2걸음씩 5번 — 2 + 2 + 2 + 2 + 2 = 10이에요.","그래서 약 10걸음쯤이에요."],"variant_rule":{"mcm":{"ask":"pace"}},"options":[{"t":"약 10걸음","correct":true},{"t":"약 7걸음","mis":"M2-2-u3-X14"},{"t":"약 5걸음","mis":"M2-2-u3-X13"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_challenge#2','math',2,2,'u3','L06','g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',2,'mc','auto','1 m가 뼘으로 약 7번이에요. 약 2 m는 뼘으로 약 몇 번일까요?',ARRAY['M2-2-u3-X14']::text[],false,'{"seq":2,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"1 m가 뼘으로 약 7번이에요. 약 2 m는 뼘으로 약 몇 번일까요?","options":[{"t":"약 14번","correct":true},{"t":"약 9번","mis":"M2-2-u3-X14"},{"t":"약 7번","mis":"M2-2-u3-X14"}],"explanation":["약 2 m는 1 m가 두 번이에요.","7번씩 두 번이니 7 + 7 = 14예요.","그래서 약 14번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_challenge#3','math',2,2,'u3','L06','g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',3,'mc','auto','끈을 약 2 m로 어림하고 자로 재어 보니 1 m 90 cm였어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u3-X12','M2-2-u3-X18']::text[],false,'{"seq":3,"concept":"M2-2-u3-C7","difficulty":3,"kind":"mc","stem":"끈을 약 2 m로 어림하고 자로 재어 보니 1 m 90 cm였어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"어림한 길이와 잰 길이가 10 cm 차이 나요","correct":true},{"t":"어림한 길이가 잰 길이와 다르니 잘못 어림했어요","mis":"M2-2-u3-X12"},{"t":"1 m 90 cm는 2 m보다 길어요","mis":"M2-2-u3-X18"}],"explanation":["2 m는 200 cm, 1 m 90 cm는 190 cm예요.","200 − 190 = 10이니 10 cm 차이예요.","어림은 짐작이라 조금 달라도 괜찮아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_challenge#4','math',2,2,'u3','L06','g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',3,'mc','auto','세 사람이 칠판의 긴 쪽을 어림했어요. 가는 약 2 m, 나는 약 3 m, 다는 약 4 m라고 했어요. 자로 재어 보니 2 m 80 cm였어요. 가장 가깝게 어림한 사람은 누구인가요?',ARRAY['M2-2-u3-X18','M2-2-u3-X14']::text[],false,'{"seq":4,"concept":"M2-2-u3-C7","difficulty":3,"kind":"mc","stem":"세 사람이 칠판의 긴 쪽을 어림했어요. 가는 약 2 m, 나는 약 3 m, 다는 약 4 m라고 했어요. 자로 재어 보니 2 m 80 cm였어요. 가장 가깝게 어림한 사람은 누구인가요?","options":[{"t":"나","correct":true},{"t":"가","mis":"M2-2-u3-X18"},{"t":"다","mis":"M2-2-u3-X14"}],"explanation":["2 m 80 cm는 280 cm예요.","약 3 m(300 cm)는 20 cm, 약 2 m(200 cm)는 80 cm 차이예요.","그래서 나가 가장 가깝게 어림했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_challenge#5','math',2,2,'u3','L06','g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',3,'ox','auto','키가 다른 두 친구가 같은 길이를 걸음으로 재면 걸음 수가 다를 수 있어요.',ARRAY['M2-2-u3-X13']::text[],false,'{"seq":5,"concept":"M2-2-u3-C7","difficulty":3,"kind":"ox","stem":"키가 다른 두 친구가 같은 길이를 걸음으로 재면 걸음 수가 다를 수 있어요.","answer":"O","reason_options":[{"t":"걸음의 크기가 사람마다 다르니까","correct":true},{"t":"같은 길이면 누가 재도 걸음 수가 같으니까","mis":"M2-2-u3-X13"}],"mis":"M2-2-u3-X13","explanation":["걸음의 크기는 사람마다 달라요.","큰 걸음은 적게, 작은 걸음은 많이 걸어요.","그래서 걸음 수가 다를 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_challenge#6','math',2,2,'u3','L06','g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',3,'mc','auto','알맞게 어림한 것은 어느 것인가요?',ARRAY['M2-2-u3-X17']::text[],false,'{"seq":6,"concept":"M2-2-u3-C7","difficulty":3,"kind":"mc","stem":"알맞게 어림한 것은 어느 것인가요?","options":[{"t":"교실 문의 높이 — 약 2 m","correct":true},{"t":"필통의 길이 — 약 2 m","mis":"M2-2-u3-X17"},{"t":"운동장의 긴 쪽 — 약 2 m","mis":"M2-2-u3-X17"},{"t":"수학책의 긴 쪽 — 약 2 m","mis":"M2-2-u3-X17"}],"explanation":["약 2 m는 양팔을 두 번 벌린 길이쯤이에요.","필통·수학책은 훨씬 짧고, 운동장은 훨씬 길어요.","교실 문의 높이가 약 2 m에 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_challenge#7','math',2,2,'u3','L06','g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',3,'sa','auto','1 m가 약 3걸음인 친구가 있어요. 이 친구가 약 6 m를 걸으면 몇 걸음쯤일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u3-C7","difficulty":3,"kind":"sa","stem":"1 m가 약 3걸음인 친구가 있어요. 이 친구가 약 6 m를 걸으면 몇 걸음쯤일까요? 숫자로 쓰세요.","explanation":["1 m가 약 3걸음이에요.","약 6 m는 1 m가 6번이니 3걸음씩 6번 — 3 + 3 + 3 + 3 + 3 + 3 = 18이에요.","그래서 약 18걸음쯤이에요."],"variant_rule":{"mcm":{"ask":"pace"}},"answer":["18"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_challenge#8','math',2,2,'u3','L06','g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',4,'essay','teacher','1 m를 기준 삼아 교실 칠판의 긴 쪽 길이를 어림하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u3-C7","difficulty":4,"kind":"essay","stem":"1 m를 기준 삼아 교실 칠판의 긴 쪽 길이를 어림하는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 양팔을 벌린 길이가 약 1 m이다. 칠판 끝에서부터 양팔을 벌려 몇 번쯤 되는지 본다. 세 번쯤이면 약 3 m로 어림하고, 줄자로 재어 확인한다.","scoring_points":["1 m를 몸의 부분 등으로 정했는가","1 m가 몇 번쯤인지 보고 어림한다고 썼는가","「약」을 붙이거나 자로 재어 확인한다고 썼는가"]},"explanation":["1 m가 얼마쯤인지 몸으로 먼저 알아 둬요.","1 m가 몇 번쯤인지 보면 길이를 어림할 수 있어요.","어림한 뒤 자로 재어 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_challenge#9','math',2,2,'u3','L06','g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',4,'essay','teacher','지아는 1 m가 두 걸음, 세미는 세 걸음이에요. 두 사람이 같은 복도를 걸음으로 재면 누구의 걸음 수가 더 많을지 쓰고, 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u3-C7","difficulty":4,"kind":"essay","stem":"지아는 1 m가 두 걸음, 세미는 세 걸음이에요. 두 사람이 같은 복도를 걸음으로 재면 누구의 걸음 수가 더 많을지 쓰고, 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 세미의 걸음 수가 더 많다. 세미는 1 m를 세 걸음에 가므로 걸음이 지아보다 작다. 작은 단위로 재면 더 여러 번 재야 한다.","scoring_points":["세미라고 답했는가","세미의 걸음이 더 작다고 썼는가","작은 단위로 재면 횟수가 많아진다고 썼는가"]},"explanation":["1 m를 지아는 2걸음, 세미는 3걸음에 가요.","세미의 한 걸음이 더 작아요.","작은 걸음으로 재면 걸음 수가 더 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L06_challenge#10','math',2,2,'u3','L06','g2_2_math_u3_L06_challenge','lesson_challenge','M2-2-u3-C7',4,'mc','auto','바다악어의 몸길이는 약 3 m예요. 양팔을 벌린 길이가 약 1 m인 친구 몇 명이 팔을 벌리고 나란히 서면 바다악어의 몸길이와 비슷할까요?',ARRAY['M2-2-u3-X14','M2-2-u3-X01']::text[],false,'{"seq":10,"concept":"M2-2-u3-C7","difficulty":4,"kind":"mc","stem":"바다악어의 몸길이는 약 3 m예요. 양팔을 벌린 길이가 약 1 m인 친구 몇 명이 팔을 벌리고 나란히 서면 바다악어의 몸길이와 비슷할까요?","options":[{"t":"약 3명","correct":true},{"t":"약 1명","mis":"M2-2-u3-X14"},{"t":"약 30명","mis":"M2-2-u3-X01"}],"explanation":["친구 한 명이 약 1 m예요.","약 3 m는 1 m가 세 번이에요.","그래서 약 3명이 나란히 서면 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_basic#1','math',2,2,'u3','L07','g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',1,'mc','auto','축구 골대의 긴 쪽은 약 5 m예요. 약 5 m의 두 배쯤은 약 몇 m인가요?',ARRAY['M2-2-u3-X14']::text[],true,'{"seq":1,"concept":"M2-2-u3-C8","difficulty":1,"kind":"mc","stem":"축구 골대의 긴 쪽은 약 5 m예요. 약 5 m의 두 배쯤은 약 몇 m인가요?","options":[{"t":"약 10 m","correct":true},{"t":"약 7 m","mis":"M2-2-u3-X14"},{"t":"약 5 m","mis":"M2-2-u3-X14"}],"explanation":["두 배쯤은 같은 길이가 두 번이에요.","5 + 5 = 10이에요.","그래서 약 10 m예요."],"variant_rule":{"alt":[{"stem":"그네의 길이는 약 4 m예요. 약 4 m의 두 배쯤은 약 몇 m인가요?","options":[{"t":"약 8 m","correct":true},{"t":"약 6 m","mis":"M2-2-u3-X14"},{"t":"약 4 m","mis":"M2-2-u3-X14"}],"explanation":["두 배쯤은 같은 길이가 두 번이에요.","4 + 4 = 8이에요.","그래서 약 8 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_basic#2','math',2,2,'u3','L07','g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',1,'sa','auto','한 칸이 약 2 m인 간격이 5개 있어요. 모두 약 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u3-C8","difficulty":1,"kind":"sa","stem":"한 칸이 약 2 m인 간격이 5개 있어요. 모두 약 몇 m인가요? 숫자로 쓰세요.","explanation":["약 2 m가 5번 있어요.","2 + 2 + 2 + 2 + 2 = 10이에요.","그래서 모두 약 10 m예요."],"variant_rule":{"mcm":{"ask":"est"}},"answer":["10"],"asset":{"type":"est_row","seg":2,"n":5}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_basic#3','math',2,2,'u3','L07','g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',1,'mc','auto','운동장의 짧은 쪽을 끝~골대 약 10 m, 골대 약 5 m, 골대~끝 약 10 m로 나누어 어림했어요. 모두 약 몇 m인가요?',ARRAY['M2-2-u3-X14']::text[],true,'{"seq":3,"concept":"M2-2-u3-C8","difficulty":1,"kind":"mc","stem":"운동장의 짧은 쪽을 끝~골대 약 10 m, 골대 약 5 m, 골대~끝 약 10 m로 나누어 어림했어요. 모두 약 몇 m인가요?","options":[{"t":"약 25 m","correct":true},{"t":"약 20 m","mis":"M2-2-u3-X14"},{"t":"약 15 m","mis":"M2-2-u3-X14"}],"explanation":["나누어 어림한 길이를 모두 더해요.","10 + 5 + 10 = 25예요.","그래서 약 25 m예요."],"variant_rule":{"alt":[{"stem":"복도를 계단~교실 약 8 m, 교실 앞 약 6 m, 교실~도서관 약 8 m로 나누어 어림했어요. 모두 약 몇 m인가요?","options":[{"t":"약 22 m","correct":true},{"t":"약 16 m","mis":"M2-2-u3-X14"},{"t":"약 14 m","mis":"M2-2-u3-X14"}],"explanation":["나누어 어림한 길이를 모두 더해요.","8 + 6 + 8 = 22예요.","그래서 약 22 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_basic#4','math',2,2,'u3','L07','g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',1,'ox','auto','긴 거리는 몇 부분으로 나누어 어림한 뒤 모두 더할 수 있어요.',ARRAY['M2-2-u3-X14']::text[],true,'{"seq":4,"concept":"M2-2-u3-C8","difficulty":1,"kind":"ox","stem":"긴 거리는 몇 부분으로 나누어 어림한 뒤 모두 더할 수 있어요.","answer":"O","reason_options":[{"t":"부분마다 어림한 길이를 더하면 전체 길이가 되니까","correct":true},{"t":"긴 거리는 한 번에 눈으로 보고 정해야만 하니까","mis":"M2-2-u3-X14"}],"mis":"M2-2-u3-X14","explanation":["긴 거리는 한 번에 짐작하기 어려워요.","몇 부분으로 나누면 부분마다 어림하기 쉬워요.","부분의 길이를 모두 더하면 전체 길이예요."],"variant_rule":{"alt":[{"stem":"이미 어림한 5 m를 기준 삼으면 10 m도 어림할 수 있어요.","answer":"O","reason_options":[{"t":"5 m가 두 번쯤이면 약 10 m니까","correct":true},{"t":"5 m와 10 m는 서로 관계가 없으니까","mis":"M2-2-u3-X14"}],"explanation":["5 m를 알고 있으면 기준으로 쓸 수 있어요.","5 m가 두 번쯤이면 약 10 m예요.","그래서 바른 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_basic#5','math',2,2,'u3','L07','g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',2,'mc','auto','학생 5명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?',ARRAY['M2-2-u3-X15']::text[],true,'{"seq":5,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"학생 5명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?","explanation":["학생이 5명이면 사이 간격은 4개예요.","약 1 m씩 4번이니 약 4 m예요.","사람 수만큼 5번 더하면 안 돼요 — 간격을 세어요."],"variant_rule":{"mcm":{"ask":"est","people":true}},"options":[{"t":"약 4 m","correct":true},{"t":"약 5 m","mis":"M2-2-u3-X15"},{"t":"약 6 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":1,"n":5,"people":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_basic#6','math',2,2,'u3','L07','g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',2,'mc','auto','한 칸이 약 5 m인 간격이 3개 있어요. 모두 약 몇 m인가요?',ARRAY['M2-2-u3-X14','M2-2-u3-X15']::text[],true,'{"seq":6,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"한 칸이 약 5 m인 간격이 3개 있어요. 모두 약 몇 m인가요?","explanation":["약 5 m가 3번 있어요.","5 + 5 + 5 = 15예요.","그래서 모두 약 15 m예요."],"variant_rule":{"mcm":{"ask":"est"}},"options":[{"t":"약 15 m","correct":true},{"t":"약 8 m","mis":"M2-2-u3-X14"},{"t":"약 10 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":5,"n":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_basic#7','math',2,2,'u3','L07','g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',2,'match','auto','어림한 거리에 알맞은 곳을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u3-C8","difficulty":2,"kind":"match","stem":"어림한 거리에 알맞은 곳을 이으세요.","pairs":[{"l":"약 1 m","r":"교실 문의 짧은 쪽"},{"l":"약 5 m","r":"축구 골대의 긴 쪽"},{"l":"약 25 m","r":"운동장의 짧은 쪽"}],"mis":"M2-2-u3-X17","explanation":["교실 문의 짧은 쪽은 양팔 벌린 길이쯤 — 약 1 m예요.","축구 골대의 긴 쪽은 약 5 m예요.","운동장의 짧은 쪽은 약 25 m예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 어림한 거리에 알맞은 곳을 이으세요.","pairs":[{"l":"약 2 m","r":"교실 문의 높이"},{"l":"약 10 m","r":"교실 두 칸의 길이"},{"l":"약 50 m","r":"운동장의 긴 쪽"}],"explanation":["교실 문의 높이는 약 2 m예요.","교실 한 칸이 약 5 m라 두 칸은 약 10 m예요.","운동장의 긴 쪽은 약 50 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_basic#8','math',2,2,'u3','L07','g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',2,'mc','auto','울타리 한 칸은 약 2 m예요. 나무에서 그네까지 울타리가 세 칸이에요. 나무에서 그네까지는 약 몇 m인가요?',ARRAY['M2-2-u3-X14']::text[],true,'{"seq":8,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"울타리 한 칸은 약 2 m예요. 나무에서 그네까지 울타리가 세 칸이에요. 나무에서 그네까지는 약 몇 m인가요?","options":[{"t":"약 6 m","correct":true},{"t":"약 5 m","mis":"M2-2-u3-X14"},{"t":"약 3 m","mis":"M2-2-u3-X14"}],"explanation":["울타리 한 칸이 약 2 m예요.","세 칸이니 2 + 2 + 2 = 6이에요.","그래서 약 6 m예요."],"variant_rule":{"alt":[{"stem":"화단 한 칸은 약 3 m예요. 정문에서 놀이터까지 화단이 네 칸이에요. 정문에서 놀이터까지는 약 몇 m인가요?","options":[{"t":"약 12 m","correct":true},{"t":"약 7 m","mis":"M2-2-u3-X14"},{"t":"약 4 m","mis":"M2-2-u3-X14"}],"explanation":["화단 한 칸이 약 3 m예요.","네 칸이니 3 + 3 + 3 + 3 = 12예요.","그래서 약 12 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_basic#9','math',2,2,'u3','L07','g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',2,'mc','auto','학생 4명이 앞 사람과 약 2 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?',ARRAY['M2-2-u3-X15']::text[],true,'{"seq":9,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"학생 4명이 앞 사람과 약 2 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?","explanation":["학생이 4명이면 사이 간격은 3개예요.","약 2 m씩 3번이니 약 6 m예요.","사람 수만큼 4번 더하면 안 돼요 — 간격을 세어요."],"variant_rule":{"mcm":{"ask":"est","people":true}},"options":[{"t":"약 6 m","correct":true},{"t":"약 8 m","mis":"M2-2-u3-X15"},{"t":"약 10 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":2,"n":4,"people":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_basic#10','math',2,2,'u3','L07','g2_2_math_u3_L07_basic','lesson_basic','M2-2-u3-C8',3,'mc','auto','운동장의 짧은 쪽을 나누어 어림해 약 25 m로 정했고, 자로 재어 보니 24 m였어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u3-X12']::text[],true,'{"seq":10,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"운동장의 짧은 쪽을 나누어 어림해 약 25 m로 정했고, 자로 재어 보니 24 m였어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"나누어 어림해서 잰 길이에 가깝게 어림했어요","correct":true},{"t":"어림한 값과 잰 값이 달라서 잘못 어림했어요","mis":"M2-2-u3-X12"},{"t":"어림한 값에 「약」을 붙여서 틀렸어요","mis":"M2-2-u3-X12"}],"explanation":["약 25 m와 24 m는 1 m 차이예요.","긴 거리에서 1 m 차이면 아주 가깝게 어림한 거예요.","나누어 어림하면 더 가깝게 어림할 수 있어요."],"variant_rule":{"alt":[{"stem":"복도를 약 2 m 간격의 기둥을 세어 약 20 m로 어림했고, 자로 재어 보니 21 m였어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"간격을 세어 잰 길이에 가깝게 어림했어요","correct":true},{"t":"어림한 값과 잰 값이 달라서 잘못 어림했어요","mis":"M2-2-u3-X12"},{"t":"어림한 값에 「약」을 붙여서 틀렸어요","mis":"M2-2-u3-X12"}],"explanation":["약 20 m와 21 m는 1 m 차이예요.","긴 거리에서 1 m 차이면 아주 가깝게 어림한 거예요.","같은 간격을 세면 더 가깝게 어림할 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_challenge#1','math',2,2,'u3','L07','g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',2,'mc','auto','학생 8명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?',ARRAY['M2-2-u3-X15']::text[],true,'{"seq":1,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"학생 8명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?","explanation":["학생이 8명이면 사이 간격은 7개예요.","약 1 m씩 7번이니 약 7 m예요.","사람 수만큼 8번 더하면 안 돼요 — 간격을 세어요."],"variant_rule":{"mcm":{"ask":"est","people":true}},"options":[{"t":"약 7 m","correct":true},{"t":"약 8 m","mis":"M2-2-u3-X15"},{"t":"약 9 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":1,"n":8,"people":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_challenge#2','math',2,2,'u3','L07','g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',2,'mc','auto','한 칸이 약 3 m인 간격이 4개 있어요. 모두 약 몇 m인가요?',ARRAY['M2-2-u3-X14','M2-2-u3-X15']::text[],true,'{"seq":2,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"한 칸이 약 3 m인 간격이 4개 있어요. 모두 약 몇 m인가요?","explanation":["약 3 m가 4번 있어요.","3 + 3 + 3 + 3 = 12예요.","그래서 모두 약 12 m예요."],"variant_rule":{"mcm":{"ask":"est"}},"options":[{"t":"약 12 m","correct":true},{"t":"약 7 m","mis":"M2-2-u3-X14"},{"t":"약 9 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":3,"n":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_challenge#3','math',2,2,'u3','L07','g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',3,'mc','auto','복도에 화분 6개가 약 2 m 간격으로 한 줄로 놓여 있어요. 첫 화분부터 마지막 화분까지는 약 몇 m인가요?',ARRAY['M2-2-u3-X15','M2-2-u3-X14']::text[],false,'{"seq":3,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"복도에 화분 6개가 약 2 m 간격으로 한 줄로 놓여 있어요. 첫 화분부터 마지막 화분까지는 약 몇 m인가요?","options":[{"t":"약 10 m","correct":true},{"t":"약 12 m","mis":"M2-2-u3-X15"},{"t":"약 8 m","mis":"M2-2-u3-X14"}],"explanation":["화분이 6개면 사이 간격은 5개예요.","약 2 m씩 5번이니 약 10 m예요.","화분 수만큼 6번 더하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_challenge#4','math',2,2,'u3','L07','g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',3,'mc','auto','정문~현관 약 20 m, 현관~교실 약 15 m, 교실~과학실 약 10 m예요. 정문에서 교실을 지나 과학실까지는 약 몇 m인가요?',ARRAY['M2-2-u3-X14']::text[],false,'{"seq":4,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"정문~현관 약 20 m, 현관~교실 약 15 m, 교실~과학실 약 10 m예요. 정문에서 교실을 지나 과학실까지는 약 몇 m인가요?","options":[{"t":"약 45 m","correct":true},{"t":"약 35 m","mis":"M2-2-u3-X14"},{"t":"약 30 m","mis":"M2-2-u3-X14"}],"explanation":["나누어 어림한 세 부분을 모두 더해요.","20 + 15 + 10 = 45예요.","그래서 약 45 m예요 — 두 부분만 더하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_challenge#5','math',2,2,'u3','L07','g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',3,'mc','auto','축구 골대의 긴 쪽은 약 5 m예요. 운동장의 긴 쪽에 골대를 8개 나란히 이어 놓을 수 있다면 운동장의 긴 쪽은 약 몇 m인가요?',ARRAY['M2-2-u3-X14','M2-2-u3-X15']::text[],false,'{"seq":5,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"축구 골대의 긴 쪽은 약 5 m예요. 운동장의 긴 쪽에 골대를 8개 나란히 이어 놓을 수 있다면 운동장의 긴 쪽은 약 몇 m인가요?","options":[{"t":"약 40 m","correct":true},{"t":"약 13 m","mis":"M2-2-u3-X14"},{"t":"약 35 m","mis":"M2-2-u3-X15"}],"explanation":["약 5 m가 8번이에요.","5씩 8번 더하면 40이에요.","그래서 약 40 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_challenge#6','math',2,2,'u3','L07','g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',3,'error','auto','학생 6명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞과 맨 뒤 학생 사이의 거리를 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u3-X15','M2-2-u3-X16']::text[],false,'{"seq":6,"concept":"M2-2-u3-C8","difficulty":3,"kind":"error","stem":"학생 6명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞과 맨 뒤 학생 사이의 거리를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"곰이 — 「6명이니까 약 6 m야.」","correct":true,"mis_target":"M2-2-u3-X15"},{"t":"펭이 — 「사이 간격이 5개니까 약 5 m야.」","mis":"M2-2-u3-X16"},{"t":"다예 — 「약 1 m씩 다섯 번이니 약 5 m야.」","mis":"M2-2-u3-X16"}],"explanation":["6명 사이의 간격은 5개예요.","약 1 m씩 5번이니 약 5 m예요.","곰이는 사람 수와 간격 수를 같다고 보았어요."],"asset":{"type":"est_row","seg":1,"n":6,"people":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_challenge#7','math',2,2,'u3','L07','g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',3,'mc','auto','같은 간격이 몇 개인지 세어 긴 거리를 어림하는 방법은 어느 것인가요?',ARRAY['M2-2-u3-X16']::text[],false,'{"seq":7,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"같은 간격이 몇 개인지 세어 긴 거리를 어림하는 방법은 어느 것인가요?","options":[{"t":"약 2 m 간격의 거리 표시가 몇 개인지 세어요","correct":true},{"t":"1 m를 기준 삼아 몇 번쯤인지 봐요","mis":"M2-2-u3-X16"},{"t":"몇 부분으로 나누어 어림한 뒤 더해요","mis":"M2-2-u3-X16"}],"explanation":["세어 어림은 같은 간격이 몇 개인지 세는 방법이에요.","약 2 m 간격이 5개면 약 10 m예요.","기준 삼아 어림·나누어 어림과는 다른 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_challenge#8','math',2,2,'u3','L07','g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',4,'essay','teacher','운동장의 짧은 쪽 길이를 어림하는 방법을 두 가지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u3-C8","difficulty":4,"kind":"essay","stem":"운동장의 짧은 쪽 길이를 어림하는 방법을 두 가지 설명해 보세요.","answer_guide":{"answer":"예: 축구 골대의 긴 쪽 약 5 m를 기준 삼아 몇 번쯤인지 본다. 끝~골대, 골대, 골대~끝으로 나누어 부분마다 어림한 뒤 모두 더한다.","scoring_points":["기준 삼아 어림하는 방법을 썼는가","나누어 어림하거나 세어 어림하는 방법을 썼는가","어림한 길이에 「약」을 붙이거나 자로 확인한다고 썼는가"]},"explanation":["아는 길이(5 m)를 기준 삼아 몇 번쯤인지 봐요.","몇 부분으로 나누어 어림하고 더해요.","같은 간격이 몇 개인지 세어 어림해도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_challenge#9','math',2,2,'u3','L07','g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',4,'essay','teacher','학생 8명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞과 맨 뒤 학생 사이의 거리를 구하고, 약 8 m가 아닌 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u3-C8","difficulty":4,"kind":"essay","stem":"학생 8명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞과 맨 뒤 학생 사이의 거리를 구하고, 약 8 m가 아닌 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 8명 사이의 간격은 7개이다. 약 1 m씩 7번이므로 약 7 m이다. 맨 앞 학생 앞에는 간격이 없어서 간격의 수가 사람 수보다 하나 적다.","scoring_points":["간격이 7개라고 썼는가","약 7 m라고 구했는가","간격 수가 사람 수보다 하나 적은 까닭을 썼는가"]},"explanation":["8명 사이의 간격을 세어요.","간격은 7개라 약 7 m예요.","사람 수와 간격 수는 달라요."],"asset":{"type":"est_row","seg":1,"n":8,"people":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_L07_challenge#10','math',2,2,'u3','L07','g2_2_math_u3_L07_challenge','lesson_challenge','M2-2-u3-C8',4,'mc','auto','약 25 m인 운동장의 짧은 쪽을 따라 약 5 m마다 깃발을 꽂아요. 처음과 끝에도 꽂으면 깃발은 몇 개 필요한가요?',ARRAY['M2-2-u3-X15']::text[],false,'{"seq":10,"concept":"M2-2-u3-C8","difficulty":4,"kind":"mc","stem":"약 25 m인 운동장의 짧은 쪽을 따라 약 5 m마다 깃발을 꽂아요. 처음과 끝에도 꽂으면 깃발은 몇 개 필요한가요?","options":[{"t":"6개","correct":true},{"t":"5개","mis":"M2-2-u3-X15"},{"t":"4개","mis":"M2-2-u3-X15"}],"explanation":["약 25 m에 약 5 m 간격은 5개예요.","처음과 끝에도 꽂으면 깃발은 간격보다 하나 많아요.","그래서 5 + 1 = 6개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#1','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C1',1,'sa','auto','200 cm는 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u3-C1","difficulty":1,"kind":"sa","stem":"200 cm는 몇 m인가요? 숫자로 쓰세요.","explanation":["100 cm는 1 m예요.","200 cm는 100 cm가 2번이에요.","그래서 200 cm = 2 m예요."],"variant_rule":{"mcm":{"ask":"m100","form":"tom"}},"answer":["2"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#2','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C1',1,'mc','auto','3 m는 몇 cm인가요?',ARRAY['M2-2-u3-X01']::text[],true,'{"seq":2,"concept":"M2-2-u3-C1","difficulty":1,"kind":"mc","stem":"3 m는 몇 cm인가요?","explanation":["1 m는 100 cm예요.","3 m는 100 cm가 3번이에요.","그래서 3 m = 300 cm예요."],"variant_rule":{"mcm":{"ask":"m100","form":"tocm"}},"options":[{"t":"300 cm","correct":true},{"t":"30 cm","mis":"M2-2-u3-X01"},{"t":"3000 cm","mis":"M2-2-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#3','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C2',1,'sa','auto','1 m 45 cm는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u3-C2","difficulty":1,"kind":"sa","stem":"1 m 45 cm는 몇 cm인가요? 숫자로 쓰세요.","explanation":["1 m는 100 cm예요.","100 cm와 45 cm를 모으면 145 cm예요.","m를 100 cm씩으로 바꾸어 cm와 모아요."],"variant_rule":{"mcm":{"ask":"tocm"}},"answer":["145"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#4','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C4',1,'sa','auto','책장의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M2-2-u3-C4","difficulty":1,"kind":"sa","stem":"책장의 길이는 몇 cm인가요? 숫자로 쓰세요.","explanation":["책장의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 127이니 127 cm예요.","127 cm는 1 m 27 cm라고도 나타내요."],"variant_rule":{"mcm":{"ask":"read"}},"answer":["127"],"asset":{"type":"tape","len":127,"label":"책장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#5','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C5',1,'mc','auto','3 m 25 cm + 1 m 30 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":5,"concept":"M2-2-u3-C5","difficulty":1,"kind":"mc","stem":"3 m 25 cm + 1 m 30 cm는 얼마인가요?","explanation":["m는 m끼리 더해요 — 3 + 1 = 4.","cm는 cm끼리 더해요 — 25 + 30 = 55.","그래서 3 m 25 cm + 1 m 30 cm = 4 m 55 cm예요."],"variant_rule":{"mcm":{"ask":"add"}},"options":[{"t":"4 m 55 cm","correct":true},{"t":"2 m 5 cm","mis":"M2-2-u3-X10"},{"t":"5 m 55 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#6','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C6',1,'mc','auto','4 m 58 cm − 2 m 25 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":6,"concept":"M2-2-u3-C6","difficulty":1,"kind":"mc","stem":"4 m 58 cm − 2 m 25 cm는 얼마인가요?","explanation":["m는 m끼리 빼요 — 4 − 2 = 2.","cm는 cm끼리 빼요 — 58 − 25 = 33.","그래서 4 m 58 cm − 2 m 25 cm = 2 m 33 cm예요."],"variant_rule":{"mcm":{"ask":"sub"}},"options":[{"t":"2 m 33 cm","correct":true},{"t":"6 m 83 cm","mis":"M2-2-u3-X10"},{"t":"3 m 33 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#7','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C7',1,'mc','auto','자로 재지 않고 칠판의 긴 쪽을 3 m쯤으로 짐작했어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u3-X12','M2-2-u3-X17']::text[],false,'{"seq":7,"concept":"M2-2-u3-C7","difficulty":1,"kind":"mc","stem":"자로 재지 않고 칠판의 긴 쪽을 3 m쯤으로 짐작했어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"약 3 m","correct":true},{"t":"3 m","mis":"M2-2-u3-X12"},{"t":"약 3 cm","mis":"M2-2-u3-X17"}],"explanation":["자로 재지 않고 짐작한 것은 어림이에요.","어림한 길이 앞에는 「약」을 붙여요.","그래서 약 3 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#8','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C3',1,'mc','auto','연필의 길이는 약 17 ▢예요. ▢에 알맞은 단위는 무엇인가요?',ARRAY['M2-2-u3-X05']::text[],false,'{"seq":8,"concept":"M2-2-u3-C3","difficulty":1,"kind":"mc","stem":"연필의 길이는 약 17 ▢예요. ▢에 알맞은 단위는 무엇인가요?","options":[{"t":"cm","correct":true},{"t":"m","mis":"M2-2-u3-X05"}],"explanation":["연필은 손에 쥘 만큼 짧아요.","약 17 m는 교실보다 길어요.","그래서 약 17 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#9','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C2',2,'mc','auto','248 cm를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X11','M2-2-u3-X02']::text[],true,'{"seq":9,"concept":"M2-2-u3-C2","difficulty":2,"kind":"mc","stem":"248 cm를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["248 cm는 200 cm와 48 cm예요.","200 cm는 2 m예요.","그래서 248 cm = 2 m 48 cm예요."],"variant_rule":{"mcm":{"ask":"tomcm"}},"options":[{"t":"2 m 48 cm","correct":true},{"t":"24 m 8 cm","mis":"M2-2-u3-X03"},{"t":"2 m 4 cm","mis":"M2-2-u3-X11"},{"t":"48 m 2 cm","mis":"M2-2-u3-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#10','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C4',2,'mc','auto','책장의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X07']::text[],true,'{"seq":10,"concept":"M2-2-u3-C4","difficulty":2,"kind":"mc","stem":"책장의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["책장의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 130이니 130 cm예요.","130 cm = 100 cm + 30 cm = 1 m 30 cm예요."],"variant_rule":{"mcm":{"ask":"read","form":"mcm"}},"options":[{"t":"1 m 30 cm","correct":true},{"t":"13 m","mis":"M2-2-u3-X03"},{"t":"1 m 31 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":130,"label":"책장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#11','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C5',2,'mc','auto','세로셈을 계산하면 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":11,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"세로셈을 계산하면 얼마인가요?","explanation":["m는 m끼리 더해요 — 5 + 3 = 8.","cm는 cm끼리 더해요 — 24 + 51 = 75.","그래서 5 m 24 cm + 3 m 51 cm = 8 m 75 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"calc"}},"options":[{"t":"8 m 75 cm","correct":true},{"t":"2 m 27 cm","mis":"M2-2-u3-X10"},{"t":"9 m 75 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mcm_calc","a":[5,24],"b":[3,51],"op":"+","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#12','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C6',2,'mc','auto','4 m 86 cm인 색 테이프에서 2 m 53 cm를 잘라 썼어요. 남은 색 테이프의 길이는 얼마인가요?',ARRAY['M2-2-u3-X08']::text[],true,'{"seq":12,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"4 m 86 cm인 색 테이프에서 2 m 53 cm를 잘라 썼어요. 남은 색 테이프의 길이는 얼마인가요?","explanation":["m는 m끼리 빼요 — 4 − 2 = 2.","cm는 cm끼리 빼요 — 86 − 53 = 33.","그래서 4 m 86 cm − 2 m 53 cm = 2 m 33 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"cut"}},"options":[{"t":"2 m 33 cm","correct":true},{"t":"3 m 33 cm","mis":"M2-2-u3-X08"},{"t":"2 m 43 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mbar","parts":[[4,86],[2,53]],"op":"-"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#13','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C2',2,'mc','auto','두 길이를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#14','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C7',2,'mc','auto','1 m가 약 2걸음인 친구가 있어요. 이 친구가 약 4 m를 걸으면 몇 걸음쯤일까요?',ARRAY['M2-2-u3-X14','M2-2-u3-X13']::text[],true,'{"seq":14,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"1 m가 약 2걸음인 친구가 있어요. 이 친구가 약 4 m를 걸으면 몇 걸음쯤일까요?","explanation":["1 m가 약 2걸음이에요.","약 4 m는 1 m가 4번이니 2걸음씩 4번 — 2 + 2 + 2 + 2 = 8이에요.","그래서 약 8걸음쯤이에요."],"variant_rule":{"mcm":{"ask":"pace"}},"options":[{"t":"약 8걸음","correct":true},{"t":"약 6걸음","mis":"M2-2-u3-X14"},{"t":"약 4걸음","mis":"M2-2-u3-X13"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#15','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C8',2,'mc','auto','학생 8명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?',ARRAY['M2-2-u3-X15']::text[],true,'{"seq":15,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"학생 8명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?","explanation":["학생이 8명이면 사이 간격은 7개예요.","약 1 m씩 7번이니 약 7 m예요.","사람 수만큼 8번 더하면 안 돼요 — 간격을 세어요."],"variant_rule":{"mcm":{"ask":"est","people":true}},"options":[{"t":"약 7 m","correct":true},{"t":"약 8 m","mis":"M2-2-u3-X15"},{"t":"약 9 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":1,"n":8,"people":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#16','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C8',2,'mc','auto','한 칸이 약 5 m인 간격이 2개 있어요. 모두 약 몇 m인가요?',ARRAY['M2-2-u3-X14','M2-2-u3-X15']::text[],true,'{"seq":16,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"한 칸이 약 5 m인 간격이 2개 있어요. 모두 약 몇 m인가요?","explanation":["약 5 m가 2번 있어요.","5 + 5 = 10이에요.","그래서 모두 약 10 m예요."],"variant_rule":{"mcm":{"ask":"est"}},"options":[{"t":"약 10 m","correct":true},{"t":"약 7 m","mis":"M2-2-u3-X14"},{"t":"약 5 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":5,"n":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#17','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C4',3,'mc','auto','탁자의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 탁자의 길이는 몇 cm인가요?',ARRAY['M2-2-u3-X06','M2-2-u3-X07']::text[],true,'{"seq":17,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"탁자의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 탁자의 길이는 몇 cm인가요?","explanation":["탁자의 한끝은 눈금 2, 다른 끝은 눈금 136에 있어요.","136 − 2 = 134이니 134 cm예요.","끝 눈금 136을 그대로 읽으면 안 돼요 — 한끝을 0에 맞추어 재요."],"variant_rule":{"mcm":{"ask":"off"}},"options":[{"t":"134 cm","correct":true},{"t":"136 cm","mis":"M2-2-u3-X06"},{"t":"135 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":134,"label":"탁자","s":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#18','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C5',3,'mc','auto','굴렁쇠가 3 m 46 cm를 굴러간 뒤 5 m 2 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X09','M2-2-u3-X08']::text[],true,'{"seq":18,"concept":"M2-2-u3-C5","difficulty":3,"kind":"mc","stem":"굴렁쇠가 3 m 46 cm를 굴러간 뒤 5 m 2 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?","explanation":["m는 m끼리 더해요 — 3 + 5 = 8.","cm는 cm끼리 더해요 — 46 + 2 = 48.","그래서 3 m 46 cm + 5 m 2 cm = 8 m 48 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"roll"}},"options":[{"t":"8 m 48 cm","correct":true},{"t":"2 m 44 cm","mis":"M2-2-u3-X10"},{"t":"8 m 66 cm","mis":"M2-2-u3-X09"},{"t":"9 m 48 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#19','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C6',3,'mc','auto','두 막대의 길이는 8 m 69 cm와 3 m 4 cm예요. 두 막대의 길이의 차는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X09','M2-2-u3-X08']::text[],true,'{"seq":19,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"두 막대의 길이는 8 m 69 cm와 3 m 4 cm예요. 두 막대의 길이의 차는 얼마인가요?","explanation":["m는 m끼리 빼요 — 8 − 3 = 5.","cm는 cm끼리 빼요 — 69 − 4 = 65.","그래서 8 m 69 cm − 3 m 4 cm = 5 m 65 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"diff"}},"options":[{"t":"5 m 65 cm","correct":true},{"t":"11 m 73 cm","mis":"M2-2-u3-X10"},{"t":"5 m 29 cm","mis":"M2-2-u3-X09"},{"t":"6 m 65 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#20','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C9',3,'mc','auto','범고래의 몸길이는 6 m 50 cm, 바다거북의 몸길이는 1 m 30 cm예요. 두 동물의 몸길이의 차는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X11']::text[],false,'{"seq":20,"concept":"M2-2-u3-C9","difficulty":3,"kind":"mc","stem":"범고래의 몸길이는 6 m 50 cm, 바다거북의 몸길이는 1 m 30 cm예요. 두 동물의 몸길이의 차는 얼마인가요?","options":[{"t":"5 m 20 cm","correct":true},{"t":"7 m 80 cm","mis":"M2-2-u3-X10"},{"t":"5 m 2 cm","mis":"M2-2-u3-X11"}],"explanation":["차는 긴 몸길이에서 짧은 몸길이를 빼요.","m끼리 6 − 1 = 5, cm끼리 50 − 30 = 20이에요.","그래서 5 m 20 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#21','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C9',3,'mc','auto','조사한 동물의 몸길이를 카드에 적었어요. 바르게 적은 것은 어느 것인가요?',ARRAY['M2-2-u3-X05','M2-2-u3-X03']::text[],false,'{"seq":21,"concept":"M2-2-u3-C9","difficulty":3,"kind":"mc","stem":"조사한 동물의 몸길이를 카드에 적었어요. 바르게 적은 것은 어느 것인가요?","options":[{"t":"가오리 — 약 2 m 40 cm","correct":true},{"t":"가오리 — 약 240","mis":"M2-2-u3-X05"},{"t":"가오리 — 약 24 m","mis":"M2-2-u3-X03"}],"explanation":["몸길이에는 단위를 꼭 붙여요.","240 cm는 2 m 40 cm예요.","약 240은 단위가 없고, 약 24 m는 열 배나 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#22','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C8',3,'mc','auto','울타리 한 칸은 약 2 m, 그네의 길이는 약 4 m예요. 나무에서 그네까지 울타리 세 칸, 그네, 그네에서 다른 나무까지 울타리 세 칸이에요. 두 나무 사이는 약 몇 m인가요?',ARRAY['M2-2-u3-X14']::text[],false,'{"seq":22,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"울타리 한 칸은 약 2 m, 그네의 길이는 약 4 m예요. 나무에서 그네까지 울타리 세 칸, 그네, 그네에서 다른 나무까지 울타리 세 칸이에요. 두 나무 사이는 약 몇 m인가요?","options":[{"t":"약 16 m","correct":true},{"t":"약 10 m","mis":"M2-2-u3-X14"},{"t":"약 12 m","mis":"M2-2-u3-X14"}],"explanation":["울타리 세 칸은 약 6 m예요.","6 + 4 + 6 = 16이에요.","그래서 두 나무 사이는 약 16 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#23','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C6',4,'essay','teacher','5 m 64 cm − 3 m 22 cm를 계산하고, 구한 답이 맞는지 덧셈으로 확인해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u3-C6","difficulty":4,"kind":"essay","stem":"5 m 64 cm − 3 m 22 cm를 계산하고, 구한 답이 맞는지 덧셈으로 확인해 보세요.","answer_guide":{"answer":"예: m끼리 5 − 3 = 2, cm끼리 64 − 22 = 42이므로 2 m 42 cm이다. 2 m 42 cm + 3 m 22 cm = 5 m 64 cm가 되어 맞다.","scoring_points":["2 m 42 cm를 구했는가","차에 뺀 길이를 더해 확인했는가","처음 길이가 나온다고 썼는가"]},"explanation":["m는 m끼리, cm는 cm끼리 빼요.","2 m 42 cm + 3 m 22 cm = 5 m 64 cm예요.","처음 길이가 나오면 맞게 계산한 거예요."],"asset":{"type":"mcm_calc","a":[5,64],"b":[3,22],"op":"-","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#24','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C9',4,'essay','teacher','범고래(6 m 50 cm)와 바다거북(1 m 30 cm)의 몸길이를 교실 바닥에 줄자로 나타냈어요. 어느 동물이 얼마나 더 긴지 구하고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u3-C9","difficulty":4,"kind":"essay","stem":"범고래(6 m 50 cm)와 바다거북(1 m 30 cm)의 몸길이를 교실 바닥에 줄자로 나타냈어요. 어느 동물이 얼마나 더 긴지 구하고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 범고래가 더 길다. 6 m 50 cm − 1 m 30 cm에서 m끼리 5, cm끼리 20이므로 범고래가 5 m 20 cm 더 길다.","scoring_points":["두 몸길이를 같은 단위로 바르게 견주었는가","합이나 차를 m끼리·cm끼리 바르게 구했는가","답을 몇 m 몇 cm로 바르게 썼는가"]},"explanation":["몸길이는 몇 m 몇 cm로 나타내요.","m는 m끼리, cm는 cm끼리 계산해요.","단위를 붙여 바르게 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_a#25','math',2,2,'u3','','g2_2_math_u3_review_a','unit_review','M2-2-u3-C9',4,'mc','auto','바다거북(1 m 30 cm)과 돌고래(2 m 20 cm)를 이은 길이는 바다악어(4 m 80 cm)보다 얼마나 짧은가요?',ARRAY['M2-2-u3-X16','M2-2-u3-X10']::text[],false,'{"seq":25,"concept":"M2-2-u3-C9","difficulty":4,"kind":"mc","stem":"바다거북(1 m 30 cm)과 돌고래(2 m 20 cm)를 이은 길이는 바다악어(4 m 80 cm)보다 얼마나 짧은가요?","options":[{"t":"1 m 30 cm","correct":true},{"t":"3 m 50 cm","mis":"M2-2-u3-X16"},{"t":"8 m 30 cm","mis":"M2-2-u3-X10"}],"explanation":["바다거북과 돌고래를 이으면 3 m 50 cm예요.","4 m 80 cm − 3 m 50 cm = 1 m 30 cm예요.","이은 길이만 구하면 안 돼요 — 한 번 더 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#1','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C1',1,'sa','auto','400 cm는 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u3-C1","difficulty":1,"kind":"sa","stem":"400 cm는 몇 m인가요? 숫자로 쓰세요.","explanation":["100 cm는 1 m예요.","400 cm는 100 cm가 4번이에요.","그래서 400 cm = 4 m예요."],"variant_rule":{"mcm":{"ask":"m100","form":"tom"}},"answer":["4"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#2','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C1',1,'mc','auto','6 m는 몇 cm인가요?',ARRAY['M2-2-u3-X01']::text[],true,'{"seq":2,"concept":"M2-2-u3-C1","difficulty":1,"kind":"mc","stem":"6 m는 몇 cm인가요?","explanation":["1 m는 100 cm예요.","6 m는 100 cm가 6번이에요.","그래서 6 m = 600 cm예요."],"variant_rule":{"mcm":{"ask":"m100","form":"tocm"}},"options":[{"t":"600 cm","correct":true},{"t":"60 cm","mis":"M2-2-u3-X01"},{"t":"6000 cm","mis":"M2-2-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#3','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C2',1,'sa','auto','3 m 8 cm는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u3-C2","difficulty":1,"kind":"sa","stem":"3 m 8 cm는 몇 cm인가요? 숫자로 쓰세요.","explanation":["3 m는 300 cm예요.","300 cm와 8 cm를 모으면 308 cm예요.","cm가 한 자리 수라 십의 자리에 0을 써서 308이에요 — 38이 아니에요."],"variant_rule":{"mcm":{"ask":"tocm"}},"answer":["308"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#4','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C4',1,'sa','auto','매트의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M2-2-u3-C4","difficulty":1,"kind":"sa","stem":"매트의 길이는 몇 cm인가요? 숫자로 쓰세요.","explanation":["매트의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 146이니 146 cm예요.","146 cm는 1 m 46 cm라고도 나타내요."],"variant_rule":{"mcm":{"ask":"read"}},"answer":["146"],"asset":{"type":"tape","len":146,"label":"매트"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#5','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C5',1,'mc','auto','2 m 41 cm + 4 m 36 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":5,"concept":"M2-2-u3-C5","difficulty":1,"kind":"mc","stem":"2 m 41 cm + 4 m 36 cm는 얼마인가요?","explanation":["m는 m끼리 더해요 — 2 + 4 = 6.","cm는 cm끼리 더해요 — 41 + 36 = 77.","그래서 2 m 41 cm + 4 m 36 cm = 6 m 77 cm예요."],"variant_rule":{"mcm":{"ask":"add"}},"options":[{"t":"6 m 77 cm","correct":true},{"t":"2 m 5 cm","mis":"M2-2-u3-X10"},{"t":"7 m 77 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#6','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C6',1,'mc','auto','7 m 69 cm − 3 m 14 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":6,"concept":"M2-2-u3-C6","difficulty":1,"kind":"mc","stem":"7 m 69 cm − 3 m 14 cm는 얼마인가요?","explanation":["m는 m끼리 빼요 — 7 − 3 = 4.","cm는 cm끼리 빼요 — 69 − 14 = 55.","그래서 7 m 69 cm − 3 m 14 cm = 4 m 55 cm예요."],"variant_rule":{"mcm":{"ask":"sub"}},"options":[{"t":"4 m 55 cm","correct":true},{"t":"10 m 83 cm","mis":"M2-2-u3-X10"},{"t":"5 m 55 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#7','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C7',1,'mc','auto','양팔을 벌린 길이로 1 m를 어림할 수 있어요. 양팔을 벌린 길이는 약 몇 m인가요?',ARRAY['M2-2-u3-X17']::text[],false,'{"seq":7,"concept":"M2-2-u3-C7","difficulty":1,"kind":"mc","stem":"양팔을 벌린 길이로 1 m를 어림할 수 있어요. 양팔을 벌린 길이는 약 몇 m인가요?","options":[{"t":"약 1 m","correct":true},{"t":"약 10 m","mis":"M2-2-u3-X17"},{"t":"약 1 cm","mis":"M2-2-u3-X17"}],"explanation":["양팔을 벌린 길이는 1 m쯤이에요.","1 m를 어림하는 기준으로 써요.","그래서 약 1 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#8','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C3',1,'mc','auto','교실의 짧은 쪽의 길이는 약 7 ▢예요. ▢에 알맞은 단위는 무엇인가요?',ARRAY['M2-2-u3-X05']::text[],false,'{"seq":8,"concept":"M2-2-u3-C3","difficulty":1,"kind":"mc","stem":"교실의 짧은 쪽의 길이는 약 7 ▢예요. ▢에 알맞은 단위는 무엇인가요?","options":[{"t":"m","correct":true},{"t":"cm","mis":"M2-2-u3-X05"}],"explanation":["교실은 아주 넓어요.","약 7 cm는 손가락만큼이라 너무 짧아요.","그래서 약 7 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#9','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C2',2,'mc','auto','405 cm를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X09','M2-2-u3-X02']::text[],true,'{"seq":9,"concept":"M2-2-u3-C2","difficulty":2,"kind":"mc","stem":"405 cm를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["405 cm는 400 cm와 5 cm예요.","400 cm는 4 m예요.","그래서 405 cm = 4 m 5 cm예요."],"variant_rule":{"mcm":{"ask":"tomcm"}},"options":[{"t":"4 m 5 cm","correct":true},{"t":"40 m 5 cm","mis":"M2-2-u3-X03"},{"t":"4 m 50 cm","mis":"M2-2-u3-X09"},{"t":"5 m 4 cm","mis":"M2-2-u3-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#10','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C4',2,'mc','auto','사물함의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X07']::text[],true,'{"seq":10,"concept":"M2-2-u3-C4","difficulty":2,"kind":"mc","stem":"사물함의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["사물함의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 520이니 520 cm예요.","520 cm = 500 cm + 20 cm = 5 m 20 cm예요."],"variant_rule":{"mcm":{"ask":"read","form":"mcm"}},"options":[{"t":"5 m 20 cm","correct":true},{"t":"52 m","mis":"M2-2-u3-X03"},{"t":"5 m 21 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":520,"label":"사물함"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#11','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C5',2,'mc','auto','세로셈을 계산하면 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":11,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"세로셈을 계산하면 얼마인가요?","explanation":["m는 m끼리 더해요 — 1 + 5 = 6.","cm는 cm끼리 더해요 — 52 + 26 = 78.","그래서 1 m 52 cm + 5 m 26 cm = 6 m 78 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"calc"}},"options":[{"t":"6 m 78 cm","correct":true},{"t":"4 m 26 cm","mis":"M2-2-u3-X10"},{"t":"7 m 78 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mcm_calc","a":[1,52],"b":[5,26],"op":"+","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#12','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C6',2,'mc','auto','길이가 6 m 88 cm인 막대를 두 도막으로 잘랐어요. 한 도막이 4 m 26 cm일 때 다른 도막의 길이는 얼마인가요?',ARRAY['M2-2-u3-X08']::text[],true,'{"seq":12,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"길이가 6 m 88 cm인 막대를 두 도막으로 잘랐어요. 한 도막이 4 m 26 cm일 때 다른 도막의 길이는 얼마인가요?","explanation":["m는 m끼리 빼요 — 6 − 4 = 2.","cm는 cm끼리 빼요 — 88 − 26 = 62.","그래서 6 m 88 cm − 4 m 26 cm = 2 m 62 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"two"}},"options":[{"t":"2 m 62 cm","correct":true},{"t":"3 m 62 cm","mis":"M2-2-u3-X08"},{"t":"2 m 72 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#13','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C2',2,'mc','auto','두 길이를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#14','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C7',2,'mc','auto','1 m가 약 3걸음인 친구가 있어요. 이 친구가 약 3 m를 걸으면 몇 걸음쯤일까요?',ARRAY['M2-2-u3-X14','M2-2-u3-X13']::text[],true,'{"seq":14,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"1 m가 약 3걸음인 친구가 있어요. 이 친구가 약 3 m를 걸으면 몇 걸음쯤일까요?","explanation":["1 m가 약 3걸음이에요.","약 3 m는 1 m가 3번이니 3걸음씩 3번 — 3 + 3 + 3 = 9예요.","그래서 약 9걸음쯤이에요."],"variant_rule":{"mcm":{"ask":"pace"}},"options":[{"t":"약 9걸음","correct":true},{"t":"약 6걸음","mis":"M2-2-u3-X14"},{"t":"약 3걸음","mis":"M2-2-u3-X13"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#15','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C8',2,'mc','auto','학생 5명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?',ARRAY['M2-2-u3-X15']::text[],true,'{"seq":15,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"학생 5명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?","explanation":["학생이 5명이면 사이 간격은 4개예요.","약 1 m씩 4번이니 약 4 m예요.","사람 수만큼 5번 더하면 안 돼요 — 간격을 세어요."],"variant_rule":{"mcm":{"ask":"est","people":true}},"options":[{"t":"약 4 m","correct":true},{"t":"약 5 m","mis":"M2-2-u3-X15"},{"t":"약 6 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":1,"n":5,"people":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#16','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C8',2,'mc','auto','한 칸이 약 2 m인 간격이 5개 있어요. 모두 약 몇 m인가요?',ARRAY['M2-2-u3-X14','M2-2-u3-X15']::text[],true,'{"seq":16,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"한 칸이 약 2 m인 간격이 5개 있어요. 모두 약 몇 m인가요?","explanation":["약 2 m가 5번 있어요.","2 + 2 + 2 + 2 + 2 = 10이에요.","그래서 모두 약 10 m예요."],"variant_rule":{"mcm":{"ask":"est"}},"options":[{"t":"약 10 m","correct":true},{"t":"약 7 m","mis":"M2-2-u3-X14"},{"t":"약 8 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":2,"n":5}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#17','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C4',3,'mc','auto','소파의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 소파의 길이는 몇 cm인가요?',ARRAY['M2-2-u3-X06','M2-2-u3-X07']::text[],true,'{"seq":17,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"소파의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 소파의 길이는 몇 cm인가요?","explanation":["소파의 한끝은 눈금 3, 다른 끝은 눈금 149에 있어요.","149 − 3 = 146이니 146 cm예요.","끝 눈금 149를 그대로 읽으면 안 돼요 — 한끝을 0에 맞추어 재요."],"variant_rule":{"mcm":{"ask":"off"}},"options":[{"t":"146 cm","correct":true},{"t":"149 cm","mis":"M2-2-u3-X06"},{"t":"147 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":146,"label":"소파","s":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#18','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C5',3,'mc','auto','굴렁쇠가 6 m 52 cm를 굴러간 뒤 2 m 7 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":18,"concept":"M2-2-u3-C5","difficulty":3,"kind":"mc","stem":"굴렁쇠가 6 m 52 cm를 굴러간 뒤 2 m 7 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?","explanation":["m는 m끼리 더해요 — 6 + 2 = 8.","cm는 cm끼리 더해요 — 52 + 7 = 59.","그래서 6 m 52 cm + 2 m 7 cm = 8 m 59 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"roll"}},"options":[{"t":"8 m 59 cm","correct":true},{"t":"4 m 45 cm","mis":"M2-2-u3-X10"},{"t":"9 m 59 cm","mis":"M2-2-u3-X08"},{"t":"8 m 69 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#19','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C6',3,'mc','auto','두 막대의 길이는 4 m 29 cm와 1 m 6 cm예요. 두 막대의 길이의 차는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":19,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"두 막대의 길이는 4 m 29 cm와 1 m 6 cm예요. 두 막대의 길이의 차는 얼마인가요?","explanation":["m는 m끼리 빼요 — 4 − 1 = 3.","cm는 cm끼리 빼요 — 29 − 6 = 23.","그래서 4 m 29 cm − 1 m 6 cm = 3 m 23 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"diff"}},"options":[{"t":"3 m 23 cm","correct":true},{"t":"5 m 35 cm","mis":"M2-2-u3-X10"},{"t":"4 m 23 cm","mis":"M2-2-u3-X08"},{"t":"3 m 33 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#20','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C9',3,'mc','auto','바다악어의 몸길이는 4 m 80 cm, 돌고래의 몸길이는 2 m 20 cm예요. 두 동물의 몸길이의 차는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X11']::text[],false,'{"seq":20,"concept":"M2-2-u3-C9","difficulty":3,"kind":"mc","stem":"바다악어의 몸길이는 4 m 80 cm, 돌고래의 몸길이는 2 m 20 cm예요. 두 동물의 몸길이의 차는 얼마인가요?","options":[{"t":"2 m 60 cm","correct":true},{"t":"7 m","mis":"M2-2-u3-X10"},{"t":"2 m 6 cm","mis":"M2-2-u3-X11"}],"explanation":["차는 긴 몸길이에서 짧은 몸길이를 빼요.","m끼리 4 − 2 = 2, cm끼리 80 − 20 = 60이에요.","그래서 2 m 60 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#21','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C9',3,'mc','auto','바다악어는 4 m 80 cm, 백상아리는 430 cm, 돌고래는 2 m 20 cm예요. 몸길이가 가장 긴 동물은 무엇인가요?',ARRAY['M2-2-u3-X18','M2-2-u3-X16']::text[],false,'{"seq":21,"concept":"M2-2-u3-C9","difficulty":3,"kind":"mc","stem":"바다악어는 4 m 80 cm, 백상아리는 430 cm, 돌고래는 2 m 20 cm예요. 몸길이가 가장 긴 동물은 무엇인가요?","options":[{"t":"바다악어","correct":true},{"t":"백상아리","mis":"M2-2-u3-X18"},{"t":"돌고래","mis":"M2-2-u3-X16"}],"explanation":["모두 cm로 바꾸면 480 cm, 430 cm, 220 cm예요.","480 cm가 가장 길어요.","보이는 수 430만 보면 안 돼요 — 바다악어가 가장 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#22','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C8',3,'mc','auto','깃발 7개가 약 5 m 간격으로 한 줄로 꽂혀 있어요. 첫 깃발에서 마지막 깃발까지는 약 몇 m인가요?',ARRAY['M2-2-u3-X15','M2-2-u3-X14']::text[],false,'{"seq":22,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"깃발 7개가 약 5 m 간격으로 한 줄로 꽂혀 있어요. 첫 깃발에서 마지막 깃발까지는 약 몇 m인가요?","options":[{"t":"약 30 m","correct":true},{"t":"약 35 m","mis":"M2-2-u3-X15"},{"t":"약 12 m","mis":"M2-2-u3-X14"}],"explanation":["깃발이 7개면 사이 간격은 6개예요.","약 5 m씩 6번이면 약 30 m예요.","깃발 수만큼 7번 더하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#23','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C5',4,'essay','teacher','11 m 35 cm + 7 m 23 cm를 세로셈으로 계산하는 방법을 차례로 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u3-C5","difficulty":4,"kind":"essay","stem":"11 m 35 cm + 7 m 23 cm를 세로셈으로 계산하는 방법을 차례로 설명해 보세요.","answer_guide":{"answer":"예: m는 m 아래, cm는 cm 아래에 맞추어 쓴다. cm끼리 35 + 23 = 58, m끼리 11 + 7 = 18이다. 합은 18 m 58 cm이다.","scoring_points":["같은 단위끼리 맞추어 쓴다고 했는가","cm끼리·m끼리 더했는가","18 m 58 cm라고 구했는가"]},"explanation":["같은 단위끼리 맞추어 써요.","cm끼리 58, m끼리 18이에요.","두 길이의 합은 18 m 58 cm예요."],"asset":{"type":"mcm_calc","a":[11,35],"b":[7,23],"op":"+","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#24','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C9',4,'essay','teacher','바다악어(4 m 80 cm)와 돌고래(2 m 20 cm) 가운데 어느 동물이 얼마나 더 긴지 구하고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u3-C9","difficulty":4,"kind":"essay","stem":"바다악어(4 m 80 cm)와 돌고래(2 m 20 cm) 가운데 어느 동물이 얼마나 더 긴지 구하고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 바다악어가 더 길다. 4 m 80 cm − 2 m 20 cm에서 m끼리 2, cm끼리 60이므로 바다악어가 2 m 60 cm 더 길다.","scoring_points":["두 몸길이를 같은 단위로 바르게 견주었는가","합이나 차를 m끼리·cm끼리 바르게 구했는가","답을 몇 m 몇 cm로 바르게 썼는가"]},"explanation":["몸길이는 몇 m 몇 cm로 나타내요.","m는 m끼리, cm는 cm끼리 계산해요.","단위를 붙여 바르게 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_b#25','math',2,2,'u3','','g2_2_math_u3_review_b','unit_review','M2-2-u3-C9',4,'mc','auto','돌고래(2 m 20 cm)와 바다거북(1 m 30 cm)을 이은 길이와 범고래(6 m 50 cm)의 몸길이의 차는 얼마인가요?',ARRAY['M2-2-u3-X16','M2-2-u3-X10']::text[],false,'{"seq":25,"concept":"M2-2-u3-C9","difficulty":4,"kind":"mc","stem":"돌고래(2 m 20 cm)와 바다거북(1 m 30 cm)을 이은 길이와 범고래(6 m 50 cm)의 몸길이의 차는 얼마인가요?","options":[{"t":"3 m","correct":true},{"t":"3 m 50 cm","mis":"M2-2-u3-X16"},{"t":"10 m","mis":"M2-2-u3-X10"}],"explanation":["돌고래와 바다거북을 이으면 3 m 50 cm예요.","6 m 50 cm − 3 m 50 cm = 3 m예요.","그래서 차는 3 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#1','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C1',1,'sa','auto','500 cm는 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u3-C1","difficulty":1,"kind":"sa","stem":"500 cm는 몇 m인가요? 숫자로 쓰세요.","explanation":["100 cm는 1 m예요.","500 cm는 100 cm가 5번이에요.","그래서 500 cm = 5 m예요."],"variant_rule":{"mcm":{"ask":"m100","form":"tom"}},"answer":["5"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#2','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C1',1,'mc','auto','8 m는 몇 cm인가요?',ARRAY['M2-2-u3-X01']::text[],true,'{"seq":2,"concept":"M2-2-u3-C1","difficulty":1,"kind":"mc","stem":"8 m는 몇 cm인가요?","explanation":["1 m는 100 cm예요.","8 m는 100 cm가 8번이에요.","그래서 8 m = 800 cm예요."],"variant_rule":{"mcm":{"ask":"m100","form":"tocm"}},"options":[{"t":"800 cm","correct":true},{"t":"80 cm","mis":"M2-2-u3-X01"},{"t":"8000 cm","mis":"M2-2-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#3','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C2',1,'sa','auto','2 m 70 cm는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u3-C2","difficulty":1,"kind":"sa","stem":"2 m 70 cm는 몇 cm인가요? 숫자로 쓰세요.","explanation":["2 m는 200 cm예요.","200 cm와 70 cm를 모으면 270 cm예요.","m를 100 cm씩으로 바꾸어 cm와 모아요."],"variant_rule":{"mcm":{"ask":"tocm"}},"answer":["270"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#4','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C4',1,'sa','auto','탁자의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M2-2-u3-C4","difficulty":1,"kind":"sa","stem":"탁자의 길이는 몇 cm인가요? 숫자로 쓰세요.","explanation":["탁자의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 118이니 118 cm예요.","118 cm는 1 m 18 cm라고도 나타내요."],"variant_rule":{"mcm":{"ask":"read"}},"answer":["118"],"asset":{"type":"tape","len":118,"label":"탁자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#5','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C5',1,'mc','auto','5 m 12 cm + 2 m 53 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":5,"concept":"M2-2-u3-C5","difficulty":1,"kind":"mc","stem":"5 m 12 cm + 2 m 53 cm는 얼마인가요?","explanation":["m는 m끼리 더해요 — 5 + 2 = 7.","cm는 cm끼리 더해요 — 12 + 53 = 65.","그래서 5 m 12 cm + 2 m 53 cm = 7 m 65 cm예요."],"variant_rule":{"mcm":{"ask":"add"}},"options":[{"t":"7 m 65 cm","correct":true},{"t":"3 m 41 cm","mis":"M2-2-u3-X10"},{"t":"8 m 65 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#6','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C6',1,'mc','auto','6 m 87 cm − 5 m 42 cm는 얼마인가요?',ARRAY['M2-2-u3-X08']::text[],true,'{"seq":6,"concept":"M2-2-u3-C6","difficulty":1,"kind":"mc","stem":"6 m 87 cm − 5 m 42 cm는 얼마인가요?","explanation":["m는 m끼리 빼요 — 6 − 5 = 1.","cm는 cm끼리 빼요 — 87 − 42 = 45.","그래서 6 m 87 cm − 5 m 42 cm = 1 m 45 cm예요."],"variant_rule":{"mcm":{"ask":"sub"}},"options":[{"t":"1 m 45 cm","correct":true},{"t":"2 m 45 cm","mis":"M2-2-u3-X08"},{"t":"1 m 55 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#7','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C7',1,'mc','auto','교실 문의 높이를 알맞게 어림한 것은 어느 것인가요?',ARRAY['M2-2-u3-X17']::text[],false,'{"seq":7,"concept":"M2-2-u3-C7","difficulty":1,"kind":"mc","stem":"교실 문의 높이를 알맞게 어림한 것은 어느 것인가요?","options":[{"t":"약 2 m","correct":true},{"t":"약 2 cm","mis":"M2-2-u3-X17"},{"t":"약 20 m","mis":"M2-2-u3-X17"}],"explanation":["교실 문은 어른 키보다 조금 높아요.","1 m의 두 배쯤이에요.","그래서 약 2 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#8','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C3',1,'mc','auto','수학책의 긴 쪽의 길이는 약 27 ▢예요. ▢에 알맞은 단위는 무엇인가요?',ARRAY['M2-2-u3-X05']::text[],false,'{"seq":8,"concept":"M2-2-u3-C3","difficulty":1,"kind":"mc","stem":"수학책의 긴 쪽의 길이는 약 27 ▢예요. ▢에 알맞은 단위는 무엇인가요?","options":[{"t":"cm","correct":true},{"t":"m","mis":"M2-2-u3-X05"}],"explanation":["수학책은 책상 위에 놓을 만큼 작아요.","약 27 m는 운동장 반쯤이에요.","그래서 약 27 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#9','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C2',2,'mc','auto','352 cm를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X11','M2-2-u3-X02']::text[],true,'{"seq":9,"concept":"M2-2-u3-C2","difficulty":2,"kind":"mc","stem":"352 cm를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["352 cm는 300 cm와 52 cm예요.","300 cm는 3 m예요.","그래서 352 cm = 3 m 52 cm예요."],"variant_rule":{"mcm":{"ask":"tomcm"}},"options":[{"t":"3 m 52 cm","correct":true},{"t":"35 m 2 cm","mis":"M2-2-u3-X03"},{"t":"3 m 5 cm","mis":"M2-2-u3-X11"},{"t":"52 m 3 cm","mis":"M2-2-u3-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#10','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C4',2,'mc','auto','현수막의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X07']::text[],true,'{"seq":10,"concept":"M2-2-u3-C4","difficulty":2,"kind":"mc","stem":"현수막의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["현수막의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 207이니 207 cm예요.","207 cm = 200 cm + 7 cm = 2 m 7 cm예요."],"variant_rule":{"mcm":{"ask":"read","form":"mcm"}},"options":[{"t":"2 m 7 cm","correct":true},{"t":"20 m 7 cm","mis":"M2-2-u3-X03"},{"t":"2 m 8 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":207,"label":"현수막"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#11','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C5',2,'mc','auto','세로셈을 계산하면 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":11,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"세로셈을 계산하면 얼마인가요?","explanation":["m는 m끼리 더해요 — 6 + 2 = 8.","cm는 cm끼리 더해요 — 14 + 71 = 85.","그래서 6 m 14 cm + 2 m 71 cm = 8 m 85 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"calc"}},"options":[{"t":"8 m 85 cm","correct":true},{"t":"4 m 57 cm","mis":"M2-2-u3-X10"},{"t":"9 m 85 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mcm_calc","a":[6,14],"b":[2,71],"op":"+","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#12','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C6',2,'mc','auto','5 m 64 cm인 색 테이프에서 3 m 22 cm를 잘라 썼어요. 남은 색 테이프의 길이는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":12,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"5 m 64 cm인 색 테이프에서 3 m 22 cm를 잘라 썼어요. 남은 색 테이프의 길이는 얼마인가요?","explanation":["m는 m끼리 빼요 — 5 − 3 = 2.","cm는 cm끼리 빼요 — 64 − 22 = 42.","그래서 5 m 64 cm − 3 m 22 cm = 2 m 42 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"cut"}},"options":[{"t":"2 m 42 cm","correct":true},{"t":"8 m 86 cm","mis":"M2-2-u3-X10"},{"t":"3 m 42 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mbar","parts":[[5,64],[3,22]],"op":"-"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#13','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C2',2,'mc','auto','두 길이를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#14','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C7',2,'mc','auto','1 m가 약 2걸음인 친구가 있어요. 이 친구가 약 6 m를 걸으면 몇 걸음쯤일까요?',ARRAY['M2-2-u3-X14','M2-2-u3-X13']::text[],true,'{"seq":14,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"1 m가 약 2걸음인 친구가 있어요. 이 친구가 약 6 m를 걸으면 몇 걸음쯤일까요?","explanation":["1 m가 약 2걸음이에요.","약 6 m는 1 m가 6번이니 2걸음씩 6번 — 2 + 2 + 2 + 2 + 2 + 2 = 12예요.","그래서 약 12걸음쯤이에요."],"variant_rule":{"mcm":{"ask":"pace"}},"options":[{"t":"약 12걸음","correct":true},{"t":"약 8걸음","mis":"M2-2-u3-X14"},{"t":"약 6걸음","mis":"M2-2-u3-X13"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#15','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C8',2,'mc','auto','학생 4명이 앞 사람과 약 2 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?',ARRAY['M2-2-u3-X15']::text[],true,'{"seq":15,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"학생 4명이 앞 사람과 약 2 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?","explanation":["학생이 4명이면 사이 간격은 3개예요.","약 2 m씩 3번이니 약 6 m예요.","사람 수만큼 4번 더하면 안 돼요 — 간격을 세어요."],"variant_rule":{"mcm":{"ask":"est","people":true}},"options":[{"t":"약 6 m","correct":true},{"t":"약 8 m","mis":"M2-2-u3-X15"},{"t":"약 10 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":2,"n":4,"people":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#16','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C8',2,'mc','auto','한 칸이 약 5 m인 간격이 3개 있어요. 모두 약 몇 m인가요?',ARRAY['M2-2-u3-X14','M2-2-u3-X15']::text[],true,'{"seq":16,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"한 칸이 약 5 m인 간격이 3개 있어요. 모두 약 몇 m인가요?","explanation":["약 5 m가 3번 있어요.","5 + 5 + 5 = 15예요.","그래서 모두 약 15 m예요."],"variant_rule":{"mcm":{"ask":"est"}},"options":[{"t":"약 15 m","correct":true},{"t":"약 8 m","mis":"M2-2-u3-X14"},{"t":"약 10 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":5,"n":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#17','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C4',3,'mc','auto','밧줄의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 밧줄의 길이는 몇 cm인가요?',ARRAY['M2-2-u3-X06','M2-2-u3-X07']::text[],true,'{"seq":17,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"밧줄의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 밧줄의 길이는 몇 cm인가요?","explanation":["밧줄의 한끝은 눈금 3, 다른 끝은 눈금 128에 있어요.","128 − 3 = 125이니 125 cm예요.","끝 눈금 128을 그대로 읽으면 안 돼요 — 한끝을 0에 맞추어 재요."],"variant_rule":{"mcm":{"ask":"off"}},"options":[{"t":"125 cm","correct":true},{"t":"128 cm","mis":"M2-2-u3-X06"},{"t":"126 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":125,"label":"밧줄","s":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#18','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C5',3,'mc','auto','굴렁쇠가 3 m 40 cm를 굴러간 뒤 4 m 9 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":18,"concept":"M2-2-u3-C5","difficulty":3,"kind":"mc","stem":"굴렁쇠가 3 m 40 cm를 굴러간 뒤 4 m 9 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?","explanation":["m는 m끼리 더해요 — 3 + 4 = 7.","cm는 cm끼리 더해요 — 40 + 9 = 49.","그래서 3 m 40 cm + 4 m 9 cm = 7 m 49 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"roll"}},"options":[{"t":"7 m 49 cm","correct":true},{"t":"1 m 31 cm","mis":"M2-2-u3-X10"},{"t":"8 m 49 cm","mis":"M2-2-u3-X08"},{"t":"7 m 59 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#19','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C6',3,'mc','auto','두 막대의 길이는 7 m 85 cm와 2 m 4 cm예요. 두 막대의 길이의 차는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X09','M2-2-u3-X08']::text[],true,'{"seq":19,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"두 막대의 길이는 7 m 85 cm와 2 m 4 cm예요. 두 막대의 길이의 차는 얼마인가요?","explanation":["m는 m끼리 빼요 — 7 − 2 = 5.","cm는 cm끼리 빼요 — 85 − 4 = 81.","그래서 7 m 85 cm − 2 m 4 cm = 5 m 81 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"diff"}},"options":[{"t":"5 m 81 cm","correct":true},{"t":"9 m 89 cm","mis":"M2-2-u3-X10"},{"t":"5 m 45 cm","mis":"M2-2-u3-X09"},{"t":"6 m 81 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#20','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C9',3,'mc','auto','바다거북(1 m 30 cm)과 돌고래(2 m 20 cm)의 몸길이를 교실 바닥에 이어서 나타냈어요. 이은 길이는 모두 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X11']::text[],false,'{"seq":20,"concept":"M2-2-u3-C9","difficulty":3,"kind":"mc","stem":"바다거북(1 m 30 cm)과 돌고래(2 m 20 cm)의 몸길이를 교실 바닥에 이어서 나타냈어요. 이은 길이는 모두 얼마인가요?","options":[{"t":"3 m 50 cm","correct":true},{"t":"90 cm","mis":"M2-2-u3-X10"},{"t":"3 m 5 cm","mis":"M2-2-u3-X11"}],"explanation":["이은 길이는 두 몸길이의 합이에요.","m끼리 1 + 2 = 3, cm끼리 30 + 20 = 50이에요.","그래서 3 m 50 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#21','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C9',3,'mc','auto','내 키는 1 m 30 cm예요. 바다거북은 130 cm, 바다표범은 1 m 80 cm, 돌고래는 220 cm예요. 내 키와 몸길이가 같은 동물은 무엇인가요?',ARRAY['M2-2-u3-X18']::text[],false,'{"seq":21,"concept":"M2-2-u3-C9","difficulty":3,"kind":"mc","stem":"내 키는 1 m 30 cm예요. 바다거북은 130 cm, 바다표범은 1 m 80 cm, 돌고래는 220 cm예요. 내 키와 몸길이가 같은 동물은 무엇인가요?","options":[{"t":"바다거북","correct":true},{"t":"바다표범","mis":"M2-2-u3-X18"},{"t":"돌고래","mis":"M2-2-u3-X18"}],"explanation":["1 m 30 cm는 130 cm예요.","바다거북의 몸길이 130 cm와 같아요.","그래서 바다거북이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#22','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C8',3,'mc','auto','약 10 m인 복도를 약 2 m씩 나누었어요. 모두 몇 칸이 되나요?',ARRAY['M2-2-u3-X14']::text[],false,'{"seq":22,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"약 10 m인 복도를 약 2 m씩 나누었어요. 모두 몇 칸이 되나요?","options":[{"t":"5칸","correct":true},{"t":"8칸","mis":"M2-2-u3-X14"},{"t":"20칸","mis":"M2-2-u3-X14"}],"explanation":["약 2 m가 몇 번이면 약 10 m인지 찾아요.","2 + 2 + 2 + 2 + 2 = 10이에요.","그래서 5칸이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#23','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C5',4,'essay','teacher','2 m 24 cm + 7 m 5 cm를 9 m 74 cm라고 계산한 친구가 있어요. 무엇이 잘못되었는지 설명하고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u3-C5","difficulty":4,"kind":"essay","stem":"2 m 24 cm + 7 m 5 cm를 9 m 74 cm라고 계산한 친구가 있어요. 무엇이 잘못되었는지 설명하고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 7 m 5 cm의 5를 50처럼 더해 24 + 50 = 74로 계산했다. cm끼리 24 + 5 = 29이므로 바른 답은 9 m 29 cm이다.","scoring_points":["5를 50으로 본 잘못을 찾았는가","cm끼리 24 + 5 = 29를 구했는가","9 m 29 cm라고 바르게 썼는가"]},"explanation":["7 m 5 cm의 cm는 5예요.","cm끼리 24 + 5 = 29예요.","바른 답은 9 m 29 cm예요."],"asset":{"type":"mcm_calc","a":[2,24],"b":[7,5],"op":"+","ask":"both","said":[9,74]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#24','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C9',4,'essay','teacher','바다거북(1 m 30 cm)과 돌고래(2 m 20 cm)를 바닥에 이어서 나타내면 길이가 얼마인지 구하고, 그 길이가 범고래(6 m 50 cm)보다 얼마나 짧은지 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u3-C9","difficulty":4,"kind":"essay","stem":"바다거북(1 m 30 cm)과 돌고래(2 m 20 cm)를 바닥에 이어서 나타내면 길이가 얼마인지 구하고, 그 길이가 범고래(6 m 50 cm)보다 얼마나 짧은지 설명해 보세요.","answer_guide":{"answer":"예: 1 m 30 cm + 2 m 20 cm = 3 m 50 cm이다. 6 m 50 cm − 3 m 50 cm = 3 m이므로 범고래보다 3 m 짧다.","scoring_points":["두 몸길이를 같은 단위로 바르게 견주었는가","합이나 차를 m끼리·cm끼리 바르게 구했는가","답을 몇 m 몇 cm로 바르게 썼는가"]},"explanation":["몸길이는 몇 m 몇 cm로 나타내요.","m는 m끼리, cm는 cm끼리 계산해요.","단위를 붙여 바르게 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_c#25','math',2,2,'u3','','g2_2_math_u3_review_c','unit_review','M2-2-u3-C9',4,'mc','auto','줄넘기 줄 2 m 45 cm에서 1 m 20 cm를 잘라 쓰고, 남은 줄에 1 m 30 cm를 이었어요. 줄의 길이는 얼마가 되었나요?',ARRAY['M2-2-u3-X16','M2-2-u3-X10']::text[],false,'{"seq":25,"concept":"M2-2-u3-C9","difficulty":4,"kind":"mc","stem":"줄넘기 줄 2 m 45 cm에서 1 m 20 cm를 잘라 쓰고, 남은 줄에 1 m 30 cm를 이었어요. 줄의 길이는 얼마가 되었나요?","options":[{"t":"2 m 55 cm","correct":true},{"t":"1 m 25 cm","mis":"M2-2-u3-X16"},{"t":"4 m 95 cm","mis":"M2-2-u3-X10"}],"explanation":["잘라 쓰고 남은 줄은 2 m 45 cm − 1 m 20 cm = 1 m 25 cm예요.","1 m 25 cm + 1 m 30 cm = 2 m 55 cm예요.","빼고 나서 더해요 — 모두 더하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#1','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C1',1,'sa','auto','700 cm는 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u3-C1","difficulty":1,"kind":"sa","stem":"700 cm는 몇 m인가요? 숫자로 쓰세요.","explanation":["100 cm는 1 m예요.","700 cm는 100 cm가 7번이에요.","그래서 700 cm = 7 m예요."],"variant_rule":{"mcm":{"ask":"m100","form":"tom"}},"answer":["7"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#2','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C1',1,'mc','auto','9 m는 몇 cm인가요?',ARRAY['M2-2-u3-X01']::text[],true,'{"seq":2,"concept":"M2-2-u3-C1","difficulty":1,"kind":"mc","stem":"9 m는 몇 cm인가요?","explanation":["1 m는 100 cm예요.","9 m는 100 cm가 9번이에요.","그래서 9 m = 900 cm예요."],"variant_rule":{"mcm":{"ask":"m100","form":"tocm"}},"options":[{"t":"900 cm","correct":true},{"t":"90 cm","mis":"M2-2-u3-X01"},{"t":"9000 cm","mis":"M2-2-u3-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#3','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C2',1,'sa','auto','6 m 15 cm는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u3-C2","difficulty":1,"kind":"sa","stem":"6 m 15 cm는 몇 cm인가요? 숫자로 쓰세요.","explanation":["6 m는 600 cm예요.","600 cm와 15 cm를 모으면 615 cm예요.","m를 100 cm씩으로 바꾸어 cm와 모아요."],"variant_rule":{"mcm":{"ask":"tocm"}},"answer":["615"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#4','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C4',1,'sa','auto','현수막의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M2-2-u3-C4","difficulty":1,"kind":"sa","stem":"현수막의 길이는 몇 cm인가요? 숫자로 쓰세요.","explanation":["현수막의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 236이니 236 cm예요.","236 cm는 2 m 36 cm라고도 나타내요."],"variant_rule":{"mcm":{"ask":"read"}},"answer":["236"],"asset":{"type":"tape","len":236,"label":"현수막"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#5','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C5',1,'mc','auto','1 m 64 cm + 6 m 23 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":5,"concept":"M2-2-u3-C5","difficulty":1,"kind":"mc","stem":"1 m 64 cm + 6 m 23 cm는 얼마인가요?","explanation":["m는 m끼리 더해요 — 1 + 6 = 7.","cm는 cm끼리 더해요 — 64 + 23 = 87.","그래서 1 m 64 cm + 6 m 23 cm = 7 m 87 cm예요."],"variant_rule":{"mcm":{"ask":"add"}},"options":[{"t":"7 m 87 cm","correct":true},{"t":"5 m 41 cm","mis":"M2-2-u3-X10"},{"t":"8 m 87 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#6','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C6',1,'mc','auto','8 m 53 cm − 2 m 31 cm는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":6,"concept":"M2-2-u3-C6","difficulty":1,"kind":"mc","stem":"8 m 53 cm − 2 m 31 cm는 얼마인가요?","explanation":["m는 m끼리 빼요 — 8 − 2 = 6.","cm는 cm끼리 빼요 — 53 − 31 = 22.","그래서 8 m 53 cm − 2 m 31 cm = 6 m 22 cm예요."],"variant_rule":{"mcm":{"ask":"sub"}},"options":[{"t":"6 m 22 cm","correct":true},{"t":"10 m 84 cm","mis":"M2-2-u3-X10"},{"t":"7 m 22 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#7','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C7',1,'mc','auto','바다악어의 몸길이를 알맞게 어림한 것은 어느 것인가요?',ARRAY['M2-2-u3-X17']::text[],false,'{"seq":7,"concept":"M2-2-u3-C7","difficulty":1,"kind":"mc","stem":"바다악어의 몸길이를 알맞게 어림한 것은 어느 것인가요?","options":[{"t":"약 3 m","correct":true},{"t":"약 3 cm","mis":"M2-2-u3-X17"},{"t":"약 300 m","mis":"M2-2-u3-X17"}],"explanation":["바다악어는 사람 키보다 훨씬 길어요.","양팔을 세 번쯤 벌린 길이예요.","그래서 약 3 m가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#8','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C3',1,'mc','auto','축구 골대의 긴 쪽의 길이는 약 5 ▢예요. ▢에 알맞은 단위는 무엇인가요?',ARRAY['M2-2-u3-X05']::text[],false,'{"seq":8,"concept":"M2-2-u3-C3","difficulty":1,"kind":"mc","stem":"축구 골대의 긴 쪽의 길이는 약 5 ▢예요. ▢에 알맞은 단위는 무엇인가요?","options":[{"t":"m","correct":true},{"t":"cm","mis":"M2-2-u3-X05"}],"explanation":["축구 골대는 사람 여러 명이 설 만큼 길어요.","약 5 cm는 지우개만큼이라 너무 짧아요.","그래서 약 5 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#9','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C2',2,'mc','auto','709 cm를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X09','M2-2-u3-X02']::text[],true,'{"seq":9,"concept":"M2-2-u3-C2","difficulty":2,"kind":"mc","stem":"709 cm를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["709 cm는 700 cm와 9 cm예요.","700 cm는 7 m예요.","그래서 709 cm = 7 m 9 cm예요."],"variant_rule":{"mcm":{"ask":"tomcm"}},"options":[{"t":"7 m 9 cm","correct":true},{"t":"70 m 9 cm","mis":"M2-2-u3-X03"},{"t":"7 m 90 cm","mis":"M2-2-u3-X09"},{"t":"9 m 7 cm","mis":"M2-2-u3-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#10','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C4',2,'mc','auto','커튼의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X03','M2-2-u3-X07']::text[],true,'{"seq":10,"concept":"M2-2-u3-C4","difficulty":2,"kind":"mc","stem":"커튼의 길이를 몇 m 몇 cm로 나타내면 얼마인가요?","explanation":["커튼의 한끝이 줄자의 눈금 0에 맞춰져 있어요.","다른 끝이 닿은 눈금이 185이니 185 cm예요.","185 cm = 100 cm + 85 cm = 1 m 85 cm예요."],"variant_rule":{"mcm":{"ask":"read","form":"mcm"}},"options":[{"t":"1 m 85 cm","correct":true},{"t":"18 m 5 cm","mis":"M2-2-u3-X03"},{"t":"1 m 86 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":185,"label":"커튼"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#11','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C5',2,'mc','auto','세로셈을 계산하면 얼마인가요?',ARRAY['M2-2-u3-X08']::text[],true,'{"seq":11,"concept":"M2-2-u3-C5","difficulty":2,"kind":"mc","stem":"세로셈을 계산하면 얼마인가요?","explanation":["m는 m끼리 더해요 — 3 + 3 = 6.","cm는 cm끼리 더해요 — 8 + 61 = 69.","그래서 3 m 8 cm + 3 m 61 cm = 6 m 69 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"calc"}},"options":[{"t":"6 m 69 cm","correct":true},{"t":"7 m 69 cm","mis":"M2-2-u3-X08"},{"t":"6 m 79 cm","mis":"M2-2-u3-X08"}],"asset":{"type":"mcm_calc","a":[3,8],"b":[3,61],"op":"+","ask":"both"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#12','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C6',2,'mc','auto','길이가 9 m 95 cm인 막대를 두 도막으로 잘랐어요. 한 도막이 6 m 40 cm일 때 다른 도막의 길이는 얼마인가요?',ARRAY['M2-2-u3-X08']::text[],true,'{"seq":12,"concept":"M2-2-u3-C6","difficulty":2,"kind":"mc","stem":"길이가 9 m 95 cm인 막대를 두 도막으로 잘랐어요. 한 도막이 6 m 40 cm일 때 다른 도막의 길이는 얼마인가요?","explanation":["m는 m끼리 빼요 — 9 − 6 = 3.","cm는 cm끼리 빼요 — 95 − 40 = 55.","그래서 9 m 95 cm − 6 m 40 cm = 3 m 55 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"two"}},"options":[{"t":"3 m 55 cm","correct":true},{"t":"4 m 55 cm","mis":"M2-2-u3-X08"},{"t":"3 m 65 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#13','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C2',2,'mc','auto','두 길이를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#14','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C7',2,'mc','auto','1 m가 약 3걸음인 친구가 있어요. 이 친구가 약 5 m를 걸으면 몇 걸음쯤일까요?',ARRAY['M2-2-u3-X14','M2-2-u3-X13']::text[],true,'{"seq":14,"concept":"M2-2-u3-C7","difficulty":2,"kind":"mc","stem":"1 m가 약 3걸음인 친구가 있어요. 이 친구가 약 5 m를 걸으면 몇 걸음쯤일까요?","explanation":["1 m가 약 3걸음이에요.","약 5 m는 1 m가 5번이니 3걸음씩 5번 — 3 + 3 + 3 + 3 + 3 = 15예요.","그래서 약 15걸음쯤이에요."],"variant_rule":{"mcm":{"ask":"pace"}},"options":[{"t":"약 15걸음","correct":true},{"t":"약 8걸음","mis":"M2-2-u3-X14"},{"t":"약 5걸음","mis":"M2-2-u3-X13"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#15','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C8',2,'mc','auto','학생 7명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?',ARRAY['M2-2-u3-X15']::text[],true,'{"seq":15,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"학생 7명이 앞 사람과 약 1 m씩 간격을 두고 줄을 섰어요. 맨 앞 학생과 맨 뒤 학생 사이의 거리는 약 몇 m인가요?","explanation":["학생이 7명이면 사이 간격은 6개예요.","약 1 m씩 6번이니 약 6 m예요.","사람 수만큼 7번 더하면 안 돼요 — 간격을 세어요."],"variant_rule":{"mcm":{"ask":"est","people":true}},"options":[{"t":"약 6 m","correct":true},{"t":"약 7 m","mis":"M2-2-u3-X15"},{"t":"약 8 m","mis":"M2-2-u3-X15"}],"asset":{"type":"est_row","seg":1,"n":7,"people":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#16','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C8',2,'mc','auto','한 칸이 약 3 m인 간격이 3개 있어요. 모두 약 몇 m인가요?',ARRAY['M2-2-u3-X14']::text[],true,'{"seq":16,"concept":"M2-2-u3-C8","difficulty":2,"kind":"mc","stem":"한 칸이 약 3 m인 간격이 3개 있어요. 모두 약 몇 m인가요?","explanation":["약 3 m가 3번 있어요.","3 + 3 + 3 = 9예요.","그래서 모두 약 9 m예요."],"variant_rule":{"mcm":{"ask":"est"}},"options":[{"t":"약 9 m","correct":true},{"t":"약 6 m","mis":"M2-2-u3-X14"},{"t":"약 12 m","mis":"M2-2-u3-X14"}],"asset":{"type":"est_row","seg":3,"n":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#17','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C4',3,'mc','auto','매트의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 매트의 길이는 몇 cm인가요?',ARRAY['M2-2-u3-X06','M2-2-u3-X07']::text[],true,'{"seq":17,"concept":"M2-2-u3-C4","difficulty":3,"kind":"mc","stem":"매트의 한끝을 줄자의 눈금 0에 맞추지 않고 재었어요. 매트의 길이는 몇 cm인가요?","explanation":["매트의 한끝은 눈금 2, 다른 끝은 눈금 215에 있어요.","215 − 2 = 213이니 213 cm예요.","끝 눈금 215를 그대로 읽으면 안 돼요 — 한끝을 0에 맞추어 재요."],"variant_rule":{"mcm":{"ask":"off"}},"options":[{"t":"213 cm","correct":true},{"t":"215 cm","mis":"M2-2-u3-X06"},{"t":"214 cm","mis":"M2-2-u3-X07"}],"asset":{"type":"tape","len":213,"label":"매트","s":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#18','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C5',3,'mc','auto','굴렁쇠가 5 m 8 cm를 굴러간 뒤 1 m 61 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],true,'{"seq":18,"concept":"M2-2-u3-C5","difficulty":3,"kind":"mc","stem":"굴렁쇠가 5 m 8 cm를 굴러간 뒤 1 m 61 cm를 더 굴러갔어요. 굴렁쇠가 굴러간 거리는 모두 얼마인가요?","explanation":["m는 m끼리 더해요 — 5 + 1 = 6.","cm는 cm끼리 더해요 — 8 + 61 = 69.","그래서 5 m 8 cm + 1 m 61 cm = 6 m 69 cm예요."],"variant_rule":{"mcm":{"ask":"add","form":"roll"}},"options":[{"t":"6 m 69 cm","correct":true},{"t":"4 m 53 cm","mis":"M2-2-u3-X10"},{"t":"7 m 69 cm","mis":"M2-2-u3-X08"},{"t":"6 m 79 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#19','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C6',3,'mc','auto','두 막대의 길이는 6 m 57 cm와 3 m 2 cm예요. 두 막대의 길이의 차는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X09','M2-2-u3-X08']::text[],true,'{"seq":19,"concept":"M2-2-u3-C6","difficulty":3,"kind":"mc","stem":"두 막대의 길이는 6 m 57 cm와 3 m 2 cm예요. 두 막대의 길이의 차는 얼마인가요?","explanation":["m는 m끼리 빼요 — 6 − 3 = 3.","cm는 cm끼리 빼요 — 57 − 2 = 55.","그래서 6 m 57 cm − 3 m 2 cm = 3 m 55 cm예요."],"variant_rule":{"mcm":{"ask":"sub","form":"diff"}},"options":[{"t":"3 m 55 cm","correct":true},{"t":"9 m 59 cm","mis":"M2-2-u3-X10"},{"t":"3 m 37 cm","mis":"M2-2-u3-X09"},{"t":"4 m 55 cm","mis":"M2-2-u3-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#20','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C9',3,'mc','auto','백상아리의 몸길이는 4 m 30 cm, 바다거북의 몸길이는 1 m 30 cm예요. 두 동물의 몸길이의 차는 얼마인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X08']::text[],false,'{"seq":20,"concept":"M2-2-u3-C9","difficulty":3,"kind":"mc","stem":"백상아리의 몸길이는 4 m 30 cm, 바다거북의 몸길이는 1 m 30 cm예요. 두 동물의 몸길이의 차는 얼마인가요?","options":[{"t":"3 m","correct":true},{"t":"5 m 60 cm","mis":"M2-2-u3-X10"},{"t":"3 m 30 cm","mis":"M2-2-u3-X08"}],"explanation":["차는 긴 몸길이에서 짧은 몸길이를 빼요.","m끼리 4 − 1 = 3, cm끼리 30 − 30 = 0이에요.","그래서 3 m예요 — cm 자리가 0이면 m만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#21','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C9',3,'mc','auto','바다표범의 몸길이 1 m 80 cm를 cm로 나타내면 얼마인가요?',ARRAY['M2-2-u3-X11','M2-2-u3-X02']::text[],false,'{"seq":21,"concept":"M2-2-u3-C9","difficulty":3,"kind":"mc","stem":"바다표범의 몸길이 1 m 80 cm를 cm로 나타내면 얼마인가요?","options":[{"t":"180 cm","correct":true},{"t":"18 cm","mis":"M2-2-u3-X11"},{"t":"108 cm","mis":"M2-2-u3-X02"}],"explanation":["1 m는 100 cm예요.","100 cm와 80 cm를 모으면 180 cm예요.","80의 0을 떼거나 자리를 바꾸면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#22','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C8',3,'mc','auto','정문에서 운동장까지 약 30 m, 운동장의 짧은 쪽은 약 25 m예요. 정문에서 운동장을 가로질러 반대쪽 끝까지는 약 몇 m인가요?',ARRAY['M2-2-u3-X10','M2-2-u3-X14']::text[],false,'{"seq":22,"concept":"M2-2-u3-C8","difficulty":3,"kind":"mc","stem":"정문에서 운동장까지 약 30 m, 운동장의 짧은 쪽은 약 25 m예요. 정문에서 운동장을 가로질러 반대쪽 끝까지는 약 몇 m인가요?","options":[{"t":"약 55 m","correct":true},{"t":"약 5 m","mis":"M2-2-u3-X10"},{"t":"약 45 m","mis":"M2-2-u3-X14"}],"explanation":["두 부분으로 나누어 어림한 길이를 더해요.","30 + 25 = 55예요.","그래서 약 55 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#23','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C6',4,'essay','teacher','색 테이프 3 m 75 cm에서 1 m 52 cm를 잘라 썼어요. 남은 색 테이프의 길이를 구하고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u3-C6","difficulty":4,"kind":"essay","stem":"색 테이프 3 m 75 cm에서 1 m 52 cm를 잘라 썼어요. 남은 색 테이프의 길이를 구하고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 남은 길이는 처음 길이에서 쓴 길이를 뺀다. 3 m 75 cm − 1 m 52 cm에서 m끼리 2, cm끼리 23이므로 2 m 23 cm이다.","scoring_points":["뺄셈으로 구해야 함을 썼는가","m끼리·cm끼리 뺐는가","2 m 23 cm라고 구했는가"]},"explanation":["남은 길이는 차로 구해요.","m끼리 3 − 1 = 2, cm끼리 75 − 52 = 23이에요.","남은 색 테이프는 2 m 23 cm예요."],"asset":{"type":"mbar","parts":[[3,75],[1,52]],"op":"-"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#24','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C9',4,'essay','teacher','내 키는 1 m 20 cm예요. 백상아리(4 m 30 cm)는 내 키보다 얼마나 더 긴지 구하고, 동물 카드에 어떻게 적으면 좋을지 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u3-C9","difficulty":4,"kind":"essay","stem":"내 키는 1 m 20 cm예요. 백상아리(4 m 30 cm)는 내 키보다 얼마나 더 긴지 구하고, 동물 카드에 어떻게 적으면 좋을지 써 보세요.","answer_guide":{"answer":"예: 4 m 30 cm − 1 m 20 cm = 3 m 10 cm이다. 카드에는 「백상아리 — 약 4 m 30 cm, 내 키보다 3 m 10 cm 더 길다」처럼 단위를 붙여 적는다.","scoring_points":["두 몸길이를 같은 단위로 바르게 견주었는가","합이나 차를 m끼리·cm끼리 바르게 구했는가","답을 몇 m 몇 cm로 바르게 썼는가"]},"explanation":["몸길이는 몇 m 몇 cm로 나타내요.","m는 m끼리, cm는 cm끼리 계산해요.","단위를 붙여 바르게 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u3_review_d#25','math',2,2,'u3','','g2_2_math_u3_review_d','unit_review','M2-2-u3-C9',4,'mc','auto','8 m 76 cm인 막대에서 2 m 34 cm짜리 도막을 두 개 잘라 냈어요. 남은 막대의 길이는 얼마인가요?',ARRAY['M2-2-u3-X16','M2-2-u3-X09']::text[],false,'{"seq":25,"concept":"M2-2-u3-C9","difficulty":4,"kind":"mc","stem":"8 m 76 cm인 막대에서 2 m 34 cm짜리 도막을 두 개 잘라 냈어요. 남은 막대의 길이는 얼마인가요?","options":[{"t":"4 m 8 cm","correct":true},{"t":"6 m 42 cm","mis":"M2-2-u3-X16"},{"t":"4 m 80 cm","mis":"M2-2-u3-X09"}],"explanation":["한 도막을 잘라 내면 8 m 76 cm − 2 m 34 cm = 6 m 42 cm예요.","한 도막을 더 잘라 내면 6 m 42 cm − 2 m 34 cm = 4 m 8 cm예요.","cm가 8이라 4 m 80 cm로 쓰면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C1','math',2,2,'u4',2,'5분 단위로 시각 읽기 — 짧은바늘로 시를, 긴바늘이 가리키는 숫자에 5를 곱해 분을 읽어 「몇 시 몇 분」으로 나타내기',ARRAY['2수03-05']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C2','math',2,2,'u4',2,'디지털시계 읽기 — 「:」 왼쪽은 시, 오른쪽은 분임을 알고 「열 시 삼십오 분」처럼 바르게 읽고 바늘 시계와 같은 시각을 찾기',ARRAY['2수03-05']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C3','math',2,2,'u4',3,'1분 단위로 시각 읽기 — 작은 눈금 한 칸이 1분임을 알고, 가까운 숫자에서 몇 칸 더(덜) 갔는지 세어 몇 시 몇 분을 읽기',ARRAY['2수03-05']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C4','math',2,2,'u4',4,'몇 시 몇 분 전 — 정각이 되기까지 남은 분을 세어 「몇 시 몇 분 전」으로 읽고, 「몇 시 몇 분 전」을 「몇 시 몇 분」으로 바꾸기',ARRAY['2수03-05']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C5','math',2,2,'u4',5,'1시간 알기 — 긴바늘이 한 바퀴 도는 데 60분이 걸리고 60분 = 1시간임을 알며, 시간 띠(한 칸 10분)로 걸린 시간을 세기',ARRAY['2수03-06']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C6','math',2,2,'u4',6,'걸린 시간 구하기 — 1시간을 먼저 돌리고 더 간 만큼 세어 걸린 시간을 구하고, 몇 시간 몇 분과 몇 분을 서로 바꾸기',ARRAY['2수03-06']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C7','math',2,2,'u4',7,'하루의 시간 — 하루는 24시간이고 오전·오후가 각각 12시간임을 알며, 생활 계획표로 하는 일의 시간을 알고, 하루가 넘는 시간과 오전·오후를 넘는 시각을 구하기',ARRAY['2수03-06']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C8','math',2,2,'u4',8,'달력과 1주일 — 달력에서 날짜와 요일을 읽고, 1주일 = 7일을 써서 몇째 무슨 요일·며칠 후(전)·요일의 횟수를 찾기',ARRAY['2수03-06']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C9','math',2,2,'u4',8,'1년과 달의 날수 — 1년 = 12개월임을 알고 몇 년 몇 개월과 몇 개월을 바꾸며, 달마다 날수가 다름을 알고 「몇 월」과 「몇 개월」을 가리기',ARRAY['2수03-06']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C10','math',2,2,'u4',10,'시간으로 문제 해결하기 — 성장 이야기와 디데이를 만들며 년·개월·주·일 사이의 관계로 날짜와 기간을 구하기',ARRAY['2수03-06']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X01','math',2,'u4',ARRAY['M2-2-u4-C1','M2-2-u4-C3']::text[],'짧은바늘과 긴바늘을 바꾸어 읽는다 — 긴바늘이 가리키는 숫자를 시로, 짧은바늘을 분으로 읽는다','짧은바늘은 시, 긴바늘은 분') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X02','math',2,'u4',ARRAY['M2-2-u4-C1','M2-2-u4-C2','M2-2-u4-C3']::text[],'긴바늘이 가리키는 숫자를 그대로 분으로 읽는다(숫자 3 → 3분)','긴바늘 숫자에 5를 곱하기 — 숫자 1이 5분') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X03','math',2,'u4',ARRAY['M2-2-u4-C1','M2-2-u4-C3','M2-2-u4-C4']::text[],'짧은바늘이 다음 숫자 가까이 있으면 다음 시로 읽는다(4시 55분 → 5시 55분)','짧은바늘이 지나온 숫자가 시 — 아직 다음 숫자에 닿지 않았어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X04','math',2,'u4',ARRAY['M2-2-u4-C1','M2-2-u4-C2','M2-2-u4-C3']::text[],'이웃 눈금·이웃 숫자로 잘못 읽어 1분·5분 어긋나게 읽는다','눈금을 손가락으로 짚으며 한 칸씩 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X05','math',2,'u4',ARRAY['M2-2-u4-C3']::text[],'숫자에서 몇 칸 「더 간」 곳과 「덜 간」 곳을 거꾸로 센다(40분에서 1칸 덜 간 곳 → 41분)','시계 방향은 더 가기, 거꾸로는 덜 가기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X06','math',2,'u4',ARRAY['M2-2-u4-C2']::text[],'디지털시계의 시와 분을 뒤바꾸거나 읽는 말을 잘못 쓴다(10 : 35 → 「십 시」, 「삼십오 시 열 분」)','「:」 왼쪽은 시 「한·두·세」, 오른쪽은 분 「일·이·삼」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X07','math',2,'u4',ARRAY['M2-2-u4-C4']::text[],'「몇 시 몇 분 전」의 시를 곧 될 정각이 아니라 지금 시로 쓴다(8시 55분 → 8시 5분 전)','「전」의 시는 곧 될 정각 — 지금 시보다 하나 커요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X08','math',2,'u4',ARRAY['M2-2-u4-C4']::text[],'정각까지 남은 분 대신 지난 분을 쓰거나 「전」을 빼고 읽는다(8시 55분 → 9시 55분 전, 9시 5분 전 → 9시 5분)','정각까지 몇 분 남았는지 세기 — 「전」은 꼭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X09','math',2,'u4',ARRAY['M2-2-u4-C5','M2-2-u4-C6']::text[],'1시간을 100분으로 보고 시간과 분을 바꾼다(1시간 10분 → 110분)','1시간은 60분 — 긴바늘 한 바퀴') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X10','math',2,'u4',ARRAY['M2-2-u4-C4','M2-2-u4-C5','M2-2-u4-C6','M2-2-u4-C7','M2-2-u4-C9','M2-2-u4-C10']::text[],'걸린 시간·지난 시각을 셀 때 칸·시간을 하나 더 세거나 덜 센다','시작에서 한 칸씩 짚으며 다시 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X11','math',2,'u4',ARRAY['M2-2-u4-C5','M2-2-u4-C6']::text[],'시각과 시간을 섞는다 — 끝난 시각을 걸린 시간으로 답하거나, 몇 시를 몇 시간으로 읽는다','시각은 「때」, 시간은 「동안」 — 시작과 끝 사이를 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X12','math',2,'u4',ARRAY['M2-2-u4-C7']::text[],'낮 12시를 넘어도 오전으로 쓰거나 13시·14시처럼 그대로 이어 쓰고, 오전·오후를 뒤바꾼다','낮 12시를 지나면 오후 1시부터 다시') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X13','math',2,'u4',ARRAY['M2-2-u4-C7']::text[],'하루를 12시간으로 알거나, 하는 일이 많은 쪽이 더 길다고 여긴다','짧은바늘 두 바퀴 = 24시간 — 오전도 오후도 12시간') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X14','math',2,'u4',ARRAY['M2-2-u4-C8','M2-2-u4-C9','M2-2-u4-C10']::text[],'날짜의 이름과 기간의 길이를 섞는다 — 「12월」과 「12개월」, 그날의 날짜와 지난 날수를 같게 본다','「월·일」은 이름, 「개월·일 동안」은 길이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X15','math',2,'u4',ARRAY['M2-2-u4-C8','M2-2-u4-C9','M2-2-u4-C10']::text[],'1주일·1년의 단위를 모른다 — 1주일을 5일·10일로, 1년을 10개월로 보거나 주와 일을 그냥 더한다','1주일 = 7일, 1년 = 12개월') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X16','math',2,'u4',ARRAY['M2-2-u4-C1','M2-2-u4-C2','M2-2-u4-C3','M2-2-u4-C4','M2-2-u4-C5','M2-2-u4-C6','M2-2-u4-C7','M2-2-u4-C8','M2-2-u4-C9','M2-2-u4-C10']::text[],'묻는 말을 거꾸로 읽는다 — 잘못된↔바른, 아닌↔맞는, 이른↔늦은','물음의 「잘못·아닌·이른」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X17','math',2,'u4',ARRAY['M2-2-u4-C8','M2-2-u4-C10']::text[],'달력에서 며칠 후(전)를 셀 때 그날을 넣어 세거나, 요일 칸을 하나 밀려 읽는다','그날은 빼고 다음 날부터 하루씩 — 요일은 세로줄 위를 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X18','math',2,'u4',ARRAY['M2-2-u4-C9','M2-2-u4-C10']::text[],'달마다 날수가 다름을 모른다 — 모든 달을 30일로 보거나 달을 넘어가는 날짜를 그대로 쓴다(7월 47일)','31일·30일 달을 주먹 손등으로 세기 — 넘치면 다음 달') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_basic#1','math',2,2,'u4','L02','g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',1,'mc','auto','긴바늘이 숫자 4를 가리키면 몇 분인가요?',ARRAY['M2-2-u4-X02']::text[],true,'{"seq":1,"concept":"M2-2-u4-C1","difficulty":1,"kind":"mc","stem":"긴바늘이 숫자 4를 가리키면 몇 분인가요?","explanation":["숫자와 숫자 사이는 작은 눈금 5칸 — 5분이에요.","숫자 4까지 5분씩 4번이니 4 × 5 = 20이에요.","그래서 20분이에요 — 숫자 그대로 4분이 아니에요."],"variant_rule":{"tm":{"ask":"numm"}},"options":[{"t":"20분","correct":true},{"t":"4분","mis":"M2-2-u4-X02"},{"t":"40분","mis":"M2-2-u4-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_basic#2','math',2,2,'u4','L02','g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',1,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X02','M2-2-u4-X01']::text[],true,'{"seq":2,"concept":"M2-2-u4-C1","difficulty":1,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 2와 3 사이에 있으니 2시예요.","긴바늘이 숫자 4를 가리키니 4 × 5 = 20분이에요.","그래서 2시 20분이에요."],"variant_rule":{"tm":{"ask":"read","step":5}},"options":[{"t":"2시 20분","correct":true},{"t":"2시 4분","mis":"M2-2-u4-X02"},{"t":"4시 10분","mis":"M2-2-u4-X01"}],"asset":{"type":"clock2","h":2,"m":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_basic#3','math',2,2,'u4','L02','g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',1,'sa','auto','시계가 나타내는 시각은 7시 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u4-C1","difficulty":1,"kind":"sa","stem":"시계가 나타내는 시각은 7시 몇 분인가요? 숫자로 쓰세요.","explanation":["짧은바늘이 7과 8 사이에 있으니 7시예요.","긴바늘이 숫자 2를 가리키니 2 × 5 = 10분이에요.","그래서 7시 10분이에요."],"variant_rule":{"tm":{"ask":"read","step":5}},"answer":["10"],"asset":{"type":"clock2","h":7,"m":10}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_basic#4','math',2,2,'u4','L02','g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',1,'mc','auto','시계에서 숫자와 숫자 사이(큰 눈금 한 칸)는 몇 분인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X04']::text[],true,'{"seq":4,"concept":"M2-2-u4-C1","difficulty":1,"kind":"mc","stem":"시계에서 숫자와 숫자 사이(큰 눈금 한 칸)는 몇 분인가요?","options":[{"t":"5분","correct":true},{"t":"1분","mis":"M2-2-u4-X02"},{"t":"10분","mis":"M2-2-u4-X04"}],"explanation":["숫자와 숫자 사이에는 작은 눈금이 5칸 있어요.","작은 눈금 한 칸은 1분이에요.","그래서 숫자와 숫자 사이는 5분이에요."],"variant_rule":{"alt":[{"stem":"시계에서 작은 눈금 한 칸은 몇 분인가요?","options":[{"t":"1분","correct":true},{"t":"5분","mis":"M2-2-u4-X02"},{"t":"10분","mis":"M2-2-u4-X04"}],"explanation":["긴바늘이 작은 눈금 한 칸을 가는 데 1분이 걸려요.","숫자와 숫자 사이는 작은 눈금 5칸 — 5분이에요.","그래서 작은 눈금 한 칸은 1분이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_basic#5','math',2,2,'u4','L02','g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C2',2,'mc','auto','디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u4-X06','M2-2-u4-X04']::text[],true,'{"seq":5,"concept":"M2-2-u4-C2","difficulty":2,"kind":"mc","stem":"디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?","explanation":["「:」 왼쪽은 시, 오른쪽은 분이에요.","10 : 35는 10시 35분이에요.","시는 「열 시」, 분은 「삼십오 분」으로 읽어요."],"variant_rule":{"tm":{"ask":"dig"}},"options":[{"t":"열 시 삼십오 분","correct":true},{"t":"삼십오 시 열 분","mis":"M2-2-u4-X06"},{"t":"십 시 삼십오 분","mis":"M2-2-u4-X06"},{"t":"열 시 삼십 분","mis":"M2-2-u4-X04"}],"asset":{"type":"digital","h":10,"m":35}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_basic#6','math',2,2,'u4','L02','g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',2,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X02','M2-2-u4-X01','M2-2-u4-X03']::text[],true,'{"seq":6,"concept":"M2-2-u4-C1","difficulty":2,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 4와 5 사이에 있으니 4시예요.","긴바늘이 숫자 9를 가리키니 9 × 5 = 45분이에요.","그래서 4시 45분이에요."],"variant_rule":{"tm":{"ask":"read","step":5}},"options":[{"t":"4시 45분","correct":true},{"t":"4시 9분","mis":"M2-2-u4-X02"},{"t":"9시 20분","mis":"M2-2-u4-X01"},{"t":"5시 45분","mis":"M2-2-u4-X03"}],"asset":{"type":"clock2","h":4,"m":45}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_basic#7','math',2,2,'u4','L02','g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',2,'ox','auto','긴바늘이 숫자 3을 가리키면 3분이에요.',ARRAY['M2-2-u4-X02']::text[],true,'{"seq":7,"concept":"M2-2-u4-C1","difficulty":2,"kind":"ox","stem":"긴바늘이 숫자 3을 가리키면 3분이에요.","answer":"X","reason_options":[{"t":"숫자 1이 5분이라 숫자 3은 3 × 5 = 15분이니까","correct":true},{"t":"긴바늘이 가리키는 숫자가 곧 분이니까","mis":"M2-2-u4-X02"}],"mis":"M2-2-u4-X02","explanation":["숫자와 숫자 사이는 5분이에요.","숫자 3까지 5분씩 3번 — 15분이에요.","그래서 3분이 아니라 15분이에요."],"variant_rule":{"alt":[{"stem":"긴바늘이 숫자 6을 가리키면 30분이에요.","answer":"O","reason_options":[{"t":"숫자 1이 5분이라 숫자 6은 6 × 5 = 30분이니까","correct":true},{"t":"긴바늘이 가리키는 숫자가 곧 분이라 6분이니까","mis":"M2-2-u4-X02"}],"explanation":["숫자와 숫자 사이는 5분이에요.","숫자 6까지 5분씩 6번 — 30분이에요.","그래서 바른 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_basic#8','math',2,2,'u4','L02','g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',2,'match','auto','긴바늘이 가리키는 숫자와 분을 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M2-2-u4-C1","difficulty":2,"kind":"match","stem":"긴바늘이 가리키는 숫자와 분을 이으세요.","pairs":[{"l":"숫자 2","r":"10분"},{"l":"숫자 7","r":"35분"},{"l":"숫자 9","r":"45분"}],"mis":"M2-2-u4-X02","explanation":["긴바늘이 가리키는 숫자에 5를 곱하면 분이에요.","2 × 5 = 10, 7 × 5 = 35예요.","9 × 5 = 45예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 긴바늘이 가리키는 숫자와 분을 이으세요.","pairs":[{"l":"숫자 3","r":"15분"},{"l":"숫자 8","r":"40분"},{"l":"숫자 11","r":"55분"}],"explanation":["긴바늘이 가리키는 숫자에 5를 곱하면 분이에요.","3 × 5 = 15, 8 × 5 = 40이에요.","11 × 5 = 55예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_basic#9','math',2,2,'u4','L02','g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C2',2,'mc','auto','디지털시계가 나타내는 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X06','M2-2-u4-X04']::text[],true,'{"seq":9,"concept":"M2-2-u4-C2","difficulty":2,"kind":"mc","stem":"디지털시계가 나타내는 시각은 몇 시 몇 분인가요?","options":[{"t":"9시 5분","correct":true},{"t":"5시 9분","mis":"M2-2-u4-X06"},{"t":"9시 50분","mis":"M2-2-u4-X04"}],"explanation":["「:」 왼쪽 9는 시, 오른쪽 05는 분이에요.","05는 5분이에요.","그래서 9시 5분이에요."],"asset":{"type":"digital","h":9,"m":5},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 디지털시계가 나타내는 시각은 몇 시 몇 분인가요?","options":[{"t":"12시 40분","correct":true},{"t":"40시 12분","mis":"M2-2-u4-X06"},{"t":"12시 4분","mis":"M2-2-u4-X04"}],"explanation":["「:」 왼쪽 12는 시, 오른쪽 40은 분이에요.","시와 분을 바꾸어 읽으면 안 돼요.","그래서 12시 40분이에요."],"asset":{"type":"digital","h":12,"m":40}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_basic#10','math',2,2,'u4','L02','g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',3,'error','auto','시계를 보고 친구들이 시각을 읽었어요. 잘못 읽은 친구는 누구인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X16']::text[],true,'{"seq":10,"concept":"M2-2-u4-C1","difficulty":3,"kind":"error","stem":"시계를 보고 친구들이 시각을 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"연우 — 「긴바늘이 3을 가리키니까 7시 3분이야.」","correct":true,"mis_target":"M2-2-u4-X02"},{"t":"지아 — 「짧은바늘이 7과 8 사이니까 7시야.」","mis":"M2-2-u4-X16"},{"t":"세미 — 「긴바늘이 3이면 15분이라 7시 15분이야.」","mis":"M2-2-u4-X16"}],"explanation":["짧은바늘이 7과 8 사이라 7시예요.","긴바늘이 숫자 3을 가리키니 3 × 5 = 15분이에요.","연우는 숫자 3을 그대로 3분으로 읽었어요."],"asset":{"type":"clock2","h":7,"m":15},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 시계를 보고 친구들이 시각을 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"민수 — 「긴바늘이 8을 가리키니까 4시 8분이야.」","correct":true,"mis_target":"M2-2-u4-X02"},{"t":"하루 — 「짧은바늘이 4와 5 사이니까 4시야.」","mis":"M2-2-u4-X16"},{"t":"서아 — 「긴바늘이 8이면 40분이라 4시 40분이야.」","mis":"M2-2-u4-X16"}],"explanation":["짧은바늘이 4와 5 사이라 4시예요.","긴바늘이 숫자 8을 가리키니 8 × 5 = 40분이에요.","민수는 숫자 8을 그대로 8분으로 읽었어요."],"asset":{"type":"clock2","h":4,"m":40}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_challenge#1','math',2,2,'u4','L02','g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C1',2,'sa','auto','시계가 나타내는 시각은 11시 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u4-C1","difficulty":2,"kind":"sa","stem":"시계가 나타내는 시각은 11시 몇 분인가요? 숫자로 쓰세요.","explanation":["짧은바늘이 11과 12 사이에 있으니 11시예요.","긴바늘이 숫자 5를 가리키니 5 × 5 = 25분이에요.","그래서 11시 25분이에요."],"variant_rule":{"tm":{"ask":"read","step":5}},"answer":["25"],"asset":{"type":"clock2","h":11,"m":25}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_challenge#2','math',2,2,'u4','L02','g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C2',2,'mc','auto','디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u4-X06','M2-2-u4-X04']::text[],true,'{"seq":2,"concept":"M2-2-u4-C2","difficulty":2,"kind":"mc","stem":"디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?","explanation":["「:」 왼쪽은 시, 오른쪽은 분이에요.","6 : 50은 6시 50분이에요.","시는 「여섯 시」, 분은 「오십 분」으로 읽어요."],"variant_rule":{"tm":{"ask":"dig"}},"options":[{"t":"여섯 시 오십 분","correct":true},{"t":"오십 시 여섯 분","mis":"M2-2-u4-X06"},{"t":"육 시 오십 분","mis":"M2-2-u4-X06"},{"t":"여섯 시 오십오 분","mis":"M2-2-u4-X04"}],"asset":{"type":"digital","h":6,"m":50}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_challenge#3','math',2,2,'u4','L02','g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C1',3,'mc','auto','지아가 일어난 시각은 7시가 조금 지났고, 긴바늘은 숫자 2를 가리켜요. 지아가 일어난 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X01','M2-2-u4-X03']::text[],false,'{"seq":3,"concept":"M2-2-u4-C1","difficulty":3,"kind":"mc","stem":"지아가 일어난 시각은 7시가 조금 지났고, 긴바늘은 숫자 2를 가리켜요. 지아가 일어난 시각은 몇 시 몇 분인가요?","options":[{"t":"7시 10분","correct":true},{"t":"7시 2분","mis":"M2-2-u4-X02"},{"t":"2시 35분","mis":"M2-2-u4-X01"},{"t":"8시 10분","mis":"M2-2-u4-X03"}],"explanation":["7시가 조금 지났으니 짧은바늘은 7과 8 사이예요.","긴바늘이 숫자 2를 가리키니 2 × 5 = 10분이에요.","그래서 7시 10분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_challenge#4','math',2,2,'u4','L02','g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C1',3,'mc','auto','4시 15분을 시계에 나타낼 때 긴바늘이 가리키는 숫자는 무엇인가요?',ARRAY['M2-2-u4-X01','M2-2-u4-X02','M2-2-u4-X04']::text[],false,'{"seq":4,"concept":"M2-2-u4-C1","difficulty":3,"kind":"mc","stem":"4시 15분을 시계에 나타낼 때 긴바늘이 가리키는 숫자는 무엇인가요?","options":[{"t":"3","correct":true},{"t":"4","mis":"M2-2-u4-X01"},{"t":"15","mis":"M2-2-u4-X02"},{"t":"5","mis":"M2-2-u4-X04"}],"explanation":["15분은 5분씩 3번이에요.","5 × 3 = 15라서 긴바늘은 숫자 3을 가리켜요.","숫자 4는 짧은바늘이 가까이 있는 숫자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_challenge#5','math',2,2,'u4','L02','g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C2',3,'mc','auto','줄넘기를 시작한 시각이 디지털시계에 나타나 있어요. 이 시각에 긴바늘이 가리키는 숫자는 무엇인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X01','M2-2-u4-X04']::text[],false,'{"seq":5,"concept":"M2-2-u4-C2","difficulty":3,"kind":"mc","stem":"줄넘기를 시작한 시각이 디지털시계에 나타나 있어요. 이 시각에 긴바늘이 가리키는 숫자는 무엇인가요?","options":[{"t":"8","correct":true},{"t":"4","mis":"M2-2-u4-X02"},{"t":"10","mis":"M2-2-u4-X01"},{"t":"9","mis":"M2-2-u4-X04"}],"explanation":["디지털시계의 시각은 10시 40분이에요.","40분은 5분씩 8번이에요.","그래서 긴바늘은 숫자 8을 가리켜요."],"asset":{"type":"digital","h":10,"m":40}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_challenge#6','math',2,2,'u4','L02','g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C1',3,'ox','auto','2시 50분에 짧은바늘은 숫자 2를 똑바로 가리켜요.',ARRAY['M2-2-u4-X03']::text[],false,'{"seq":6,"concept":"M2-2-u4-C1","difficulty":3,"kind":"ox","stem":"2시 50분에 짧은바늘은 숫자 2를 똑바로 가리켜요.","answer":"X","reason_options":[{"t":"50분이 지나 짧은바늘은 2와 3 사이에서 3에 가까이 가 있으니까","correct":true},{"t":"몇 분이든 짧은바늘은 시의 숫자를 똑바로 가리키니까","mis":"M2-2-u4-X03"}],"mis":"M2-2-u4-X03","explanation":["짧은바늘은 분이 지나는 만큼 다음 숫자 쪽으로 조금씩 가요.","2시 50분에는 2와 3 사이, 3에 가까운 곳에 있어요.","정각일 때만 숫자를 똑바로 가리켜요."],"asset":{"type":"clock2","h":2,"m":50}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_challenge#7','math',2,2,'u4','L02','g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C1',3,'mc','auto','시각이 가장 늦은 것은 어느 것인가요?',ARRAY['M2-2-u4-X04','M2-2-u4-X16','M2-2-u4-X03']::text[],false,'{"seq":7,"concept":"M2-2-u4-C1","difficulty":3,"kind":"mc","stem":"시각이 가장 늦은 것은 어느 것인가요?","options":[{"t":"3시 50분","correct":true},{"t":"3시 45분","mis":"M2-2-u4-X04"},{"t":"3시 10분","mis":"M2-2-u4-X16"},{"t":"2시 55분","mis":"M2-2-u4-X03"}],"explanation":["시가 같으면 분이 클수록 늦은 시각이에요.","2시 55분은 3시보다 이른 시각이에요.","그래서 3시 50분이 가장 늦어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_challenge#8','math',2,2,'u4','L02','g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C1',4,'essay','teacher','긴바늘이 숫자 7을 가리킬 때 몇 분인지 구하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u4-C1","difficulty":4,"kind":"essay","stem":"긴바늘이 숫자 7을 가리킬 때 몇 분인지 구하는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 숫자와 숫자 사이는 작은 눈금 5칸이라 5분이다. 숫자 7까지 5분씩 7번이므로 7 × 5 = 35분이다.","scoring_points":["숫자와 숫자 사이가 5분임을 썼는가","5씩 7번 또는 7 × 5로 셈했는가","35분이라고 구했는가"]},"explanation":["숫자와 숫자 사이는 5분이에요.","숫자 7까지는 5분씩 7번이에요.","7 × 5 = 35 — 35분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_challenge#9','math',2,2,'u4','L02','g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C1',4,'essay','teacher','연우는 이 시계를 보고 「7시 3분」이라고 읽었어요. 무엇이 잘못되었는지 설명하고 바른 시각을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u4-C1","difficulty":4,"kind":"essay","stem":"연우는 이 시계를 보고 「7시 3분」이라고 읽었어요. 무엇이 잘못되었는지 설명하고 바른 시각을 써 보세요.","answer_guide":{"answer":"예: 긴바늘이 가리키는 숫자 3을 그대로 3분으로 읽었다. 숫자 3은 3 × 5 = 15분이므로 바른 시각은 7시 15분이다.","scoring_points":["숫자를 그대로 분으로 읽은 잘못을 찾았는가","3 × 5 = 15를 셈했는가","7시 15분이라고 바르게 썼는가"]},"explanation":["짧은바늘이 7과 8 사이라 7시예요.","긴바늘 숫자 3은 15분이에요.","바른 시각은 7시 15분이에요."],"asset":{"type":"clock2","h":7,"m":15}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_challenge#10','math',2,2,'u4','L02','g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C2',4,'mc','auto','디지털시계와 같은 시각을 나타낸 바늘 시계는 어느 것인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X03','M2-2-u4-X01']::text[],false,'{"seq":10,"concept":"M2-2-u4-C2","difficulty":4,"kind":"mc","stem":"디지털시계와 같은 시각을 나타낸 바늘 시계는 어느 것인가요?","options":[{"t":"짧은바늘은 8과 9 사이, 긴바늘은 숫자 7","correct":true},{"t":"짧은바늘은 8과 9 사이, 긴바늘은 숫자 3과 4 사이","mis":"M2-2-u4-X02"},{"t":"짧은바늘은 7과 8 사이, 긴바늘은 숫자 7","mis":"M2-2-u4-X03"},{"t":"짧은바늘은 숫자 7, 긴바늘은 8과 9 사이","mis":"M2-2-u4-X01"}],"explanation":["디지털시계의 시각은 8시 35분이에요.","8시가 지났으니 짧은바늘은 8과 9 사이예요.","35분은 5 × 7 — 긴바늘은 숫자 7을 가리켜요."],"asset":{"type":"digital","h":8,"m":35}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_basic#1','math',2,2,'u4','L03','g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',1,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X04','M2-2-u4-X05']::text[],true,'{"seq":1,"concept":"M2-2-u4-C3","difficulty":1,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 1과 2 사이에 있으니 1시예요.","긴바늘이 숫자 2(10분)에서 작은 눈금 3칸 더 간 곳이니 10 + 3 = 13분이에요.","그래서 1시 13분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"options":[{"t":"1시 13분","correct":true},{"t":"1시 14분","mis":"M2-2-u4-X04"},{"t":"1시 17분","mis":"M2-2-u4-X05"}],"asset":{"type":"clock2","h":1,"m":13}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_basic#2','math',2,2,'u4','L03','g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',1,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X04','M2-2-u4-X05']::text[],true,'{"seq":2,"concept":"M2-2-u4-C3","difficulty":1,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 7과 8 사이에 있으니 7시예요.","긴바늘이 숫자 4(20분)에서 작은 눈금 2칸 더 간 곳이니 20 + 2 = 22분이에요.","그래서 7시 22분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"options":[{"t":"7시 22분","correct":true},{"t":"7시 23분","mis":"M2-2-u4-X04"},{"t":"7시 28분","mis":"M2-2-u4-X05"}],"asset":{"type":"clock2","h":7,"m":22}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_basic#3','math',2,2,'u4','L03','g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',1,'mc','auto','긴바늘이 작은 눈금 3칸을 움직이면 몇 분이 지나나요?',ARRAY['M2-2-u4-X02','M2-2-u4-X04']::text[],true,'{"seq":3,"concept":"M2-2-u4-C3","difficulty":1,"kind":"mc","stem":"긴바늘이 작은 눈금 3칸을 움직이면 몇 분이 지나나요?","options":[{"t":"3분","correct":true},{"t":"15분","mis":"M2-2-u4-X02"},{"t":"30분","mis":"M2-2-u4-X04"}],"explanation":["작은 눈금 한 칸은 1분이에요.","3칸이면 1분씩 3번이에요.","그래서 3분이 지나요."],"variant_rule":{"alt":[{"stem":"긴바늘이 작은 눈금 4칸을 움직이면 몇 분이 지나나요?","options":[{"t":"4분","correct":true},{"t":"20분","mis":"M2-2-u4-X02"},{"t":"40분","mis":"M2-2-u4-X04"}],"explanation":["작은 눈금 한 칸은 1분이에요.","4칸이면 1분씩 4번이에요.","그래서 4분이 지나요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_basic#4','math',2,2,'u4','L03','g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',1,'sa','auto','시계가 나타내는 시각은 3시 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M2-2-u4-C3","difficulty":1,"kind":"sa","stem":"시계가 나타내는 시각은 3시 몇 분인가요? 숫자로 쓰세요.","explanation":["짧은바늘이 3과 4 사이에 있으니 3시예요.","긴바늘이 숫자 7(35분)에서 작은 눈금 4칸 더 간 곳이니 35 + 4 = 39분이에요.","그래서 3시 39분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"answer":["39"],"asset":{"type":"clock2","h":3,"m":39}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_basic#5','math',2,2,'u4','L03','g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',2,'mc','auto','디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u4-X06','M2-2-u4-X04']::text[],true,'{"seq":5,"concept":"M2-2-u4-C3","difficulty":2,"kind":"mc","stem":"디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?","explanation":["「:」 왼쪽은 시, 오른쪽은 분이에요.","11 : 43은 11시 43분이에요.","시는 「열한 시」, 분은 「사십삼 분」으로 읽어요."],"variant_rule":{"tm":{"ask":"dig"}},"options":[{"t":"열한 시 사십삼 분","correct":true},{"t":"사십삼 시 열한 분","mis":"M2-2-u4-X06"},{"t":"십일 시 사십삼 분","mis":"M2-2-u4-X06"},{"t":"열한 시 사십 분","mis":"M2-2-u4-X04"}],"asset":{"type":"digital","h":11,"m":43}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_basic#6','math',2,2,'u4','L03','g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',2,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X04','M2-2-u4-X05','M2-2-u4-X03']::text[],true,'{"seq":6,"concept":"M2-2-u4-C3","difficulty":2,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 5와 6 사이에 있으니 5시예요.","긴바늘이 숫자 9(45분)에서 작은 눈금 3칸 더 간 곳이니 45 + 3 = 48분이에요.","그래서 5시 48분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"options":[{"t":"5시 48분","correct":true},{"t":"5시 49분","mis":"M2-2-u4-X04"},{"t":"5시 52분","mis":"M2-2-u4-X05"},{"t":"6시 48분","mis":"M2-2-u4-X03"}],"asset":{"type":"clock2","h":5,"m":48}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_basic#7','math',2,2,'u4','L03','g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',2,'mc','auto','긴바늘이 숫자 4(20분)에서 작은 눈금 2칸 더 간 곳을 가리켜요. 몇 분인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X05','M2-2-u4-X04']::text[],true,'{"seq":7,"concept":"M2-2-u4-C3","difficulty":2,"kind":"mc","stem":"긴바늘이 숫자 4(20분)에서 작은 눈금 2칸 더 간 곳을 가리켜요. 몇 분인가요?","options":[{"t":"22분","correct":true},{"t":"42분","mis":"M2-2-u4-X02"},{"t":"18분","mis":"M2-2-u4-X05"},{"t":"24분","mis":"M2-2-u4-X04"}],"explanation":["숫자 4는 20분이에요.","2칸 더 갔으니 20 + 2 = 22예요.","그래서 22분이에요."],"variant_rule":{"alt":[{"stem":"긴바늘이 숫자 8(40분)에서 작은 눈금 1칸 덜 간 곳을 가리켜요. 몇 분인가요?","options":[{"t":"39분","correct":true},{"t":"41분","mis":"M2-2-u4-X05"},{"t":"81분","mis":"M2-2-u4-X02"},{"t":"38분","mis":"M2-2-u4-X04"}],"explanation":["숫자 8은 40분이에요.","1칸 덜 갔으니 40 − 1 = 39예요.","그래서 39분이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_basic#8','math',2,2,'u4','L03','g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',2,'match','auto','긴바늘이 가리키는 같은 곳끼리 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M2-2-u4-C3","difficulty":2,"kind":"match","stem":"긴바늘이 가리키는 같은 곳끼리 이으세요.","pairs":[{"l":"숫자 2에서 4칸 더 간 곳","r":"숫자 3에서 1칸 덜 간 곳"},{"l":"숫자 5에서 3칸 더 간 곳","r":"숫자 6에서 2칸 덜 간 곳"},{"l":"숫자 9에서 1칸 더 간 곳","r":"숫자 10에서 4칸 덜 간 곳"}],"mis":"M2-2-u4-X05","explanation":["숫자와 숫자 사이는 5칸이에요.","4칸 더 간 곳은 다음 숫자에서 1칸 덜 간 곳이에요.","더 간 칸과 덜 간 칸을 합하면 5칸이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 긴바늘이 가리키는 같은 곳끼리 이으세요.","pairs":[{"l":"숫자 1에서 2칸 더 간 곳","r":"숫자 2에서 3칸 덜 간 곳"},{"l":"숫자 6에서 4칸 더 간 곳","r":"숫자 7에서 1칸 덜 간 곳"},{"l":"숫자 10에서 1칸 더 간 곳","r":"숫자 11에서 4칸 덜 간 곳"}],"explanation":["숫자와 숫자 사이는 5칸이에요.","2칸 더 간 곳은 다음 숫자에서 3칸 덜 간 곳이에요.","더 간 칸과 덜 간 칸을 합하면 5칸이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_basic#9','math',2,2,'u4','L03','g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',2,'ox','auto','긴바늘이 숫자 6에서 작은 눈금 2칸 더 간 곳을 가리키면 32분이에요.',ARRAY['M2-2-u4-X02']::text[],true,'{"seq":9,"concept":"M2-2-u4-C3","difficulty":2,"kind":"ox","stem":"긴바늘이 숫자 6에서 작은 눈금 2칸 더 간 곳을 가리키면 32분이에요.","answer":"O","reason_options":[{"t":"숫자 6은 30분이고 2칸 더 갔으니 30 + 2 = 32분이니까","correct":true},{"t":"숫자 6에서 2칸이니 6 + 2 = 8분이니까","mis":"M2-2-u4-X02"}],"mis":"M2-2-u4-X02","explanation":["숫자 6은 6 × 5 = 30분이에요.","2칸 더 갔으니 2분을 더해요.","30 + 2 = 32 — 32분이에요."],"variant_rule":{"alt":[{"stem":"긴바늘이 숫자 9에서 작은 눈금 3칸 더 간 곳을 가리키면 12분이에요.","answer":"X","reason_options":[{"t":"숫자 9는 45분이라 45 + 3 = 48분이니까","correct":true},{"t":"9 + 3 = 12라서 12분이니까","mis":"M2-2-u4-X02"}],"explanation":["숫자 9는 9 × 5 = 45분이에요.","3칸 더 갔으니 3분을 더해요.","45 + 3 = 48 — 12분이 아니라 48분이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_basic#10','math',2,2,'u4','L03','g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',3,'error','auto','시계를 보고 친구들이 시각을 읽었어요. 잘못 읽은 친구는 누구인가요?',ARRAY['M2-2-u4-X04','M2-2-u4-X16']::text[],true,'{"seq":10,"concept":"M2-2-u4-C3","difficulty":3,"kind":"error","stem":"시계를 보고 친구들이 시각을 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"도윤 — 「긴바늘이 4 근처니까 7시 20분이야.」","correct":true,"mis_target":"M2-2-u4-X04"},{"t":"은솔 — 「숫자 4에서 2칸 더 갔으니 7시 22분이야.」","mis":"M2-2-u4-X16"},{"t":"예린 — 「짧은바늘이 7과 8 사이라 7시야.」","mis":"M2-2-u4-X16"}],"explanation":["긴바늘은 숫자 4(20분)에서 작은 눈금 2칸 더 간 곳이에요.","20 + 2 = 22라서 7시 22분이에요.","도윤이는 2칸 더 간 것을 놓쳤어요."],"asset":{"type":"clock2","h":7,"m":22},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 시계를 보고 친구들이 시각을 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"하루 — 「긴바늘이 8 근처니까 2시 40분이야.」","correct":true,"mis_target":"M2-2-u4-X04"},{"t":"지우 — 「숫자 8에서 2칸 덜 갔으니 2시 38분이야.」","mis":"M2-2-u4-X16"},{"t":"서아 — 「짧은바늘이 2와 3 사이라 2시야.」","mis":"M2-2-u4-X16"}],"explanation":["긴바늘은 숫자 8(40분)에서 작은 눈금 2칸 덜 간 곳이에요.","40 − 2 = 38이라서 2시 38분이에요.","하루는 2칸 덜 간 것을 놓쳤어요."],"asset":{"type":"clock2","h":2,"m":38}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_challenge#1','math',2,2,'u4','L03','g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',2,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X04','M2-2-u4-X03']::text[],true,'{"seq":1,"concept":"M2-2-u4-C3","difficulty":2,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 9와 10 사이에 있으니 9시예요.","긴바늘이 숫자 11(55분)에서 작은 눈금 2칸 더 간 곳이니 55 + 2 = 57분이에요.","그래서 9시 57분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"options":[{"t":"9시 57분","correct":true},{"t":"9시 58분","mis":"M2-2-u4-X04"},{"t":"10시 57분","mis":"M2-2-u4-X03"},{"t":"9시 50분","mis":"M2-2-u4-X04"}],"asset":{"type":"clock2","h":9,"m":57}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_challenge#2','math',2,2,'u4','L03','g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',2,'sa','auto','시계가 나타내는 시각은 4시 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u4-C3","difficulty":2,"kind":"sa","stem":"시계가 나타내는 시각은 4시 몇 분인가요? 숫자로 쓰세요.","explanation":["짧은바늘이 4와 5 사이에 있으니 4시예요.","긴바늘이 숫자 5(25분)에서 작은 눈금 3칸 더 간 곳이니 25 + 3 = 28분이에요.","그래서 4시 28분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"answer":["28"],"asset":{"type":"clock2","h":4,"m":28}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_challenge#3','math',2,2,'u4','L03','g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',3,'mc','auto','긴바늘이 숫자 9에서 작은 눈금 4칸 더 간 곳은 숫자 10에서 몇 칸 덜 간 곳과 같나요?',ARRAY['M2-2-u4-X05','M2-2-u4-X04','M2-2-u4-X10']::text[],false,'{"seq":3,"concept":"M2-2-u4-C3","difficulty":3,"kind":"mc","stem":"긴바늘이 숫자 9에서 작은 눈금 4칸 더 간 곳은 숫자 10에서 몇 칸 덜 간 곳과 같나요?","options":[{"t":"1칸","correct":true},{"t":"4칸","mis":"M2-2-u4-X05"},{"t":"5칸","mis":"M2-2-u4-X04"},{"t":"2칸","mis":"M2-2-u4-X10"}],"explanation":["숫자와 숫자 사이는 작은 눈금 5칸이에요.","9에서 4칸 더 갔으니 10까지 1칸 남았어요.","그래서 숫자 10에서 1칸 덜 간 곳이에요 — 49분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_challenge#4','math',2,2,'u4','L03','g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',3,'mc','auto','짧은바늘은 3과 4 사이, 긴바늘은 7에서 작은 눈금 2칸 더 간 곳이에요. 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X03','M2-2-u4-X05']::text[],false,'{"seq":4,"concept":"M2-2-u4-C3","difficulty":3,"kind":"mc","stem":"짧은바늘은 3과 4 사이, 긴바늘은 7에서 작은 눈금 2칸 더 간 곳이에요. 몇 시 몇 분인가요?","options":[{"t":"3시 37분","correct":true},{"t":"3시 9분","mis":"M2-2-u4-X02"},{"t":"4시 37분","mis":"M2-2-u4-X03"},{"t":"3시 33분","mis":"M2-2-u4-X05"}],"explanation":["짧은바늘이 3과 4 사이라 3시예요.","숫자 7은 35분, 2칸 더 가서 37분이에요.","그래서 3시 37분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_challenge#5','math',2,2,'u4','L03','g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',3,'mc','auto','디지털시계의 시각을 바늘 시계로 나타낼 때 긴바늘은 어디를 가리키나요?',ARRAY['M2-2-u4-X02','M2-2-u4-X04','M2-2-u4-X05']::text[],false,'{"seq":5,"concept":"M2-2-u4-C3","difficulty":3,"kind":"mc","stem":"디지털시계의 시각을 바늘 시계로 나타낼 때 긴바늘은 어디를 가리키나요?","options":[{"t":"숫자 8에서 작은 눈금 3칸 더 간 곳","correct":true},{"t":"숫자 4와 3 사이","mis":"M2-2-u4-X02"},{"t":"숫자 9에서 작은 눈금 3칸 더 간 곳","mis":"M2-2-u4-X04"},{"t":"숫자 8에서 작은 눈금 3칸 덜 간 곳","mis":"M2-2-u4-X05"}],"explanation":["디지털시계의 시각은 11시 43분이에요.","40분은 숫자 8이고 3분이 더 있어요.","그래서 숫자 8에서 3칸 더 간 곳이에요."],"asset":{"type":"digital","h":11,"m":43}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_challenge#6','math',2,2,'u4','L03','g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',3,'mc','auto','시각이 가장 이른 것은 어느 것인가요?',ARRAY['M2-2-u4-X16']::text[],false,'{"seq":6,"concept":"M2-2-u4-C3","difficulty":3,"kind":"mc","stem":"시각이 가장 이른 것은 어느 것인가요?","options":[{"t":"6시 48분","correct":true},{"t":"6시 52분","mis":"M2-2-u4-X16"},{"t":"7시 3분","mis":"M2-2-u4-X16"},{"t":"6시 55분","mis":"M2-2-u4-X16"}],"explanation":["시가 같으면 분이 작을수록 이른 시각이에요.","6시 48분, 6시 52분, 6시 55분, 7시 3분 차례로 늦어져요.","그래서 6시 48분이 가장 일러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_challenge#7','math',2,2,'u4','L03','g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',3,'ox','auto','긴바늘이 숫자 5에서 작은 눈금 4칸 더 간 곳과 숫자 6에서 작은 눈금 1칸 덜 간 곳은 같아요.',ARRAY['M2-2-u4-X05']::text[],false,'{"seq":7,"concept":"M2-2-u4-C3","difficulty":3,"kind":"ox","stem":"긴바늘이 숫자 5에서 작은 눈금 4칸 더 간 곳과 숫자 6에서 작은 눈금 1칸 덜 간 곳은 같아요.","answer":"O","reason_options":[{"t":"25 + 4 = 29, 30 − 1 = 29로 같은 곳이니까","correct":true},{"t":"더 간 곳과 덜 간 곳은 언제나 다른 곳이니까","mis":"M2-2-u4-X05"}],"mis":"M2-2-u4-X05","explanation":["숫자 5는 25분이라 4칸 더 가면 29분이에요.","숫자 6은 30분이라 1칸 덜 가면 29분이에요.","둘 다 29분 — 같은 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_challenge#8','math',2,2,'u4','L03','g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',4,'essay','teacher','긴바늘이 숫자 8에서 작은 눈금 1칸 덜 간 곳을 가리켜요. 몇 분인지 두 가지 방법으로 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u4-C3","difficulty":4,"kind":"essay","stem":"긴바늘이 숫자 8에서 작은 눈금 1칸 덜 간 곳을 가리켜요. 몇 분인지 두 가지 방법으로 설명해 보세요.","answer_guide":{"answer":"예: 숫자 8은 40분이고 1칸 덜 갔으니 40 − 1 = 39분이다. 숫자 7(35분)에서 4칸 더 간 곳이므로 35 + 4 = 39분이다.","scoring_points":["40 − 1로 구했는가","35 + 4로 구했는가","39분이라고 구했는가"]},"explanation":["숫자 8에서 거꾸로 1칸 — 40 − 1 = 39예요.","숫자 7에서 앞으로 4칸 — 35 + 4 = 39예요.","두 방법 모두 39분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_challenge#9','math',2,2,'u4','L03','g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',4,'essay','teacher','4시 28분을 시계에 나타내려고 해요. 짧은바늘과 긴바늘을 어디에 그려야 하는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u4-C3","difficulty":4,"kind":"essay","stem":"4시 28분을 시계에 나타내려고 해요. 짧은바늘과 긴바늘을 어디에 그려야 하는지 설명해 보세요.","answer_guide":{"answer":"예: 짧은바늘은 4와 5 사이에 그린다. 28분은 숫자 5(25분)에서 3칸 더 간 곳이므로 긴바늘은 숫자 5에서 작은 눈금 3칸 더 간 곳에 그린다.","scoring_points":["짧은바늘을 4와 5 사이에 그린다고 썼는가","28분이 숫자 5에서 3칸 더 간 곳임을 썼는가","긴바늘의 자리를 바르게 썼는가"]},"explanation":["4시가 지났으니 짧은바늘은 4와 5 사이예요.","28 = 25 + 3이에요.","긴바늘은 숫자 5에서 3칸 더 간 곳이에요."],"asset":{"type":"clock2","h":4,"m":28}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_challenge#10','math',2,2,'u4','L03','g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',4,'mc','auto','시각 읽기 놀이에서 지아는 2시 17분을 나타냈어요. 세미는 지아보다 긴바늘을 작은 눈금 5칸 더 돌렸어요. 세미가 나타낸 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X16','M2-2-u4-X02','M2-2-u4-X03']::text[],false,'{"seq":10,"concept":"M2-2-u4-C3","difficulty":4,"kind":"mc","stem":"시각 읽기 놀이에서 지아는 2시 17분을 나타냈어요. 세미는 지아보다 긴바늘을 작은 눈금 5칸 더 돌렸어요. 세미가 나타낸 시각은 몇 시 몇 분인가요?","options":[{"t":"2시 22분","correct":true},{"t":"2시 12분","mis":"M2-2-u4-X16"},{"t":"2시 42분","mis":"M2-2-u4-X02"},{"t":"3시 17분","mis":"M2-2-u4-X03"}],"explanation":["작은 눈금 5칸은 5분이에요.","2시 17분에서 5분이 지나면 2시 22분이에요.","긴바늘을 더 돌렸으니 시각이 늦어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_basic#1','math',2,2,'u4','L04','g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',1,'mc','auto','시계가 나타내는 시각은 몇 시 몇 분 전인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],true,'{"seq":1,"concept":"M2-2-u4-C4","difficulty":1,"kind":"mc","stem":"시계가 나타내는 시각은 몇 시 몇 분 전인가요?","explanation":["8시 55분에서 5분이 지나면 9시가 돼요.","그래서 8시 55분을 9시 5분 전이라고도 해요.","「몇 시 전」의 시는 곧 될 정각 9시예요 — 지금 시 8시가 아니에요."],"variant_rule":{"tm":{"ask":"before","form":"clock"}},"options":[{"t":"9시 5분 전","correct":true},{"t":"8시 5분 전","mis":"M2-2-u4-X07"},{"t":"9시 55분 전","mis":"M2-2-u4-X08"}],"asset":{"type":"clock2","h":8,"m":55}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_basic#2','math',2,2,'u4','L04','g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',1,'sa','auto','3시 50분은 4시 몇 분 전인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u4-C4","difficulty":1,"kind":"sa","stem":"3시 50분은 4시 몇 분 전인가요? 숫자로 쓰세요.","explanation":["3시 50분에서 10분이 지나면 4시가 돼요.","그래서 3시 50분을 4시 10분 전이라고도 해요.","「몇 시 전」의 시는 곧 될 정각 4시예요 — 지금 시 3시가 아니에요."],"variant_rule":{"tm":{"ask":"before"}},"answer":["10"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_basic#3','math',2,2,'u4','L04','g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',1,'mc','auto','7시 5분 전은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],true,'{"seq":3,"concept":"M2-2-u4-C4","difficulty":1,"kind":"mc","stem":"7시 5분 전은 몇 시 몇 분인가요?","explanation":["7시 5분 전은 7시가 되기 5분 전이에요.","7시에서 긴바늘을 5분만큼 거꾸로 돌리면 6시 55분이에요.","짧은바늘은 아직 6과 7 사이에 있어서 6시예요."],"variant_rule":{"tm":{"ask":"beforer"}},"options":[{"t":"6시 55분","correct":true},{"t":"7시 55분","mis":"M2-2-u4-X07"},{"t":"7시 5분","mis":"M2-2-u4-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_basic#4','math',2,2,'u4','L04','g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',1,'mc','auto','8시 55분에서 몇 분이 지나면 9시가 되나요?',ARRAY['M2-2-u4-X08','M2-2-u4-X04']::text[],true,'{"seq":4,"concept":"M2-2-u4-C4","difficulty":1,"kind":"mc","stem":"8시 55분에서 몇 분이 지나면 9시가 되나요?","options":[{"t":"5분","correct":true},{"t":"55분","mis":"M2-2-u4-X08"},{"t":"10분","mis":"M2-2-u4-X04"}],"explanation":["긴바늘이 숫자 11에서 12까지 가면 9시예요.","숫자 11에서 12까지는 5칸 — 5분이에요.","그래서 5분이 지나면 9시가 돼요."],"variant_rule":{"alt":[{"stem":"3시 50분에서 몇 분이 지나면 4시가 되나요?","options":[{"t":"10분","correct":true},{"t":"50분","mis":"M2-2-u4-X08"},{"t":"5분","mis":"M2-2-u4-X04"}],"explanation":["긴바늘이 숫자 10에서 12까지 가면 4시예요.","숫자 10에서 12까지는 10칸 — 10분이에요.","그래서 10분이 지나면 4시가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_basic#5','math',2,2,'u4','L04','g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',2,'mc','auto','시계가 나타내는 시각은 몇 시 몇 분 전인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08','M2-2-u4-X04']::text[],true,'{"seq":5,"concept":"M2-2-u4-C4","difficulty":2,"kind":"mc","stem":"시계가 나타내는 시각은 몇 시 몇 분 전인가요?","explanation":["5시 55분에서 5분이 지나면 6시가 돼요.","그래서 5시 55분을 6시 5분 전이라고도 해요.","「몇 시 전」의 시는 곧 될 정각 6시예요 — 지금 시 5시가 아니에요."],"variant_rule":{"tm":{"ask":"before","form":"clock"}},"options":[{"t":"6시 5분 전","correct":true},{"t":"5시 5분 전","mis":"M2-2-u4-X07"},{"t":"6시 55분 전","mis":"M2-2-u4-X08"},{"t":"6시 10분 전","mis":"M2-2-u4-X04"}],"asset":{"type":"clock2","h":5,"m":55}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_basic#6','math',2,2,'u4','L04','g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',2,'mc','auto','10시 10분 전은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],true,'{"seq":6,"concept":"M2-2-u4-C4","difficulty":2,"kind":"mc","stem":"10시 10분 전은 몇 시 몇 분인가요?","explanation":["10시 10분 전은 10시가 되기 10분 전이에요.","10시에서 긴바늘을 10분만큼 거꾸로 돌리면 9시 50분이에요.","짧은바늘은 아직 9와 10 사이에 있어서 9시예요."],"variant_rule":{"tm":{"ask":"beforer"}},"options":[{"t":"9시 50분","correct":true},{"t":"10시 50분","mis":"M2-2-u4-X07"},{"t":"10시 10분","mis":"M2-2-u4-X08"},{"t":"9시 10분","mis":"M2-2-u4-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_basic#7','math',2,2,'u4','L04','g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',2,'ox','auto','10시 55분은 10시 5분 전이에요.',ARRAY['M2-2-u4-X07']::text[],true,'{"seq":7,"concept":"M2-2-u4-C4","difficulty":2,"kind":"ox","stem":"10시 55분은 10시 5분 전이에요.","answer":"X","reason_options":[{"t":"10시 55분에서 5분이 지나면 11시라서 11시 5분 전이니까","correct":true},{"t":"지금 짧은바늘이 10과 11 사이라 10시 5분 전이니까","mis":"M2-2-u4-X07"}],"mis":"M2-2-u4-X07","explanation":["10시 55분에서 5분이 지나면 11시가 돼요.","「몇 시 전」의 시는 곧 될 정각이에요.","그래서 10시 55분은 11시 5분 전이에요."],"asset":{"type":"clock2","h":10,"m":55},"variant_rule":{"alt":[{"stem":"1시 50분은 2시 10분 전이에요.","answer":"O","reason_options":[{"t":"1시 50분에서 10분이 지나면 2시가 되니까","correct":true},{"t":"1시 50분은 1시 10분 전이니까","mis":"M2-2-u4-X07"}],"explanation":["1시 50분에서 10분이 지나면 2시가 돼요.","「몇 시 전」의 시는 곧 될 정각 2시예요.","그래서 바른 말이에요."],"asset":{"type":"clock2","h":1,"m":50}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_basic#8','math',2,2,'u4','L04','g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',2,'match','auto','같은 시각끼리 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M2-2-u4-C4","difficulty":2,"kind":"match","stem":"같은 시각끼리 이으세요.","pairs":[{"l":"8시 55분","r":"9시 5분 전"},{"l":"3시 50분","r":"4시 10분 전"},{"l":"6시 45분","r":"7시 15분 전"}],"mis":"M2-2-u4-X07","explanation":["8시 55분에서 5분 지나면 9시예요.","3시 50분에서 10분 지나면 4시예요.","6시 45분에서 15분 지나면 7시예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 같은 시각끼리 이으세요.","pairs":[{"l":"11시 55분","r":"12시 5분 전"},{"l":"5시 50분","r":"6시 10분 전"},{"l":"1시 45분","r":"2시 15분 전"}],"explanation":["11시 55분에서 5분 지나면 12시예요.","5시 50분에서 10분 지나면 6시예요.","1시 45분에서 15분 지나면 2시예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_basic#9','math',2,2,'u4','L04','g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',2,'sa','auto','1시 45분은 2시 몇 분 전인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M2-2-u4-C4","difficulty":2,"kind":"sa","stem":"1시 45분은 2시 몇 분 전인가요? 숫자로 쓰세요.","explanation":["1시 45분에서 15분이 지나면 2시가 돼요.","그래서 1시 45분을 2시 15분 전이라고도 해요.","「몇 시 전」의 시는 곧 될 정각 2시예요 — 지금 시 1시가 아니에요."],"variant_rule":{"tm":{"ask":"before"}},"answer":["15"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_basic#10','math',2,2,'u4','L04','g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',3,'error','auto','시계의 시각을 다른 방법으로 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X16']::text[],true,'{"seq":10,"concept":"M2-2-u4-C4","difficulty":3,"kind":"error","stem":"시계의 시각을 다른 방법으로 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하루 — 「9시 5분 전이야.」","correct":true,"mis_target":"M2-2-u4-X07"},{"t":"지우 — 「10시 5분 전이야.」","mis":"M2-2-u4-X16"},{"t":"서아 — 「5분이 지나면 10시가 돼.」","mis":"M2-2-u4-X16"}],"explanation":["시계의 시각은 9시 55분이에요.","5분이 지나면 10시가 되니 10시 5분 전이에요.","하루는 곧 될 정각이 아니라 지금 시 9시를 썼어요."],"asset":{"type":"clock2","h":9,"m":55},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 시계의 시각을 다른 방법으로 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「4시 10분 전이야.」","correct":true,"mis_target":"M2-2-u4-X07"},{"t":"은솔 — 「5시 10분 전이야.」","mis":"M2-2-u4-X16"},{"t":"예린 — 「10분이 지나면 5시가 돼.」","mis":"M2-2-u4-X16"}],"explanation":["시계의 시각은 4시 50분이에요.","10분이 지나면 5시가 되니 5시 10분 전이에요.","도윤이는 곧 될 정각이 아니라 지금 시 4시를 썼어요."],"asset":{"type":"clock2","h":4,"m":50}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_challenge#1','math',2,2,'u4','L04','g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',2,'mc','auto','시계가 나타내는 시각은 몇 시 몇 분 전인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08','M2-2-u4-X04']::text[],true,'{"seq":1,"concept":"M2-2-u4-C4","difficulty":2,"kind":"mc","stem":"시계가 나타내는 시각은 몇 시 몇 분 전인가요?","explanation":["10시 50분에서 10분이 지나면 11시가 돼요.","그래서 10시 50분을 11시 10분 전이라고도 해요.","「몇 시 전」의 시는 곧 될 정각 11시예요 — 지금 시 10시가 아니에요."],"variant_rule":{"tm":{"ask":"before","form":"clock"}},"options":[{"t":"11시 10분 전","correct":true},{"t":"10시 10분 전","mis":"M2-2-u4-X07"},{"t":"11시 50분 전","mis":"M2-2-u4-X08"},{"t":"11시 15분 전","mis":"M2-2-u4-X04"}],"asset":{"type":"clock2","h":10,"m":50}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_challenge#2','math',2,2,'u4','L04','g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',2,'mc','auto','8시 10분 전은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],true,'{"seq":2,"concept":"M2-2-u4-C4","difficulty":2,"kind":"mc","stem":"8시 10분 전은 몇 시 몇 분인가요?","explanation":["8시 10분 전은 8시가 되기 10분 전이에요.","8시에서 긴바늘을 10분만큼 거꾸로 돌리면 7시 50분이에요.","짧은바늘은 아직 7과 8 사이에 있어서 7시예요."],"variant_rule":{"tm":{"ask":"beforer"}},"options":[{"t":"7시 50분","correct":true},{"t":"8시 50분","mis":"M2-2-u4-X07"},{"t":"8시 10분","mis":"M2-2-u4-X08"},{"t":"7시 10분","mis":"M2-2-u4-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_challenge#3','math',2,2,'u4','L04','g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',3,'mc','auto','슬기는 「8시 10분 전이야. 학교에 가려면 서둘러야지.」라고 했어요. 지금 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X08','M2-2-u4-X07']::text[],false,'{"seq":3,"concept":"M2-2-u4-C4","difficulty":3,"kind":"mc","stem":"슬기는 「8시 10분 전이야. 학교에 가려면 서둘러야지.」라고 했어요. 지금 시각은 몇 시 몇 분인가요?","options":[{"t":"7시 50분","correct":true},{"t":"8시 10분","mis":"M2-2-u4-X08"},{"t":"8시 50분","mis":"M2-2-u4-X07"},{"t":"7시 10분","mis":"M2-2-u4-X08"}],"explanation":["8시 10분 전은 8시가 되기 10분 전이에요.","8시에서 10분 거꾸로 가면 7시 50분이에요.","그래서 지금은 7시 50분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_challenge#4','math',2,2,'u4','L04','g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',3,'mc','auto','「벌써 4시 55분인가?」 하고 시계를 보았어요. 이 시각을 「몇 시 몇 분 전」으로 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08','M2-2-u4-X03']::text[],false,'{"seq":4,"concept":"M2-2-u4-C4","difficulty":3,"kind":"mc","stem":"「벌써 4시 55분인가?」 하고 시계를 보았어요. 이 시각을 「몇 시 몇 분 전」으로 바르게 말한 것은 어느 것인가요?","options":[{"t":"5시 5분 전","correct":true},{"t":"4시 5분 전","mis":"M2-2-u4-X07"},{"t":"5시 55분 전","mis":"M2-2-u4-X08"},{"t":"6시 5분 전","mis":"M2-2-u4-X03"}],"explanation":["짧은바늘이 4와 5 사이라 4시 55분이에요.","5분이 지나면 5시가 돼요.","그래서 5시 5분 전이에요."],"asset":{"type":"clock2","h":4,"m":55}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_challenge#5','math',2,2,'u4','L04','g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',3,'mc','auto','7시 5분 전을 시계에 나타낼 때 긴바늘이 가리키는 숫자는 무엇인가요?',ARRAY['M2-2-u4-X08','M2-2-u4-X02']::text[],false,'{"seq":5,"concept":"M2-2-u4-C4","difficulty":3,"kind":"mc","stem":"7시 5분 전을 시계에 나타낼 때 긴바늘이 가리키는 숫자는 무엇인가요?","options":[{"t":"11","correct":true},{"t":"1","mis":"M2-2-u4-X08"},{"t":"7","mis":"M2-2-u4-X02"},{"t":"5","mis":"M2-2-u4-X02"}],"explanation":["7시 5분 전은 6시 55분이에요.","55분은 5 × 11이에요.","그래서 긴바늘은 숫자 11을 가리켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_challenge#6','math',2,2,'u4','L04','g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',3,'mc','auto','같은 시각끼리 바르게 짝 지은 것은 어느 것인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],false,'{"seq":6,"concept":"M2-2-u4-C4","difficulty":3,"kind":"mc","stem":"같은 시각끼리 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"2시 45분 — 3시 15분 전","correct":true},{"t":"2시 45분 — 2시 15분 전","mis":"M2-2-u4-X07"},{"t":"2시 45분 — 3시 45분 전","mis":"M2-2-u4-X08"}],"explanation":["2시 45분에서 15분이 지나면 3시예요.","그래서 2시 45분은 3시 15분 전이에요.","「전」의 시는 곧 될 정각이고, 분은 정각까지 남은 분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_challenge#7','math',2,2,'u4','L04','g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',3,'ox','auto','「11시 10분 전」과 「11시 10분」은 같은 시각이에요.',ARRAY['M2-2-u4-X08']::text[],false,'{"seq":7,"concept":"M2-2-u4-C4","difficulty":3,"kind":"ox","stem":"「11시 10분 전」과 「11시 10분」은 같은 시각이에요.","answer":"X","reason_options":[{"t":"11시 10분 전은 10시 50분이라 11시 10분과 다른 시각이니까","correct":true},{"t":"「전」은 붙여도 안 붙여도 같은 뜻이니까","mis":"M2-2-u4-X08"}],"mis":"M2-2-u4-X08","explanation":["11시 10분 전은 11시가 되기 10분 전 — 10시 50분이에요.","11시 10분은 11시에서 10분 지난 시각이에요.","「몇 시 몇 분 전」과 「몇 시 몇 분」은 같은 시각이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_challenge#8','math',2,2,'u4','L04','g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',4,'essay','teacher','5시 55분을 「몇 시 몇 분 전」으로 나타내는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u4-C4","difficulty":4,"kind":"essay","stem":"5시 55분을 「몇 시 몇 분 전」으로 나타내는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 5시 55분에서 5분이 지나면 6시가 된다. 「몇 시 전」의 시는 곧 될 정각이므로 5시 55분은 6시 5분 전이다.","scoring_points":["5분이 지나면 6시가 됨을 썼는가","곧 될 정각 6시를 썼는가","6시 5분 전이라고 나타냈는가"]},"explanation":["정각이 되기까지 몇 분 남았는지 세어요.","5분 남았고 곧 될 정각은 6시예요.","그래서 6시 5분 전이에요."],"asset":{"type":"clock2","h":5,"m":55}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_challenge#9','math',2,2,'u4','L04','g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',4,'essay','teacher','세미는 이 시계를 보고 「1시 10분 전」이라고 했어요. 잘못된 점을 설명하고 바르게 고쳐 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u4-C4","difficulty":4,"kind":"essay","stem":"세미는 이 시계를 보고 「1시 10분 전」이라고 했어요. 잘못된 점을 설명하고 바르게 고쳐 보세요.","answer_guide":{"answer":"예: 시계의 시각은 1시 50분이다. 10분이 지나면 2시가 되므로 2시 10분 전이다. 세미는 곧 될 정각이 아니라 지금 시를 썼다.","scoring_points":["시계의 시각 1시 50분을 읽었는가","곧 될 정각이 2시임을 썼는가","2시 10분 전으로 고쳤는가"]},"explanation":["시계의 시각은 1시 50분이에요.","10분이 지나면 2시예요.","그래서 2시 10분 전이에요."],"asset":{"type":"clock2","h":1,"m":50}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_challenge#10','math',2,2,'u4','L04','g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',4,'mc','auto','영화가 3시 10분 전에 시작해요. 지금이 2시 35분이라면 영화가 시작하기까지 몇 분 남았나요?',ARRAY['M2-2-u4-X08','M2-2-u4-X10']::text[],false,'{"seq":10,"concept":"M2-2-u4-C4","difficulty":4,"kind":"mc","stem":"영화가 3시 10분 전에 시작해요. 지금이 2시 35분이라면 영화가 시작하기까지 몇 분 남았나요?","options":[{"t":"15분","correct":true},{"t":"35분","mis":"M2-2-u4-X08"},{"t":"10분","mis":"M2-2-u4-X08"},{"t":"25분","mis":"M2-2-u4-X10"}],"explanation":["3시 10분 전은 2시 50분이에요.","2시 35분에서 2시 50분까지는 15분이에요.","「전」을 빼고 3시 10분까지 세면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_basic#1','math',2,2,'u4','L05','g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',1,'mc','auto','긴바늘이 시계를 한 바퀴 도는 데 걸리는 시간은 몇 분인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X09']::text[],true,'{"seq":1,"concept":"M2-2-u4-C5","difficulty":1,"kind":"mc","stem":"긴바늘이 시계를 한 바퀴 도는 데 걸리는 시간은 몇 분인가요?","options":[{"t":"60분","correct":true},{"t":"12분","mis":"M2-2-u4-X02"},{"t":"100분","mis":"M2-2-u4-X09"}],"explanation":["긴바늘이 작은 눈금 한 칸을 가는 데 1분이 걸려요.","시계 한 바퀴에는 작은 눈금이 60칸 있어요.","그래서 한 바퀴는 60분이에요."],"variant_rule":{"alt":[{"stem":"60분은 몇 시간인가요?","options":[{"t":"1시간","correct":true},{"t":"6시간","mis":"M2-2-u4-X09"},{"t":"10시간","mis":"M2-2-u4-X09"}],"explanation":["긴바늘이 한 바퀴 도는 데 60분이 걸려요.","그동안 짧은바늘은 숫자 한 칸을 가요.","그래서 60분은 1시간이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_basic#2','math',2,2,'u4','L05','g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',1,'sa','auto','책 읽기를 한 시간을 시간 띠에 나타냈어요. 책 읽기를 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u4-C5","difficulty":1,"kind":"sa","stem":"책 읽기를 한 시간을 시간 띠에 나타냈어요. 책 읽기를 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.","explanation":["시작한 시각은 10시 30분, 끝난 시각은 11시 30분이에요.","칠한 칸이 6칸 — 한 칸이 10분이니 60분이에요.","1시간은 60분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"bar"}},"answer":["60"],"asset":{"type":"tbar","from":[10,30],"to":[11,30],"label":"책 읽기를 한 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_basic#3','math',2,2,'u4','L05','g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',1,'sa','auto','1시 30분에서 5시 30분이 될 때까지 긴바늘은 몇 바퀴 돌았나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u4-C5","difficulty":1,"kind":"sa","stem":"1시 30분에서 5시 30분이 될 때까지 긴바늘은 몇 바퀴 돌았나요? 숫자로 쓰세요.","explanation":["긴바늘이 한 바퀴 돌면 60분 — 1시간이 지나요.","1시 30분부터 5시 30분까지 4시간이 지났어요.","그래서 긴바늘은 4바퀴 돌았어요."],"variant_rule":{"tm":{"ask":"laps"}},"answer":["4"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_basic#4','math',2,2,'u4','L05','g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',1,'mc','auto','5시에 출발해서 6시에 도착했어요. 그동안 짧은바늘은 어떻게 움직였나요?',ARRAY['M2-2-u4-X01','M2-2-u4-X11']::text[],true,'{"seq":4,"concept":"M2-2-u4-C5","difficulty":1,"kind":"mc","stem":"5시에 출발해서 6시에 도착했어요. 그동안 짧은바늘은 어떻게 움직였나요?","options":[{"t":"5에서 6으로 숫자 한 칸 갔어요","correct":true},{"t":"한 바퀴 돌았어요","mis":"M2-2-u4-X01"},{"t":"움직이지 않았어요","mis":"M2-2-u4-X11"}],"explanation":["5시에서 6시까지는 1시간이에요.","1시간 동안 긴바늘은 한 바퀴 돌아요.","짧은바늘은 숫자 한 칸 — 5에서 6으로 가요."],"variant_rule":{"alt":[{"stem":"5시에 출발해서 6시에 도착했어요. 그동안 긴바늘은 어떻게 움직였나요?","options":[{"t":"한 바퀴 돌았어요","correct":true},{"t":"5에서 6으로 숫자 한 칸 갔어요","mis":"M2-2-u4-X01"},{"t":"숫자 12에 멈춰 있었어요","mis":"M2-2-u4-X11"}],"explanation":["5시에서 6시까지는 1시간이에요.","1시간은 60분 — 긴바늘이 한 바퀴 도는 시간이에요.","그래서 긴바늘은 한 바퀴 돌았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_basic#5','math',2,2,'u4','L05','g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',2,'sa','auto','수영을 한 시간을 시간 띠에 나타냈어요. 수영을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-2-u4-C5","difficulty":2,"kind":"sa","stem":"수영을 한 시간을 시간 띠에 나타냈어요. 수영을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.","explanation":["시작한 시각은 9시, 끝난 시각은 11시예요.","칠한 칸이 12칸 — 한 칸이 10분이니 120분이에요.","2시간은 60분씩 2번 — 120분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"bar"}},"answer":["120"],"asset":{"type":"tbar","from":[9,0],"to":[11,0],"label":"수영을 한 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_basic#6','math',2,2,'u4','L05','g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',2,'mc','auto','2시간은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":6,"concept":"M2-2-u4-C5","difficulty":2,"kind":"mc","stem":"2시간은 몇 분인가요?","options":[{"t":"120분","correct":true},{"t":"200분","mis":"M2-2-u4-X09"},{"t":"20분","mis":"M2-2-u4-X09"},{"t":"60분","mis":"M2-2-u4-X10"}],"explanation":["1시간은 60분이에요.","2시간은 60분이 2번이에요.","60 + 60 = 120 — 120분이에요."],"variant_rule":{"alt":[{"stem":"120분은 몇 시간인가요?","options":[{"t":"2시간","correct":true},{"t":"12시간","mis":"M2-2-u4-X09"},{"t":"1시간","mis":"M2-2-u4-X10"},{"t":"20시간","mis":"M2-2-u4-X09"}],"explanation":["60분은 1시간이에요.","120분은 60분이 2번이에요.","그래서 2시간이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_basic#7','math',2,2,'u4','L05','g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',2,'mc','auto','3시에서 5시가 될 때까지 긴바늘은 몇 바퀴 돌았나요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],true,'{"seq":7,"concept":"M2-2-u4-C5","difficulty":2,"kind":"mc","stem":"3시에서 5시가 될 때까지 긴바늘은 몇 바퀴 돌았나요?","explanation":["긴바늘이 한 바퀴 돌면 60분 — 1시간이 지나요.","3시부터 5시까지 2시간이 지났어요.","그래서 긴바늘은 2바퀴 돌았어요."],"variant_rule":{"tm":{"ask":"laps"}},"options":[{"t":"2바퀴","correct":true},{"t":"5바퀴","mis":"M2-2-u4-X11"},{"t":"3바퀴","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_basic#8','math',2,2,'u4','L05','g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',2,'ox','auto','시간 띠 한 칸이 10분이면, 6칸은 1시간이에요.',ARRAY['M2-2-u4-X10']::text[],true,'{"seq":8,"concept":"M2-2-u4-C5","difficulty":2,"kind":"ox","stem":"시간 띠 한 칸이 10분이면, 6칸은 1시간이에요.","answer":"O","reason_options":[{"t":"10분씩 6칸이면 60분이고 60분은 1시간이니까","correct":true},{"t":"6칸이니 6분이니까","mis":"M2-2-u4-X10"}],"mis":"M2-2-u4-X10","explanation":["한 칸이 10분이에요.","6칸이면 10 + 10 + 10 + 10 + 10 + 10 = 60분이에요.","60분은 1시간이라 바른 말이에요."],"variant_rule":{"alt":[{"stem":"시간 띠 한 칸이 10분일 때, 8칸이 칠해져 있으면 8분이에요.","answer":"X","reason_options":[{"t":"10분씩 8칸이면 80분이니까","correct":true},{"t":"칠한 칸 수가 곧 분이니까","mis":"M2-2-u4-X10"}],"explanation":["한 칸이 10분이에요.","8칸이면 10분이 8번 — 80분이에요.","8분이 아니라 80분이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_basic#9','math',2,2,'u4','L05','g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',2,'mc','auto','수영을 시작한 시각과 끝난 시각이에요. 수영을 하는 데 걸린 시간은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":9,"concept":"M2-2-u4-C5","difficulty":2,"kind":"mc","stem":"수영을 시작한 시각과 끝난 시각이에요. 수영을 하는 데 걸린 시간은 몇 분인가요?","explanation":["시작한 시각은 10시 30분, 끝난 시각은 11시 30분이에요.","10시 30분에서 긴바늘이 1바퀴 돌면 11시 30분이에요 — 1시간이에요.","1시간은 60분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"pair"}},"options":[{"t":"60분","correct":true},{"t":"100분","mis":"M2-2-u4-X09"},{"t":"70분","mis":"M2-2-u4-X10"}],"asset":{"type":"dpair","a":[10,30],"b":[11,30]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_basic#10','math',2,2,'u4','L05','g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',3,'error','auto','비행기가 10시 30분에 출발해서 11시 30분에 도착했어요. 비행기를 타고 간 시간을 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u4-X11','M2-2-u4-X16']::text[],true,'{"seq":10,"concept":"M2-2-u4-C5","difficulty":3,"kind":"error","stem":"비행기가 10시 30분에 출발해서 11시 30분에 도착했어요. 비행기를 타고 간 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"곰이 — 「도착한 시각이 11시 30분이니까 90분이야.」","correct":true,"mis_target":"M2-2-u4-X11"},{"t":"펭이 — 「긴바늘이 한 바퀴 돌았으니 60분이야.」","mis":"M2-2-u4-X16"},{"t":"다예 — 「60분은 1시간이야.」","mis":"M2-2-u4-X16"}],"explanation":["10시 30분에서 11시 30분까지 긴바늘이 한 바퀴 돌았어요.","그래서 걸린 시간은 60분 — 1시간이에요.","곰이는 출발한 시각을 보지 않았어요."],"asset":{"type":"dpair","a":[10,30],"b":[11,30]},"variant_rule":{"alt":[{"stem":"공연이 9시에 시작해서 11시에 끝났어요. 공연을 본 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"곰이 — 「11시에 끝났으니까 11시간이야.」","correct":true,"mis_target":"M2-2-u4-X11"},{"t":"펭이 — 「긴바늘이 두 바퀴 돌았으니 2시간이야.」","mis":"M2-2-u4-X16"},{"t":"다예 — 「2시간은 120분이야.」","mis":"M2-2-u4-X16"}],"explanation":["9시에서 11시까지 긴바늘이 두 바퀴 돌았어요.","그래서 공연을 본 시간은 2시간 — 120분이에요.","곰이는 끝난 시각을 걸린 시간으로 말했어요."],"asset":{"type":"dpair","a":[9,0],"b":[11,0]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_challenge#1','math',2,2,'u4','L05','g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',2,'sa','auto','책 읽기를 한 시간을 시간 띠에 나타냈어요. 책 읽기를 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u4-C5","difficulty":2,"kind":"sa","stem":"책 읽기를 한 시간을 시간 띠에 나타냈어요. 책 읽기를 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.","explanation":["시작한 시각은 2시 20분, 끝난 시각은 3시 20분이에요.","칠한 칸이 6칸 — 한 칸이 10분이니 60분이에요.","1시간은 60분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"bar"}},"answer":["60"],"asset":{"type":"tbar","from":[2,20],"to":[3,20],"label":"책 읽기를 한 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_challenge#2','math',2,2,'u4','L05','g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',2,'mc','auto','6시 20분에서 9시 20분이 될 때까지 긴바늘은 몇 바퀴 돌았나요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],true,'{"seq":2,"concept":"M2-2-u4-C5","difficulty":2,"kind":"mc","stem":"6시 20분에서 9시 20분이 될 때까지 긴바늘은 몇 바퀴 돌았나요?","explanation":["긴바늘이 한 바퀴 돌면 60분 — 1시간이 지나요.","6시 20분부터 9시 20분까지 3시간이 지났어요.","그래서 긴바늘은 3바퀴 돌았어요."],"variant_rule":{"tm":{"ask":"laps"}},"options":[{"t":"3바퀴","correct":true},{"t":"9바퀴","mis":"M2-2-u4-X11"},{"t":"4바퀴","mis":"M2-2-u4-X10"},{"t":"2바퀴","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_challenge#3','math',2,2,'u4','L05','g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',3,'mc','auto','멈춘 시계가 1시 30분을 가리켜요. 5시 30분으로 맞추려면 긴바늘을 몇 바퀴 돌려야 하나요?',ARRAY['M2-2-u4-X11','M2-2-u4-X02','M2-2-u4-X10']::text[],false,'{"seq":3,"concept":"M2-2-u4-C5","difficulty":3,"kind":"mc","stem":"멈춘 시계가 1시 30분을 가리켜요. 5시 30분으로 맞추려면 긴바늘을 몇 바퀴 돌려야 하나요?","options":[{"t":"4바퀴","correct":true},{"t":"5바퀴","mis":"M2-2-u4-X11"},{"t":"30바퀴","mis":"M2-2-u4-X02"},{"t":"3바퀴","mis":"M2-2-u4-X10"}],"explanation":["긴바늘이 한 바퀴 돌 때마다 1시간이 지나요.","1시 30분에서 5시 30분까지는 4시간이에요.","그래서 긴바늘을 4바퀴 돌려요."],"asset":{"type":"clock2","h":1,"m":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_challenge#4','math',2,2,'u4','L05','g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',3,'mc','auto','공연이 9시에 시작해서 11시에 끝났어요. 공연을 본 시간은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X11','M2-2-u4-X10']::text[],false,'{"seq":4,"concept":"M2-2-u4-C5","difficulty":3,"kind":"mc","stem":"공연이 9시에 시작해서 11시에 끝났어요. 공연을 본 시간은 몇 분인가요?","options":[{"t":"120분","correct":true},{"t":"200분","mis":"M2-2-u4-X09"},{"t":"11분","mis":"M2-2-u4-X11"},{"t":"60분","mis":"M2-2-u4-X10"}],"explanation":["9시에서 11시까지 긴바늘이 두 바퀴 돌았어요.","한 바퀴는 60분이에요.","60 + 60 = 120 — 120분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_challenge#5','math',2,2,'u4','L05','g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',3,'mc','auto','긴바늘이 세 바퀴 도는 동안 짧은바늘은 숫자 몇 칸을 움직이나요?',ARRAY['M2-2-u4-X01','M2-2-u4-X10','M2-2-u4-X09']::text[],false,'{"seq":5,"concept":"M2-2-u4-C5","difficulty":3,"kind":"mc","stem":"긴바늘이 세 바퀴 도는 동안 짧은바늘은 숫자 몇 칸을 움직이나요?","options":[{"t":"3칸","correct":true},{"t":"12칸","mis":"M2-2-u4-X01"},{"t":"1칸","mis":"M2-2-u4-X10"},{"t":"30칸","mis":"M2-2-u4-X09"}],"explanation":["긴바늘이 한 바퀴 돌면 1시간이 지나요.","1시간 동안 짧은바늘은 숫자 한 칸을 가요.","세 바퀴면 짧은바늘은 3칸을 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_challenge#6','math',2,2,'u4','L05','g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',3,'mc','auto','4시 10분부터 시간 띠를 7칸 칠했어요. 한 칸이 10분이면 끝난 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],false,'{"seq":6,"concept":"M2-2-u4-C5","difficulty":3,"kind":"mc","stem":"4시 10분부터 시간 띠를 7칸 칠했어요. 한 칸이 10분이면 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"5시 20분","correct":true},{"t":"4시 80분","mis":"M2-2-u4-X09"},{"t":"4시 17분","mis":"M2-2-u4-X10"},{"t":"5시 10분","mis":"M2-2-u4-X10"}],"explanation":["7칸은 10분이 7번 — 70분이에요.","70분은 1시간 10분이에요.","4시 10분에서 1시간 10분 뒤는 5시 20분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_challenge#7','math',2,2,'u4','L05','g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',3,'ox','auto','1시간 동안 짧은바늘은 시계를 한 바퀴 돌아요.',ARRAY['M2-2-u4-X01']::text[],false,'{"seq":7,"concept":"M2-2-u4-C5","difficulty":3,"kind":"ox","stem":"1시간 동안 짧은바늘은 시계를 한 바퀴 돌아요.","answer":"X","reason_options":[{"t":"1시간 동안 짧은바늘은 숫자 한 칸만 가고 한 바퀴는 긴바늘이 도니까","correct":true},{"t":"짧은바늘과 긴바늘은 같이 한 바퀴를 도니까","mis":"M2-2-u4-X01"}],"mis":"M2-2-u4-X01","explanation":["1시간 동안 긴바늘이 한 바퀴 돌아요.","그동안 짧은바늘은 숫자 한 칸을 가요.","짧은바늘이 한 바퀴 돌려면 12시간이 걸려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_challenge#8','math',2,2,'u4','L05','g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',4,'essay','teacher','자전거를 5시에 출발해서 6시에 도착했어요. 자전거를 탄 시간이 1시간이자 60분인 까닭을 시계의 두 바늘로 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u4-C5","difficulty":4,"kind":"essay","stem":"자전거를 5시에 출발해서 6시에 도착했어요. 자전거를 탄 시간이 1시간이자 60분인 까닭을 시계의 두 바늘로 설명해 보세요.","answer_guide":{"answer":"예: 긴바늘이 12에서 시작해 한 바퀴를 돌아 다시 12로 왔다. 긴바늘이 한 바퀴 도는 데 60분이 걸린다. 그동안 짧은바늘은 5에서 6으로 한 칸 가서 1시간이 지났다. 그래서 60분 = 1시간이다.","scoring_points":["긴바늘이 한 바퀴 돌았다고 썼는가","한 바퀴가 60분임을 썼는가","짧은바늘이 한 칸 가서 1시간임을 썼는가"]},"explanation":["긴바늘은 한 바퀴 — 60분이에요.","짧은바늘은 5에서 6으로 — 1시간이에요.","그래서 60분 = 1시간이에요."],"asset":{"type":"dpair","a":[5,0],"b":[6,0]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_challenge#9','math',2,2,'u4','L05','g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',4,'essay','teacher','민수는 이 시간 띠를 보고 「90분 걸렸어.」라고 했어요. 잘못된 점을 설명하고 걸린 시간을 바르게 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u4-C5","difficulty":4,"kind":"essay","stem":"민수는 이 시간 띠를 보고 「90분 걸렸어.」라고 했어요. 잘못된 점을 설명하고 걸린 시간을 바르게 구해 보세요.","answer_guide":{"answer":"예: 칠한 칸은 10시 30분부터 11시 30분까지 6칸이다. 한 칸이 10분이므로 60분이다. 민수는 출발한 시각을 보지 않고 칸을 잘못 셌다.","scoring_points":["칠한 칸이 6칸임을 찾았는가","한 칸이 10분이라 60분임을 셈했는가","60분(1시간)이라고 바르게 구했는가"]},"explanation":["10시 30분부터 11시 30분까지 칠한 칸은 6칸이에요.","10분씩 6칸이면 60분이에요.","걸린 시간은 60분 — 1시간이에요."],"asset":{"type":"tbar","from":[10,30],"to":[11,30],"label":"비행기를 탄 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_challenge#10','math',2,2,'u4','L05','g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',4,'mc','auto','지아는 3시 20분부터 긴바늘이 두 바퀴 도는 동안 책을 읽고, 이어서 30분 동안 그림을 그렸어요. 그림을 다 그린 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X16','M2-2-u4-X10']::text[],false,'{"seq":10,"concept":"M2-2-u4-C5","difficulty":4,"kind":"mc","stem":"지아는 3시 20분부터 긴바늘이 두 바퀴 도는 동안 책을 읽고, 이어서 30분 동안 그림을 그렸어요. 그림을 다 그린 시각은 몇 시 몇 분인가요?","options":[{"t":"5시 50분","correct":true},{"t":"5시 20분","mis":"M2-2-u4-X16"},{"t":"3시 50분","mis":"M2-2-u4-X10"},{"t":"4시 50분","mis":"M2-2-u4-X10"}],"explanation":["긴바늘이 두 바퀴 돌면 2시간 — 3시 20분에서 5시 20분이에요.","거기서 30분 더 그림을 그렸어요.","그래서 5시 50분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_basic#1','math',2,2,'u4','L06','g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',1,'mc','auto','1시간 20분은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":1,"concept":"M2-2-u4-C6","difficulty":1,"kind":"mc","stem":"1시간 20분은 몇 분인가요?","explanation":["1시간은 60분이에요.","1시간 20분 = 60분 + 20분이에요.","그래서 80분이에요 — 1시간을 100분으로 보면 안 돼요."],"variant_rule":{"tm":{"ask":"h60","form":"tomin"}},"options":[{"t":"80분","correct":true},{"t":"120분","mis":"M2-2-u4-X09"},{"t":"90분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_basic#2','math',2,2,'u4','L06','g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',1,'sa','auto','등산을 한 시간을 시간 띠에 나타냈어요. 등산을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u4-C6","difficulty":1,"kind":"sa","stem":"등산을 한 시간을 시간 띠에 나타냈어요. 등산을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.","explanation":["시작한 시각은 9시, 끝난 시각은 10시 20분이에요.","칠한 칸이 8칸 — 한 칸이 10분이니 80분이에요.","1시간 20분은 60분 + 20분 = 80분이에요."],"variant_rule":{"tm":{"ask":"elapsed","act":"등산","form":"bar"}},"answer":["80"],"asset":{"type":"tbar","from":[9,0],"to":[10,20],"label":"등산을 한 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_basic#3','math',2,2,'u4','L06','g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',1,'sa','auto','1시간 10분은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u4-C6","difficulty":1,"kind":"sa","stem":"1시간 10분은 몇 분인가요? 숫자로 쓰세요.","explanation":["1시간은 60분이에요.","1시간 10분 = 60분 + 10분이에요.","그래서 70분이에요 — 1시간을 100분으로 보면 안 돼요."],"variant_rule":{"tm":{"ask":"h60","form":"tomin"}},"answer":["70"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_basic#4','math',2,2,'u4','L06','g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',1,'mc','auto','9시에 등산을 시작해서 10시 10분에 끝냈어요. 걸린 시간은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":4,"concept":"M2-2-u4-C6","difficulty":1,"kind":"mc","stem":"9시에 등산을 시작해서 10시 10분에 끝냈어요. 걸린 시간은 몇 분인가요?","explanation":["시작한 시각은 9시, 끝난 시각은 10시 10분이에요.","9시에서 1시간 뒤인 10시를 먼저 찾고 남은 만큼 더 세면 1시간 10분이에요.","1시간 10분은 60분 + 10분 = 70분이에요."],"variant_rule":{"tm":{"ask":"elapsed","act":"등산","form":"text"}},"options":[{"t":"70분","correct":true},{"t":"110분","mis":"M2-2-u4-X09"},{"t":"80분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_basic#5','math',2,2,'u4','L06','g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',2,'mc','auto','100분은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":5,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"100분은 몇 시간 몇 분인가요?","explanation":["60분은 1시간이에요.","100분 = 60분 + 40분이에요.","60분은 1시간이니 1시간 40분이에요."],"variant_rule":{"tm":{"ask":"h60","form":"tohm"}},"options":[{"t":"1시간 40분","correct":true},{"t":"1시간","mis":"M2-2-u4-X09"},{"t":"10시간","mis":"M2-2-u4-X09"},{"t":"1시간 50분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_basic#6','math',2,2,'u4','L06','g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',2,'mc','auto','수영을 시작한 시각과 끝난 시각이에요. 수영을 하는 데 걸린 시간은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],true,'{"seq":6,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"수영을 시작한 시각과 끝난 시각이에요. 수영을 하는 데 걸린 시간은 몇 시간 몇 분인가요?","explanation":["시작한 시각은 9시, 끝난 시각은 11시 40분이에요.","9시에서 1시간 뒤인 10시를 먼저 찾고 남은 만큼 더 세면 2시간 40분이에요.","160분 = 2시간 40분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"pair","unit":"hm"}},"options":[{"t":"2시간 40분","correct":true},{"t":"11시간 40분","mis":"M2-2-u4-X11"},{"t":"2시간 50분","mis":"M2-2-u4-X10"},{"t":"2시간 30분","mis":"M2-2-u4-X10"}],"asset":{"type":"dpair","a":[9,0],"b":[11,40]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_basic#7','math',2,2,'u4','L06','g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',2,'sa','auto','수영을 한 시간을 시간 띠에 나타냈어요. 수영을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u4-C6","difficulty":2,"kind":"sa","stem":"수영을 한 시간을 시간 띠에 나타냈어요. 수영을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.","explanation":["시작한 시각은 1시 30분, 끝난 시각은 3시예요.","칠한 칸이 9칸 — 한 칸이 10분이니 90분이에요.","1시간 30분은 60분 + 30분 = 90분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"bar"}},"answer":["90"],"asset":{"type":"tbar","from":[1,30],"to":[3,0],"label":"수영을 한 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_basic#8','math',2,2,'u4','L06','g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',2,'match','auto','같은 시간끼리 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M2-2-u4-C6","difficulty":2,"kind":"match","stem":"같은 시간끼리 이으세요.","pairs":[{"l":"1시간 10분","r":"70분"},{"l":"1시간 40분","r":"100분"},{"l":"2시간 20분","r":"140분"}],"mis":"M2-2-u4-X09","explanation":["1시간은 60분이에요.","1시간 10분 = 60 + 10 = 70분, 1시간 40분 = 60 + 40 = 100분이에요.","2시간 20분 = 120 + 20 = 140분이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 같은 시간끼리 이으세요.","pairs":[{"l":"1시간 30분","r":"90분"},{"l":"2시간","r":"120분"},{"l":"1시간 50분","r":"110분"}],"explanation":["1시간은 60분이에요.","1시간 30분 = 60 + 30 = 90분, 2시간 = 60 + 60 = 120분이에요.","1시간 50분 = 60 + 50 = 110분이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_basic#9','math',2,2,'u4','L06','g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',2,'ox','auto','1시간 10분은 110분이에요.',ARRAY['M2-2-u4-X09']::text[],true,'{"seq":9,"concept":"M2-2-u4-C6","difficulty":2,"kind":"ox","stem":"1시간 10분은 110분이에요.","answer":"X","reason_options":[{"t":"1시간은 60분이라 1시간 10분은 60 + 10 = 70분이니까","correct":true},{"t":"1과 10을 이어 쓰면 110이니까","mis":"M2-2-u4-X09"}],"mis":"M2-2-u4-X09","explanation":["1시간은 100분이 아니라 60분이에요.","1시간 10분 = 60분 + 10분이에요.","그래서 70분이에요."],"variant_rule":{"alt":[{"stem":"1시간 50분은 110분이에요.","answer":"O","reason_options":[{"t":"1시간은 60분이라 1시간 50분은 60 + 50 = 110분이니까","correct":true},{"t":"1시간은 100분이라 150분이니까","mis":"M2-2-u4-X09"}],"explanation":["1시간은 60분이에요.","1시간 50분 = 60분 + 50분이에요.","그래서 110분 — 바른 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_basic#10','math',2,2,'u4','L06','g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',3,'error','auto','체험학습에서 열매 줍기를 한 시각이에요. 걸린 시간을 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X16']::text[],true,'{"seq":10,"concept":"M2-2-u4-C6","difficulty":3,"kind":"error","stem":"체험학습에서 열매 줍기를 한 시각이에요. 걸린 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"지우 — 「1시간 10분이니까 110분이야.」","correct":true,"mis_target":"M2-2-u4-X09"},{"t":"서아 — 「9시 30분에서 1시간 뒤 10시 30분, 10분 더 가서 1시간 10분이야.」","mis":"M2-2-u4-X16"},{"t":"하루 — 「60분과 10분을 합해 70분이야.」","mis":"M2-2-u4-X16"}],"explanation":["9시 30분부터 10시 40분까지는 1시간 10분이에요.","1시간 10분 = 60분 + 10분 = 70분이에요.","지우는 1시간을 100분으로 보았어요."],"asset":{"type":"dpair","a":[9,30],"b":[10,40]},"variant_rule":{"alt":[{"stem":"체험학습에서 음식을 만들어 먹은 시각이에요. 걸린 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「1시간 20분이니까 120분이야.」","correct":true,"mis_target":"M2-2-u4-X09"},{"t":"은솔 — 「10시 40분에서 1시간 뒤 11시 40분, 20분 더 가서 1시간 20분이야.」","mis":"M2-2-u4-X16"},{"t":"예린 — 「60분과 20분을 합해 80분이야.」","mis":"M2-2-u4-X16"}],"explanation":["10시 40분부터 12시까지는 1시간 20분이에요.","1시간 20분 = 60분 + 20분 = 80분이에요.","도윤이는 1시간을 100분으로 보았어요."],"asset":{"type":"dpair","a":[10,40],"b":[12,0]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_challenge#1','math',2,2,'u4','L06','g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',2,'mc','auto','130분은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":1,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"130분은 몇 시간 몇 분인가요?","explanation":["60분은 1시간이에요.","130분 = 120분 + 10분이에요.","120분은 2시간이니 2시간 10분이에요."],"variant_rule":{"tm":{"ask":"h60","form":"tohm"}},"options":[{"t":"2시간 10분","correct":true},{"t":"1시간 30분","mis":"M2-2-u4-X09"},{"t":"13시간","mis":"M2-2-u4-X09"},{"t":"2시간 20분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_challenge#2','math',2,2,'u4','L06','g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',2,'mc','auto','10시 40분에 책 읽기를 시작해서 12시에 끝냈어요. 걸린 시간은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],true,'{"seq":2,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"10시 40분에 책 읽기를 시작해서 12시에 끝냈어요. 걸린 시간은 몇 시간 몇 분인가요?","explanation":["시작한 시각은 10시 40분, 끝난 시각은 12시예요.","10시 40분에서 1시간 뒤인 11시 40분을 먼저 찾고 남은 만큼 더 세면 1시간 20분이에요.","80분 = 1시간 20분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"text","unit":"hm"}},"options":[{"t":"1시간 20분","correct":true},{"t":"12시간","mis":"M2-2-u4-X11"},{"t":"1시간 30분","mis":"M2-2-u4-X10"},{"t":"1시간 10분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_challenge#3','math',2,2,'u4','L06','g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',3,'mc','auto','2시 40분에 책 읽기를 시작해서 1시간 30분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":3,"concept":"M2-2-u4-C6","difficulty":3,"kind":"mc","stem":"2시 40분에 책 읽기를 시작해서 1시간 30분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","explanation":["시작한 시각 2시 40분에서 1시간 30분이 지난 시각을 찾아요.","1시간 뒤는 3시 40분, 거기서 30분 더 지나면 4시 10분이에요.","분이 60분이 되면 시가 하나 커져요."],"variant_rule":{"tm":{"ask":"after"}},"options":[{"t":"4시 10분","correct":true},{"t":"3시 70분","mis":"M2-2-u4-X09"},{"t":"4시 20분","mis":"M2-2-u4-X10"},{"t":"4시","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_challenge#4','math',2,2,'u4','L06','g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',3,'mc','auto','서울에서 9시에 출발한 기차가 부산에 11시 40분에 도착했어요. 걸린 시간은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],false,'{"seq":4,"concept":"M2-2-u4-C6","difficulty":3,"kind":"mc","stem":"서울에서 9시에 출발한 기차가 부산에 11시 40분에 도착했어요. 걸린 시간은 몇 분인가요?","options":[{"t":"160분","correct":true},{"t":"240분","mis":"M2-2-u4-X09"},{"t":"140분","mis":"M2-2-u4-X10"},{"t":"100분","mis":"M2-2-u4-X10"}],"explanation":["9시에서 긴바늘이 두 바퀴 돌면 11시 — 2시간이에요.","거기서 40분 더 가서 2시간 40분이에요.","120 + 40 = 160 — 160분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_challenge#5','math',2,2,'u4','L06','g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',3,'mc','auto','체험학습에서 「음식 만들어 먹기」를 10시 40분부터 12시까지 했어요. 걸린 시간은 얼마인가요?',ARRAY['M2-2-u4-X10','M2-2-u4-X09','M2-2-u4-X11']::text[],false,'{"seq":5,"concept":"M2-2-u4-C6","difficulty":3,"kind":"mc","stem":"체험학습에서 「음식 만들어 먹기」를 10시 40분부터 12시까지 했어요. 걸린 시간은 얼마인가요?","options":[{"t":"1시간 20분","correct":true},{"t":"2시간","mis":"M2-2-u4-X10"},{"t":"1시간 60분","mis":"M2-2-u4-X09"},{"t":"12시간","mis":"M2-2-u4-X11"}],"explanation":["10시 40분에서 1시간 뒤는 11시 40분이에요.","11시 40분에서 12시까지 20분 더 갔어요.","그래서 1시간 20분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_challenge#6','math',2,2,'u4','L06','g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',3,'mc','auto','하루에 30분씩 운동해요. 4일 동안 운동한 시간은 모두 몇 시간인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],false,'{"seq":6,"concept":"M2-2-u4-C6","difficulty":3,"kind":"mc","stem":"하루에 30분씩 운동해요. 4일 동안 운동한 시간은 모두 몇 시간인가요?","options":[{"t":"2시간","correct":true},{"t":"1시간 20분","mis":"M2-2-u4-X09"},{"t":"4시간","mis":"M2-2-u4-X10"},{"t":"3시간","mis":"M2-2-u4-X10"}],"explanation":["30분씩 4번이면 120분이에요.","60분이 1시간이라 120분은 2시간이에요.","1시간을 100분으로 보면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_challenge#7','math',2,2,'u4','L06','g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',3,'ox','auto','2시 30분부터 4시까지는 1시간 30분이에요.',ARRAY['M2-2-u4-X10']::text[],false,'{"seq":7,"concept":"M2-2-u4-C6","difficulty":3,"kind":"ox","stem":"2시 30분부터 4시까지는 1시간 30분이에요.","answer":"O","reason_options":[{"t":"2시 30분에서 1시간 뒤가 3시 30분이고 30분 더 가면 4시라서 1시간 30분이니까","correct":true},{"t":"4 − 2 = 2라서 2시간이니까","mis":"M2-2-u4-X10"}],"mis":"M2-2-u4-X10","explanation":["2시 30분에서 1시간 뒤는 3시 30분이에요.","3시 30분에서 4시까지 30분이에요.","그래서 1시간 30분 — 바른 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_challenge#8','math',2,2,'u4','L06','g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',4,'essay','teacher','9시에 등산을 시작해서 10시 20분에 산 정상에 도착했어요. 걸린 시간을 「몇 시간 몇 분」과 「몇 분」으로 나타내고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u4-C6","difficulty":4,"kind":"essay","stem":"9시에 등산을 시작해서 10시 20분에 산 정상에 도착했어요. 걸린 시간을 「몇 시간 몇 분」과 「몇 분」으로 나타내고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 9시에서 1시간 뒤는 10시이고 20분 더 갔으므로 1시간 20분이다. 1시간은 60분이라 60 + 20 = 80분이다.","scoring_points":["1시간을 먼저 찾고 남은 만큼 세었는가","1시간 20분이라고 구했는가","80분으로 바꾸었는가"]},"explanation":["1시간을 먼저 — 9시에서 10시까지예요.","20분 더 갔으니 1시간 20분이에요.","60분 + 20분 = 80분이에요."],"asset":{"type":"tbar","from":[9,0],"to":[10,20],"label":"등산한 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_challenge#9','math',2,2,'u4','L06','g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',4,'essay','teacher','「1시간 10분」을 110분이라고 한 친구가 있어요. 잘못된 점을 설명하고 바르게 고쳐 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u4-C6","difficulty":4,"kind":"essay","stem":"「1시간 10분」을 110분이라고 한 친구가 있어요. 잘못된 점을 설명하고 바르게 고쳐 보세요.","answer_guide":{"answer":"예: 1시간을 100분으로 생각해서 110분이라고 했다. 1시간은 60분이므로 1시간 10분은 60 + 10 = 70분이다.","scoring_points":["1시간을 100분으로 본 잘못을 찾았는가","1시간 = 60분을 썼는가","70분이라고 고쳤는가"]},"explanation":["1시간은 60분이에요.","1시간 10분 = 60분 + 10분이에요.","바른 답은 70분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_challenge#10','math',2,2,'u4','L06','g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',4,'mc','auto','열매 줍기(9시 30분~10시 40분)와 자연물로 작품 만들기(12시~12시 40분)를 했어요. 두 활동에 걸린 시간은 모두 몇 분인가요?',ARRAY['M2-2-u4-X16','M2-2-u4-X09','M2-2-u4-X10']::text[],false,'{"seq":10,"concept":"M2-2-u4-C6","difficulty":4,"kind":"mc","stem":"열매 줍기(9시 30분~10시 40분)와 자연물로 작품 만들기(12시~12시 40분)를 했어요. 두 활동에 걸린 시간은 모두 몇 분인가요?","options":[{"t":"110분","correct":true},{"t":"70분","mis":"M2-2-u4-X16"},{"t":"150분","mis":"M2-2-u4-X09"},{"t":"100분","mis":"M2-2-u4-X10"}],"explanation":["열매 줍기는 1시간 10분 — 70분이에요.","작품 만들기는 40분이에요.","70 + 40 = 110 — 110분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_basic#1','math',2,2,'u4','L07','g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',1,'mc','auto','하루는 몇 시간인가요?',ARRAY['M2-2-u4-X13','M2-2-u4-X09']::text[],true,'{"seq":1,"concept":"M2-2-u4-C7","difficulty":1,"kind":"mc","stem":"하루는 몇 시간인가요?","options":[{"t":"24시간","correct":true},{"t":"12시간","mis":"M2-2-u4-X13"},{"t":"60시간","mis":"M2-2-u4-X09"}],"explanation":["짧은바늘이 한 바퀴 돌면 12시간이에요.","하루 동안 짧은바늘은 두 바퀴 돌아요.","12 + 12 = 24 — 하루는 24시간이에요."],"variant_rule":{"alt":[{"stem":"짧은바늘이 두 바퀴 돌면 몇 시간이 지나나요?","options":[{"t":"24시간","correct":true},{"t":"2시간","mis":"M2-2-u4-X01"},{"t":"12시간","mis":"M2-2-u4-X13"}],"explanation":["짧은바늘이 한 바퀴 돌면 12시간이에요.","두 바퀴면 12시간이 2번이에요.","그래서 24시간 — 하루예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_basic#2','math',2,2,'u4','L07','g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',1,'mc','auto','밤 12시부터 낮 12시까지를 무엇이라고 하나요?',ARRAY['M2-2-u4-X12','M2-2-u4-X13']::text[],true,'{"seq":2,"concept":"M2-2-u4-C7","difficulty":1,"kind":"mc","stem":"밤 12시부터 낮 12시까지를 무엇이라고 하나요?","options":[{"t":"오전","correct":true},{"t":"오후","mis":"M2-2-u4-X12"},{"t":"하루","mis":"M2-2-u4-X13"}],"explanation":["하루는 낮 12시에서 둘로 나뉘어요.","밤 12시부터 낮 12시까지가 오전이에요.","낮 12시부터 밤 12시까지가 오후예요."],"variant_rule":{"alt":[{"stem":"낮 12시부터 밤 12시까지를 무엇이라고 하나요?","options":[{"t":"오후","correct":true},{"t":"오전","mis":"M2-2-u4-X12"},{"t":"정각","mis":"M2-2-u4-X11"}],"explanation":["하루는 낮 12시에서 둘로 나뉘어요.","밤 12시부터 낮 12시까지가 오전이에요.","낮 12시부터 밤 12시까지가 오후예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_basic#3','math',2,2,'u4','L07','g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',1,'sa','auto','1일 5시간은 몇 시간인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u4-C7","difficulty":1,"kind":"sa","stem":"1일 5시간은 몇 시간인가요? 숫자로 쓰세요.","explanation":["하루는 24시간이에요 — 짧은바늘이 두 바퀴 돌아요.","1일 5시간 = 24시간 + 5시간이에요.","그래서 29시간이에요."],"variant_rule":{"tm":{"ask":"day","form":"toh"}},"answer":["29"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_basic#4','math',2,2,'u4','L07','g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',1,'mc','auto','오전 11시에 수영을 시작해서 2시간 동안 했어요. 끝난 시각은 언제인가요?',ARRAY['M2-2-u4-X12']::text[],true,'{"seq":4,"concept":"M2-2-u4-C7","difficulty":1,"kind":"mc","stem":"오전 11시에 수영을 시작해서 2시간 동안 했어요. 끝난 시각은 언제인가요?","explanation":["낮 12시부터 밤 12시까지가 오후예요.","오전 11시에서 1시간 뒤가 낮 12시, 거기서 1시간 더 가면 오후 1시예요.","낮 12시를 지나면 오전이 오후로 바뀌어요."],"variant_rule":{"tm":{"ask":"ampm"}},"options":[{"t":"오후 1시","correct":true},{"t":"오전 1시","mis":"M2-2-u4-X12"},{"t":"오후 13시","mis":"M2-2-u4-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_basic#5','math',2,2,'u4','L07','g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',2,'mc','auto','30시간은 며칠 몇 시간인가요?',ARRAY['M2-2-u4-X13','M2-2-u4-X10']::text[],true,'{"seq":5,"concept":"M2-2-u4-C7","difficulty":2,"kind":"mc","stem":"30시간은 며칠 몇 시간인가요?","explanation":["24시간은 1일이에요.","30시간 = 24시간 + 6시간이에요.","그래서 1일 6시간이에요."],"variant_rule":{"tm":{"ask":"day","form":"tod"}},"options":[{"t":"1일 6시간","correct":true},{"t":"2일 6시간","mis":"M2-2-u4-X13"},{"t":"3일","mis":"M2-2-u4-X13"},{"t":"1일 7시간","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_basic#6','math',2,2,'u4','L07','g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',2,'mc','auto','세미의 생활 계획표예요. 박물관 관람은 몇 시간 동안 했나요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],true,'{"seq":6,"concept":"M2-2-u4-C7","difficulty":2,"kind":"mc","stem":"세미의 생활 계획표예요. 박물관 관람은 몇 시간 동안 했나요?","options":[{"t":"5시간","correct":true},{"t":"17시간","mis":"M2-2-u4-X11"},{"t":"12시간","mis":"M2-2-u4-X11"},{"t":"4시간","mis":"M2-2-u4-X10"}],"explanation":["박물관 관람은 낮 12시에 시작해서 오후 5시에 끝났어요.","낮 12시에서 오후 5시까지 칸을 세면 5칸이에요.","그래서 5시간이에요."],"asset":{"type":"dbar","acts":[["잠",0,7,"😴"],["아침 식사",7,8,"🍚"],["블록 놀이",8,11,"🧱"],["점심 식사",11,12,"🍜"],["박물관 관람",12,17,"🖼️"],["저녁 식사",17,18,"🍲"],["독서",18,21,"📖"],["잠",21,24,"😴"]]},"variant_rule":{"alt":[{"stem":"세미의 생활 계획표예요. 블록 놀이는 몇 시간 동안 했나요?","options":[{"t":"3시간","correct":true},{"t":"11시간","mis":"M2-2-u4-X11"},{"t":"8시간","mis":"M2-2-u4-X11"},{"t":"2시간","mis":"M2-2-u4-X10"}],"explanation":["블록 놀이는 오전 8시에 시작해서 오전 11시에 끝났어요.","오전 8시에서 11시까지 칸을 세면 3칸이에요.","그래서 3시간이에요."],"asset":{"type":"dbar","acts":[["잠",0,7,"😴"],["아침 식사",7,8,"🍚"],["블록 놀이",8,11,"🧱"],["점심 식사",11,12,"🍜"],["박물관 관람",12,17,"🖼️"],["저녁 식사",17,18,"🍲"],["독서",18,21,"📖"],["잠",21,24,"😴"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_basic#7','math',2,2,'u4','L07','g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',2,'mc','auto','세미의 생활 계획표에서 오전에 한 일이 아닌 것은 어느 것인가요?',ARRAY['M2-2-u4-X16']::text[],true,'{"seq":7,"concept":"M2-2-u4-C7","difficulty":2,"kind":"mc","stem":"세미의 생활 계획표에서 오전에 한 일이 아닌 것은 어느 것인가요?","options":[{"t":"박물관 관람","correct":true},{"t":"아침 식사","mis":"M2-2-u4-X16"},{"t":"블록 놀이","mis":"M2-2-u4-X16"}],"explanation":["오전은 밤 12시부터 낮 12시까지예요.","아침 식사·블록 놀이·점심 식사는 낮 12시 전에 했어요.","박물관 관람은 낮 12시부터라 오후에 한 일이에요."],"asset":{"type":"dbar","acts":[["잠",0,7,"😴"],["아침 식사",7,8,"🍚"],["블록 놀이",8,11,"🧱"],["점심 식사",11,12,"🍜"],["박물관 관람",12,17,"🖼️"],["저녁 식사",17,18,"🍲"],["독서",18,21,"📖"],["잠",21,24,"😴"]]},"variant_rule":{"alt":[{"stem":"세미의 생활 계획표에서 오후에 한 일이 아닌 것은 어느 것인가요?","options":[{"t":"블록 놀이","correct":true},{"t":"저녁 식사","mis":"M2-2-u4-X16"},{"t":"독서","mis":"M2-2-u4-X16"}],"explanation":["오후는 낮 12시부터 밤 12시까지예요.","저녁 식사·독서는 낮 12시가 지나서 했어요.","블록 놀이는 오전 8시부터 11시까지라 오전에 한 일이에요."],"asset":{"type":"dbar","acts":[["잠",0,7,"😴"],["아침 식사",7,8,"🍚"],["블록 놀이",8,11,"🧱"],["점심 식사",11,12,"🍜"],["박물관 관람",12,17,"🖼️"],["저녁 식사",17,18,"🍲"],["독서",18,21,"📖"],["잠",21,24,"😴"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_basic#8','math',2,2,'u4','L07','g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',2,'ox','auto','오후에 하는 일이 많으면 오후가 오전보다 더 길어요.',ARRAY['M2-2-u4-X13']::text[],true,'{"seq":8,"concept":"M2-2-u4-C7","difficulty":2,"kind":"ox","stem":"오후에 하는 일이 많으면 오후가 오전보다 더 길어요.","answer":"X","reason_options":[{"t":"오전도 12시간, 오후도 12시간으로 길이가 같으니까","correct":true},{"t":"하는 일이 많을수록 시간이 길어지니까","mis":"M2-2-u4-X13"}],"mis":"M2-2-u4-X13","explanation":["오전은 밤 12시부터 낮 12시까지 12시간이에요.","오후는 낮 12시부터 밤 12시까지 12시간이에요.","하는 일이 많아도 시간의 길이는 같아요."],"variant_rule":{"alt":[{"stem":"오전과 오후는 각각 12시간이에요.","answer":"O","reason_options":[{"t":"짧은바늘이 한 바퀴 도는 12시간씩으로 나뉘니까","correct":true},{"t":"오후가 오전보다 하는 일이 많아서 더 기니까","mis":"M2-2-u4-X13"}],"explanation":["오전은 짧은바늘이 한 바퀴 — 12시간이에요.","오후도 짧은바늘이 한 바퀴 — 12시간이에요.","그래서 바른 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_basic#9','math',2,2,'u4','L07','g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',2,'mc','auto','오전 10시에 수영을 시작해서 4시간 동안 했어요. 끝난 시각은 언제인가요?',ARRAY['M2-2-u4-X12']::text[],true,'{"seq":9,"concept":"M2-2-u4-C7","difficulty":2,"kind":"mc","stem":"오전 10시에 수영을 시작해서 4시간 동안 했어요. 끝난 시각은 언제인가요?","explanation":["낮 12시부터 밤 12시까지가 오후예요.","오전 10시에서 2시간 뒤가 낮 12시, 거기서 2시간 더 가면 오후 2시예요.","낮 12시를 지나면 오전이 오후로 바뀌어요."],"variant_rule":{"tm":{"ask":"ampm"}},"options":[{"t":"오후 2시","correct":true},{"t":"오전 2시","mis":"M2-2-u4-X12"},{"t":"오후 14시","mis":"M2-2-u4-X12"},{"t":"오전 14시","mis":"M2-2-u4-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_basic#10','math',2,2,'u4','L07','g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',3,'error','auto','어제 오전 9시에 여행을 떠나 오늘 오전 11시에 돌아왔어요. 여행한 시간을 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u4-X13','M2-2-u4-X16']::text[],true,'{"seq":10,"concept":"M2-2-u4-C7","difficulty":3,"kind":"error","stem":"어제 오전 9시에 여행을 떠나 오늘 오전 11시에 돌아왔어요. 여행한 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"펭이 — 「9시부터 11시까지니까 2시간이야.」","correct":true,"mis_target":"M2-2-u4-X13"},{"t":"곰이 — 「하루 지나 오늘 오전 9시, 2시간 더 가서 26시간이야.」","mis":"M2-2-u4-X16"},{"t":"다예 — 「1일 2시간이라고도 해.」","mis":"M2-2-u4-X16"}],"explanation":["어제 오전 9시에서 하루(24시간)가 지나면 오늘 오전 9시예요.","거기서 2시간 더 가면 오늘 오전 11시예요.","24 + 2 = 26시간 — 펭이는 하루를 빠뜨렸어요."],"variant_rule":{"alt":[{"stem":"어제 오전 8시에 여행을 떠나 오늘 오전 11시에 돌아왔어요. 여행한 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"펭이 — 「8시부터 11시까지니까 3시간이야.」","correct":true,"mis_target":"M2-2-u4-X13"},{"t":"곰이 — 「하루 지나 오늘 오전 8시, 3시간 더 가서 27시간이야.」","mis":"M2-2-u4-X16"},{"t":"다예 — 「1일 3시간이라고도 해.」","mis":"M2-2-u4-X16"}],"explanation":["어제 오전 8시에서 하루(24시간)가 지나면 오늘 오전 8시예요.","거기서 3시간 더 가면 오늘 오전 11시예요.","24 + 3 = 27시간 — 펭이는 하루를 빠뜨렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_challenge#1','math',2,2,'u4','L07','g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',2,'sa','auto','2일은 몇 시간인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u4-C7","difficulty":2,"kind":"sa","stem":"2일은 몇 시간인가요? 숫자로 쓰세요.","explanation":["하루는 24시간이에요 — 짧은바늘이 두 바퀴 돌아요.","2일은 24시간이 2번 — 48시간이에요.","그래서 48시간이에요."],"variant_rule":{"tm":{"ask":"day","form":"toh"}},"answer":["48"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_challenge#2','math',2,2,'u4','L07','g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',2,'mc','auto','오전 9시에 책 읽기를 시작해서 5시간 동안 했어요. 끝난 시각은 언제인가요?',ARRAY['M2-2-u4-X12']::text[],true,'{"seq":2,"concept":"M2-2-u4-C7","difficulty":2,"kind":"mc","stem":"오전 9시에 책 읽기를 시작해서 5시간 동안 했어요. 끝난 시각은 언제인가요?","explanation":["낮 12시부터 밤 12시까지가 오후예요.","오전 9시에서 3시간 뒤가 낮 12시, 거기서 2시간 더 가면 오후 2시예요.","낮 12시를 지나면 오전이 오후로 바뀌어요."],"variant_rule":{"tm":{"ask":"ampm"}},"options":[{"t":"오후 2시","correct":true},{"t":"오전 2시","mis":"M2-2-u4-X12"},{"t":"오후 14시","mis":"M2-2-u4-X12"},{"t":"오전 14시","mis":"M2-2-u4-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_challenge#3','math',2,2,'u4','L07','g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',3,'mc','auto','오전 10시 30분에 박물관에 들어가 3시간 동안 관람했어요. 박물관에서 나온 시각은 언제인가요?',ARRAY['M2-2-u4-X12','M2-2-u4-X10']::text[],false,'{"seq":3,"concept":"M2-2-u4-C7","difficulty":3,"kind":"mc","stem":"오전 10시 30분에 박물관에 들어가 3시간 동안 관람했어요. 박물관에서 나온 시각은 언제인가요?","options":[{"t":"오후 1시 30분","correct":true},{"t":"오전 1시 30분","mis":"M2-2-u4-X12"},{"t":"오후 13시 30분","mis":"M2-2-u4-X12"},{"t":"오후 2시 30분","mis":"M2-2-u4-X10"}],"explanation":["오전 10시 30분에서 1시간 30분 뒤가 낮 12시예요.","거기서 1시간 30분 더 가면 오후 1시 30분이에요.","낮 12시를 지나면 오후 1시부터 다시 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_challenge#4','math',2,2,'u4','L07','g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',3,'mc','auto','하루 동안 짧은바늘과 긴바늘은 각각 몇 바퀴 도나요?',ARRAY['M2-2-u4-X13','M2-2-u4-X01','M2-2-u4-X09']::text[],false,'{"seq":4,"concept":"M2-2-u4-C7","difficulty":3,"kind":"mc","stem":"하루 동안 짧은바늘과 긴바늘은 각각 몇 바퀴 도나요?","options":[{"t":"짧은바늘 2바퀴, 긴바늘 24바퀴","correct":true},{"t":"짧은바늘 1바퀴, 긴바늘 12바퀴","mis":"M2-2-u4-X13"},{"t":"짧은바늘 24바퀴, 긴바늘 2바퀴","mis":"M2-2-u4-X01"},{"t":"짧은바늘 2바퀴, 긴바늘 60바퀴","mis":"M2-2-u4-X09"}],"explanation":["짧은바늘은 12시간에 한 바퀴 — 하루에 2바퀴예요.","긴바늘은 1시간에 한 바퀴 — 하루 24시간에 24바퀴예요.","하루는 24시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_challenge#5','math',2,2,'u4','L07','g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',3,'mc','auto','세미의 생활 계획표에서 하는 일에 걸린 시간을 모두 더하면 몇 시간인가요?',ARRAY['M2-2-u4-X13','M2-2-u4-X10']::text[],false,'{"seq":5,"concept":"M2-2-u4-C7","difficulty":3,"kind":"mc","stem":"세미의 생활 계획표에서 하는 일에 걸린 시간을 모두 더하면 몇 시간인가요?","options":[{"t":"24시간","correct":true},{"t":"12시간","mis":"M2-2-u4-X13"},{"t":"7시간","mis":"M2-2-u4-X10"},{"t":"20시간","mis":"M2-2-u4-X10"}],"explanation":["잠 10시간, 아침 1, 블록 3, 점심 1, 박물관 5, 저녁 1, 독서 3시간이에요.","10 + 1 + 3 + 1 + 5 + 1 + 3 = 24예요.","하루를 모두 칠했으니 24시간 — 하루예요."],"asset":{"type":"dbar","acts":[["잠",0,7,"😴"],["아침 식사",7,8,"🍚"],["블록 놀이",8,11,"🧱"],["점심 식사",11,12,"🍜"],["박물관 관람",12,17,"🖼️"],["저녁 식사",17,18,"🍲"],["독서",18,21,"📖"],["잠",21,24,"😴"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_challenge#6','math',2,2,'u4','L07','g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',3,'mc','auto','오후 3시는 낮 12시에서 몇 시간 뒤인가요?',ARRAY['M2-2-u4-X12','M2-2-u4-X13']::text[],false,'{"seq":6,"concept":"M2-2-u4-C7","difficulty":3,"kind":"mc","stem":"오후 3시는 낮 12시에서 몇 시간 뒤인가요?","options":[{"t":"3시간","correct":true},{"t":"15시간","mis":"M2-2-u4-X12"},{"t":"9시간","mis":"M2-2-u4-X12"},{"t":"12시간","mis":"M2-2-u4-X13"}],"explanation":["낮 12시 다음이 오후 1시예요.","오후 1시, 2시, 3시 — 3시간 뒤예요.","오후의 시는 낮 12시에서 다시 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_challenge#7','math',2,2,'u4','L07','g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',3,'ox','auto','오전 9시부터 오후 2시까지는 5시간이에요.',ARRAY['M2-2-u4-X12']::text[],false,'{"seq":7,"concept":"M2-2-u4-C7","difficulty":3,"kind":"ox","stem":"오전 9시부터 오후 2시까지는 5시간이에요.","answer":"O","reason_options":[{"t":"오전 9시에서 3시간 뒤가 낮 12시이고 2시간 더 가면 오후 2시라서 5시간이니까","correct":true},{"t":"9 − 2 = 7이라서 7시간이니까","mis":"M2-2-u4-X12"}],"mis":"M2-2-u4-X12","explanation":["오전 9시에서 낮 12시까지 3시간이에요.","낮 12시에서 오후 2시까지 2시간이에요.","3 + 2 = 5 — 바른 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_challenge#8','math',2,2,'u4','L07','g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',4,'essay','teacher','어제 오전 9시에 여행을 떠나 오늘 오전 11시에 돌아왔어요. 여행한 시간은 몇 시간인지 구하고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u4-C7","difficulty":4,"kind":"essay","stem":"어제 오전 9시에 여행을 떠나 오늘 오전 11시에 돌아왔어요. 여행한 시간은 몇 시간인지 구하고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 어제 오전 9시에서 하루가 지나면 오늘 오전 9시이고 하루는 24시간이다. 오늘 오전 9시에서 11시까지 2시간 더 갔다. 24 + 2 = 26시간이다.","scoring_points":["하루(24시간)가 지났음을 썼는가","2시간을 더 셈했는가","26시간(1일 2시간)이라고 구했는가"]},"explanation":["하루가 지나면 같은 시각이 돼요 — 24시간이에요.","거기서 2시간 더 갔어요.","24 + 2 = 26시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_challenge#9','math',2,2,'u4','L07','g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',4,'essay','teacher','세미는 오후에 하는 일이 더 많아서 「오후가 오전보다 길어.」라고 했어요. 세미의 말이 맞는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u4-C7","difficulty":4,"kind":"essay","stem":"세미는 오후에 하는 일이 더 많아서 「오후가 오전보다 길어.」라고 했어요. 세미의 말이 맞는지 설명해 보세요.","answer_guide":{"answer":"예: 맞지 않다. 오전은 밤 12시부터 낮 12시까지 12시간이고, 오후도 낮 12시부터 밤 12시까지 12시간이다. 하는 일이 많아도 시간의 길이는 같다.","scoring_points":["세미의 말이 맞지 않다고 했는가","오전·오후가 각각 12시간임을 썼는가","하는 일의 수와 시간의 길이는 다르다고 썼는가"]},"explanation":["오전은 12시간이에요.","오후도 12시간이에요.","하는 일이 많다고 시간이 길어지지 않아요."],"asset":{"type":"dbar","acts":[["잠",0,7,"😴"],["아침 식사",7,8,"🍚"],["블록 놀이",8,11,"🧱"],["점심 식사",11,12,"🍜"],["박물관 관람",12,17,"🖼️"],["저녁 식사",17,18,"🍲"],["독서",18,21,"📖"],["잠",21,24,"😴"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_challenge#10','math',2,2,'u4','L07','g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',4,'mc','auto','오후 9시에 잠들어 다음 날 오전 7시에 일어났어요. 잠잔 시간은 몇 시간인가요?',ARRAY['M2-2-u4-X12','M2-2-u4-X10']::text[],false,'{"seq":10,"concept":"M2-2-u4-C7","difficulty":4,"kind":"mc","stem":"오후 9시에 잠들어 다음 날 오전 7시에 일어났어요. 잠잔 시간은 몇 시간인가요?","options":[{"t":"10시간","correct":true},{"t":"2시간","mis":"M2-2-u4-X12"},{"t":"16시간","mis":"M2-2-u4-X12"},{"t":"14시간","mis":"M2-2-u4-X10"}],"explanation":["오후 9시에서 밤 12시까지 3시간이에요.","밤 12시에서 오전 7시까지 7시간이에요.","3 + 7 = 10 — 10시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_basic#1','math',2,2,'u4','L08','g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C8',1,'mc','auto','1주일은 며칠인가요?',ARRAY['M2-2-u4-X15']::text[],true,'{"seq":1,"concept":"M2-2-u4-C8","difficulty":1,"kind":"mc","stem":"1주일은 며칠인가요?","options":[{"t":"7일","correct":true},{"t":"5일","mis":"M2-2-u4-X15"},{"t":"10일","mis":"M2-2-u4-X15"}],"explanation":["일요일부터 토요일까지가 1주일이에요.","일, 월, 화, 수, 목, 금, 토 — 7일이에요.","달력의 한 줄도 7칸이에요."],"variant_rule":{"alt":[{"stem":"달력에서 한 줄(일요일부터 토요일까지)은 며칠인가요?","options":[{"t":"7일","correct":true},{"t":"5일","mis":"M2-2-u4-X15"},{"t":"30일","mis":"M2-2-u4-X14"}],"explanation":["달력의 한 줄에는 일요일부터 토요일까지 있어요.","7칸이라 7일 — 1주일이에요.","그래서 7일이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_basic#2','math',2,2,'u4','L08','g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C8',1,'mc','auto','11월 14일은 무슨 요일인가요?',ARRAY['M2-2-u4-X17']::text[],true,'{"seq":2,"concept":"M2-2-u4-C8","difficulty":1,"kind":"mc","stem":"11월 14일은 무슨 요일인가요?","explanation":["달력에서 14일을 찾아요.","14일이 있는 칸의 위를 따라 올라가면 토요일이에요.","같은 세로줄은 모두 같은 요일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"wday"}},"options":[{"t":"토요일","correct":true},{"t":"일요일","mis":"M2-2-u4-X17"},{"t":"금요일","mis":"M2-2-u4-X17"}],"asset":{"type":"cal","mon":11,"start":0,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_basic#3','math',2,2,'u4','L08','g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C9',1,'mc','auto','4월은 며칠까지 있나요?',ARRAY['M2-2-u4-X18']::text[],true,'{"seq":3,"concept":"M2-2-u4-C9","difficulty":1,"kind":"mc","stem":"4월은 며칠까지 있나요?","explanation":["달마다 날수가 달라요.","4월은 30일까지 있어요.","주먹을 쥐고 손등의 튀어나온 곳을 31일, 들어간 곳을 30일로 세면 쉬워요(2월은 28일 또는 29일)."],"variant_rule":{"tm":{"ask":"units","form":"mdays"}},"options":[{"t":"30일","correct":true},{"t":"31일","mis":"M2-2-u4-X18"},{"t":"28일","mis":"M2-2-u4-X18"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_basic#4','math',2,2,'u4','L08','g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C9',1,'mc','auto','1년은 몇 개월인가요?',ARRAY['M2-2-u4-X15']::text[],true,'{"seq":4,"concept":"M2-2-u4-C9","difficulty":1,"kind":"mc","stem":"1년은 몇 개월인가요?","options":[{"t":"12개월","correct":true},{"t":"10개월","mis":"M2-2-u4-X15"},{"t":"24개월","mis":"M2-2-u4-X15"}],"explanation":["1월부터 12월까지 달이 있어요.","모두 열두 달이에요.","그래서 1년은 12개월이에요."],"variant_rule":{"alt":[{"stem":"12개월은 몇 년인가요?","options":[{"t":"1년","correct":true},{"t":"12년","mis":"M2-2-u4-X14"},{"t":"2년","mis":"M2-2-u4-X15"}],"explanation":["1월부터 12월까지가 1년이에요.","열두 달 — 12개월이에요.","그래서 12개월은 1년이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_basic#5','math',2,2,'u4','L08','g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C8',2,'sa','auto','11월의 둘째 토요일은 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-2-u4-C8","difficulty":2,"kind":"sa","stem":"11월의 둘째 토요일은 며칠인가요? 숫자로 쓰세요.","explanation":["11월의 첫째 토요일은 7일이에요.","한 주에 7일씩 — 7, 14예요.","그래서 둘째 토요일은 14일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"nth"}},"answer":["14"],"asset":{"type":"cal","mon":11,"start":0,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_basic#6','math',2,2,'u4','L08','g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C8',2,'mc','auto','11월 7일에서 2주일 후는 며칠인가요?',ARRAY['M2-2-u4-X15','M2-2-u4-X17']::text[],true,'{"seq":6,"concept":"M2-2-u4-C8","difficulty":2,"kind":"mc","stem":"11월 7일에서 2주일 후는 며칠인가요?","explanation":["1주일은 7일 — 2주일은 14일이에요.","7 + 14 = 21이에요.","달력에서 아랫줄로 2칸 내려가면 같은 요일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"after","weeks":true}},"options":[{"t":"21일","correct":true},{"t":"9일","mis":"M2-2-u4-X15"},{"t":"22일","mis":"M2-2-u4-X17"},{"t":"20일","mis":"M2-2-u4-X17"}],"asset":{"type":"cal","mon":11,"start":0,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_basic#7','math',2,2,'u4','L08','g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C8',2,'mc','auto','3주일은 며칠인가요?',ARRAY['M2-2-u4-X15']::text[],true,'{"seq":7,"concept":"M2-2-u4-C8","difficulty":2,"kind":"mc","stem":"3주일은 며칠인가요?","explanation":["1주일은 7일이에요.","3주일은 7일이 3번이에요.","7 + 7 + 7 = 21 — 21일이에요."],"variant_rule":{"tm":{"ask":"units","form":"wk2d"}},"options":[{"t":"21일","correct":true},{"t":"15일","mis":"M2-2-u4-X15"},{"t":"30일","mis":"M2-2-u4-X15"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_basic#8','math',2,2,'u4','L08','g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C9',2,'sa','auto','1년 6개월은 몇 개월인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M2-2-u4-C9","difficulty":2,"kind":"sa","stem":"1년 6개월은 몇 개월인가요? 숫자로 쓰세요.","explanation":["1년은 12개월이에요.","1년 6개월 = 12개월 + 6개월이에요.","그래서 18개월이에요."],"variant_rule":{"tm":{"ask":"units","form":"y2m"}},"answer":["18"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_basic#9','math',2,2,'u4','L08','g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C9',2,'match','auto','같은 것끼리 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M2-2-u4-C9","difficulty":2,"kind":"match","stem":"같은 것끼리 이으세요.","pairs":[{"l":"1주일","r":"7일"},{"l":"1년","r":"12개월"},{"l":"1일","r":"24시간"}],"mis":"M2-2-u4-X15","explanation":["1주일은 7일이에요.","1년은 12개월이에요.","1일은 24시간이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 같은 것끼리 이으세요.","pairs":[{"l":"2주일","r":"14일"},{"l":"2년","r":"24개월"},{"l":"1시간","r":"60분"}],"explanation":["2주일은 7일이 2번 — 14일이에요.","2년은 12개월이 2번 — 24개월이에요.","1시간은 60분이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_basic#10','math',2,2,'u4','L08','g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C9',3,'error','auto','「12월」과 「12개월」에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u4-X14','M2-2-u4-X16']::text[],true,'{"seq":10,"concept":"M2-2-u4-C9","difficulty":3,"kind":"error","stem":"「12월」과 「12개월」에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지안 — 「12월과 12개월은 같은 말이야.」","correct":true,"mis_target":"M2-2-u4-X14"},{"t":"아린 — 「12월은 달의 이름이야.」","mis":"M2-2-u4-X16"},{"t":"태민 — 「12개월은 열두 달 동안의 길이야.」","mis":"M2-2-u4-X16"}],"explanation":["12월은 1년 가운데 마지막 달의 이름이에요.","12개월은 열두 달 동안 — 1년의 길이예요.","지안이는 이름과 길이를 같게 보았어요."],"variant_rule":{"alt":[{"stem":"「3월」과 「3개월」에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지안 — 「3월과 3개월은 같은 말이야.」","correct":true,"mis_target":"M2-2-u4-X14"},{"t":"아린 — 「3월은 달의 이름이야.」","mis":"M2-2-u4-X16"},{"t":"태민 — 「3개월은 세 달 동안의 길이야.」","mis":"M2-2-u4-X16"}],"explanation":["3월은 달의 이름이에요.","3개월은 세 달 동안의 길이예요.","지안이는 이름과 길이를 같게 보았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_challenge#1','math',2,2,'u4','L08','g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C8',2,'sa','auto','11월에 월요일은 모두 몇 번 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u4-C8","difficulty":2,"kind":"sa","stem":"11월에 월요일은 모두 몇 번 있나요? 숫자로 쓰세요.","explanation":["월요일 세로줄을 따라 날짜를 세어요.","2, 9, 16, 23, 30일 — 5번이에요.","빈칸은 세지 않아요."],"variant_rule":{"tm":{"ask":"cal","form":"count"}},"answer":["5"],"asset":{"type":"cal","mon":11,"start":0,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_challenge#2','math',2,2,'u4','L08','g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C9',2,'mc','auto','20개월은 몇 년 몇 개월인가요?',ARRAY['M2-2-u4-X15','M2-2-u4-X10']::text[],true,'{"seq":2,"concept":"M2-2-u4-C9","difficulty":2,"kind":"mc","stem":"20개월은 몇 년 몇 개월인가요?","explanation":["12개월은 1년이에요.","20개월 = 12개월 + 8개월이에요.","12개월은 1년이니 1년 8개월이에요."],"variant_rule":{"tm":{"ask":"units","form":"m2y"}},"options":[{"t":"1년 8개월","correct":true},{"t":"2년","mis":"M2-2-u4-X15"},{"t":"1년 9개월","mis":"M2-2-u4-X10"},{"t":"2년 8개월","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_challenge#3','math',2,2,'u4','L08','g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C8',3,'mc','auto','슬기는 매주 월요일과 수요일에 음악 줄넘기를 해요. 11월에 음악 줄넘기를 하는 날은 모두 며칠인가요?',ARRAY['M2-2-u4-X17','M2-2-u4-X14']::text[],false,'{"seq":3,"concept":"M2-2-u4-C8","difficulty":3,"kind":"mc","stem":"슬기는 매주 월요일과 수요일에 음악 줄넘기를 해요. 11월에 음악 줄넘기를 하는 날은 모두 며칠인가요?","options":[{"t":"9일","correct":true},{"t":"8일","mis":"M2-2-u4-X17"},{"t":"10일","mis":"M2-2-u4-X17"},{"t":"2일","mis":"M2-2-u4-X14"}],"explanation":["월요일은 2, 9, 16, 23, 30일 — 5번이에요.","수요일은 4, 11, 18, 25일 — 4번이에요.","5 + 4 = 9 — 모두 9일이에요."],"asset":{"type":"cal","mon":11,"start":0,"days":30,"marks":{"2":"🎵","4":"🎵","9":"🎵","11":"🎵","16":"🎵","18":"🎵","23":"🎵","25":"🎵","30":"🎵"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_challenge#4','math',2,2,'u4','L08','g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C8',3,'mc','auto','11월 28일 토요일에서 2주일 뒤는 언제인가요?',ARRAY['M2-2-u4-X18','M2-2-u4-X17']::text[],false,'{"seq":4,"concept":"M2-2-u4-C8","difficulty":3,"kind":"mc","stem":"11월 28일 토요일에서 2주일 뒤는 언제인가요?","options":[{"t":"12월 12일 토요일","correct":true},{"t":"11월 42일 토요일","mis":"M2-2-u4-X18"},{"t":"12월 14일 월요일","mis":"M2-2-u4-X17"},{"t":"12월 10일 목요일","mis":"M2-2-u4-X17"}],"explanation":["2주일은 14일이에요.","11월은 30일까지라 28일에서 2일 지나면 11월 30일, 12일 더 지나면 12월 12일이에요.","2주일 뒤는 같은 요일 — 토요일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_challenge#5','math',2,2,'u4','L08','g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C9',3,'mc','auto','날수가 31일인 달끼리 짝 지은 것은 어느 것인가요?',ARRAY['M2-2-u4-X18']::text[],false,'{"seq":5,"concept":"M2-2-u4-C9","difficulty":3,"kind":"mc","stem":"날수가 31일인 달끼리 짝 지은 것은 어느 것인가요?","options":[{"t":"7월, 8월","correct":true},{"t":"4월, 6월","mis":"M2-2-u4-X18"},{"t":"2월, 3월","mis":"M2-2-u4-X18"},{"t":"9월, 11월","mis":"M2-2-u4-X18"}],"explanation":["7월과 8월은 둘 다 31일까지 있어요.","4월·6월·9월·11월은 30일까지예요.","2월은 28일 또는 29일까지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_challenge#6','math',2,2,'u4','L08','g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C8',3,'mc','auto','연우 생일은 11월 14일이에요. 생일의 10일 후는 며칠인가요?',ARRAY['M2-2-u4-X17','M2-2-u4-X16']::text[],false,'{"seq":6,"concept":"M2-2-u4-C8","difficulty":3,"kind":"mc","stem":"연우 생일은 11월 14일이에요. 생일의 10일 후는 며칠인가요?","options":[{"t":"11월 24일","correct":true},{"t":"11월 23일","mis":"M2-2-u4-X17"},{"t":"11월 25일","mis":"M2-2-u4-X17"},{"t":"11월 4일","mis":"M2-2-u4-X16"}],"explanation":["생일은 빼고 다음 날부터 세요 — 15일이 1일 후예요.","14 + 10 = 24예요.","그래서 11월 24일이에요."],"asset":{"type":"cal","mon":11,"start":0,"days":30,"marks":{"14":"🎂"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_challenge#7','math',2,2,'u4','L08','g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C8',3,'ox','auto','2주일 3일은 17일이에요.',ARRAY['M2-2-u4-X15']::text[],false,'{"seq":7,"concept":"M2-2-u4-C8","difficulty":3,"kind":"ox","stem":"2주일 3일은 17일이에요.","answer":"O","reason_options":[{"t":"2주일은 14일이라 14 + 3 = 17일이니까","correct":true},{"t":"2주일 3일은 2 + 3 = 5일이니까","mis":"M2-2-u4-X15"}],"mis":"M2-2-u4-X15","explanation":["1주일은 7일 — 2주일은 14일이에요.","14일과 3일을 모으면 17일이에요.","그래서 바른 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_challenge#8','math',2,2,'u4','L08','g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C8',4,'essay','teacher','11월 둘째 토요일부터 2주일마다 등산을 가요. 11월에 등산 가는 날을 모두 찾고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u4-C8","difficulty":4,"kind":"essay","stem":"11월 둘째 토요일부터 2주일마다 등산을 가요. 11월에 등산 가는 날을 모두 찾고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 11월 1일이 일요일이므로 첫째 토요일은 7일, 둘째 토요일은 14일이다. 2주일은 14일이므로 14일 다음은 28일이다. 등산 가는 날은 14일과 28일이다.","scoring_points":["둘째 토요일이 14일임을 찾았는가","2주일이 14일임을 썼는가","14일·28일을 찾았는가"]},"explanation":["첫째 토요일은 7일, 둘째 토요일은 14일이에요.","2주일 = 14일이라 14 + 14 = 28이에요.","등산 가는 날은 14일과 28일이에요."],"asset":{"type":"cal","mon":11,"start":0,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_challenge#9','math',2,2,'u4','L08','g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C9',4,'essay','teacher','「12월」과 「12개월」은 어떻게 다른지 예를 들어 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u4-C9","difficulty":4,"kind":"essay","stem":"「12월」과 「12개월」은 어떻게 다른지 예를 들어 설명해 보세요.","answer_guide":{"answer":"예: 12월은 1년 가운데 마지막 달의 이름이다. 12개월은 열두 달 동안의 길이로 1년과 같다. 「12월에 눈이 왔다」는 때를, 「12개월 동안 저금했다」는 길이를 나타낸다.","scoring_points":["12월이 달의 이름임을 썼는가","12개월이 기간(길이)임을 썼는가","알맞은 예를 들었는가"]},"explanation":["12월은 달의 이름이에요.","12개월은 열두 달 동안 — 1년이에요.","때를 말할 때와 길이를 말할 때가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_challenge#10','math',2,2,'u4','L08','g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C9',4,'mc','auto','지아는 15개월, 연우는 1년 2개월 동안 줄넘기를 했어요. 누가 몇 개월 더 오래 했나요?',ARRAY['M2-2-u4-X15','M2-2-u4-X10']::text[],false,'{"seq":10,"concept":"M2-2-u4-C9","difficulty":4,"kind":"mc","stem":"지아는 15개월, 연우는 1년 2개월 동안 줄넘기를 했어요. 누가 몇 개월 더 오래 했나요?","options":[{"t":"지아가 1개월 더","correct":true},{"t":"연우가 1개월 더","mis":"M2-2-u4-X15"},{"t":"지아가 13개월 더","mis":"M2-2-u4-X15"},{"t":"연우가 2개월 더","mis":"M2-2-u4-X10"}],"explanation":["1년 2개월은 12 + 2 = 14개월이에요.","15개월과 14개월을 견주면 15개월이 1개월 더 길어요.","그래서 지아가 1개월 더 오래 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#1','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C1',1,'sa','auto','시계가 나타내는 시각은 2시 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u4-C1","difficulty":1,"kind":"sa","stem":"시계가 나타내는 시각은 2시 몇 분인가요? 숫자로 쓰세요.","explanation":["짧은바늘이 2와 3 사이에 있으니 2시예요.","긴바늘이 숫자 4를 가리키니 4 × 5 = 20분이에요.","그래서 2시 20분이에요."],"variant_rule":{"tm":{"ask":"read","step":5}},"answer":["20"],"asset":{"type":"clock2","h":2,"m":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#2','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C1',1,'mc','auto','긴바늘이 숫자 4를 가리키면 몇 분인가요?',ARRAY['M2-2-u4-X02']::text[],true,'{"seq":2,"concept":"M2-2-u4-C1","difficulty":1,"kind":"mc","stem":"긴바늘이 숫자 4를 가리키면 몇 분인가요?","explanation":["숫자와 숫자 사이는 작은 눈금 5칸 — 5분이에요.","숫자 4까지 5분씩 4번이니 4 × 5 = 20이에요.","그래서 20분이에요 — 숫자 그대로 4분이 아니에요."],"variant_rule":{"tm":{"ask":"numm"}},"options":[{"t":"20분","correct":true},{"t":"4분","mis":"M2-2-u4-X02"},{"t":"40분","mis":"M2-2-u4-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#3','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C2',1,'mc','auto','디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u4-X06']::text[],true,'{"seq":3,"concept":"M2-2-u4-C2","difficulty":1,"kind":"mc","stem":"디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?","explanation":["「:」 왼쪽은 시, 오른쪽은 분이에요.","10 : 35는 10시 35분이에요.","시는 「열 시」, 분은 「삼십오 분」으로 읽어요."],"variant_rule":{"tm":{"ask":"dig"}},"options":[{"t":"열 시 삼십오 분","correct":true},{"t":"삼십오 시 열 분","mis":"M2-2-u4-X06"},{"t":"십 시 삼십오 분","mis":"M2-2-u4-X06"}],"asset":{"type":"digital","h":10,"m":35}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#4','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C3',1,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X04','M2-2-u4-X05']::text[],true,'{"seq":4,"concept":"M2-2-u4-C3","difficulty":1,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 1과 2 사이에 있으니 1시예요.","긴바늘이 숫자 2(10분)에서 작은 눈금 3칸 더 간 곳이니 10 + 3 = 13분이에요.","그래서 1시 13분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"options":[{"t":"1시 13분","correct":true},{"t":"1시 14분","mis":"M2-2-u4-X04"},{"t":"1시 17분","mis":"M2-2-u4-X05"}],"asset":{"type":"clock2","h":1,"m":13}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#5','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C4',1,'sa','auto','8시 55분은 9시 몇 분 전인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-2-u4-C4","difficulty":1,"kind":"sa","stem":"8시 55분은 9시 몇 분 전인가요? 숫자로 쓰세요.","explanation":["8시 55분에서 5분이 지나면 9시가 돼요.","그래서 8시 55분을 9시 5분 전이라고도 해요.","「몇 시 전」의 시는 곧 될 정각 9시예요 — 지금 시 8시가 아니에요."],"variant_rule":{"tm":{"ask":"before"}},"answer":["5"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#6','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C5',1,'sa','auto','수영을 한 시간을 시간 띠에 나타냈어요. 수영을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M2-2-u4-C5","difficulty":1,"kind":"sa","stem":"수영을 한 시간을 시간 띠에 나타냈어요. 수영을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.","explanation":["시작한 시각은 10시 30분, 끝난 시각은 11시 30분이에요.","칠한 칸이 6칸 — 한 칸이 10분이니 60분이에요.","1시간은 60분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"bar"}},"answer":["60"],"asset":{"type":"tbar","from":[10,30],"to":[11,30],"label":"수영을 한 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#7','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C7',1,'mc','auto','하루는 몇 시간인가요?',ARRAY['M2-2-u4-X13','M2-2-u4-X09']::text[],false,'{"seq":7,"concept":"M2-2-u4-C7","difficulty":1,"kind":"mc","stem":"하루는 몇 시간인가요?","options":[{"t":"24시간","correct":true},{"t":"12시간","mis":"M2-2-u4-X13"},{"t":"60시간","mis":"M2-2-u4-X09"}],"explanation":["짧은바늘이 하루에 두 바퀴 돌아요.","한 바퀴는 12시간이에요.","12 + 12 = 24 — 하루는 24시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#8','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C8',1,'mc','auto','11월 14일은 무슨 요일인가요?',ARRAY['M2-2-u4-X17']::text[],true,'{"seq":8,"concept":"M2-2-u4-C8","difficulty":1,"kind":"mc","stem":"11월 14일은 무슨 요일인가요?","explanation":["달력에서 14일을 찾아요.","14일이 있는 칸의 위를 따라 올라가면 토요일이에요.","같은 세로줄은 모두 같은 요일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"wday"}},"options":[{"t":"토요일","correct":true},{"t":"일요일","mis":"M2-2-u4-X17"},{"t":"금요일","mis":"M2-2-u4-X17"}],"asset":{"type":"cal","mon":11,"start":0,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#9','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C4',2,'mc','auto','7시 5분 전은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],true,'{"seq":9,"concept":"M2-2-u4-C4","difficulty":2,"kind":"mc","stem":"7시 5분 전은 몇 시 몇 분인가요?","explanation":["7시 5분 전은 7시가 되기 5분 전이에요.","7시에서 긴바늘을 5분만큼 거꾸로 돌리면 6시 55분이에요.","짧은바늘은 아직 6과 7 사이에 있어서 6시예요."],"variant_rule":{"tm":{"ask":"beforer"}},"options":[{"t":"6시 55분","correct":true},{"t":"7시 55분","mis":"M2-2-u4-X07"},{"t":"7시 5분","mis":"M2-2-u4-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#10','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C6',2,'mc','auto','1시간 10분은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":10,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"1시간 10분은 몇 분인가요?","explanation":["1시간은 60분이에요.","1시간 10분 = 60분 + 10분이에요.","그래서 70분이에요 — 1시간을 100분으로 보면 안 돼요."],"variant_rule":{"tm":{"ask":"h60","form":"tomin"}},"options":[{"t":"70분","correct":true},{"t":"110분","mis":"M2-2-u4-X09"},{"t":"80분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#11','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C6',2,'mc','auto','80분은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":11,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"80분은 몇 시간 몇 분인가요?","explanation":["60분은 1시간이에요.","80분 = 60분 + 20분이에요.","60분은 1시간이니 1시간 20분이에요."],"variant_rule":{"tm":{"ask":"h60","form":"tohm"}},"options":[{"t":"1시간 20분","correct":true},{"t":"8시간","mis":"M2-2-u4-X09"},{"t":"1시간 30분","mis":"M2-2-u4-X10"},{"t":"1시간 10분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#12','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C6',2,'mc','auto','피아노 연습을 시작한 시각과 끝난 시각이에요. 피아노 연습을 하는 데 걸린 시간은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],true,'{"seq":12,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"피아노 연습을 시작한 시각과 끝난 시각이에요. 피아노 연습을 하는 데 걸린 시간은 몇 시간 몇 분인가요?","explanation":["시작한 시각은 9시, 끝난 시각은 10시 10분이에요.","9시에서 1시간 뒤인 10시를 먼저 찾고 남은 만큼 더 세면 1시간 10분이에요.","70분 = 1시간 10분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"pair","unit":"hm"}},"options":[{"t":"1시간 10분","correct":true},{"t":"10시간 10분","mis":"M2-2-u4-X11"},{"t":"1시간 20분","mis":"M2-2-u4-X10"}],"asset":{"type":"dpair","a":[9,0],"b":[10,10]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#13','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C7',2,'sa','auto','1일 5시간은 몇 시간인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M2-2-u4-C7","difficulty":2,"kind":"sa","stem":"1일 5시간은 몇 시간인가요? 숫자로 쓰세요.","explanation":["하루는 24시간이에요 — 짧은바늘이 두 바퀴 돌아요.","1일 5시간 = 24시간 + 5시간이에요.","그래서 29시간이에요."],"variant_rule":{"tm":{"ask":"day","form":"toh"}},"answer":["29"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#14','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C7',2,'mc','auto','오전 11시에 피아노 연습을 시작해서 2시간 동안 했어요. 끝난 시각은 언제인가요?',ARRAY['M2-2-u4-X12']::text[],true,'{"seq":14,"concept":"M2-2-u4-C7","difficulty":2,"kind":"mc","stem":"오전 11시에 피아노 연습을 시작해서 2시간 동안 했어요. 끝난 시각은 언제인가요?","explanation":["낮 12시부터 밤 12시까지가 오후예요.","오전 11시에서 1시간 뒤가 낮 12시, 거기서 1시간 더 가면 오후 1시예요.","낮 12시를 지나면 오전이 오후로 바뀌어요."],"variant_rule":{"tm":{"ask":"ampm"}},"options":[{"t":"오후 1시","correct":true},{"t":"오전 1시","mis":"M2-2-u4-X12"},{"t":"오후 13시","mis":"M2-2-u4-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#15','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C9',2,'sa','auto','1년 6개월은 몇 개월인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M2-2-u4-C9","difficulty":2,"kind":"sa","stem":"1년 6개월은 몇 개월인가요? 숫자로 쓰세요.","explanation":["1년은 12개월이에요.","1년 6개월 = 12개월 + 6개월이에요.","그래서 18개월이에요."],"variant_rule":{"tm":{"ask":"units","form":"y2m"}},"answer":["18"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#16','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C8',2,'sa','auto','11월의 둘째 토요일은 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M2-2-u4-C8","difficulty":2,"kind":"sa","stem":"11월의 둘째 토요일은 며칠인가요? 숫자로 쓰세요.","explanation":["11월의 첫째 토요일은 7일이에요.","한 주에 7일씩 — 7, 14예요.","그래서 둘째 토요일은 14일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"nth"}},"answer":["14"],"asset":{"type":"cal","mon":11,"start":0,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#17','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C3',3,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X04','M2-2-u4-X03']::text[],true,'{"seq":17,"concept":"M2-2-u4-C3","difficulty":3,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 11과 12 사이에 있으니 11시예요.","긴바늘이 숫자 11(55분)에서 작은 눈금 1칸 더 간 곳이니 55 + 1 = 56분이에요.","그래서 11시 56분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"options":[{"t":"11시 56분","correct":true},{"t":"11시 57분","mis":"M2-2-u4-X04"},{"t":"12시 56분","mis":"M2-2-u4-X03"},{"t":"11시 50분","mis":"M2-2-u4-X04"}],"asset":{"type":"clock2","h":11,"m":56}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#18','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C6',3,'mc','auto','2시 40분에 피아노 연습을 시작해서 1시간 30분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":18,"concept":"M2-2-u4-C6","difficulty":3,"kind":"mc","stem":"2시 40분에 피아노 연습을 시작해서 1시간 30분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","explanation":["시작한 시각 2시 40분에서 1시간 30분이 지난 시각을 찾아요.","1시간 뒤는 3시 40분, 거기서 30분 더 지나면 4시 10분이에요.","분이 60분이 되면 시가 하나 커져요."],"variant_rule":{"tm":{"ask":"after"}},"options":[{"t":"4시 10분","correct":true},{"t":"3시 70분","mis":"M2-2-u4-X09"},{"t":"4시 20분","mis":"M2-2-u4-X10"},{"t":"4시","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#19','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C8',3,'mc','auto','11월 14일에서 10일 후는 며칠인가요?',ARRAY['M2-2-u4-X17']::text[],true,'{"seq":19,"concept":"M2-2-u4-C8","difficulty":3,"kind":"mc","stem":"11월 14일에서 10일 후는 며칠인가요?","explanation":["14일은 빼고 다음 날부터 하루씩 세어요.","14 + 10 = 24예요.","그래서 11월 24일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"after"}},"options":[{"t":"24일","correct":true},{"t":"23일","mis":"M2-2-u4-X17"},{"t":"25일","mis":"M2-2-u4-X17"},{"t":"22일","mis":"M2-2-u4-X17"}],"asset":{"type":"cal","mon":11,"start":0,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#20','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C10',3,'mc','auto','슬기가 처음 세발자전거를 탄 날은 2022년 5월 12일, 처음 줄넘기를 성공한 날은 2024년 5월 12일이에요. 몇 년 후인가요?',ARRAY['M2-2-u4-X14','M2-2-u4-X15']::text[],false,'{"seq":20,"concept":"M2-2-u4-C10","difficulty":3,"kind":"mc","stem":"슬기가 처음 세발자전거를 탄 날은 2022년 5월 12일, 처음 줄넘기를 성공한 날은 2024년 5월 12일이에요. 몇 년 후인가요?","options":[{"t":"2년 후","correct":true},{"t":"12년 후","mis":"M2-2-u4-X14"},{"t":"2개월 후","mis":"M2-2-u4-X15"}],"explanation":["월과 일은 5월 12일로 같아요.","2022년에서 2024년으로 년만 2 커졌어요.","그래서 2년 후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#21','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C10',3,'mc','auto','2025년 4월 22일에서 1년 후는 언제인가요?',ARRAY['M2-2-u4-X15']::text[],false,'{"seq":21,"concept":"M2-2-u4-C10","difficulty":3,"kind":"mc","stem":"2025년 4월 22일에서 1년 후는 언제인가요?","options":[{"t":"2026년 4월 22일","correct":true},{"t":"2025년 5월 22일","mis":"M2-2-u4-X15"},{"t":"2025년 4월 23일","mis":"M2-2-u4-X15"}],"explanation":["1년 후는 년만 1 커져요.","월과 일은 그대로예요.","그래서 2026년 4월 22일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#22','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C5',3,'mc','auto','2시에서 5시가 될 때까지 긴바늘은 몇 바퀴 돌았나요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],true,'{"seq":22,"concept":"M2-2-u4-C5","difficulty":3,"kind":"mc","stem":"2시에서 5시가 될 때까지 긴바늘은 몇 바퀴 돌았나요?","explanation":["긴바늘이 한 바퀴 돌면 60분 — 1시간이 지나요.","2시부터 5시까지 3시간이 지났어요.","그래서 긴바늘은 3바퀴 돌았어요."],"variant_rule":{"tm":{"ask":"laps"}},"options":[{"t":"3바퀴","correct":true},{"t":"5바퀴","mis":"M2-2-u4-X11"},{"t":"4바퀴","mis":"M2-2-u4-X10"},{"t":"2바퀴","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#23','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C4',4,'essay','teacher','10시 50분을 「몇 시 몇 분 전」으로 나타내고, 그렇게 나타낸 방법을 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u4-C4","difficulty":4,"kind":"essay","stem":"10시 50분을 「몇 시 몇 분 전」으로 나타내고, 그렇게 나타낸 방법을 설명해 보세요.","answer_guide":{"answer":"예: 10시 50분에서 10분이 지나면 11시가 된다. 「몇 시 전」의 시는 곧 될 정각이므로 10시 50분은 11시 10분 전이다.","scoring_points":["정각까지 10분 남았음을 썼는가","곧 될 정각 11시를 썼는가","11시 10분 전이라고 나타냈는가"]},"explanation":["10시 50분에서 10분이 지나면 11시예요.","「전」의 시는 곧 될 정각이에요.","그래서 11시 10분 전이에요."],"asset":{"type":"clock2","h":10,"m":50}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#24','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C10',4,'essay','teacher','슬기가 처음 세발자전거를 탄 날은 2022년 5월 12일, 처음 두발자전거를 탄 날은 2024년 7월 12일이에요. 몇 년 몇 개월 후인지 구하고, 몇 개월인지도 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u4-C10","difficulty":4,"kind":"essay","stem":"슬기가 처음 세발자전거를 탄 날은 2022년 5월 12일, 처음 두발자전거를 탄 날은 2024년 7월 12일이에요. 몇 년 몇 개월 후인지 구하고, 몇 개월인지도 설명해 보세요.","answer_guide":{"answer":"예: 2022년에서 2024년은 2년 후, 5월에서 7월은 2개월 후이므로 2년 2개월 후이다. 1년은 12개월이라 2년은 24개월, 24 + 2 = 26개월이다.","scoring_points":["두 날짜 사이의 년·개월·주를 바르게 찾았는가","1년 = 12개월, 1주일 = 7일을 바르게 썼는가","날짜나 기간을 단위와 함께 바르게 썼는가"]},"explanation":["년이 바뀌면 년을, 월이 바뀌면 개월을 세요.","주는 7일씩 — 달의 날수도 따져요.","날짜와 기간을 단위와 함께 바르게 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#25','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C10',4,'mc','auto','2022년 5월 12일부터 2024년 7월 12일까지는 몇 개월인가요?',ARRAY['M2-2-u4-X15','M2-2-u4-X14']::text[],false,'{"seq":25,"concept":"M2-2-u4-C10","difficulty":4,"kind":"mc","stem":"2022년 5월 12일부터 2024년 7월 12일까지는 몇 개월인가요?","options":[{"t":"26개월","correct":true},{"t":"22개월","mis":"M2-2-u4-X15"},{"t":"4개월","mis":"M2-2-u4-X15"},{"t":"2개월","mis":"M2-2-u4-X14"}],"explanation":["2022년 5월에서 2024년 5월까지 2년 — 24개월이에요.","5월에서 7월까지 2개월이에요.","24 + 2 = 26개월이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#1','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C1',1,'sa','auto','시계가 나타내는 시각은 7시 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u4-C1","difficulty":1,"kind":"sa","stem":"시계가 나타내는 시각은 7시 몇 분인가요? 숫자로 쓰세요.","explanation":["짧은바늘이 7과 8 사이에 있으니 7시예요.","긴바늘이 숫자 2를 가리키니 2 × 5 = 10분이에요.","그래서 7시 10분이에요."],"variant_rule":{"tm":{"ask":"read","step":5}},"answer":["10"],"asset":{"type":"clock2","h":7,"m":10}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#2','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C1',1,'mc','auto','긴바늘이 숫자 7을 가리키면 몇 분인가요?',ARRAY['M2-2-u4-X02']::text[],true,'{"seq":2,"concept":"M2-2-u4-C1","difficulty":1,"kind":"mc","stem":"긴바늘이 숫자 7을 가리키면 몇 분인가요?","explanation":["숫자와 숫자 사이는 작은 눈금 5칸 — 5분이에요.","숫자 7까지 5분씩 7번이니 7 × 5 = 35예요.","그래서 35분이에요 — 숫자 그대로 7분이 아니에요."],"variant_rule":{"tm":{"ask":"numm"}},"options":[{"t":"35분","correct":true},{"t":"7분","mis":"M2-2-u4-X02"},{"t":"70분","mis":"M2-2-u4-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#3','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C2',1,'mc','auto','디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u4-X06']::text[],true,'{"seq":3,"concept":"M2-2-u4-C2","difficulty":1,"kind":"mc","stem":"디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?","explanation":["「:」 왼쪽은 시, 오른쪽은 분이에요.","11 : 43은 11시 43분이에요.","시는 「열한 시」, 분은 「사십삼 분」으로 읽어요."],"variant_rule":{"tm":{"ask":"dig"}},"options":[{"t":"열한 시 사십삼 분","correct":true},{"t":"사십삼 시 열한 분","mis":"M2-2-u4-X06"},{"t":"십일 시 사십삼 분","mis":"M2-2-u4-X06"}],"asset":{"type":"digital","h":11,"m":43}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#4','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C3',1,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X04','M2-2-u4-X05']::text[],true,'{"seq":4,"concept":"M2-2-u4-C3","difficulty":1,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 4와 5 사이에 있으니 4시예요.","긴바늘이 숫자 5(25분)에서 작은 눈금 3칸 더 간 곳이니 25 + 3 = 28분이에요.","그래서 4시 28분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"options":[{"t":"4시 28분","correct":true},{"t":"4시 29분","mis":"M2-2-u4-X04"},{"t":"4시 32분","mis":"M2-2-u4-X05"}],"asset":{"type":"clock2","h":4,"m":28}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#5','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C4',1,'sa','auto','3시 50분은 4시 몇 분 전인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-2-u4-C4","difficulty":1,"kind":"sa","stem":"3시 50분은 4시 몇 분 전인가요? 숫자로 쓰세요.","explanation":["3시 50분에서 10분이 지나면 4시가 돼요.","그래서 3시 50분을 4시 10분 전이라고도 해요.","「몇 시 전」의 시는 곧 될 정각 4시예요 — 지금 시 3시가 아니에요."],"variant_rule":{"tm":{"ask":"before"}},"answer":["10"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#6','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C5',1,'sa','auto','수영을 한 시간을 시간 띠에 나타냈어요. 수영을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M2-2-u4-C5","difficulty":1,"kind":"sa","stem":"수영을 한 시간을 시간 띠에 나타냈어요. 수영을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.","explanation":["시작한 시각은 9시, 끝난 시각은 11시예요.","칠한 칸이 12칸 — 한 칸이 10분이니 120분이에요.","2시간은 60분씩 2번 — 120분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"bar"}},"answer":["120"],"asset":{"type":"tbar","from":[9,0],"to":[11,0],"label":"수영을 한 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#7','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C7',1,'mc','auto','밤 12시부터 낮 12시까지를 무엇이라고 하나요?',ARRAY['M2-2-u4-X12','M2-2-u4-X13']::text[],false,'{"seq":7,"concept":"M2-2-u4-C7","difficulty":1,"kind":"mc","stem":"밤 12시부터 낮 12시까지를 무엇이라고 하나요?","options":[{"t":"오전","correct":true},{"t":"오후","mis":"M2-2-u4-X12"},{"t":"하루","mis":"M2-2-u4-X13"}],"explanation":["하루는 낮 12시에서 오전과 오후로 나뉘어요.","밤 12시부터 낮 12시까지가 오전이에요.","그래서 오전이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#8','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C8',1,'mc','auto','10월 20일은 무슨 요일인가요?',ARRAY['M2-2-u4-X17']::text[],true,'{"seq":8,"concept":"M2-2-u4-C8","difficulty":1,"kind":"mc","stem":"10월 20일은 무슨 요일인가요?","explanation":["달력에서 20일을 찾아요.","20일이 있는 칸의 위를 따라 올라가면 화요일이에요.","같은 세로줄은 모두 같은 요일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"wday"}},"options":[{"t":"화요일","correct":true},{"t":"수요일","mis":"M2-2-u4-X17"},{"t":"월요일","mis":"M2-2-u4-X17"}],"asset":{"type":"cal","mon":10,"start":4,"days":31}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#9','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C4',2,'mc','auto','10시 10분 전은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],true,'{"seq":9,"concept":"M2-2-u4-C4","difficulty":2,"kind":"mc","stem":"10시 10분 전은 몇 시 몇 분인가요?","explanation":["10시 10분 전은 10시가 되기 10분 전이에요.","10시에서 긴바늘을 10분만큼 거꾸로 돌리면 9시 50분이에요.","짧은바늘은 아직 9와 10 사이에 있어서 9시예요."],"variant_rule":{"tm":{"ask":"beforer"}},"options":[{"t":"9시 50분","correct":true},{"t":"10시 50분","mis":"M2-2-u4-X07"},{"t":"10시 10분","mis":"M2-2-u4-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#10','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C6',2,'mc','auto','1시간 40분은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":10,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"1시간 40분은 몇 분인가요?","explanation":["1시간은 60분이에요.","1시간 40분 = 60분 + 40분이에요.","그래서 100분이에요 — 1시간을 100분으로 보면 안 돼요."],"variant_rule":{"tm":{"ask":"h60","form":"tomin"}},"options":[{"t":"100분","correct":true},{"t":"140분","mis":"M2-2-u4-X09"},{"t":"110분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#11','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C6',2,'mc','auto','100분은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":11,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"100분은 몇 시간 몇 분인가요?","explanation":["60분은 1시간이에요.","100분 = 60분 + 40분이에요.","60분은 1시간이니 1시간 40분이에요."],"variant_rule":{"tm":{"ask":"h60","form":"tohm"}},"options":[{"t":"1시간 40분","correct":true},{"t":"1시간","mis":"M2-2-u4-X09"},{"t":"10시간","mis":"M2-2-u4-X09"},{"t":"1시간 50분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#12','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C6',2,'mc','auto','피아노 연습을 시작한 시각과 끝난 시각이에요. 피아노 연습을 하는 데 걸린 시간은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],true,'{"seq":12,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"피아노 연습을 시작한 시각과 끝난 시각이에요. 피아노 연습을 하는 데 걸린 시간은 몇 시간 몇 분인가요?","explanation":["시작한 시각은 10시 40분, 끝난 시각은 12시예요.","10시 40분에서 1시간 뒤인 11시 40분을 먼저 찾고 남은 만큼 더 세면 1시간 20분이에요.","80분 = 1시간 20분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"pair","unit":"hm"}},"options":[{"t":"1시간 20분","correct":true},{"t":"12시간","mis":"M2-2-u4-X11"},{"t":"1시간 30분","mis":"M2-2-u4-X10"}],"asset":{"type":"dpair","a":[10,40],"b":[12,0]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#13','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C7',2,'sa','auto','1일 10시간은 몇 시간인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M2-2-u4-C7","difficulty":2,"kind":"sa","stem":"1일 10시간은 몇 시간인가요? 숫자로 쓰세요.","explanation":["하루는 24시간이에요 — 짧은바늘이 두 바퀴 돌아요.","1일 10시간 = 24시간 + 10시간이에요.","그래서 34시간이에요."],"variant_rule":{"tm":{"ask":"day","form":"toh"}},"answer":["34"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#14','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C7',2,'mc','auto','오전 10시에 피아노 연습을 시작해서 4시간 동안 했어요. 끝난 시각은 언제인가요?',ARRAY['M2-2-u4-X12']::text[],true,'{"seq":14,"concept":"M2-2-u4-C7","difficulty":2,"kind":"mc","stem":"오전 10시에 피아노 연습을 시작해서 4시간 동안 했어요. 끝난 시각은 언제인가요?","explanation":["낮 12시부터 밤 12시까지가 오후예요.","오전 10시에서 2시간 뒤가 낮 12시, 거기서 2시간 더 가면 오후 2시예요.","낮 12시를 지나면 오전이 오후로 바뀌어요."],"variant_rule":{"tm":{"ask":"ampm"}},"options":[{"t":"오후 2시","correct":true},{"t":"오전 2시","mis":"M2-2-u4-X12"},{"t":"오후 14시","mis":"M2-2-u4-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#15','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C9',2,'sa','auto','2년 3개월은 몇 개월인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M2-2-u4-C9","difficulty":2,"kind":"sa","stem":"2년 3개월은 몇 개월인가요? 숫자로 쓰세요.","explanation":["1년은 12개월이에요.","2년은 12개월이 2번 — 24개월이에요.","그래서 27개월이에요."],"variant_rule":{"tm":{"ask":"units","form":"y2m"}},"answer":["27"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#16','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C8',2,'sa','auto','10월의 셋째 일요일은 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M2-2-u4-C8","difficulty":2,"kind":"sa","stem":"10월의 셋째 일요일은 며칠인가요? 숫자로 쓰세요.","explanation":["10월의 첫째 일요일은 4일이에요.","한 주에 7일씩 — 4, 11, 18이에요.","그래서 셋째 일요일은 18일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"nth"}},"answer":["18"],"asset":{"type":"cal","mon":10,"start":4,"days":31}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#17','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C3',3,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X04','M2-2-u4-X03']::text[],true,'{"seq":17,"concept":"M2-2-u4-C3","difficulty":3,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 2와 3 사이에 있으니 2시예요.","긴바늘이 숫자 11(55분)에서 작은 눈금 4칸 더 간 곳이니 55 + 4 = 59분이에요.","그래서 2시 59분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"options":[{"t":"2시 59분","correct":true},{"t":"2시 57분","mis":"M2-2-u4-X04"},{"t":"3시 59분","mis":"M2-2-u4-X03"},{"t":"2시 50분","mis":"M2-2-u4-X04"}],"asset":{"type":"clock2","h":2,"m":59}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#18','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C6',3,'mc','auto','9시 30분에 피아노 연습을 시작해서 50분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":18,"concept":"M2-2-u4-C6","difficulty":3,"kind":"mc","stem":"9시 30분에 피아노 연습을 시작해서 50분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","explanation":["시작한 시각 9시 30분에서 50분이 지난 시각을 찾아요.","50분 뒤는 10시 20분이에요.","분이 60분이 되면 시가 하나 커져요."],"variant_rule":{"tm":{"ask":"after"}},"options":[{"t":"10시 20분","correct":true},{"t":"9시 80분","mis":"M2-2-u4-X09"},{"t":"10시 30분","mis":"M2-2-u4-X10"},{"t":"10시 10분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#19','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C8',3,'mc','auto','10월 25일에서 6일 전은 며칠인가요?',ARRAY['M2-2-u4-X17']::text[],true,'{"seq":19,"concept":"M2-2-u4-C8","difficulty":3,"kind":"mc","stem":"10월 25일에서 6일 전은 며칠인가요?","explanation":["25일은 빼고 전날부터 하루씩 세어요.","25 − 6 = 19예요.","그래서 10월 19일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"before"}},"options":[{"t":"19일","correct":true},{"t":"20일","mis":"M2-2-u4-X17"},{"t":"18일","mis":"M2-2-u4-X17"},{"t":"12일","mis":"M2-2-u4-X17"}],"asset":{"type":"cal","mon":10,"start":4,"days":31}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#20','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C10',3,'mc','auto','처음 줄넘기를 성공한 날 2024년 5월 12일에서 처음 두발자전거를 탄 날 2024년 7월 12일은 몇 개월 후인가요?',ARRAY['M2-2-u4-X14','M2-2-u4-X15']::text[],false,'{"seq":20,"concept":"M2-2-u4-C10","difficulty":3,"kind":"mc","stem":"처음 줄넘기를 성공한 날 2024년 5월 12일에서 처음 두발자전거를 탄 날 2024년 7월 12일은 몇 개월 후인가요?","options":[{"t":"2개월 후","correct":true},{"t":"7개월 후","mis":"M2-2-u4-X14"},{"t":"2년 후","mis":"M2-2-u4-X15"}],"explanation":["년과 일은 같아요.","5월에서 7월로 월만 2 커졌어요.","그래서 2개월 후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#21','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C10',3,'mc','auto','2024년 12월 22일에서 4개월 후는 언제인가요?',ARRAY['M2-2-u4-X10','M2-2-u4-X15']::text[],false,'{"seq":21,"concept":"M2-2-u4-C10","difficulty":3,"kind":"mc","stem":"2024년 12월 22일에서 4개월 후는 언제인가요?","options":[{"t":"2025년 4월 22일","correct":true},{"t":"2024년 4월 22일","mis":"M2-2-u4-X10"},{"t":"2024년 12월 26일","mis":"M2-2-u4-X15"}],"explanation":["12월에서 1개월 후는 다음 해 1월이에요.","1월, 2월, 3월, 4월 — 4개월 후는 2025년 4월이에요.","일은 그대로 22일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#22','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C5',3,'mc','auto','5시 30분에서 9시 30분이 될 때까지 긴바늘은 몇 바퀴 돌았나요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],true,'{"seq":22,"concept":"M2-2-u4-C5","difficulty":3,"kind":"mc","stem":"5시 30분에서 9시 30분이 될 때까지 긴바늘은 몇 바퀴 돌았나요?","explanation":["긴바늘이 한 바퀴 돌면 60분 — 1시간이 지나요.","5시 30분부터 9시 30분까지 4시간이 지났어요.","그래서 긴바늘은 4바퀴 돌았어요."],"variant_rule":{"tm":{"ask":"laps"}},"options":[{"t":"4바퀴","correct":true},{"t":"9바퀴","mis":"M2-2-u4-X11"},{"t":"5바퀴","mis":"M2-2-u4-X10"},{"t":"3바퀴","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#23','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C6',4,'essay','teacher','오후 2시 20분에 영화가 시작해서 오후 3시 30분에 끝났어요. 영화를 본 시간을 몇 분으로 구하고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u4-C6","difficulty":4,"kind":"essay","stem":"오후 2시 20분에 영화가 시작해서 오후 3시 30분에 끝났어요. 영화를 본 시간을 몇 분으로 구하고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 2시 20분에서 1시간 뒤는 3시 20분이고 10분 더 가서 1시간 10분이다. 1시간은 60분이므로 60 + 10 = 70분이다.","scoring_points":["1시간을 먼저 찾고 남은 만큼 셈했는가","1시간 10분을 구했는가","70분으로 바꾸었는가"]},"explanation":["2시 20분에서 1시간 뒤는 3시 20분이에요.","10분 더 가서 1시간 10분이에요.","60 + 10 = 70분이에요."],"asset":{"type":"dpair","a":[2,20],"b":[3,30]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#24','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C10',4,'essay','teacher','2024년 7월 12일에서 2024년 7월 26일은 몇 주 후인지 구하고, 년·개월과 달리 주를 셀 때 조심할 점을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u4-C10","difficulty":4,"kind":"essay","stem":"2024년 7월 12일에서 2024년 7월 26일은 몇 주 후인지 구하고, 년·개월과 달리 주를 셀 때 조심할 점을 설명해 보세요.","answer_guide":{"answer":"예: 12일에서 26일까지는 14일이고 1주일은 7일이므로 2주 후이다. 주는 7일씩 더해야 해서 달을 넘어가면 그 달의 날수를 따져야 한다.","scoring_points":["두 날짜 사이의 년·개월·주를 바르게 찾았는가","1년 = 12개월, 1주일 = 7일을 바르게 썼는가","날짜나 기간을 단위와 함께 바르게 썼는가"]},"explanation":["년이 바뀌면 년을, 월이 바뀌면 개월을 세요.","주는 7일씩 — 달의 날수도 따져요.","날짜와 기간을 단위와 함께 바르게 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#25','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C10',4,'mc','auto','2022년 5월 12일에서 2년 2개월 2주 후는 언제인가요?',ARRAY['M2-2-u4-X15','M2-2-u4-X10','M2-2-u4-X14']::text[],false,'{"seq":25,"concept":"M2-2-u4-C10","difficulty":4,"kind":"mc","stem":"2022년 5월 12일에서 2년 2개월 2주 후는 언제인가요?","options":[{"t":"2024년 7월 26일","correct":true},{"t":"2024년 7월 14일","mis":"M2-2-u4-X15"},{"t":"2024년 5월 26일","mis":"M2-2-u4-X10"},{"t":"2024년 9월 12일","mis":"M2-2-u4-X14"}],"explanation":["2년 후는 2024년 5월 12일, 2개월 더 가면 2024년 7월 12일이에요.","2주는 14일 — 12 + 14 = 26이에요.","그래서 2024년 7월 26일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#1','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C1',1,'sa','auto','시계가 나타내는 시각은 4시 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u4-C1","difficulty":1,"kind":"sa","stem":"시계가 나타내는 시각은 4시 몇 분인가요? 숫자로 쓰세요.","explanation":["짧은바늘이 4와 5 사이에 있으니 4시예요.","긴바늘이 숫자 9를 가리키니 9 × 5 = 45분이에요.","그래서 4시 45분이에요."],"variant_rule":{"tm":{"ask":"read","step":5}},"answer":["45"],"asset":{"type":"clock2","h":4,"m":45}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#2','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C1',1,'mc','auto','긴바늘이 숫자 9를 가리키면 몇 분인가요?',ARRAY['M2-2-u4-X02']::text[],true,'{"seq":2,"concept":"M2-2-u4-C1","difficulty":1,"kind":"mc","stem":"긴바늘이 숫자 9를 가리키면 몇 분인가요?","explanation":["숫자와 숫자 사이는 작은 눈금 5칸 — 5분이에요.","숫자 9까지 5분씩 9번이니 9 × 5 = 45예요.","그래서 45분이에요 — 숫자 그대로 9분이 아니에요."],"variant_rule":{"tm":{"ask":"numm"}},"options":[{"t":"45분","correct":true},{"t":"9분","mis":"M2-2-u4-X02"},{"t":"90분","mis":"M2-2-u4-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#3','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C2',1,'mc','auto','디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u4-X06']::text[],true,'{"seq":3,"concept":"M2-2-u4-C2","difficulty":1,"kind":"mc","stem":"디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?","explanation":["「:」 왼쪽은 시, 오른쪽은 분이에요.","6 : 50은 6시 50분이에요.","시는 「여섯 시」, 분은 「오십 분」으로 읽어요."],"variant_rule":{"tm":{"ask":"dig"}},"options":[{"t":"여섯 시 오십 분","correct":true},{"t":"오십 시 여섯 분","mis":"M2-2-u4-X06"},{"t":"육 시 오십 분","mis":"M2-2-u4-X06"}],"asset":{"type":"digital","h":6,"m":50}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#4','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C3',1,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X04','M2-2-u4-X05']::text[],true,'{"seq":4,"concept":"M2-2-u4-C3","difficulty":1,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 9와 10 사이에 있으니 9시예요.","긴바늘이 숫자 8(40분)에서 작은 눈금 1칸 더 간 곳이니 40 + 1 = 41분이에요.","그래서 9시 41분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"options":[{"t":"9시 41분","correct":true},{"t":"9시 42분","mis":"M2-2-u4-X04"},{"t":"9시 49분","mis":"M2-2-u4-X05"}],"asset":{"type":"clock2","h":9,"m":41}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#5','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C4',1,'sa','auto','6시 45분은 7시 몇 분 전인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-2-u4-C4","difficulty":1,"kind":"sa","stem":"6시 45분은 7시 몇 분 전인가요? 숫자로 쓰세요.","explanation":["6시 45분에서 15분이 지나면 7시가 돼요.","그래서 6시 45분을 7시 15분 전이라고도 해요.","「몇 시 전」의 시는 곧 될 정각 7시예요 — 지금 시 6시가 아니에요."],"variant_rule":{"tm":{"ask":"before"}},"answer":["15"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#6','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C5',1,'sa','auto','수영을 한 시간을 시간 띠에 나타냈어요. 수영을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M2-2-u4-C5","difficulty":1,"kind":"sa","stem":"수영을 한 시간을 시간 띠에 나타냈어요. 수영을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.","explanation":["시작한 시각은 2시 20분, 끝난 시각은 3시 20분이에요.","칠한 칸이 6칸 — 한 칸이 10분이니 60분이에요.","1시간은 60분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"bar"}},"answer":["60"],"asset":{"type":"tbar","from":[2,20],"to":[3,20],"label":"수영을 한 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#7','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C7',1,'mc','auto','낮 12시부터 밤 12시까지를 무엇이라고 하나요?',ARRAY['M2-2-u4-X12','M2-2-u4-X13']::text[],false,'{"seq":7,"concept":"M2-2-u4-C7","difficulty":1,"kind":"mc","stem":"낮 12시부터 밤 12시까지를 무엇이라고 하나요?","options":[{"t":"오후","correct":true},{"t":"오전","mis":"M2-2-u4-X12"},{"t":"하루","mis":"M2-2-u4-X13"}],"explanation":["하루는 낮 12시에서 오전과 오후로 나뉘어요.","낮 12시부터 밤 12시까지가 오후예요.","그래서 오후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#8','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C8',1,'mc','auto','3월 17일은 무슨 요일인가요?',ARRAY['M2-2-u4-X17']::text[],true,'{"seq":8,"concept":"M2-2-u4-C8","difficulty":1,"kind":"mc","stem":"3월 17일은 무슨 요일인가요?","explanation":["달력에서 17일을 찾아요.","17일이 있는 칸의 위를 따라 올라가면 화요일이에요.","같은 세로줄은 모두 같은 요일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"wday"}},"options":[{"t":"화요일","correct":true},{"t":"수요일","mis":"M2-2-u4-X17"},{"t":"월요일","mis":"M2-2-u4-X17"}],"asset":{"type":"cal","mon":3,"start":0,"days":31}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#9','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C4',2,'mc','auto','4시 15분 전은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],true,'{"seq":9,"concept":"M2-2-u4-C4","difficulty":2,"kind":"mc","stem":"4시 15분 전은 몇 시 몇 분인가요?","explanation":["4시 15분 전은 4시가 되기 15분 전이에요.","4시에서 긴바늘을 15분만큼 거꾸로 돌리면 3시 45분이에요.","짧은바늘은 아직 3과 4 사이에 있어서 3시예요."],"variant_rule":{"tm":{"ask":"beforer"}},"options":[{"t":"3시 45분","correct":true},{"t":"4시 45분","mis":"M2-2-u4-X07"},{"t":"4시 15분","mis":"M2-2-u4-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#10','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C6',2,'mc','auto','2시간 15분은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":10,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"2시간 15분은 몇 분인가요?","explanation":["1시간은 60분이에요.","2시간은 60분이 2번 — 120분이에요.","그래서 135분이에요 — 1시간을 100분으로 보면 안 돼요."],"variant_rule":{"tm":{"ask":"h60","form":"tomin"}},"options":[{"t":"135분","correct":true},{"t":"215분","mis":"M2-2-u4-X09"},{"t":"145분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#11','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C6',2,'mc','auto','135분은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":11,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"135분은 몇 시간 몇 분인가요?","explanation":["60분은 1시간이에요.","135분 = 120분 + 15분이에요.","120분은 2시간이니 2시간 15분이에요."],"variant_rule":{"tm":{"ask":"h60","form":"tohm"}},"options":[{"t":"2시간 15분","correct":true},{"t":"1시간 35분","mis":"M2-2-u4-X09"},{"t":"13시간 5분","mis":"M2-2-u4-X09"},{"t":"2시간 25분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#12','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C6',2,'mc','auto','피아노 연습을 시작한 시각과 끝난 시각이에요. 피아노 연습을 하는 데 걸린 시간은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],true,'{"seq":12,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"피아노 연습을 시작한 시각과 끝난 시각이에요. 피아노 연습을 하는 데 걸린 시간은 몇 시간 몇 분인가요?","explanation":["시작한 시각은 1시 20분, 끝난 시각은 3시예요.","1시 20분에서 1시간 뒤인 2시 20분을 먼저 찾고 남은 만큼 더 세면 1시간 40분이에요.","100분 = 1시간 40분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"pair","unit":"hm"}},"options":[{"t":"1시간 40분","correct":true},{"t":"3시간","mis":"M2-2-u4-X11"},{"t":"1시간 50분","mis":"M2-2-u4-X10"}],"asset":{"type":"dpair","a":[1,20],"b":[3,0]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#13','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C7',2,'sa','auto','2일은 몇 시간인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M2-2-u4-C7","difficulty":2,"kind":"sa","stem":"2일은 몇 시간인가요? 숫자로 쓰세요.","explanation":["하루는 24시간이에요 — 짧은바늘이 두 바퀴 돌아요.","2일은 24시간이 2번 — 48시간이에요.","그래서 48시간이에요."],"variant_rule":{"tm":{"ask":"day","form":"toh"}},"answer":["48"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#14','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C7',2,'mc','auto','오전 9시에 피아노 연습을 시작해서 5시간 동안 했어요. 끝난 시각은 언제인가요?',ARRAY['M2-2-u4-X12']::text[],true,'{"seq":14,"concept":"M2-2-u4-C7","difficulty":2,"kind":"mc","stem":"오전 9시에 피아노 연습을 시작해서 5시간 동안 했어요. 끝난 시각은 언제인가요?","explanation":["낮 12시부터 밤 12시까지가 오후예요.","오전 9시에서 3시간 뒤가 낮 12시, 거기서 2시간 더 가면 오후 2시예요.","낮 12시를 지나면 오전이 오후로 바뀌어요."],"variant_rule":{"tm":{"ask":"ampm"}},"options":[{"t":"오후 2시","correct":true},{"t":"오전 2시","mis":"M2-2-u4-X12"},{"t":"오후 14시","mis":"M2-2-u4-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#15','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C9',2,'sa','auto','1년 9개월은 몇 개월인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M2-2-u4-C9","difficulty":2,"kind":"sa","stem":"1년 9개월은 몇 개월인가요? 숫자로 쓰세요.","explanation":["1년은 12개월이에요.","1년 9개월 = 12개월 + 9개월이에요.","그래서 21개월이에요."],"variant_rule":{"tm":{"ask":"units","form":"y2m"}},"answer":["21"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#16','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C8',2,'sa','auto','5월의 둘째 수요일은 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M2-2-u4-C8","difficulty":2,"kind":"sa","stem":"5월의 둘째 수요일은 며칠인가요? 숫자로 쓰세요.","explanation":["5월의 첫째 수요일은 6일이에요.","한 주에 7일씩 — 6, 13이에요.","그래서 둘째 수요일은 13일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"nth"}},"answer":["13"],"asset":{"type":"cal","mon":5,"start":5,"days":31}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#17','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C3',3,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X04','M2-2-u4-X05','M2-2-u4-X03']::text[],true,'{"seq":17,"concept":"M2-2-u4-C3","difficulty":3,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 7과 8 사이에 있으니 7시예요.","긴바늘이 숫자 10(50분)에서 작은 눈금 3칸 더 간 곳이니 50 + 3 = 53분이에요.","그래서 7시 53분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"options":[{"t":"7시 53분","correct":true},{"t":"7시 54분","mis":"M2-2-u4-X04"},{"t":"7시 57분","mis":"M2-2-u4-X05"},{"t":"8시 53분","mis":"M2-2-u4-X03"}],"asset":{"type":"clock2","h":7,"m":53}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#18','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C6',3,'mc','auto','10시 45분에 피아노 연습을 시작해서 1시간 20분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":18,"concept":"M2-2-u4-C6","difficulty":3,"kind":"mc","stem":"10시 45분에 피아노 연습을 시작해서 1시간 20분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","explanation":["시작한 시각 10시 45분에서 1시간 20분이 지난 시각을 찾아요.","1시간 뒤는 11시 45분, 거기서 20분 더 지나면 12시 5분이에요.","분이 60분이 되면 시가 하나 커져요."],"variant_rule":{"tm":{"ask":"after"}},"options":[{"t":"12시 5분","correct":true},{"t":"11시 65분","mis":"M2-2-u4-X09"},{"t":"12시 15분","mis":"M2-2-u4-X10"},{"t":"11시 55분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#19','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C8',3,'mc','auto','7월 12일에서 9일 후는 며칠인가요?',ARRAY['M2-2-u4-X17']::text[],true,'{"seq":19,"concept":"M2-2-u4-C8","difficulty":3,"kind":"mc","stem":"7월 12일에서 9일 후는 며칠인가요?","explanation":["12일은 빼고 다음 날부터 하루씩 세어요.","12 + 9 = 21이에요.","그래서 7월 21일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"after"}},"options":[{"t":"21일","correct":true},{"t":"20일","mis":"M2-2-u4-X17"},{"t":"22일","mis":"M2-2-u4-X17"},{"t":"28일","mis":"M2-2-u4-X17"}],"asset":{"type":"cal","mon":7,"start":3,"days":31}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#20','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C10',3,'mc','auto','2024년 7월 12일에서 처음 혼자서 수영한 날 2024년 7월 26일은 몇 주 후인가요?',ARRAY['M2-2-u4-X15','M2-2-u4-X14']::text[],false,'{"seq":20,"concept":"M2-2-u4-C10","difficulty":3,"kind":"mc","stem":"2024년 7월 12일에서 처음 혼자서 수영한 날 2024년 7월 26일은 몇 주 후인가요?","options":[{"t":"2주 후","correct":true},{"t":"14주 후","mis":"M2-2-u4-X15"},{"t":"26주 후","mis":"M2-2-u4-X14"}],"explanation":["12일에서 26일까지는 14일이에요.","1주일은 7일이라 14일은 2주일이에요.","그래서 2주 후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#21','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C10',3,'mc','auto','7월 12일에서 2주 후는 7월 며칠인가요?',ARRAY['M2-2-u4-X15','M2-2-u4-X14']::text[],false,'{"seq":21,"concept":"M2-2-u4-C10","difficulty":3,"kind":"mc","stem":"7월 12일에서 2주 후는 7월 며칠인가요?","options":[{"t":"7월 26일","correct":true},{"t":"7월 14일","mis":"M2-2-u4-X15"},{"t":"9월 12일","mis":"M2-2-u4-X14"}],"explanation":["2주는 14일이에요.","12 + 14 = 26이에요.","그래서 7월 26일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#22','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C5',3,'mc','auto','1시 20분에서 7시 20분이 될 때까지 긴바늘은 몇 바퀴 돌았나요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10','M2-2-u4-X09']::text[],true,'{"seq":22,"concept":"M2-2-u4-C5","difficulty":3,"kind":"mc","stem":"1시 20분에서 7시 20분이 될 때까지 긴바늘은 몇 바퀴 돌았나요?","explanation":["긴바늘이 한 바퀴 돌면 60분 — 1시간이 지나요.","1시 20분부터 7시 20분까지 6시간이 지났어요.","그래서 긴바늘은 6바퀴 돌았어요."],"variant_rule":{"tm":{"ask":"laps"}},"options":[{"t":"6바퀴","correct":true},{"t":"7바퀴","mis":"M2-2-u4-X11"},{"t":"5바퀴","mis":"M2-2-u4-X10"},{"t":"360바퀴","mis":"M2-2-u4-X09"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#23','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C3',4,'essay','teacher','11시 55분을 보고 「12시 55분」이라고 읽은 친구가 있어요. 무엇이 잘못되었는지 설명하고 바르게 읽어 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u4-C3","difficulty":4,"kind":"essay","stem":"11시 55분을 보고 「12시 55분」이라고 읽은 친구가 있어요. 무엇이 잘못되었는지 설명하고 바르게 읽어 보세요.","answer_guide":{"answer":"예: 짧은바늘이 12에 아주 가까이 있지만 아직 11과 12 사이에 있다. 그래서 시는 11시이고, 긴바늘이 11을 가리키니 55분이다. 바른 시각은 11시 55분이다.","scoring_points":["짧은바늘이 아직 11과 12 사이임을 썼는가","시가 11시임을 썼는가","11시 55분이라고 바르게 읽었는가"]},"explanation":["짧은바늘은 12에 닿지 않았어요 — 11과 12 사이예요.","그래서 시는 11시예요.","긴바늘이 11 — 55분, 11시 55분이에요."],"asset":{"type":"clock2","h":11,"m":55}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#24','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C10',4,'essay','teacher','2024년 12월 1일에 수영을 배우고 3주 후에 스케이트를 탔어요. 스케이트를 탄 날에서 4개월 후에 배드민턴을 했어요. 배드민턴을 한 날은 언제인지 구하고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u4-C10","difficulty":4,"kind":"essay","stem":"2024년 12월 1일에 수영을 배우고 3주 후에 스케이트를 탔어요. 스케이트를 탄 날에서 4개월 후에 배드민턴을 했어요. 배드민턴을 한 날은 언제인지 구하고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 3주는 21일이므로 스케이트를 탄 날은 2024년 12월 22일이다. 12월에서 4개월 후는 다음 해 4월이므로 배드민턴을 한 날은 2025년 4월 22일이다.","scoring_points":["두 날짜 사이의 년·개월·주를 바르게 찾았는가","1년 = 12개월, 1주일 = 7일을 바르게 썼는가","날짜나 기간을 단위와 함께 바르게 썼는가"]},"explanation":["년이 바뀌면 년을, 월이 바뀌면 개월을 세요.","주는 7일씩 — 달의 날수도 따져요.","날짜와 기간을 단위와 함께 바르게 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#25','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C10',4,'mc','auto','7월 26일에서 3주일 후는 몇 월 며칠인가요?',ARRAY['M2-2-u4-X18','M2-2-u4-X15']::text[],false,'{"seq":25,"concept":"M2-2-u4-C10","difficulty":4,"kind":"mc","stem":"7월 26일에서 3주일 후는 몇 월 며칠인가요?","options":[{"t":"8월 16일","correct":true},{"t":"7월 47일","mis":"M2-2-u4-X18"},{"t":"8월 17일","mis":"M2-2-u4-X18"},{"t":"7월 29일","mis":"M2-2-u4-X15"}],"explanation":["3주일은 21일이에요.","7월은 31일까지라 26일에서 5일 지나면 7월 31일이에요.","16일 더 지나면 8월 16일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#1','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C1',1,'sa','auto','시계가 나타내는 시각은 11시 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u4-C1","difficulty":1,"kind":"sa","stem":"시계가 나타내는 시각은 11시 몇 분인가요? 숫자로 쓰세요.","explanation":["짧은바늘이 11과 12 사이에 있으니 11시예요.","긴바늘이 숫자 5를 가리키니 5 × 5 = 25분이에요.","그래서 11시 25분이에요."],"variant_rule":{"tm":{"ask":"read","step":5}},"answer":["25"],"asset":{"type":"clock2","h":11,"m":25}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#2','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C1',1,'mc','auto','긴바늘이 숫자 11을 가리키면 몇 분인가요?',ARRAY['M2-2-u4-X02']::text[],true,'{"seq":2,"concept":"M2-2-u4-C1","difficulty":1,"kind":"mc","stem":"긴바늘이 숫자 11을 가리키면 몇 분인가요?","explanation":["숫자와 숫자 사이는 작은 눈금 5칸 — 5분이에요.","숫자 11까지 5분씩 11번이니 11 × 5 = 55예요.","그래서 55분이에요 — 숫자 그대로 11분이 아니에요."],"variant_rule":{"tm":{"ask":"numm"}},"options":[{"t":"55분","correct":true},{"t":"11분","mis":"M2-2-u4-X02"},{"t":"110분","mis":"M2-2-u4-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#3','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C2',1,'mc','auto','디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u4-X06']::text[],true,'{"seq":3,"concept":"M2-2-u4-C2","difficulty":1,"kind":"mc","stem":"디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?","explanation":["「:」 왼쪽은 시, 오른쪽은 분이에요.","3 : 08은 3시 8분이에요.","시는 「세 시」, 분은 「팔 분」으로 읽어요."],"variant_rule":{"tm":{"ask":"dig"}},"options":[{"t":"세 시 팔 분","correct":true},{"t":"팔 시 세 분","mis":"M2-2-u4-X06"},{"t":"삼 시 팔 분","mis":"M2-2-u4-X06"}],"asset":{"type":"digital","h":3,"m":8}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#4','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C3',1,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X04','M2-2-u4-X05']::text[],true,'{"seq":4,"concept":"M2-2-u4-C3","difficulty":1,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 6과 7 사이에 있으니 6시예요.","긴바늘이 숫자 1(5분)에서 작은 눈금 2칸 더 간 곳이니 5 + 2 = 7분이에요.","그래서 6시 7분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"options":[{"t":"6시 7분","correct":true},{"t":"6시 8분","mis":"M2-2-u4-X04"},{"t":"6시 13분","mis":"M2-2-u4-X05"}],"asset":{"type":"clock2","h":6,"m":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#5','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C4',1,'sa','auto','11시 50분은 12시 몇 분 전인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-2-u4-C4","difficulty":1,"kind":"sa","stem":"11시 50분은 12시 몇 분 전인가요? 숫자로 쓰세요.","explanation":["11시 50분에서 10분이 지나면 12시가 돼요.","그래서 11시 50분을 12시 10분 전이라고도 해요.","「몇 시 전」의 시는 곧 될 정각 12시예요 — 지금 시 11시가 아니에요."],"variant_rule":{"tm":{"ask":"before"}},"answer":["10"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#6','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C5',1,'sa','auto','수영을 한 시간을 시간 띠에 나타냈어요. 수영을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M2-2-u4-C5","difficulty":1,"kind":"sa","stem":"수영을 한 시간을 시간 띠에 나타냈어요. 수영을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.","explanation":["시작한 시각은 4시, 끝난 시각은 6시예요.","칠한 칸이 12칸 — 한 칸이 10분이니 120분이에요.","2시간은 60분씩 2번 — 120분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"bar"}},"answer":["120"],"asset":{"type":"tbar","from":[4,0],"to":[6,0],"label":"수영을 한 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#7','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C7',1,'mc','auto','짧은바늘이 시계를 한 바퀴 도는 데 걸리는 시간은 몇 시간인가요?',ARRAY['M2-2-u4-X13','M2-2-u4-X01']::text[],false,'{"seq":7,"concept":"M2-2-u4-C7","difficulty":1,"kind":"mc","stem":"짧은바늘이 시계를 한 바퀴 도는 데 걸리는 시간은 몇 시간인가요?","options":[{"t":"12시간","correct":true},{"t":"24시간","mis":"M2-2-u4-X13"},{"t":"1시간","mis":"M2-2-u4-X01"}],"explanation":["짧은바늘은 1시간에 숫자 한 칸을 가요.","숫자는 12개예요.","그래서 한 바퀴는 12시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#8','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C8',1,'mc','auto','6월 9일은 무슨 요일인가요?',ARRAY['M2-2-u4-X17']::text[],true,'{"seq":8,"concept":"M2-2-u4-C8","difficulty":1,"kind":"mc","stem":"6월 9일은 무슨 요일인가요?","explanation":["달력에서 9일을 찾아요.","9일이 있는 칸의 위를 따라 올라가면 화요일이에요.","같은 세로줄은 모두 같은 요일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"wday"}},"options":[{"t":"화요일","correct":true},{"t":"수요일","mis":"M2-2-u4-X17"},{"t":"월요일","mis":"M2-2-u4-X17"}],"asset":{"type":"cal","mon":6,"start":1,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#9','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C4',2,'mc','auto','12시 5분 전은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],true,'{"seq":9,"concept":"M2-2-u4-C4","difficulty":2,"kind":"mc","stem":"12시 5분 전은 몇 시 몇 분인가요?","explanation":["12시 5분 전은 12시가 되기 5분 전이에요.","12시에서 긴바늘을 5분만큼 거꾸로 돌리면 11시 55분이에요.","짧은바늘은 아직 11과 12 사이에 있어서 11시예요."],"variant_rule":{"tm":{"ask":"beforer"}},"options":[{"t":"11시 55분","correct":true},{"t":"12시 55분","mis":"M2-2-u4-X07"},{"t":"12시 5분","mis":"M2-2-u4-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#10','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C6',2,'mc','auto','1시간 25분은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":10,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"1시간 25분은 몇 분인가요?","explanation":["1시간은 60분이에요.","1시간 25분 = 60분 + 25분이에요.","그래서 85분이에요 — 1시간을 100분으로 보면 안 돼요."],"variant_rule":{"tm":{"ask":"h60","form":"tomin"}},"options":[{"t":"85분","correct":true},{"t":"125분","mis":"M2-2-u4-X09"},{"t":"95분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#11','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C6',2,'mc','auto','150분은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":11,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"150분은 몇 시간 몇 분인가요?","explanation":["60분은 1시간이에요.","150분 = 120분 + 30분이에요.","120분은 2시간이니 2시간 30분이에요."],"variant_rule":{"tm":{"ask":"h60","form":"tohm"}},"options":[{"t":"2시간 30분","correct":true},{"t":"1시간 50분","mis":"M2-2-u4-X09"},{"t":"15시간","mis":"M2-2-u4-X09"},{"t":"2시간 40분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#12','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C6',2,'mc','auto','피아노 연습을 시작한 시각과 끝난 시각이에요. 피아노 연습을 하는 데 걸린 시간은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],true,'{"seq":12,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"피아노 연습을 시작한 시각과 끝난 시각이에요. 피아노 연습을 하는 데 걸린 시간은 몇 시간 몇 분인가요?","explanation":["시작한 시각은 3시 30분, 끝난 시각은 5시 40분이에요.","3시 30분에서 1시간 뒤인 4시 30분을 먼저 찾고 남은 만큼 더 세면 2시간 10분이에요.","130분 = 2시간 10분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"pair","unit":"hm"}},"options":[{"t":"2시간 10분","correct":true},{"t":"5시간 40분","mis":"M2-2-u4-X11"},{"t":"2시간 20분","mis":"M2-2-u4-X10"}],"asset":{"type":"dpair","a":[3,30],"b":[5,40]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#13','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C7',2,'sa','auto','1일 12시간은 몇 시간인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M2-2-u4-C7","difficulty":2,"kind":"sa","stem":"1일 12시간은 몇 시간인가요? 숫자로 쓰세요.","explanation":["하루는 24시간이에요 — 짧은바늘이 두 바퀴 돌아요.","1일 12시간 = 24시간 + 12시간이에요.","그래서 36시간이에요."],"variant_rule":{"tm":{"ask":"day","form":"toh"}},"answer":["36"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#14','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C7',2,'mc','auto','오전 8시에 피아노 연습을 시작해서 6시간 동안 했어요. 끝난 시각은 언제인가요?',ARRAY['M2-2-u4-X12']::text[],true,'{"seq":14,"concept":"M2-2-u4-C7","difficulty":2,"kind":"mc","stem":"오전 8시에 피아노 연습을 시작해서 6시간 동안 했어요. 끝난 시각은 언제인가요?","explanation":["낮 12시부터 밤 12시까지가 오후예요.","오전 8시에서 4시간 뒤가 낮 12시, 거기서 2시간 더 가면 오후 2시예요.","낮 12시를 지나면 오전이 오후로 바뀌어요."],"variant_rule":{"tm":{"ask":"ampm"}},"options":[{"t":"오후 2시","correct":true},{"t":"오전 2시","mis":"M2-2-u4-X12"},{"t":"오후 14시","mis":"M2-2-u4-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#15','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C9',2,'sa','auto','2년은 몇 개월인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M2-2-u4-C9","difficulty":2,"kind":"sa","stem":"2년은 몇 개월인가요? 숫자로 쓰세요.","explanation":["1년은 12개월이에요.","2년은 12개월이 2번 — 24개월이에요.","그래서 24개월이에요."],"variant_rule":{"tm":{"ask":"units","form":"y2m"}},"answer":["24"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#16','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C8',2,'sa','auto','9월의 넷째 금요일은 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M2-2-u4-C8","difficulty":2,"kind":"sa","stem":"9월의 넷째 금요일은 며칠인가요? 숫자로 쓰세요.","explanation":["9월의 첫째 금요일은 4일이에요.","한 주에 7일씩 — 4, 11, 18, 25예요.","그래서 넷째 금요일은 25일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"nth"}},"answer":["25"],"asset":{"type":"cal","mon":9,"start":2,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#17','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C3',3,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X04','M2-2-u4-X03']::text[],true,'{"seq":17,"concept":"M2-2-u4-C3","difficulty":3,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 5와 6 사이에 있으니 5시예요.","긴바늘이 숫자 11(55분)에서 작은 눈금 3칸 더 간 곳이니 55 + 3 = 58분이에요.","그래서 5시 58분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"options":[{"t":"5시 58분","correct":true},{"t":"5시 59분","mis":"M2-2-u4-X04"},{"t":"6시 58분","mis":"M2-2-u4-X03"},{"t":"5시 50분","mis":"M2-2-u4-X04"}],"asset":{"type":"clock2","h":5,"m":58}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#18','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C6',3,'mc','auto','1시 35분에 피아노 연습을 시작해서 1시간 40분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":18,"concept":"M2-2-u4-C6","difficulty":3,"kind":"mc","stem":"1시 35분에 피아노 연습을 시작해서 1시간 40분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","explanation":["시작한 시각 1시 35분에서 1시간 40분이 지난 시각을 찾아요.","1시간 뒤는 2시 35분, 거기서 40분 더 지나면 3시 15분이에요.","분이 60분이 되면 시가 하나 커져요."],"variant_rule":{"tm":{"ask":"after"}},"options":[{"t":"3시 15분","correct":true},{"t":"2시 75분","mis":"M2-2-u4-X09"},{"t":"3시 25분","mis":"M2-2-u4-X10"},{"t":"3시 5분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#19','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C8',3,'mc','auto','5월 20일에서 8일 전은 며칠인가요?',ARRAY['M2-2-u4-X17']::text[],true,'{"seq":19,"concept":"M2-2-u4-C8","difficulty":3,"kind":"mc","stem":"5월 20일에서 8일 전은 며칠인가요?","explanation":["20일은 빼고 전날부터 하루씩 세어요.","20 − 8 = 12예요.","그래서 5월 12일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"before"}},"options":[{"t":"12일","correct":true},{"t":"13일","mis":"M2-2-u4-X17"},{"t":"11일","mis":"M2-2-u4-X17"},{"t":"5일","mis":"M2-2-u4-X17"}],"asset":{"type":"cal","mon":5,"start":5,"days":31}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#20','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C10',3,'mc','auto','2024년 12월 1일에 수영을 배우고 3주 후에 스케이트를 탔어요. 스케이트를 탄 날은 언제인가요?',ARRAY['M2-2-u4-X15','M2-2-u4-X14']::text[],false,'{"seq":20,"concept":"M2-2-u4-C10","difficulty":3,"kind":"mc","stem":"2024년 12월 1일에 수영을 배우고 3주 후에 스케이트를 탔어요. 스케이트를 탄 날은 언제인가요?","options":[{"t":"2024년 12월 22일","correct":true},{"t":"2024년 12월 4일","mis":"M2-2-u4-X15"},{"t":"2025년 3월 1일","mis":"M2-2-u4-X14"}],"explanation":["3주는 7일이 3번 — 21일이에요.","1 + 21 = 22예요.","그래서 2024년 12월 22일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#21','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C10',3,'mc','auto','방학식은 7월 24일이에요. 오늘이 7월 10일이면 방학식까지 며칠 남았나요?',ARRAY['M2-2-u4-X17','M2-2-u4-X14']::text[],false,'{"seq":21,"concept":"M2-2-u4-C10","difficulty":3,"kind":"mc","stem":"방학식은 7월 24일이에요. 오늘이 7월 10일이면 방학식까지 며칠 남았나요?","options":[{"t":"14일","correct":true},{"t":"15일","mis":"M2-2-u4-X17"},{"t":"24일","mis":"M2-2-u4-X14"}],"explanation":["오늘은 빼고 내일부터 하루씩 세요.","24 − 10 = 14예요.","그래서 14일 남았어요 — 디데이 14일 전이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#22','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C5',3,'mc','auto','7시 10분에서 9시 10분이 될 때까지 긴바늘은 몇 바퀴 돌았나요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],true,'{"seq":22,"concept":"M2-2-u4-C5","difficulty":3,"kind":"mc","stem":"7시 10분에서 9시 10분이 될 때까지 긴바늘은 몇 바퀴 돌았나요?","explanation":["긴바늘이 한 바퀴 돌면 60분 — 1시간이 지나요.","7시 10분부터 9시 10분까지 2시간이 지났어요.","그래서 긴바늘은 2바퀴 돌았어요."],"variant_rule":{"tm":{"ask":"laps"}},"options":[{"t":"2바퀴","correct":true},{"t":"9바퀴","mis":"M2-2-u4-X11"},{"t":"3바퀴","mis":"M2-2-u4-X10"},{"t":"1바퀴","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#23','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C6',4,'essay','teacher','「1시간 = 60분」을 쓰는 까닭을 시계의 두 바늘로 설명하고, 2시간 30분은 몇 분인지 구해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u4-C6","difficulty":4,"kind":"essay","stem":"「1시간 = 60분」을 쓰는 까닭을 시계의 두 바늘로 설명하고, 2시간 30분은 몇 분인지 구해 보세요.","answer_guide":{"answer":"예: 긴바늘이 한 바퀴 돌면 60분이 지나고 그동안 짧은바늘은 숫자 한 칸을 가서 1시간이 지난다. 그래서 1시간 = 60분이다. 2시간 30분은 60 + 60 + 30 = 150분이다.","scoring_points":["긴바늘 한 바퀴가 60분임을 썼는가","짧은바늘 한 칸이 1시간임을 썼는가","150분이라고 구했는가"]},"explanation":["긴바늘 한 바퀴 = 60분이에요.","그동안 짧은바늘 한 칸 = 1시간이에요.","2시간 30분 = 60 + 60 + 30 = 150분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#24','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C10',4,'essay','teacher','오늘은 10월 12일이고 내 생일은 11월 2일이에요. 생일까지 며칠 남았는지 달력으로 세는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u4-C10","difficulty":4,"kind":"essay","stem":"오늘은 10월 12일이고 내 생일은 11월 2일이에요. 생일까지 며칠 남았는지 달력으로 세는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 오늘은 빼고 센다. 10월은 31일까지라 10월 12일에서 10월 31일까지 19일, 11월 1일과 2일이 2일이므로 19 + 2 = 21일 남았다.","scoring_points":["두 날짜 사이의 년·개월·주를 바르게 찾았는가","1년 = 12개월, 1주일 = 7일을 바르게 썼는가","날짜나 기간을 단위와 함께 바르게 썼는가"]},"explanation":["년이 바뀌면 년을, 월이 바뀌면 개월을 세요.","주는 7일씩 — 달의 날수도 따져요.","날짜와 기간을 단위와 함께 바르게 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#25','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C10',4,'mc','auto','10월 20일에서 2주일 후는 몇 월 며칠인가요?',ARRAY['M2-2-u4-X18','M2-2-u4-X15']::text[],false,'{"seq":25,"concept":"M2-2-u4-C10","difficulty":4,"kind":"mc","stem":"10월 20일에서 2주일 후는 몇 월 며칠인가요?","options":[{"t":"11월 3일","correct":true},{"t":"11월 4일","mis":"M2-2-u4-X18"},{"t":"10월 34일","mis":"M2-2-u4-X18"},{"t":"10월 22일","mis":"M2-2-u4-X15"}],"explanation":["2주일은 14일이에요.","10월은 31일까지라 20일에서 11일 지나면 10월 31일이에요.","3일 더 지나면 11월 3일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u5-C1','math',2,2,'u5',2,'자료를 분류하여 표로 나타내기 — 기준을 정해 같은 것끼리 모으고, ／ 표시를 하며 빠짐없이 세어 수로 적기',ARRAY['2수04-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u5-C2','math',2,2,'u5',2,'표의 합계와 편리한 점 — 항목별 수를 모두 더한 합계가 전체 수임을 알고, 자료와 표가 각각 무엇을 알기 좋은지 말하기',ARRAY['2수04-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u5-C3','math',2,2,'u5',3,'자료를 조사하는 방법 — 말하기·손 들기·이름 붙이기 등 알맞은 방법을 고르고, 빠진 사람 없이 조사하기',ARRAY['2수04-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u5-C4','math',2,2,'u5',3,'조사한 자료를 표로 나타내기 — 제목·항목·수·합계를 갖추어 표를 만들고, ／ 표시를 세어 빈칸을 채우며 합계로 확인하기',ARRAY['2수04-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u5-C5','math',2,2,'u5',4,'그래프를 그리는 차례 — 가로·세로에 나타낼 것을 정하고 가장 큰 수만큼 칸을 나누며, 가로와 세로를 바꾸어도 수는 같음을 알기',ARRAY['2수04-03']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u5-C6','math',2,2,'u5',4,'맨 아래부터 빠짐없이 그리기 — ◯·×·／를 한 칸에 하나씩 맨 아래부터 빠짐없이 그리고, 표와 그래프의 수가 같게 옮기며 잘못 그린 곳 찾기',ARRAY['2수04-03']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u5-C7','math',2,2,'u5',5,'표와 그래프 읽기 — 표에서 수와 합계를, 그래프에서 많고 적음을 읽고 차이·「n보다 많은」을 찾으며 둘의 편리한 점을 가리기',ARRAY['2수04-03']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u5-C8','math',2,2,'u5',6,'조사하여 표와 그래프로 나타내기 — 우리 반을 조사해 표와 그래프로 옮기고, 알게 된 것을 그대로 적어 전하기',ARRAY['2수04-03']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X01','math',2,'u5',ARRAY['M2-2-u5-C1','M2-2-u5-C2','M2-2-u5-C4','M2-2-u5-C6','M2-2-u5-C7','M2-2-u5-C8']::text[],'세다가 빠뜨리거나 두 번 세어 수가 하나 어긋난다','센 것에 ／ 표시를 하며 하나씩 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X02','math',2,'u5',ARRAY['M2-2-u5-C1','M2-2-u5-C4','M2-2-u5-C7']::text[],'자료에서 묻는 항목이 아닌 것까지 세거나 이웃 칸의 수를 읽는다','묻는 항목 이름에 동그라미를 치고 그것만 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X03','math',2,'u5',ARRAY['M2-2-u5-C2','M2-2-u5-C4','M2-2-u5-C7','M2-2-u5-C8']::text[],'합계와 한 칸의 수를 섞는다 — 가장 큰 수를 합계로, 합계를 한 항목의 수로 답한다','합계는 모든 칸을 더한 수 — 한 칸보다 언제나 커요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X04','math',2,'u5',ARRAY['M2-2-u5-C2','M2-2-u5-C7']::text[],'「몇 가지」와 「몇 명」을 섞는다 — 항목 수를 학생 수로, 학생 수를 가짓수로 답한다','가지는 칸의 수, 명은 사람 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X05','math',2,'u5',ARRAY['M2-2-u5-C2','M2-2-u5-C4']::text[],'표의 빈칸을 합계에서 빼지 않고 나머지 칸의 합을 그대로 쓴다','합계 − 나머지 칸의 합 = 빈칸') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X06','math',2,'u5',ARRAY['M2-2-u5-C1','M2-2-u5-C4','M2-2-u5-C8']::text[],'／ 표시를 셀 때 다섯 묶음을 4나 6으로 세거나 한 줄을 통째로 빠뜨린다','／／／／／ 한 묶음은 5 — 5, 10 하고 묶음부터 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X07','math',2,'u5',ARRAY['M2-2-u5-C7','M2-2-u5-C8']::text[],'많고 적음을 수가 아니라 칸의 자리나 이름으로 판단한다(맨 앞 칸이 가장 많다)','수를 보고 견주기 — 그래프는 높이, 표는 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X08','math',2,'u5',ARRAY['M2-2-u5-C2','M2-2-u5-C7']::text[],'「몇 더 많은」을 묻는데 두 수를 더하거나, 「모두 몇」을 묻는데 뺀다','더 많은 → 빼기, 모두 → 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X09','math',2,'u5',ARRAY['M2-2-u5-C1','M2-2-u5-C2','M2-2-u5-C3','M2-2-u5-C4','M2-2-u5-C5','M2-2-u5-C6','M2-2-u5-C7','M2-2-u5-C8']::text[],'묻는 말을 거꾸로 읽는다 — 많은↔적은, 아닌↔맞는, 바른↔잘못된','물음의 「가장·아닌·잘못」에 동그라미 치기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X10','math',2,'u5',ARRAY['M2-2-u5-C5','M2-2-u5-C6']::text[],'◯를 위에서부터 그리거나 중간 칸을 건너뛰어 그린다','맨 아래 칸부터 한 칸에 하나씩 빠짐없이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X11','math',2,'u5',ARRAY['M2-2-u5-C6','M2-2-u5-C8']::text[],'표의 수와 그래프의 ◯ 수를 다르게 옮긴다(하나 많거나 적게)','표의 수를 짚어 가며 ◯를 하나씩 세어 그리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X12','math',2,'u5',ARRAY['M2-2-u5-C5']::text[],'그래프의 칸 수를 합계나 항목 수로 잡는다(칸이 모자라거나 빈 칸이 많이 남음)','세로 칸 수 = 가장 큰 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X13','math',2,'u5',ARRAY['M2-2-u5-C5','M2-2-u5-C6']::text[],'한 그래프에 기호를 섞어 쓰거나, 가로와 세로를 바꾸면 수도 달라진다고 여긴다','기호는 한 가지로 — 자리를 바꿔도 수는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X14','math',2,'u5',ARRAY['M2-2-u5-C7']::text[],'「n보다 많은」에 딱 n인 것을 넣는다(경곗값)','n인 칸 위에 선을 긋고 그 위에 ◯가 있는 것만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X15','math',2,'u5',ARRAY['M2-2-u5-C1','M2-2-u5-C3','M2-2-u5-C4','M2-2-u5-C8']::text[],'조사·표 만들기의 절차를 어긴다 — 기준 없이 모으기, 몇 명만 조사하기, 제목·합계 빠뜨리기, 합계를 마음대로 고치기','모두 조사 → 기준에 따라 모으기 → 제목·항목·수·합계') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u5-X16','math',2,'u5',ARRAY['M2-2-u5-C2','M2-2-u5-C7','M2-2-u5-C8']::text[],'자료·표·그래프가 각각 알기 좋은 것을 뒤바꾼다(표에서 누가 골랐는지 안다, 그래프가 수를 알기 좋다)','자료는 누가, 표는 수와 합계, 그래프는 많고 적음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_basic#1','math',2,2,'u5','L02','g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C1',1,'sa','auto','놀이 한마당이 즐거웠던 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u5-C1","difficulty":1,"kind":"sa","stem":"놀이 한마당이 즐거웠던 학생은 몇 명인가요? 숫자로 쓰세요.","explanation":["표에서 「놀이 한마당」 칸 아래의 수를 읽어요.","놀이 한마당이 즐거웠던 학생은 5명이에요.","항목 이름과 그 아래 수를 짝지어 읽어요."],"variant_rule":{"tg":{"ask":"count"}},"answer":["5","5명"],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_basic#2','math',2,2,'u5','L02','g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C1',1,'mc','auto','자료를 보세요. 현장체험학습이 즐거웠던 학생은 몇 명인가요?',ARRAY['M2-2-u5-X01']::text[],true,'{"seq":2,"concept":"M2-2-u5-C1","difficulty":1,"kind":"mc","stem":"자료를 보세요. 현장체험학습이 즐거웠던 학생은 몇 명인가요?","explanation":["자료에서 「현장체험학습」을 고른 이름표만 ／ 표시를 하며 세어요.","현장체험학습이 즐거웠던 학생은 3명이에요.","빠뜨리거나 두 번 세지 않게 표시하며 세요."],"variant_rule":{"tg":{"ask":"count","src":"cards"}},"options":[{"t":"3명","correct":true},{"t":"4명","mis":"M2-2-u5-X01"},{"t":"2명","mis":"M2-2-u5-X01"}],"asset":{"type":"cards","topic":"act","items":[["호진","현장체험학습"],["재이","현장체험학습"],["효주","놀이 한마당"],["연우","안전 체험"],["상혁","안전 체험"],["수찬","신나는 무용"],["시후","놀이 한마당"],["세미","신나는 무용"],["슬기","놀이 한마당"],["민하","현장체험학습"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_basic#3','math',2,2,'u5','L02','g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C1',1,'mc','auto','자료를 분류하여 표로 나타낼 때 가장 먼저 할 일은 무엇인가요?',ARRAY['M2-2-u5-X15','M2-2-u5-X16']::text[],true,'{"seq":3,"concept":"M2-2-u5-C1","difficulty":1,"kind":"mc","stem":"자료를 분류하여 표로 나타낼 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"기준을 정해 같은 것끼리 모은다","correct":true},{"t":"합계부터 쓴다","mis":"M2-2-u5-X15"},{"t":"그래프를 그린다","mis":"M2-2-u5-X16"}],"explanation":["먼저 무엇을 기준으로 나눌지 정해요.","같은 것끼리 모은 다음 세어서 수로 적어요.","합계는 수를 다 적은 뒤에 더해서 써요."],"variant_rule":{"alt":[{"stem":"분류한 칸의 이름을 세어서 수로 적은 것을 무엇이라고 하나요?","options":[{"t":"표","correct":true},{"t":"그래프","mis":"M2-2-u5-X16"},{"t":"자료","mis":"M2-2-u5-X16"}],"explanation":["분류한 칸마다 몇 개인지 세어 수로 적어요.","그렇게 적은 것이 표예요.","그래프는 ◯를 쌓아 나타낸 것이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_basic#4','math',2,2,'u5','L02','g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C2',1,'mc','auto','슬기네 반 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X03','M2-2-u5-X04']::text[],true,'{"seq":4,"concept":"M2-2-u5-C2","difficulty":1,"kind":"mc","stem":"슬기네 반 학생은 모두 몇 명인가요?","explanation":["표의 각 활동별 수는 현장체험학습 7명, 안전 체험 3명, 놀이 한마당 5명, 신나는 무용 2명, 텃밭 가꾸기 3명이에요.","7 + 3 + 5 + 2 + 3 = 20이니 모두 20명이에요.","항목별 수를 모두 더한 것이 합계 — 전체 수예요."],"variant_rule":{"tg":{"ask":"total"}},"options":[{"t":"20명","correct":true},{"t":"7명","mis":"M2-2-u5-X03"},{"t":"5명","mis":"M2-2-u5-X04"}],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_basic#5','math',2,2,'u5','L02','g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C1',2,'mc','auto','신나는 무용이 즐거웠던 학생은 몇 명인가요?',ARRAY['M2-2-u5-X01','M2-2-u5-X02']::text[],true,'{"seq":5,"concept":"M2-2-u5-C1","difficulty":2,"kind":"mc","stem":"신나는 무용이 즐거웠던 학생은 몇 명인가요?","explanation":["표에서 「신나는 무용」 칸 아래의 수를 읽어요.","신나는 무용이 즐거웠던 학생은 2명이에요.","항목 이름과 그 아래 수를 짝지어 읽어요."],"variant_rule":{"tg":{"ask":"count"}},"options":[{"t":"2명","correct":true},{"t":"3명","mis":"M2-2-u5-X01"},{"t":"1명","mis":"M2-2-u5-X01"},{"t":"7명","mis":"M2-2-u5-X02"}],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_basic#6','math',2,2,'u5','L02','g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C2',2,'ox','auto','표를 보면 서준이가 어떤 활동을 골랐는지 알 수 있어요.',ARRAY['M2-2-u5-X16']::text[],true,'{"seq":6,"concept":"M2-2-u5-C2","difficulty":2,"kind":"ox","stem":"표를 보면 서준이가 어떤 활동을 골랐는지 알 수 있어요.","answer":"X","reason_options":[{"t":"표에는 활동별 학생 수만 있고 누가 골랐는지는 없으니까","correct":true},{"t":"표에는 조사한 것이 다 적혀 있으니까","mis":"M2-2-u5-X16"}],"mis":"M2-2-u5-X16","explanation":["표에는 활동별 학생 수와 합계만 적혀 있어요.","누가 무엇을 골랐는지는 자료(이름표)를 봐야 알아요.","표는 활동별 학생 수를 한눈에 알기 좋아요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20},"variant_rule":{"alt":[{"stem":"표를 보면 활동별로 몇 명인지 한눈에 알 수 있어요.","answer":"O","reason_options":[{"t":"활동마다 수가 적혀 있으니까","correct":true},{"t":"이름이 하나씩 다 적혀 있으니까","mis":"M2-2-u5-X16"}],"explanation":["표에는 활동별 학생 수가 수로 적혀 있어요.","그래서 몇 명인지 바로 읽을 수 있어요.","이름은 자료에만 있어요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_basic#7','math',2,2,'u5','L02','g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C1',2,'match','auto','분류한 칸에 모인 이름 수를 세어 표의 수와 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u5-C1","difficulty":2,"kind":"match","stem":"분류한 칸에 모인 이름 수를 세어 표의 수와 이으세요.","pairs":[{"l":"안전 체험 — 채원·세미·도현","r":"3명"},{"l":"신나는 무용 — 호진·지아","r":"2명"},{"l":"놀이 한마당 — 지은·시후·다윤·정우·소민","r":"5명"}],"mis":"M2-2-u5-X01","explanation":["칸에 모인 이름을 하나씩 세요.","안전 체험 3명, 신나는 무용 2명이에요.","놀이 한마당은 5명이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 분류한 칸에 모인 이름 수를 세어 표의 수와 이으세요.","pairs":[{"l":"현장체험학습 — 서준·소희·재이·효주·슬기·우영·수찬","r":"7명"},{"l":"텃밭 가꾸기 — 상혁·연우·민하","r":"3명"},{"l":"신나는 무용 — 호진·지아","r":"2명"}],"explanation":["칸에 모인 이름을 하나씩 세요.","현장체험학습 7명, 텃밭 가꾸기 3명이에요.","신나는 무용은 2명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_basic#8','math',2,2,'u5','L02','g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C2',2,'sa','auto','표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M2-2-u5-C2","difficulty":2,"kind":"sa","stem":"표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["나머지 칸을 더하면 3 + 5 + 2 + 3 = 13이에요.","13 + □ = 20이니 □ = 7이에요.","합계에서 나머지 칸의 수를 빼면 빈칸의 수예요."],"variant_rule":{"tg":{"ask":"blank"}},"answer":["7"],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[null,3,5,2,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_basic#9','math',2,2,'u5','L02','g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C2',2,'mc','auto','현장체험학습이 즐거웠던 학생과 놀이 한마당이 즐거웠던 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X08','M2-2-u5-X03']::text[],true,'{"seq":9,"concept":"M2-2-u5-C2","difficulty":2,"kind":"mc","stem":"현장체험학습이 즐거웠던 학생과 놀이 한마당이 즐거웠던 학생은 모두 몇 명인가요?","explanation":["현장체험학습이 즐거웠던 학생은 7명, 놀이 한마당이 즐거웠던 학생은 5명이에요.","7 + 5 = 12이니 모두 12명이에요.","두 칸의 수를 더해요 — 전체 합계가 아니에요."],"variant_rule":{"tg":{"ask":"sum2"}},"options":[{"t":"12명","correct":true},{"t":"2명","mis":"M2-2-u5-X08"},{"t":"20명","mis":"M2-2-u5-X03"}],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_basic#10','math',2,2,'u5','L02','g2_2_math_u5_L02_basic','lesson_basic','M2-2-u5-C2',3,'error','auto','표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u5-X03','M2-2-u5-X16']::text[],true,'{"seq":10,"concept":"M2-2-u5-C2","difficulty":3,"kind":"error","stem":"표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수찬 — 「합계가 20이니까 현장체험학습을 고른 학생이 20명이야.」","correct":true,"mis_target":"M2-2-u5-X03"},{"t":"지아 — 「활동별 학생 수를 한눈에 알 수 있어.」","mis":"M2-2-u5-X16"},{"t":"연우 — 「7 + 3 + 5 + 2 + 3 = 20이니까 합계는 20이야.」","mis":"M2-2-u5-X16"}],"explanation":["합계 20은 모든 활동의 학생 수를 더한 수예요.","현장체험학습은 7명이에요.","수찬이는 합계를 한 활동의 수로 읽었어요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「가장 큰 수가 7이니까 슬기네 반은 7명이야.」","correct":true,"mis_target":"M2-2-u5-X03"},{"t":"서아 — 「놀이 한마당이 즐거웠던 학생은 5명이야.」","mis":"M2-2-u5-X16"},{"t":"민수 — 「합계 20이 슬기네 반 학생 수야.」","mis":"M2-2-u5-X16"}],"explanation":["반 학생 수는 합계 20명이에요.","7은 현장체험학습 한 칸의 수예요.","하람이는 한 칸의 수를 전체로 읽었어요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_challenge#1','math',2,2,'u5','L02','g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C1',2,'sa','auto','파란색 연결 모형은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u5-C1","difficulty":2,"kind":"sa","stem":"파란색 연결 모형은 몇 개인가요? 숫자로 쓰세요.","explanation":["표에서 「파란색」 칸 아래의 수를 읽어요.","파란색 연결 모형은 10개예요.","항목 이름과 그 아래 수를 짝지어 읽어요."],"variant_rule":{"tg":{"ask":"count"}},"answer":["10","10개"],"asset":{"type":"ftable","topic":"block","title":"슬기네 모둠이 가지고 있는 연결 모형의 색깔별 개수","head":"색깔","cols":["주황색","파란색","노란색"],"counts":[9,10,8],"unit":"개","vh":"연결 모형 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_challenge#2','math',2,2,'u5','L02','g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C2',2,'mc','auto','슬기네 모둠의 연결 모형은 모두 몇 개인가요?',ARRAY['M2-2-u5-X03','M2-2-u5-X04']::text[],true,'{"seq":2,"concept":"M2-2-u5-C2","difficulty":2,"kind":"mc","stem":"슬기네 모둠의 연결 모형은 모두 몇 개인가요?","explanation":["표의 각 색깔별 수는 주황색 9개, 파란색 10개, 노란색 8개예요.","9 + 10 + 8 = 27이니 모두 27개예요.","항목별 수를 모두 더한 것이 합계 — 전체 수예요."],"variant_rule":{"tg":{"ask":"total"}},"options":[{"t":"27개","correct":true},{"t":"10개","mis":"M2-2-u5-X03"},{"t":"3개","mis":"M2-2-u5-X04"}],"asset":{"type":"ftable","topic":"block","title":"슬기네 모둠이 가지고 있는 연결 모형의 색깔별 개수","head":"색깔","cols":["주황색","파란색","노란색"],"counts":[9,10,8],"unit":"개","vh":"연결 모형 수","total":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_challenge#3','math',2,2,'u5','L02','g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C1',3,'mc','auto','자료를 보세요. 놀이 한마당이 즐거웠던 학생은 몇 명인가요?',ARRAY['M2-2-u5-X01','M2-2-u5-X02']::text[],true,'{"seq":3,"concept":"M2-2-u5-C1","difficulty":3,"kind":"mc","stem":"자료를 보세요. 놀이 한마당이 즐거웠던 학생은 몇 명인가요?","explanation":["자료에서 「놀이 한마당」을 고른 이름표만 ／ 표시를 하며 세어요.","놀이 한마당이 즐거웠던 학생은 2명이에요.","빠뜨리거나 두 번 세지 않게 표시하며 세요."],"variant_rule":{"tg":{"ask":"count","src":"cards"}},"options":[{"t":"2명","correct":true},{"t":"3명","mis":"M2-2-u5-X01"},{"t":"1명","mis":"M2-2-u5-X01"},{"t":"4명","mis":"M2-2-u5-X02"}],"asset":{"type":"cards","topic":"act","items":[["세미","현장체험학습"],["소민","안전 체험"],["소희","안전 체험"],["채원","현장체험학습"],["연우","놀이 한마당"],["상혁","현장체험학습"],["수찬","안전 체험"],["정우","신나는 무용"],["효주","놀이 한마당"],["도현","현장체험학습"],["다윤","신나는 무용"],["재이","신나는 무용"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_challenge#4','math',2,2,'u5','L02','g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C2',3,'mc','auto','현장체험학습이 아닌 활동을 고른 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X03','M2-2-u5-X01']::text[],false,'{"seq":4,"concept":"M2-2-u5-C2","difficulty":3,"kind":"mc","stem":"현장체험학습이 아닌 활동을 고른 학생은 모두 몇 명인가요?","options":[{"t":"13명","correct":true},{"t":"7명","mis":"M2-2-u5-X09"},{"t":"20명","mis":"M2-2-u5-X03"},{"t":"12명","mis":"M2-2-u5-X01"}],"explanation":["현장체험학습이 아닌 활동은 안전 체험·놀이 한마당·신나는 무용·텃밭 가꾸기예요.","3 + 5 + 2 + 3 = 13이에요.","합계 20에서 7을 빼도 13이에요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_challenge#5','math',2,2,'u5','L02','g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C2',3,'mc','auto','현장체험학습이 즐거웠던 학생은 놀이 한마당이 즐거웠던 학생보다 몇 명 더 많은가요?',ARRAY['M2-2-u5-X08','M2-2-u5-X01']::text[],true,'{"seq":5,"concept":"M2-2-u5-C2","difficulty":3,"kind":"mc","stem":"현장체험학습이 즐거웠던 학생은 놀이 한마당이 즐거웠던 학생보다 몇 명 더 많은가요?","explanation":["현장체험학습이 즐거웠던 학생은 7명, 놀이 한마당이 즐거웠던 학생은 5명이에요.","7 − 5 = 2이니 2명 더 많아요.","「더 많은」 수는 두 수의 차이예요 — 더하지 않아요."],"variant_rule":{"tg":{"ask":"diff"}},"options":[{"t":"2명","correct":true},{"t":"12명","mis":"M2-2-u5-X08"},{"t":"7명","mis":"M2-2-u5-X08"},{"t":"3명","mis":"M2-2-u5-X01"}],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_challenge#6','math',2,2,'u5','L02','g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C1',3,'ox','auto','「현장체험학습」을 센 낱장에 ／ 표시를 하면 빠뜨리거나 두 번 세는 일이 없어요.',ARRAY['M2-2-u5-X01']::text[],false,'{"seq":6,"concept":"M2-2-u5-C1","difficulty":3,"kind":"ox","stem":"「현장체험학습」을 센 낱장에 ／ 표시를 하면 빠뜨리거나 두 번 세는 일이 없어요.","answer":"O","reason_options":[{"t":"센 것과 아직 안 센 것이 구분되니까","correct":true},{"t":"표시를 하면 수가 늘어나니까","mis":"M2-2-u5-X01"}],"mis":"M2-2-u5-X01","explanation":["센 낱장에 표시를 하면 어디까지 셌는지 보여요.","그래서 빠뜨리거나 두 번 세지 않아요.","표시는 수를 바꾸지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_challenge#7','math',2,2,'u5','L02','g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C2',3,'error','auto','자료와 표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u5-X16']::text[],false,'{"seq":7,"concept":"M2-2-u5-C2","difficulty":3,"kind":"error","stem":"자료와 표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「표를 보면 효주가 무엇을 골랐는지 바로 알 수 있어.」","correct":true,"mis_target":"M2-2-u5-X16"},{"t":"소율 — 「자료를 보면 누가 무엇을 골랐는지 알 수 있어.」","mis":"M2-2-u5-X16"},{"t":"예준 — 「표를 보면 활동별 학생 수를 한눈에 알 수 있어.」","mis":"M2-2-u5-X16"}],"explanation":["자료(이름표)에는 누가 무엇을 골랐는지 적혀 있어요.","표에는 활동별 학생 수와 합계가 있어요.","효주가 고른 활동은 표가 아니라 자료에서 찾아요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_challenge#8','math',2,2,'u5','L02','g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C2',4,'essay','teacher','표의 합계 20은 어떻게 구한 수인지 설명하고, 합계가 무엇을 뜻하는지 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u5-C2","difficulty":4,"kind":"essay","stem":"표의 합계 20은 어떻게 구한 수인지 설명하고, 합계가 무엇을 뜻하는지 써 보세요.","answer_guide":{"answer":"예: 활동별 학생 수 7, 3, 5, 2, 3을 모두 더해서 7 + 3 + 5 + 2 + 3 = 20으로 구했다. 합계는 조사한 학생 전체의 수, 곧 슬기네 반 학생 수이다.","scoring_points":["항목별 수를 모두 더했음을 썼는가","7 + 3 + 5 + 2 + 3 = 20을 썼는가","합계가 전체 학생 수임을 썼는가"]},"explanation":["합계는 항목별 수를 모두 더한 수예요.","7 + 3 + 5 + 2 + 3 = 20이에요.","합계 20명이 슬기네 반 전체 학생 수예요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_challenge#9','math',2,2,'u5','L02','g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C1',4,'essay','teacher','자료를 그대로 둘 때보다 표로 나타내면 좋은 점을 한 가지 쓰고, 자료에서만 알 수 있는 것도 한 가지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u5-C1","difficulty":4,"kind":"essay","stem":"자료를 그대로 둘 때보다 표로 나타내면 좋은 점을 한 가지 쓰고, 자료에서만 알 수 있는 것도 한 가지 써 보세요.","answer_guide":{"answer":"예: 표로 나타내면 활동별 학생 수를 한눈에 알 수 있고 합계도 바로 알 수 있다. 자료에서는 누가 어떤 활동을 골랐는지 알 수 있다.","scoring_points":["표의 좋은 점(활동별 수·합계를 한눈에)을 썼는가","자료에서만 알 수 있는 것(누가 무엇을 골랐는지)을 썼는가","둘을 구분해서 썼는가"]},"explanation":["표는 활동별 학생 수와 합계를 한눈에 보여 줘요.","자료는 누가 무엇을 골랐는지 보여 줘요.","표와 자료는 알기 좋은 것이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L02_challenge#10','math',2,2,'u5','L02','g2_2_math_u5_L02_challenge','lesson_challenge','M2-2-u5-C2',4,'mc','auto','표에서 두 번째로 많은 학생이 즐거워한 활동은 무엇인가요?',ARRAY['M2-2-u5-X09','M2-2-u5-X07']::text[],false,'{"seq":10,"concept":"M2-2-u5-C2","difficulty":4,"kind":"mc","stem":"표에서 두 번째로 많은 학생이 즐거워한 활동은 무엇인가요?","options":[{"t":"놀이 한마당","correct":true},{"t":"현장체험학습","mis":"M2-2-u5-X09"},{"t":"안전 체험","mis":"M2-2-u5-X07"},{"t":"신나는 무용","mis":"M2-2-u5-X09"}],"explanation":["수가 큰 순서로 늘어놓으면 7, 5, 3, 3, 2예요.","가장 많은 것은 현장체험학습(7명)이에요.","두 번째로 많은 것은 놀이 한마당(5명)이에요."],"asset":{"type":"ftable","topic":"act","title":"2학년 때 즐거웠던 활동별 학생 수","head":"활동","cols":["현장체험학습","안전 체험","놀이 한마당","신나는 무용","텃밭 가꾸기"],"counts":[7,3,5,2,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_basic#1','math',2,2,'u5','L03','g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C3',1,'mc','auto','자료를 조사할 때 꼭 지켜야 할 것은 무엇인가요?',ARRAY['M2-2-u5-X15','M2-2-u5-X01']::text[],true,'{"seq":1,"concept":"M2-2-u5-C3","difficulty":1,"kind":"mc","stem":"자료를 조사할 때 꼭 지켜야 할 것은 무엇인가요?","options":[{"t":"빠진 친구가 없도록 모두 조사한다","correct":true},{"t":"빨리 끝나도록 몇 명만 조사한다","mis":"M2-2-u5-X15"},{"t":"한 친구에게 두 번씩 물어본다","mis":"M2-2-u5-X01"}],"explanation":["조사는 빠진 사람이 없어야 해요.","몇 명만 조사하면 우리 반의 결과가 아니에요.","한 사람에게 두 번 물으면 두 번 세게 돼요."],"variant_rule":{"alt":[{"stem":"조사하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"내가 좋아하는 친구에게만 물어본다","correct":true},{"t":"한 사람씩 차례로 말한다","mis":"M2-2-u5-X15"},{"t":"계절별로 손을 들어 센다","mis":"M2-2-u5-X15"}],"explanation":["조사는 반 친구 모두에게 해야 해요.","한 사람씩 말하거나 손을 들게 하면 모두 조사할 수 있어요.","몇 명만 고르면 빠진 친구가 생겨요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_basic#2','math',2,2,'u5','L03','g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C3',1,'match','auto','태어난 달을 보고 알맞은 계절과 이으세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u5-C3","difficulty":1,"kind":"match","stem":"태어난 달을 보고 알맞은 계절과 이으세요.","pairs":[{"l":"4월","r":"봄"},{"l":"7월","r":"여름"},{"l":"1월","r":"겨울"}],"mis":"M2-2-u5-X02","explanation":["3·4·5월은 봄, 6·7·8월은 여름이에요.","9·10·11월은 가을이에요.","12·1·2월은 겨울이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 태어난 달을 보고 알맞은 계절과 이으세요.","pairs":[{"l":"10월","r":"가을"},{"l":"6월","r":"여름"},{"l":"2월","r":"겨울"}],"explanation":["6·7·8월은 여름이에요.","9·10·11월은 가을이에요.","12·1·2월은 겨울이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_basic#3','math',2,2,'u5','L03','g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C4',1,'sa','auto','가을에 태어난 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u5-C4","difficulty":1,"kind":"sa","stem":"가을에 태어난 학생은 몇 명인가요? 숫자로 쓰세요.","explanation":["표에서 「가을」 칸 아래의 수를 읽어요.","가을에 태어난 학생은 6명이에요.","항목 이름과 그 아래 수를 짝지어 읽어요."],"variant_rule":{"tg":{"ask":"count"}},"answer":["6","6명"],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_basic#4','math',2,2,'u5','L03','g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C4',1,'mc','auto','／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u5-X06','M2-2-u5-X01']::text[],true,'{"seq":4,"concept":"M2-2-u5-C4","difficulty":1,"kind":"mc","stem":"／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마인가요?","explanation":["「봄」 칸의 ／ 표시를 세어요.","다섯 개 묶음 하나는 5예요. ／／／／／ ／／ → 7","그래서 빈칸은 7이에요."],"variant_rule":{"tg":{"ask":"tally"}},"options":[{"t":"7","correct":true},{"t":"6","mis":"M2-2-u5-X06"},{"t":"8","mis":"M2-2-u5-X01"}],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[null,4,6,3],"unit":"명","vh":"학생 수","tally":[7,4,6,3]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_basic#5','math',2,2,'u5','L03','g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C4',2,'sa','auto','표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-2-u5-C4","difficulty":2,"kind":"sa","stem":"표의 빈칸에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["나머지 칸을 더하면 7 + 6 + 3 = 16이에요.","16 + □ = 20이니 □ = 4예요.","합계에서 나머지 칸의 수를 빼면 빈칸의 수예요."],"variant_rule":{"tg":{"ask":"blank"}},"answer":["4"],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,null,6,3],"unit":"명","vh":"학생 수","total":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_basic#6','math',2,2,'u5','L03','g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C4',2,'mc','auto','표에 꼭 있어야 하는 것이 아닌 것은 무엇인가요?',ARRAY['M2-2-u5-X15']::text[],true,'{"seq":6,"concept":"M2-2-u5-C4","difficulty":2,"kind":"mc","stem":"표에 꼭 있어야 하는 것이 아닌 것은 무엇인가요?","options":[{"t":"조사한 친구들의 이름","correct":true},{"t":"무엇을 조사했는지 알려 주는 제목","mis":"M2-2-u5-X15"},{"t":"모두 더한 합계","mis":"M2-2-u5-X15"}],"explanation":["표에는 제목·항목·수·합계를 갖추어요.","이름은 자료에 있고 표에는 수만 적어요.","제목이 없으면 무엇을 조사했는지 알 수 없어요."],"variant_rule":{"alt":[{"stem":"표의 제목은 무엇을 알려 주나요?","options":[{"t":"무엇을 조사했는지","correct":true},{"t":"합계가 얼마인지","mis":"M2-2-u5-X03"},{"t":"누가 조사했는지","mis":"M2-2-u5-X16"}],"explanation":["제목은 무엇을 조사한 표인지 알려 줘요.","「우리 반 친구들이 태어난 계절별 학생 수」처럼 써요.","합계는 표 맨 끝 칸에 따로 적어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_basic#7','math',2,2,'u5','L03','g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C3',2,'ox','auto','조사하는 방법은 무엇을 조사하느냐에 따라 알맞은 것이 달라요.',ARRAY['M2-2-u5-X15']::text[],false,'{"seq":7,"concept":"M2-2-u5-C3","difficulty":2,"kind":"ox","stem":"조사하는 방법은 무엇을 조사하느냐에 따라 알맞은 것이 달라요.","answer":"O","reason_options":[{"t":"말하기·손 들기·이름 붙이기 가운데 조사할 것에 맞는 방법을 고르니까","correct":true},{"t":"조사 방법은 언제나 한 가지뿐이니까","mis":"M2-2-u5-X15"}],"mis":"M2-2-u5-X15","explanation":["조사 방법에는 말하기, 손 들기, 이름 써서 붙이기 등이 있어요.","무엇을 조사하느냐에 따라 알맞은 방법이 달라요.","어떤 방법이든 빠진 친구가 없어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_basic#8','math',2,2,'u5','L03','g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C4',2,'mc','auto','봄에 태어난 학생과 여름에 태어난 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X08','M2-2-u5-X03']::text[],true,'{"seq":8,"concept":"M2-2-u5-C4","difficulty":2,"kind":"mc","stem":"봄에 태어난 학생과 여름에 태어난 학생은 모두 몇 명인가요?","explanation":["봄에 태어난 학생은 7명, 여름에 태어난 학생은 4명이에요.","7 + 4 = 11이니 모두 11명이에요.","두 칸의 수를 더해요 — 전체 합계가 아니에요."],"variant_rule":{"tg":{"ask":"sum2"}},"options":[{"t":"11명","correct":true},{"t":"3명","mis":"M2-2-u5-X08"},{"t":"20명","mis":"M2-2-u5-X03"}],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_basic#9','math',2,2,'u5','L03','g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C4',2,'mc','auto','우리 반 학생은 모두 몇 명인가요?',ARRAY['M2-2-u5-X03','M2-2-u5-X01']::text[],true,'{"seq":9,"concept":"M2-2-u5-C4","difficulty":2,"kind":"mc","stem":"우리 반 학생은 모두 몇 명인가요?","explanation":["표의 각 과일별 수는 자두 3명, 포도 5명, 키위 2명, 감 4명, 복숭아 4명이에요.","3 + 5 + 2 + 4 + 4 = 18이니 모두 18명이에요.","항목별 수를 모두 더한 것이 합계 — 전체 수예요."],"variant_rule":{"tg":{"ask":"total"}},"options":[{"t":"18명","correct":true},{"t":"5명","mis":"M2-2-u5-X03"},{"t":"19명","mis":"M2-2-u5-X01"}],"asset":{"type":"ftable","topic":"fruit","title":"우리 반 학생들이 좋아하는 과일별 학생 수","head":"과일","cols":["자두","포도","키위","감","복숭아"],"counts":[3,5,2,4,4],"unit":"명","vh":"학생 수","total":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_basic#10','math',2,2,'u5','L03','g2_2_math_u5_L03_basic','lesson_basic','M2-2-u5-C4',3,'error','auto','친구들이 표를 만들었어요. 잘못 만든 친구는 누구인가요?',ARRAY['M2-2-u5-X15']::text[],true,'{"seq":10,"concept":"M2-2-u5-C4","difficulty":3,"kind":"error","stem":"친구들이 표를 만들었어요. 잘못 만든 친구는 누구인가요?","options":[{"t":"윤슬 — 조사한 친구가 적어서 합계를 25로 늘려 적었다","correct":true,"mis_target":"M2-2-u5-X15"},{"t":"가은 — 제목을 「우리 반 친구들이 태어난 계절별 학생 수」라고 썼다","mis":"M2-2-u5-X15"},{"t":"태오 — 7 + 4 + 6 + 3을 더해 합계 20을 썼다","mis":"M2-2-u5-X15"}],"explanation":["합계는 항목별 수를 더한 그대로 적어요.","마음대로 늘려 쓰면 조사한 것이 아니에요.","제목을 쓰고 더해서 합계를 쓴 것은 바르게 만든 거예요."],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수","total":20},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 표를 만들었어요. 잘못 만든 친구는 누구인가요?","options":[{"t":"도윤 — 제목 없이 수만 적었다","correct":true,"mis_target":"M2-2-u5-X15"},{"t":"나린 — 계절 칸을 봄·여름·가을·겨울로 나누어 적었다","mis":"M2-2-u5-X15"},{"t":"서아 — 합계 칸에 20을 적었다","mis":"M2-2-u5-X15"}],"explanation":["표에는 무엇을 조사한 것인지 제목을 써야 해요.","항목을 나누고 합계를 쓴 것은 바르게 만든 거예요.","제목·항목·수·합계를 다 갖추어요."],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수","total":20}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u5_L03_challenge#1','math',2,2,'u5','L03','g2_2_math_u5_L03_challenge','lesson_challenge','M2-2-u5-C4',2,'mc','auto','겨울에 태어난 학생은 몇 명인가요?',ARRAY['M2-2-u5-X01','M2-2-u5-X02']::text[],true,'{"seq":1,"concept":"M2-2-u5-C4","difficulty":2,"kind":"mc","stem":"겨울에 태어난 학생은 몇 명인가요?","explanation":["표에서 「겨울」 칸 아래의 수를 읽어요.","겨울에 태어난 학생은 3명이에요.","항목 이름과 그 아래 수를 짝지어 읽어요."],"variant_rule":{"tg":{"ask":"count"}},"options":[{"t":"3명","correct":true},{"t":"4명","mis":"M2-2-u5-X01"},{"t":"2명","mis":"M2-2-u5-X01"},{"t":"7명","mis":"M2-2-u5-X02"}],"asset":{"type":"ftable","topic":"season","title":"우리 반 친구들이 태어난 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,4,6,3],"unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
